window.BEC_DATA = {"version":"1.0","storageKey":"becHy.","catOrder":["conditions","skills","medicines","reference"],"ui":{"barTitle":"ԱԲՕՀ / BEC","appTitle":"Անհետաձգելի բուժօգնության հիմունքներ","tagline":"Անցանց տեղեկատու - առաջին գծի սպասարկողների համար։","searchPlaceholder":"Որոնել","searchTitle":"Որոնում","searchAria":"Որոնում","aboutAria":"Հավելվածի մասին","aboutTitle":"Հավելվածի մասին","back":"Հետ","browse":"Բաժիններ","saved":"Պահված էջեր","recent":"Դիտված","save":"Պահել","savedBtn":"Պահված է","smaller":"Փոքրացնել տառաչափը","larger":"Մեծացնել տառաչափը","filterPlaceholder":"Զտել ցանկը","noMatch":"Համընկնումներ չկան։","pagesCount":"{n} էջ։","searchEmpty":"Մուտքագրեք դեղի անունը՝ հայերեն կամ լատինատառ, օրինակ՝ նալոքսոն կամ naloxone։","searchNone":"«{q}» հարցմանը համապատասխան էջեր չեն գտնվել։ Ստուգեք ուղղագրությունը կամ փորձեք ավելի կարճ բառ։","searchMore":"Ցուցադրված է լավագույն 40-ը {n} համընկնումից։ Ավելացրեք ևս մեկ բառ։","updateAvail":"Հասանելի է թարմացում","updateBtn":"Թարմացնել","notFoundTitle":"Էջը չի գտնվել","notFound":"Նման էջ հավելվածում առկա չէ։","home":"Գլխավոր էջ","pilotNote":"Ներառված են «ABCDE» մոտեցումը, վիճակների 45 էջ, հմտությունների 23 էջ, դեղորայքի 11 էջ և տեղեկանքի 3 էջ։ Ամբողջ բովանդակությունը հասանելի է անցանց։","footHome":"Ոչ պաշտոնական անցանց տարբերակ։ Դեղաչափերը համապատասխանում են Հայաստանում հասանելի դեղամիջոցներին։","footPage":"Ոչ պաշտոնական անցանց տարբերակ, նախատեսված է վերապատրաստված մասնագետների համար և չի փոխարինում կլինիկական դատողությանը։ Դեղաչափերը համապատասխանում են Հայաստանում հասանելի դեղամիջոցներին։","footAbout":"Հավելվածի մասին, արտոնագիր և պատասխանատվության ժխտում","version":"Հավելվածի տարբերակ","zoomHint":"Սահեցրեք կամ մեծացրեք","close":"Փակել","abcdeHeading":"«ABCDE» մոտեցում","abcdeMore":"Կարդալ «ABCDE» մոտեցումն ամբողջությամբ","jumpAria":"Անցնել բաժնին"},"cats":{"medicines":{"label":"Դեղորայք","one":"Դեղորայք","desc":"Ցուցումներ, դեղաչափեր և անցանկալի ազդեցություններ"},"conditions":{"label":"Վիճակներ","one":"Վիճակ","desc":"Հիվանդություններ և վնասվածքներ"},"skills":{"label":"Հմտություններ","one":"Հմտություն","desc":"Քայլ առ քայլ ընթացակարգեր"},"reference":{"label":"Տեղեկանք","one":"Տեղեկանք","desc":"Նորմալ ցուցանիշներ և մանկաբուժական նկատառումներ"},"abcde":{"label":"«ABCDE»","one":"«ABCDE»","desc":""}},"about":[{"h":"Հավելվածի մասին","p":["Սա «Անհետաձգելի բուժօգնության հիմունքներ» (BEC) դասընթացի անցանց տեղեկատու է՝ առաջին գծի բժշկական սպասարկողների համար։ Բոլոր էջերը պահվում են ձեր հեռախոսում, ուստի հավելվածը աշխատում է առանց ինտերնետի։","Ներառված են «ABCDE» մոտեցումը, վիճակների 45 էջ, հմտությունների 23 էջ, դեղորայքի 11 էջ և տեղեկանքի 3 էջ։"]},{"h":"Դեղաչափերի մասին","p":["Այս հավելվածում նշված դեղաչափերը համապատասխանում են Հայաստանում հասանելի անվանումներին, դրանց դեղաձևերին, դեղաչափերին և կոնցենտրացիային՝ ինչպես նշված է ԱՀԿ/ԿԽՄԿ «Անհետաձգելի բուժօգնության հիմունքներ» ձեռնարկի հայերեն հրատարակության մեջ։ Այն երկրներում, որտեղ հասանելի են այլ դեղամիջոցներ կամ կոնցենտրացիաներ, ստուգեք տեղական գործելակարգերը։"]},{"h":"Հեղինակներ և շնորհակալություն","p":["Բովանդակությունը հիմնված է ԱՀԿ-ի և ԿԽՄԿ-ի «Անհետաձգելի բուժօգնության հիմունքներ» դասընթացի վրա։ Ձեռնարկի հայերեն թարգմանությունը պատրաստվել է ԱՀԿ հայաստանյան գրասենյակի կողմից՝ 2019 թվականին, և խմբագրվել է ԿԽՄԿ հայաստանյան պատվիրակության կողմից՝ 2023–2025 թվականներին։","Էջերի կառուցվածքը և անգլերեն բնագիրը վերցված են BEC հավելվածից, որը մշակվել է UCSF-ի ԱՀԿ համագործակցող կենտրոնի կողմից՝ անհետաձգելի և տրավմայի խնամքի ոլորտում (UCSF WHO Collaborating Centre for Emergency and Trauma Care)։ Հիմնական մշակողներ՝ Christian Rose, Rana Waleed Asmat և Andrea Tenner։"]},{"h":"Արտոնագիր","p":["© Առողջության համաշխարհային կազմակերպություն (ԱՀԿ) և Կարմիր խաչի միջազգային կոմիտե (ԿԽՄԿ), 2018։ Սույն աշխատանքը հասանելի է Creative Commons Attribution-NonCommercial-ShareAlike 3.0 IGO արտոնագրի ներքո (CC BY-NC-SA 3.0 IGO; https://creativecommons.org/licenses/by-nc-sa/3.0/igo)։ Այս հավելվածը հարմարեցված տարբերակ է. այն տարածվում է նույն արտոնագրով և միայն ոչ առևտրային նպատակներով։","Առաջարկվող հղումը. \"Անհետաձգելի բժշկական օգնության հիմունքներ\". Մոտեցումը՝ սուր հիվանդություններով և վնասվածքներով հիվանդներին. Ժնև. Առողջապահության համաշխարհային կազմակերպություն և Կարմիր խաչի միջազգային կոմիտե, 2018թ. Արտոնագիր՝ CC BY-NC-SA 3.0 IGO։","Այս հավելվածից օգտվելու դեպքում չի թույլատրվում որևէ ենթադրություն առ այն, որ ԱՀԿ-ն կամ ԿԽՄԿ-ն աջակցում են որևէ կոնկրետ կազմակերպության կամ հավելվածի։ Այս հավելվածը կապ չունի ԱՀԿ-ի, ԿԽՄԿ-ի և UCSF-ի հետ և նրանց կողմից առայժմ հավանության չի արժանացել։ ԱՀԿ-ի և ԿԽՄԿ-ի տարբերանշանները այս հավելվածում չեն օգտագործվում։","Թարգմանության մասին հայտարարություն. «Տվյալ հավելվածի թարգմանությունը դեռևս պաշտոնապես չի հաստատվել ԱՀԿ-ի կամ ԿԽՄԿ-ի կողմից։ ԱՀԿ-ն և ԿԽՄԿ-ն պատասխանատվություն չեն կրում սույն թարգմանության բովանդակության և ճշգրտության համար։ Պարտավորեցնող և վավեր է համարվում անգլերեն լեզվով հրատարակությունը»։"]},{"h":"Պատասխանատվության ժխտում","p":["Այս հավելվածը պարունակում է կլինիկական գործիքներ և բովանդակություն, որոնք նախատեսված են առողջապահության մասնագետների համար։ Այս գործիքները մասնագիտական խորհրդատվություն չեն տալիս. այն բժիշկները և առողջապահության այլ մասնագետները, որոնք օգտագործում են այս գործիքները կամ տվյալների շտեմարանները պետք է իրենց տրամադրած տեղեկատվության նկատմամբ կիրառեն սեփական կլինիկական դատողությունը։ Սպառողները (ոչ բժշկական մասնագետները), որոնք օգտագործում են այս գործիքները կամ տվյալների շտեմարանները դա անում են իրենց սեփական ռիսկով։ Ցանկացած բժշկական վիճակ ունեցող անձանց հատուկ զգուշացվում է դիմել մասնագիտական բժշկական խորհրդատվության՝ ցանկացած բուժում սկսելուց առաջ։ Բժշկական հարցերի, այդ թվում՝ դեղորայքի և այլ բուժումների վերաբերյալ որոշումների համար ոչ բժշկական օգտատերերը միշտ պետք է խորհրդակցեն իրենց բժշկի կամ այլ որակավորված առողջապահության մասնագետի հետ։","Այս հավելվածի բովանդակությունը մշակողները ջանացել են ստեղծել այնպես, որ այն համապատասխանի մշակման պահին գործող մասնագիտական պրակտիկայի չափանիշներին։ Սակայն բժշկության մեջ չափանիշներն ու պրակտիկան փոխվում են նոր տվյալների հայտնվելուն զուգընթաց, և յուրաքանչյուր բժշկական մասնագետ պետք է դիմի տարբեր աղբյուրների։ Հավելվածի բովանդակությունը՝ տեքստը, գրաֆիկան և պատկերները, նախատեսված է միայն տեղեկատվական նպատակներով։ Այս հավելվածը չի առաջարկում և հավանություն չի տալիս որևէ կոնկրետ հետազոտության, բժշկի, արտադրանքի, միջամտության, կարծիքի կամ այլ տեղեկատվության, որոնք կարող են նշված լինել հավելվածում։","Թեև տեղեկատվությունը ստացվել է հուսալի համարվող աղբյուրներից, ո՛չ մենք, ո՛չ մեր բովանդակության տրամադրողները չենք երաշխավորում դրա ճշգրտությունը։ Հավելվածը նախատեսված է բուժանձնակազմի վերապատրաստման և հետագայում օգտագործելու համար՝ իրենց դատողությունների և պաշտոնապես ընդունված գործելակարգերի համաձայն։ Մենք բժշկական խորհրդատվություն չենք տրամադրում և բժշկական կամ ախտորոշիչ ծառայություններ չենք մատուցում։ Բժշկական տեղեկատվությունը արագ է փոխվում։ Ո՛չ մենք, ո՛չ մեր բովանդակության տրամադրողները չենք երաշխավորում, որ բովանդակությունը ընդգրկում է ցանկացած բուժման հետ կապված բոլոր հնարավոր կիրառումները, ցուցումները, զգուշացումները, դեղերի փոխազդեցությունները կամ անցանկալի ազդեցությունները։ Ծրագրում ստացված տեղեկատվության և բովանդակության վրա ապավինելը ձեր սեփական ռիսկով է։ Ո՛չ մենք, ո՛չ մեր բովանդակության տրամադրողները պատասխանատվություն չենք կրում որևէ վնասի կամ վնասվածքի (ներառյալ մահվան) համար, որը կարող է հասցվել ձեզ, այլ անձանց կամ գույքին՝ հավելվածում տրամադրված որևէ արտադրանքի, տեղեկատվության, գաղափարի կամ հրահանգի օգտագործման հետևանքով։"],"plain":true}],"abcdeWords":[["A","Շնչուղիներ","airway"],["B","Շնչառություն","breathing"],["C","Արյան շրջանառություն","circulation"],["D","Գիտակցության խանգարում","disability"],["E","Բացահայտում","exposure"]],"pages":[{"id":"c-Femurfracture","cat":"conditions","title":"Ազդրոսկրի կոտրվածք","keywords":"Femur fracture","html":"<p>Մեծ քանակությամբ արյուն կարող է կորչել նաև ազդրում՝ նախքան արյունահոսության նկատելի դառնալը։ Չվերահսկվող ներքին արյունահոսությունը կարող է արագ հանգեցնել շոկի։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Ստուգեք և՛ արտաքին, և՛ ներքին արյունահոսության առկայությունը, ներառյալ կրծքավանդակում, որովայնում, ստամոքսից կամ աղիքներից, կոնքի կամ ազդրոսկրի կոտրվածքից, վերքերից։</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li><a href=\"#/p/s-Fractureimmobilization\" class=\"xref\">Անշարժացրեք</a> վերջույթը՝ ազդրոսկրի կոտրվածքի կասկածի դեպքում։</li><li>Թույլ պերֆուզիայի նշանների դեպքում <a href=\"#/p/s-PlaceIV\" class=\"xref\">տվեք ն/ե հեղուկներ</a> և <a href=\"#/p/s-Giveoxygen\" class=\"xref\">թթվածին։</a></li></ul>","text":"Մեծ քանակությամբ արյուն կարող է կորչել նաև ազդրում՝ նախքան արյունահոսության նկատելի դառնալը։ Չվերահսկվող ներքին արյունահոսությունը կարող է արագ հանգեցնել շոկի։ Նշաններ և ախտանշաններ Ստուգեք և՛ արտաքին, և՛ ներքին արյունահոսության առկայությունը, ներառյալ կրծքավանդակում, որովայնում, ստամոքսից կամ աղիքներից, կոնքի կամ ազդրոսկրի կոտրվածքից, վերքերից։ Վարման հիմնական որոշումներ Անշարժացրեք վերջույթը՝ ազդրոսկրի կոտրվածքի կասկածի դեպքում։ Թույլ պերֆուզիայի նշանների դեպքում տվեք ն/ե հեղուկներ և թթվածին։"},{"id":"c-Allergicreaction","cat":"conditions","title":"Ալերգիկ ռեակցիա","keywords":"Allergic reaction","html":"<p>Ծանր ալերգիկ ռեակցիաները (անաֆիլաքսիա) կարող են առաջացնել շնչուղիների այտուցվածություն, ինչը կարող է հանգեցնել խցանման։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Բերանի, շրթունքի և լեզվի այտուցվածություն</li><li>Դժվարացած շնչառություն՝ ուղեկցվող ստրիդորով (բարձրահնչյուն կամ «սուլող» ձայներ ՆԵՐշնչելիս, որոնք առաջանում են վերին շնչուղիների նեղացման հետևանքով) և/կամ սուլոցով (բարձրահնչյուն ձայն ԱՐՏԱշնչելիս, որն առաջանում է թոքերի ստորին շնչուղիների նեղացման կամ սպազմի հետևանքով)։</li><li>Ձայնի փոփոխություն</li><li>Ցանավորում կամ եղնջացան (գունատ կամ կարմրավուն հետքեր, քոր եկող, տաք և այտուցված մաշկ)</li><li>Տախիկարդիա և հիպոտենզիա</li><li>Ոչ բնորոշ ձայներ շնչուղիներից (ստրիդոր, խռխռոց, կլկլոց)</li><li>Կրծքավանդակի թույլ բարձրացում</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Հեռացրեք ալերգենը, եթե հնարավոր է։</li><li>Շնչուղիների խցանման, ուժգին սուլոցի կամ շոկի դեպքում կատարեք մ/մ <a href=\"#/p/m-Adrenaline_Epinephrine_\" class=\"xref\">ադրենալին</a> ներարկում։</li><li>Ադրենալինի գործողությունը կարող է մի քանի րոպեից դադարել, ուստի պատրաստ եղեք լրացուցիչ դեղաչափեր ներարկել։</li><li>Ռեակցիան կարող է վերադառնալ, երբ ադրենալինի ազդեցությունը դադարի։ Հիվանդները պետք է ուշադիր հսկվեն։</li><li><a href=\"#/p/s-PlaceIV\" class=\"xref\">Տեղադրեք ն/ե կատետր </a>և տվեք ն/ե հեղուկներ։</li><li>Փոխեք շնչուղիների դիրքն անհրաժեշտության դեպքում (եթե վնասվածք չկա, ուղիղ նստեցրեք հիվանդին) և <a href=\"#/p/s-Giveoxygen\" class=\"xref\">տվեք թթվածին։</a></li><li>Եթե հիվանդի վիճակը ծանր է կամ չի բարելավվում, պատրաստվեք հիվանդի արագ <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցմանը/հանձնմանը </a>շնչուղիների վարման գծով առավել բարձր կարգի սպասարկողի։</li><li>Ոչ բնորոշ ձայների առկայության դեպքում հաճախակի վերագնահատեք շնչուղիները, քանի որ մասնակի խցանումը կարող է արագ վատթարանալ և ամբողջությամբ խցանել շնչուղիները։</li></ul>","text":"Ծանր ալերգիկ ռեակցիաները (անաֆիլաքսիա) կարող են առաջացնել շնչուղիների այտուցվածություն, ինչը կարող է հանգեցնել խցանման։ Նշաններ և ախտանշաններ Բերանի, շրթունքի և լեզվի այտուցվածություն Դժվարացած շնչառություն՝ ուղեկցվող ստրիդորով (բարձրահնչյուն կամ «սուլող» ձայներ ՆԵՐշնչելիս, որոնք առաջանում են վերին շնչուղիների նեղացման հետևանքով) և/կամ սուլոցով (բարձրահնչյուն ձայն ԱՐՏԱշնչելիս, որն առաջանում է թոքերի ստորին շնչուղիների նեղացման կամ սպազմի հետևանքով)։ Ձայնի փոփոխություն Ցանավորում կամ եղնջացան (գունատ կամ կարմրավուն հետքեր, քոր եկող, տաք և այտուցված մաշկ) Տախիկարդիա և հիպոտենզիա Ոչ բնորոշ ձայներ շնչուղիներից (ստրիդոր, խռխռոց, կլկլոց) Կրծքավանդակի թույլ բարձրացում Վարման հիմնական որոշումներ Հեռացրեք ալերգենը, եթե հնարավոր է։ Շնչուղիների խցանման, ուժգին սուլոցի կամ շոկի դեպքում կատարեք մ/մ ադրենալին ներարկում։ Ադրենալինի գործողությունը կարող է մի քանի րոպեից դադարել, ուստի պատրաստ եղեք լրացուցիչ դեղաչափեր ներարկել։ Ռեակցիան կարող է վերադառնալ, երբ ադրենալինի ազդեցությունը դադարի։ Հիվանդները պետք է ուշադիր հսկվեն։ Տեղադրեք ն/ե կատետր և տվեք ն/ե հեղուկներ։ Փոխեք շնչուղիների դիրքն անհրաժեշտության դեպքում (եթե վնասվածք չկա, ուղիղ նստեցրեք հիվանդին) և տվեք թթվածին։ Եթե հիվանդի վիճակը ծանր է կամ չի բարելավվում, պատրաստվեք հիվանդի արագ փոխանցմանը/հանձնմանը շնչուղիների վարման գծով առավել բարձր կարգի սպասարկողի։ Ոչ բնորոշ ձայների առկայության դեպքում հաճախակի վերագնահատեք շնչուղիները, քանի որ մասնակի խցանումը կարող է արագ վատթարանալ և ամբողջությամբ խցանել շնչուղիները։"},{"id":"c-Burns","cat":"conditions","title":"Այրվածքներ","keywords":"Burns","html":"<p>Հրից առաջացած այրվածքները (բոցային այրվածքներ) ամենատարածվածն են։ Փակ տարածությունում բոցային այրվածքի պատմությունը կարող է նաև հուշել <a href=\"#/p/c-Inhalationinjury\" class=\"xref\">ինհալացիոն կամ շնչուղիների վնասվածքի</a> մասին։ Տաք հեղուկներից առաջացած այրվածքները տարածված են երեխաների մոտ։</p><p>Այրվածքների այլ տեսակների թվում են էլեկտրական և քիմիական այրվածքները։ Էլեկտրական վնասվածքները հաճախ առաջանում են բարձրավոլտ աղբյուրներից, ինչպիսիք են մարմնի հետ շփման մեջ մտնող  բացօդյա մալուխներն ու էլեկտրալարերը։ Մակերեսորեն այս էլեկտրական վնասվածքները կարող են փոքր թվալ, սակայն կարող են հյուսվածքների և մկանների ծանր վնասում առաջացնել։ Էլեկտրական հոսանքը հաճախ անցնում է մարմնով՝ ընտրելով ամենակարճ ճանապարհը մաշկի հետ շփման կետից մինչև հող, հաճախ թողնելով մուտքի և ելքի այրվածքային նշաններ։ \n<a href=\"#/p/c-ChemicalInjury\" class=\"xref\">Քիմիական այրվածքների</a> դեպքում կարող է անհրաժեշտ լինել տեղեկություն կոնկրետ քիմիական նյութի մասին՝ այն ճիշտ հեռացնելու համար։ Եթե առկա է քիմիական նյութի հետ կոնտակտի պատմություն, պաշտպանեք ինքներդ ձեզ քիմիական նյութից և համոզվեք, որ այն պատշաճորեն հեռացված է մաշկից։ Կարևոր է իմանալ՝ արդյոք կատարվել է ախտահանում։ Եթե այրվածք ստանալուց դեռևս չի անցել 3 ժամ և առաջին օգնություն չի տրամադրվել, ապա վերքը պետք է լվանալ մաքուր ջրով՝ այրման ընթացքը դադարեցնելու համար։</p><p>Ստորև ներկայացված վարումը կենտրոնացած է հրից առաջացած այրվածքների վրա։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Մաշկի կարմիր, սպիտակ կամ սև հատվածներ՝ կախված այրվածքի խորությունից</li><li>Հնարավոր է լինեն բշտեր</li><li>Հնարավոր են ինհալացիոն վնասվածքի նշաններ.</li><li>Մուր (մոխիր) քթի կամ բերանի շուրջ, կամ խանձված քթի մազիկներ</li><li>Շուրթերի կամ բերանի այտուց</li><li>Ձայնի փոփոխություններ</li></ul><h3>Վարման հիմնական որոշումներ</h3><p>Այրվածքները կարող են ազդել ամբողջ օրգանիզմի վրա և առաջացնել փափուկ հյուսվածքի վնասվածք, այտուց և շոկ՝ այրվածքի հետևանքով հեղուկի կորստի պատճառով։ Այրվածքի վարման նպատակն է դադարեցնել այրման ընթացքը, հետևել այտուցին և փոխհատուցել հեղուկի կորուստը։ Ծանր այրվածքային վնասվածքի դեպքում հեղուկը արտահոսում է դեպի մաշկ և շրջակա հյուսվածք՝ առաջացնելով այտուց և <a href=\"#/p/c-Shock\" class=\"xref\">շոկ։</a></p><ul><li>Շնչուղիները ներառող այրվածքները կարող են արագ առաջացնել <a href=\"#/p/c-Inhalationinjury\" class=\"xref\">շնչուղիների խցանում։</a></li><li>Կարևոր է փոխհատուցել հեղուկի կորուստը և կանխատեսել շարունակվող կորուստները։</li><li><a href=\"#/p/s-Burnfluids\" class=\"xref\">Ն/ե հեղուկի անհրաժեշտ քանակը հաշվարկելու համար կարևոր է որոշել այրվածքի խորությունը և մարմնի մակերեսի տոկոսը (ՄՄՏ), որն այրված է։</a></li><li>Այրվածքային վնասվածքների դեպքում մի մոռացեք կատարել <a href=\"#/p/m-Tetanusvaccination\" class=\"xref\">փայտացման դեմ պատվաստում </a>և ցավազրկում։</li><li>Հանեք բոլոր զարդերը և հնարավորության դեպքում բարձրացրեք այրված վերջույթը։</li><li>Այրվածքների վարակման ռիսկը բարձր է, անգամ լավ խնամքի դեպքում։ <a href=\"#/p/s-Burnwoundmanagement\" class=\"xref\">Զգուշորեն մաքրեք և վիրակապեք վերքը։</a></li></ul><p><strong>ԱՅՐՎԱԾՔՆԵՐ, ՈՐՈՆՔ ՊԱՀԱՆՋՈՒՄ ԵՆ ԱՐԱԳ <a href=\"#/p/s-Transferandhandover\" class=\"xref\">ՓՈԽԱՆՑՈՒՄ/ՀԱՆՁՆՈՒՄ</a>.</strong></p><ul><li>Մարմնի 15%-ից ավելի մակերեսի ծանր այրվածքներ (հաշվարկի համար տե՛ս ստորև նկարը)</li><li>Ձեռքերը, դեմքը, աճուկային հատվածը, հոդերը ներառող այրվածքներ, կամ օղակող այրվածքներ</li><li><a href=\"#/p/c-Inhalationinjury\" class=\"xref\">Ինհալացիոն վնասվածք</a></li><li>Այրվածքները կարող են առաջացնել շնչուղիների այտուց՝ ինհալացիոն վնասվածքների պատճառով</li><li>Այրվածքներ՝ այլ ուղեկցող վնասվածքներով</li><li>Ցանկացած այրվածք մանկահասակ կամ տարեց անձանց մոտ</li><li>Այրվածքից առաջ առկա լուրջ հիվանդություն (օրինակ՝ շաքարային դիաբետ)</li></ul>","text":"Հրից առաջացած այրվածքները (բոցային այրվածքներ) ամենատարածվածն են։ Փակ տարածությունում բոցային այրվածքի պատմությունը կարող է նաև հուշել ինհալացիոն կամ շնչուղիների վնասվածքի մասին։ Տաք հեղուկներից առաջացած այրվածքները տարածված են երեխաների մոտ։ Այրվածքների այլ տեսակների թվում են էլեկտրական և քիմիական այրվածքները։ Էլեկտրական վնասվածքները հաճախ առաջանում են բարձրավոլտ աղբյուրներից, ինչպիսիք են մարմնի հետ շփման մեջ մտնող  բացօդյա մալուխներն ու էլեկտրալարերը։ Մակերեսորեն այս էլեկտրական վնասվածքները կարող են փոքր թվալ, սակայն կարող են հյուսվածքների և մկանների ծանր վնասում առաջացնել։ Էլեկտրական հոսանքը հաճախ անցնում է մարմնով՝ ընտրելով ամենակարճ ճանապարհը մաշկի հետ շփման կետից մինչև հող, հաճախ թողնելով մուտքի և ելքի այրվածքային նշաններ։ \nՔիմիական այրվածքների դեպքում կարող է անհրաժեշտ լինել տեղեկություն կոնկրետ քիմիական նյութի մասին՝ այն ճիշտ հեռացնելու համար։ Եթե առկա է քիմիական նյութի հետ կոնտակտի պատմություն, պաշտպանեք ինքներդ ձեզ քիմիական նյութից և համոզվեք, որ այն պատշաճորեն հեռացված է մաշկից։ Կարևոր է իմանալ՝ արդյոք կատարվել է ախտահանում։ Եթե այրվածք ստանալուց դեռևս չի անցել 3 ժամ և առաջին օգնություն չի տրամադրվել, ապա վերքը պետք է լվանալ մաքուր ջրով՝ այրման ընթացքը դադարեցնելու համար։ Ստորև ներկայացված վարումը կենտրոնացած է հրից առաջացած այրվածքների վրա։ Նշաններ և ախտանշաններ Մաշկի կարմիր, սպիտակ կամ սև հատվածներ՝ կախված այրվածքի խորությունից Հնարավոր է լինեն բշտեր Հնարավոր են ինհալացիոն վնասվածքի նշաններ. Մուր (մոխիր) քթի կամ բերանի շուրջ, կամ խանձված քթի մազիկներ Շուրթերի կամ բերանի այտուց Ձայնի փոփոխություններ Վարման հիմնական որոշումներ Այրվածքները կարող են ազդել ամբողջ օրգանիզմի վրա և առաջացնել փափուկ հյուսվածքի վնասվածք, այտուց և շոկ՝ այրվածքի հետևանքով հեղուկի կորստի պատճառով։ Այրվածքի վարման նպատակն է դադարեցնել այրման ընթացքը, հետևել այտուցին և փոխհատուցել հեղուկի կորուստը։ Ծանր այրվածքային վնասվածքի դեպքում հեղուկը արտահոսում է դեպի մաշկ և շրջակա հյուսվածք՝ առաջացնելով այտուց և շոկ։ Շնչուղիները ներառող այրվածքները կարող են արագ առաջացնել շնչուղիների խցանում։ Կարևոր է փոխհատուցել հեղուկի կորուստը և կանխատեսել շարունակվող կորուստները։ Ն/ե հեղուկի անհրաժեշտ քանակը հաշվարկելու համար կարևոր է որոշել այրվածքի խորությունը և մարմնի մակերեսի տոկոսը (ՄՄՏ), որն այրված է։ Այրվածքային վնասվածքների դեպքում մի մոռացեք կատարել փայտացման դեմ պատվաստում և ցավազրկում։ Հանեք բոլոր զարդերը և հնարավորության դեպքում բարձրացրեք այրված վերջույթը։ Այրվածքների վարակման ռիսկը բարձր է, անգամ լավ խնամքի դեպքում։ Զգուշորեն մաքրեք և վիրակապեք վերքը։ ԱՅՐՎԱԾՔՆԵՐ, ՈՐՈՆՔ ՊԱՀԱՆՋՈՒՄ ԵՆ ԱՐԱԳ ՓՈԽԱՆՑՈՒՄ/ՀԱՆՁՆՈՒՄ. Մարմնի 15%-ից ավելի մակերեսի ծանր այրվածքներ (հաշվարկի համար տե՛ս ստորև նկարը) Ձեռքերը, դեմքը, աճուկային հատվածը, հոդերը ներառող այրվածքներ, կամ օղակող այրվածքներ Ինհալացիոն վնասվածք Այրվածքները կարող են առաջացնել շնչուղիների այտուց՝ ինհալացիոն վնասվածքների պատճառով Այրվածքներ՝ այլ ուղեկցող վնասվածքներով Ցանկացած այրվածք մանկահասակ կամ տարեց անձանց մոտ Այրվածքից առաջ առկա լուրջ հիվանդություն (օրինակ՝ շաքարային դիաբետ)"},{"id":"c-Falls","cat":"conditions","title":"Անկումներ","keywords":"Falls","html":"<p>Վայր ընկնելը, կամ անկումը մեծահասակների և երեխաների մոտ վնասվածքի տարածված պատճառ է։ Որքան մեծ է անկման բարձրությունը, այնքան ավելի է մեծանում լուրջ վնասվածք ստանալու հավանականությունը։ Բարձր ռիսկի մեխանիզմների շարքում են 3 մետրից ավելի բարձրությունից ընկնելը (կամ երեխաների դեպքում՝ իրենց հասակը երկու անգամ գերազանցող բարձրությունից)։ Մեծահասակների մոտ անկումը հաճախ կապված է լինում ավելի ծեր տարիքի, ալկոհոլային ինտոքսիկացիայի կամ աշխատավայրի սարքավորումների ու հարմարանքների, այդ թվում՝ լաստակների և սանդուղքների հետ կապված վթարների հետ։ Երեխաները հաճախ ընկնում են ծառերից, պատուհաններից կամ պատշգամբներից։</p>","text":"Վայր ընկնելը, կամ անկումը մեծահասակների և երեխաների մոտ վնասվածքի տարածված պատճառ է։ Որքան մեծ է անկման բարձրությունը, այնքան ավելի է մեծանում լուրջ վնասվածք ստանալու հավանականությունը։ Բարձր ռիսկի մեխանիզմների շարքում են 3 մետրից ավելի բարձրությունից ընկնելը (կամ երեխաների դեպքում՝ իրենց հասակը երկու անգամ գերազանցող բարձրությունից)։ Մեծահասակների մոտ անկումը հաճախ կապված է լինում ավելի ծեր տարիքի, ալկոհոլային ինտոքսիկացիայի կամ աշխատավայրի սարքավորումների ու հարմարանքների, այդ թվում՝ լաստակների և սանդուղքների հետ կապված վթարների հետ։ Երեխաները հաճախ ընկնում են ծառերից, պատուհաններից կամ պատշգամբներից։"},{"id":"c-Penetratingeyeinjury","cat":"conditions","title":"Աչքի ներթափանցող վնասվածք","keywords":"Penetrating eye injury","html":"<h3>Նշաններ և ախտանշաններ</h3><ul><li>Աչքում տեսանելի ցանկացած առարկա</li><li>Ցավոտ, կարմրած աչք կամ աչքում ինչ-որ բանի զգացողության հաղորդում. աչք ներթափանցած փոքր առարկաները կարող են դժվար նկատելի լինել</li><li>Տեսողության խնդիրներ</li><li>Աչքի բիբի ոչ բնորոշ ձևը կամ աչքից հոսող թափանցիկ հեղուկը կարող են վկայել ծակվածքային վերքի մասին</li><li>Դեմքի վնասվածքի նշաններ</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Խուսափեք վնասված աչքին ցանկացած ճնշում գործադրելուց. սա կարող է վատթարացնել վնասվածքը</li><li>Մի հեռացրեք աչք ներթափանցած առարկաները։</li><li><a href=\"#/p/m-Antibiotics\" class=\"xref\">Տվեք հակաբիոտիկներ։</a></li><li>Անհրաժեշտության դեպքում թարմացրեք <a href=\"#/p/m-Tetanusvaccination\" class=\"xref\">փայտացման դեմ պատվաստումը։</a></li><li>Գլուխը պահեք բարձրացված վիճակում և երկու աչքերի վրա դրեք չամրացված վիրակապ (աչքին ճնշում ՄԻ՛ գործադրեք)։</li><li>Պլանավորեք <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցում/հանձնում</a> մասնագիտացված սպասարկողի։</li></ul>","text":"Նշաններ և ախտանշաններ Աչքում տեսանելի ցանկացած առարկա Ցավոտ, կարմրած աչք կամ աչքում ինչ-որ բանի զգացողության հաղորդում. աչք ներթափանցած փոքր առարկաները կարող են դժվար նկատելի լինել Տեսողության խնդիրներ Աչքի բիբի ոչ բնորոշ ձևը կամ աչքից հոսող թափանցիկ հեղուկը կարող են վկայել ծակվածքային վերքի մասին Դեմքի վնասվածքի նշաններ Վարման հիմնական որոշումներ Խուսափեք վնասված աչքին ցանկացած ճնշում գործադրելուց. սա կարող է վատթարացնել վնասվածքը Մի հեռացրեք աչք ներթափանցած առարկաները։ Տվեք հակաբիոտիկներ։ Անհրաժեշտության դեպքում թարմացրեք փայտացման դեմ պատվաստումը։ Գլուխը պահեք բարձրացված վիճակում և երկու աչքերի վրա դրեք չամրացված վիրակապ (աչքին ճնշում ՄԻ՛ գործադրեք)։ Պլանավորեք փոխանցում/հանձնում մասնագիտացված սպասարկողի։"},{"id":"c-AsthmaCOPD","cat":"conditions","title":"Ասթմա/ԹՔՕՀ","keywords":"Asthma/COPD","html":"<p>Ասթման և ԹՔՕՀ-ն այնպիսի վիճակներ են, որոնք առաջացնում են լորձի արտադրություն և պարբերաբար կրկնվող սպազմ բրոնխային շնչուղիներում, ինչի հետևանքով շնչուղիները նեղանում են՝ առաջացնելով շնչելու դժվարություն և սուլոց։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Սուլոց</li><li>Հազ</li><li>Շնչառական մկանների լրացուցիչ մասնակցություն շնչառությանը</li><li>Եռոտանու դիրք</li><li>Կարող է ունենալ ասթմայի/ԹՔՕՀ-ի, ալերգիաների կամ ծխելու պատմություն</li><li>Հատուկ նկատառումներ՝ <a href=\"#/p/c-Respiratorydistresspaediatric\" class=\"xref\">մանկահասակ հիվանդների շնչառական խանգարումների վերաբերյալ. </a></li><li>Քթանցքերի եզրերի լայնացումը, գլխի վերև-ներքև շարժումը, հևոցը և կրծքավանդակի ներքաշումը ԿԱՄ ետքաշումները երեխաների մոտ շնչառական խանգարման նշաններ են։</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Հնարավորինս արագ տվեք <a href=\"#/p/m-Salbutamol_albuterol_\" class=\"xref\">սալբուտամոլ։</a> (Սալբուտամոլն օգնում է թուլացնել շնչուղիների սպազմը)</li><li><a href=\"#/p/s-Giveoxygen\" class=\"xref\">Տվեք թթվածին,</a> եթե ցուցված է։</li></ul>","text":"Ասթման և ԹՔՕՀ-ն այնպիսի վիճակներ են, որոնք առաջացնում են լորձի արտադրություն և պարբերաբար կրկնվող սպազմ բրոնխային շնչուղիներում, ինչի հետևանքով շնչուղիները նեղանում են՝ առաջացնելով շնչելու դժվարություն և սուլոց։ Նշաններ և ախտանշաններ Սուլոց Հազ Շնչառական մկանների լրացուցիչ մասնակցություն շնչառությանը Եռոտանու դիրք Կարող է ունենալ ասթմայի/ԹՔՕՀ-ի, ալերգիաների կամ ծխելու պատմություն Հատուկ նկատառումներ՝ մանկահասակ հիվանդների շնչառական խանգարումների վերաբերյալ. Քթանցքերի եզրերի լայնացումը, գլխի վերև-ներքև շարժումը, հևոցը և կրծքավանդակի ներքաշումը ԿԱՄ ետքաշումները երեխաների մոտ շնչառական խանգարման նշաններ են։ Վարման հիմնական որոշումներ Հնարավորինս արագ տվեք սալբուտամոլ։ (Սալբուտամոլն օգնում է թուլացնել շնչուղիների սպազմը) Տվեք թթվածին, եթե ցուցված է։"},{"id":"c-Haemorrhage","cat":"conditions","title":"Արյունահոսություն","keywords":"Haemorrhage","html":"<p>Արյունահոսությունը արյան ծանր կորուստ է։ Չվերահսկվող արտաքին արյունահոսությունը կարող է արագ հանգեցնել հիպովոլեմիկ շոկի։ Արյան մեծ քանակություն կարող է կորչել նաև կրծքավանդակում, կոնքում, ազդրում և որովայնում՝ նախքան արյունահոսությունը նկատելը։ Հիվանդների համար սովորաբար բավական դժվար է գնահատել արյան կորստի ծավալը, սակայն օգտակար կարող է լինել իմանալ, թե որքան ժամանակ է շարունակվում արյունահոսությունը, քանի վիրակապ է թրջվել, և արյունահոսությունն ուժեղանում է, թե՞ թուլանում։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Հիպովոլեմիկ շոկի մեջ գտնվող մեծահասակ հիվանդի մոտ կարող են լինել միայն տախիկարդիա (սրտի կծկումների արագացում) և/կամ տախիպնոէ (շնչառության արագացում), և արյան ճնշման անկում կարող է չլինել՝ մինչև վիճակը դառնա անմիջապես կյանքին սպառնացող։</li><li>Նույնիսկ երբ սիստոլիկ զարկերակային ճնշումը 90 մմ ս.ս.-ից բարձր է, կասկածեք հիպովոլեմիկ շոկի, եթե առկա է ծանր արյունահոսություն կամ թույլ պերֆուզիայի որևէ նշան (ինչպիսիք են սառը, խոնավ կամ գունատ մաշկը, մազանոթների դանդաղ վերալցումը, արագացած շնչառությունը, շփոթվածությունը, անհանգստությունը, տագնապը)։</li><li>ՀԻՇԵ՛Ք. Երեխաները և երիտասարդները կարող են պահպանել արյան նորմալ ճնշումը, քանի դեռ չեն կորցրել իրենց արյան ընդհանուր ծավալի մեկ քառորդը։ Միշտ ստուգեք շոկի այլ նշանների առկայությունը։</li><li>Արյունահոսող վերքեր</li><li>Պորտի շուրջ կամ որովայնի կողմնային շրջանում կապտուկները կարող են վկայել ներքին արյունահոսության մասին</li><li>Արյունահոսություն ուղիղ աղիքից կամ արյան առկայություն փսխուքում</li><li>Ստամոքսում և/կամ աղիքներում արյունահոսությունը կարող է ծանր լինել՝ նախքան այն նկատելը։ Մարդը կարող է կորցնել իր արյան ծավալի զգալի մասը աղիքներում։ Արյունը և՛ փսխուքում, և՛ կղանքում կարող է ունենալ սև գույն։</li><li>Արյունահոսություն հեշտոցից</li><li>Ծննդաբերությունից հետո արյան կորուստը կարող է ծանր լինել, եթե արգանդը լավ չի կծկվում։ Թաքնված արյան կորուստը, որը հանգեցնում է շոկի, կարող է առաջանալ արտարգանդային հղիության պատռման դեպքում, նույնիսկ այն կանանց մոտ, ովքեր չգիտեն, որ հղի են։ Վերարտադրողական տարիքի ցանկացած կին, ով գտնվում է շոկի մեջ, պետք է հետազոտվի հղիության առկայության համար։</li><li>Կոնքի կոտրվածք</li><li>Ազդրոսկրի կոտրվածք</li><li><a href=\"#/p/c-Haemothoraxpleuraleffusion\" class=\"xref\">Թուլացած շնչառական ձայներ կրծքավանդակի մի կողմում (հեմոթորաքս)</a></li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li><a href=\"#/p/s-Externalbleedingcontrol\" class=\"xref\">Դադարեցրեք արյունահոսությունը։</a> Կախված աղբյուրից՝ կիրառեք.</li><li>անմիջական ճնշում</li><li>խորը վերքի տամպոնավորում, եթե վերքը լայն բացվածքով է</li><li>լարան (լարանը պետք է կիրառել միայն կյանքին սպառնացող արյունահոսության դեպքում)</li><li><a href=\"#/p/s-Pelvicbinderapplication\" class=\"xref\">կոնքի գոտևորող կապ</a></li><li><a href=\"#/p/s-Fractureimmobilization\" class=\"xref\">ազդրոսկրի բեկակալ</a></li><li><a href=\"#/p/s-PlaceIV\" class=\"xref\">Տեղադրեք երկու մեծ տրամաչափի ն/ե կատետր</a> և տվեք ն/ե հեղուկներ։</li><li>Մեծ հեմոթորաքսի կամ այլ ներքին արյունահոսության կասկածի դեպքում հիվանդներին անհրաժեշտ կլինի արագ <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցում/հանձնում</a> այնպիսի բաժանմունք, որտեղ հնարավոր են վիրաբուժական խնամք և արյան փոխներարկում։</li></ul><p>ՀԻՇԵ՛Ք. Արյան մակարդման վրա ազդող դեղերը (օրինակ՝ ասպիրին, վարֆարին, կլոպիդոգրել) կարող են դժվարացնել արյունահոսության վերահսկումը և մեծացնել ուշացած արյունահոսության ռիսկը։ Արյան ճնշումը նվազեցնող դեղերը կարող են դժվարացնել շոկի վարումը։ Հնարավորության դեպքում ստացեք հիվանդի ընդունած դեղերի ամբողջական ցանկը կամ խնդրեք ընտանիքի անդամներին բերել դեղերը։</p>","text":"Արյունահոսությունը արյան ծանր կորուստ է։ Չվերահսկվող արտաքին արյունահոսությունը կարող է արագ հանգեցնել հիպովոլեմիկ շոկի։ Արյան մեծ քանակություն կարող է կորչել նաև կրծքավանդակում, կոնքում, ազդրում և որովայնում՝ նախքան արյունահոսությունը նկատելը։ Հիվանդների համար սովորաբար բավական դժվար է գնահատել արյան կորստի ծավալը, սակայն օգտակար կարող է լինել իմանալ, թե որքան ժամանակ է շարունակվում արյունահոսությունը, քանի վիրակապ է թրջվել, և արյունահոսությունն ուժեղանում է, թե՞ թուլանում։ Նշաններ և ախտանշաններ Հիպովոլեմիկ շոկի մեջ գտնվող մեծահասակ հիվանդի մոտ կարող են լինել միայն տախիկարդիա (սրտի կծկումների արագացում) և/կամ տախիպնոէ (շնչառության արագացում), և արյան ճնշման անկում կարող է չլինել՝ մինչև վիճակը դառնա անմիջապես կյանքին սպառնացող։ Նույնիսկ երբ սիստոլիկ զարկերակային ճնշումը 90 մմ ս.ս.-ից բարձր է, կասկածեք հիպովոլեմիկ շոկի, եթե առկա է ծանր արյունահոսություն կամ թույլ պերֆուզիայի որևէ նշան (ինչպիսիք են սառը, խոնավ կամ գունատ մաշկը, մազանոթների դանդաղ վերալցումը, արագացած շնչառությունը, շփոթվածությունը, անհանգստությունը, տագնապը)։ ՀԻՇԵ՛Ք. Երեխաները և երիտասարդները կարող են պահպանել արյան նորմալ ճնշումը, քանի դեռ չեն կորցրել իրենց արյան ընդհանուր ծավալի մեկ քառորդը։ Միշտ ստուգեք շոկի այլ նշանների առկայությունը։ Արյունահոսող վերքեր Պորտի շուրջ կամ որովայնի կողմնային շրջանում կապտուկները կարող են վկայել ներքին արյունահոսության մասին Արյունահոսություն ուղիղ աղիքից կամ արյան առկայություն փսխուքում Ստամոքսում և/կամ աղիքներում արյունահոսությունը կարող է ծանր լինել՝ նախքան այն նկատելը։ Մարդը կարող է կորցնել իր արյան ծավալի զգալի մասը աղիքներում։ Արյունը և՛ փսխուքում, և՛ կղանքում կարող է ունենալ սև գույն։ Արյունահոսություն հեշտոցից Ծննդաբերությունից հետո արյան կորուստը կարող է ծանր լինել, եթե արգանդը լավ չի կծկվում։ Թաքնված արյան կորուստը, որը հանգեցնում է շոկի, կարող է առաջանալ արտարգանդային հղիության պատռման դեպքում, նույնիսկ այն կանանց մոտ, ովքեր չգիտեն, որ հղի են։ Վերարտադրողական տարիքի ցանկացած կին, ով գտնվում է շոկի մեջ, պետք է հետազոտվի հղիության առկայության համար։ Կոնքի կոտրվածք Ազդրոսկրի կոտրվածք Թուլացած շնչառական ձայներ կրծքավանդակի մի կողմում (հեմոթորաքս) Վարման հիմնական որոշումներ Դադարեցրեք արյունահոսությունը։ Կախված աղբյուրից՝ կիրառեք. անմիջական ճնշում խորը վերքի տամպոնավորում, եթե վերքը լայն բացվածքով է լարան (լարանը պետք է կիրառել միայն կյանքին սպառնացող արյունահոսության դեպքում) կոնքի գոտևորող կապ ազդրոսկրի բեկակալ Տեղադրեք երկու մեծ տրամաչափի ն/ե կատետր և տվեք ն/ե հեղուկներ։ Մեծ հեմոթորաքսի կամ այլ ներքին արյունահոսության կասկածի դեպքում հիվանդներին անհրաժեշտ կլինի արագ փոխանցում/հանձնում այնպիսի բաժանմունք, որտեղ հնարավոր են վիրաբուժական խնամք և արյան փոխներարկում։ ՀԻՇԵ՛Ք. Արյան մակարդման վրա ազդող դեղերը (օրինակ՝ ասպիրին, վարֆարին, կլոպիդոգրել) կարող են դժվարացնել արյունահոսության վերահսկումը և մեծացնել ուշացած արյունահոսության ռիսկը։ Արյան ճնշումը նվազեցնող դեղերը կարող են դժվարացնել շոկի վարումը։ Հնարավորության դեպքում ստացեք հիվանդի ընդունած դեղերի ամբողջական ցանկը կամ խնդրեք ընտանիքի անդամներին բերել դեղերը։"},{"id":"c-HaemorrhageSevereBleeding","cat":"conditions","title":"Արյունահոսություն (ծանր արյունահոսություն)","keywords":"Haemorrhage (Severe Bleeding)","html":"<p>Չվերահսկվող արտաքին արյունահոսությունը կարող է արագ հանգեցնել հիպովոլեմիկ շոկի։ Արյան մեծ քանակություն կարող է կորչել նաև կրծքավանդակում, կոնքում, ազդրում և որովայնում՝ նախքան արյունահոսությունը նկատելը։ Հիվանդների համար սովորաբար բավական դժվար է գնահատել արյան կորստի ծավալը, սակայն օգտակար կարող է լինել իմանալ, թե որքան ժամանակ է շարունակվում արյունահոսությունը, քանի վիրակապ է թրջվել, և արյունահոսությունն ուժեղանում է, թե՞ թուլանում։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Թույլ պերֆուզիայի նշաններ (ինչպիսիք են հիպոտենզիան, տախիկարդիան, գունատ մաշկը, դիաֆորեզը)</li><li>Հիպովոլեմիկ շոկի մեջ գտնվող մեծահասակ հիվանդի մոտ կարող են լինել միայն տախիկարդիա (սրտի կծկումների արագացում) և/կամ տախիպնոէ (շնչառության արագացում),մինչդեռ արյան ճնշման անկում կարող է չլինել՝ մինչև վիճակը դառնա անմիջապես կյանքին սպառնացող։</li><li>Նույնիսկ երբ սիստոլիկ զարկերակային ճնշումը 90 մմ ս.ս.-ից բարձր է, կասկածեք հիպովոլեմիկ շոկի, եթե առկա է ծանր արյունահոսություն կամ թույլ պերֆուզիայի որևէ նշան (ինչպիսիք են սառը, խոնավ կամ գունատ մաշկը, մազանոթների դանդաղ վերալցումը, արագացած շնչառությունը, շփոթվածությունը, անհանգստությունը, տագնապը)։</li><li>ՀԻՇԵ՛Ք. Երեխաները և երիտասարդները կարող են պահպանել արյան նորմալ ճնշումը, քանի դեռ չեն կորցրել իրենց արյան ընդհանուր ծավալի մեկ քառորդը։ Միշտ ստուգեք շոկի այլ նշանների առկայությունը։</li><li>Արյունահոսող վերքեր</li><li>Պորտի շուրջ կամ որովայնի կողմնային շրջանում կապտուկները կարող են վկայել ներքին արյունահոսության մասին</li><li>Արյունահոսություն ուղիղ աղիքից կամ արյան առկայություն փսխուքում</li><li>Ստամոքսում և/կամ աղիքներում արյունահոսությունը կարող է ծանր լինել՝ նախքան այն նկատելը։ Մարդը կարող է կորցնել իր արյան ծավալի զգալի մասը աղիքներում։ Արյունը և՛ փսխուքում, և՛ կղանքում կարող է ունենալ սև գույն։</li><li>Արյունահոսություն հեշտոցից</li><li>Ծննդաբերությունից հետո արյան կորուստը կարող է ծանր լինել, եթե արգանդը լավ չի կծկվում։ Թաքնված արյան կորուստը, որը հանգեցնում է շոկի, կարող է առաջանալ արտարգանդային հղիության պատռման դեպքում, նույնիսկ այն կանանց մոտ, ովքեր չգիտեն, որ հղի են։ Վերարտադրողական տարիքի ցանկացած կին, ով գտնվում է շոկի մեջ, պետք է հետազոտվի հղիության առկայության համար։</li><li>Կոնքի կոտրվածք</li><li>Ազդրոսկրի կոտրվածք</li><li><a href=\"#/p/c-Haemothoraxpleuraleffusion\" class=\"xref\">Թուլացած շնչառական ձայներ կրծքավանդակի մի կողմում (հեմոթորաքս)</a></li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li><a href=\"#/p/s-Externalbleedingcontrol\" class=\"xref\">Դադարեցրեք արյունահոսությունը։</a> Կախված աղբյուրից՝ կիրառեք.</li><li>անմիջական ճնշում</li><li>խորը վերքի տամպոնավորում, եթե վերքը լայն բացվածքով է</li><li>լարան (լարանը պետք է կիրառել միայն կյանքին սպառնացող արյունահոսության դեպքում)</li><li><a href=\"#/p/s-Pelvicbinderapplication\" class=\"xref\">կոնքի գոտևորող կապ</a></li><li><a href=\"#/p/s-Fractureimmobilization\" class=\"xref\">ազդրոսկրի բեկակալ</a></li><li><a href=\"#/p/s-PlaceIV\" class=\"xref\">Տեղադրեք երկու մեծ տրամաչափի ն/ե կատետր</a> և <a href=\"#/p/s-IVFluidAdministrationAdult\" class=\"xref\">տվեք ն/ե հեղուկներ։</a></li><li>Մեծ հեմոթորաքսի կամ այլ ներքին արյունահոսության կասկածի դեպքում հիվանդներին անհրաժեշտ կլինի արագ <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցում/հանձնում</a> այնպիսի բաժանմունք, որտեղ հնարավոր են վիրաբուժական խնամք և արյան փոխներարկում։</li></ul><p>ՀԻՇԵ՛Ք. Արյան մակարդման վրա ազդող դեղերը (օրինակ՝ ասպիրին, վարֆարին, կլոպիդոգրել) կարող են դժվարացնել արյունահոսության վերահսկումը և մեծացնել ուշացած արյունահոսության ռիսկը։ Արյան ճնշումը նվազեցնող դեղերը կարող են դժվարացնել շոկի վարումը։ Հնարավորության դեպքում ստացեք հիվանդի ընդունած դեղերի ամբողջական ցանկը կամ խնդրեք ընտանիքի անդամներին բերել դեղերը։</p>","text":"Չվերահսկվող արտաքին արյունահոսությունը կարող է արագ հանգեցնել հիպովոլեմիկ շոկի։ Արյան մեծ քանակություն կարող է կորչել նաև կրծքավանդակում, կոնքում, ազդրում և որովայնում՝ նախքան արյունահոսությունը նկատելը։ Հիվանդների համար սովորաբար բավական դժվար է գնահատել արյան կորստի ծավալը, սակայն օգտակար կարող է լինել իմանալ, թե որքան ժամանակ է շարունակվում արյունահոսությունը, քանի վիրակապ է թրջվել, և արյունահոսությունն ուժեղանում է, թե՞ թուլանում։ Նշաններ և ախտանշաններ Թույլ պերֆուզիայի նշաններ (ինչպիսիք են հիպոտենզիան, տախիկարդիան, գունատ մաշկը, դիաֆորեզը) Հիպովոլեմիկ շոկի մեջ գտնվող մեծահասակ հիվանդի մոտ կարող են լինել միայն տախիկարդիա (սրտի կծկումների արագացում) և/կամ տախիպնոէ (շնչառության արագացում),մինչդեռ արյան ճնշման անկում կարող է չլինել՝ մինչև վիճակը դառնա անմիջապես կյանքին սպառնացող։ Նույնիսկ երբ սիստոլիկ զարկերակային ճնշումը 90 մմ ս.ս.-ից բարձր է, կասկածեք հիպովոլեմիկ շոկի, եթե առկա է ծանր արյունահոսություն կամ թույլ պերֆուզիայի որևէ նշան (ինչպիսիք են սառը, խոնավ կամ գունատ մաշկը, մազանոթների դանդաղ վերալցումը, արագացած շնչառությունը, շփոթվածությունը, անհանգստությունը, տագնապը)։ ՀԻՇԵ՛Ք. Երեխաները և երիտասարդները կարող են պահպանել արյան նորմալ ճնշումը, քանի դեռ չեն կորցրել իրենց արյան ընդհանուր ծավալի մեկ քառորդը։ Միշտ ստուգեք շոկի այլ նշանների առկայությունը։ Արյունահոսող վերքեր Պորտի շուրջ կամ որովայնի կողմնային շրջանում կապտուկները կարող են վկայել ներքին արյունահոսության մասին Արյունահոսություն ուղիղ աղիքից կամ արյան առկայություն փսխուքում Ստամոքսում և/կամ աղիքներում արյունահոսությունը կարող է ծանր լինել՝ նախքան այն նկատելը։ Մարդը կարող է կորցնել իր արյան ծավալի զգալի մասը աղիքներում։ Արյունը և՛ փսխուքում, և՛ կղանքում կարող է ունենալ սև գույն։ Արյունահոսություն հեշտոցից Ծննդաբերությունից հետո արյան կորուստը կարող է ծանր լինել, եթե արգանդը լավ չի կծկվում։ Թաքնված արյան կորուստը, որը հանգեցնում է շոկի, կարող է առաջանալ արտարգանդային հղիության պատռման դեպքում, նույնիսկ այն կանանց մոտ, ովքեր չգիտեն, որ հղի են։ Վերարտադրողական տարիքի ցանկացած կին, ով գտնվում է շոկի մեջ, պետք է հետազոտվի հղիության առկայության համար։ Կոնքի կոտրվածք Ազդրոսկրի կոտրվածք Թուլացած շնչառական ձայներ կրծքավանդակի մի կողմում (հեմոթորաքս) Վարման հիմնական որոշումներ Դադարեցրեք արյունահոսությունը։ Կախված աղբյուրից՝ կիրառեք. անմիջական ճնշում խորը վերքի տամպոնավորում, եթե վերքը լայն բացվածքով է լարան (լարանը պետք է կիրառել միայն կյանքին սպառնացող արյունահոսության դեպքում) կոնքի գոտևորող կապ ազդրոսկրի բեկակալ Տեղադրեք երկու մեծ տրամաչափի ն/ե կատետր և տվեք ն/ե հեղուկներ։ Մեծ հեմոթորաքսի կամ այլ ներքին արյունահոսության կասկածի դեպքում հիվանդներին անհրաժեշտ կլինի արագ փոխանցում/հանձնում այնպիսի բաժանմունք, որտեղ հնարավոր են վիրաբուժական խնամք և արյան փոխներարկում։ ՀԻՇԵ՛Ք. Արյան մակարդման վրա ազդող դեղերը (օրինակ՝ ասպիրին, վարֆարին, կլոպիդոգրել) կարող են դժվարացնել արյունահոսության վերահսկումը և մեծացնել ուշացած արյունահոսության ռիսկը։ Արյան ճնշումը նվազեցնող դեղերը կարող են դժվարացնել շոկի վարումը։ Հնարավորության դեպքում ստացեք հիվանդի ընդունած դեղերի ամբողջական ցանկը կամ խնդրեք ընտանիքի անդամներին բերել դեղերը։"},{"id":"c-Opioidoverdose","cat":"conditions","title":"Ափիոնային գերդոզավորում","keywords":"Opioid Overdose","html":"<p>Ափիոնային դեղորայքը (ինչպես օրինակ՝ մորֆինը, պետիդինը և հերոինը) կարող է նվազեցնել օրգանիզմի շնչառական մղումը։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Գիտակցության փոփոխություն</li><li>Շնչառության ցածր հաճախականություն</li><li>Թթվածնաքաղց</li><li>Շատ նեղացած բիբեր</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Տվեք <a href=\"#/p/m-Naloxone\" class=\"xref\">նալոքսոն՝</a> ափիոնային ազդեցությանը հակազդելու համար։</li><li>Նալոքսոնի ազդեցությունը տևում է մոտավորապես 1 ժամ։ Ափիոնների մեծ մասի ազդեցությունը տևում է ավելի երկար, ուստի հիվանդին կարող է անհրաժեշտ լինել նալոքսոնի կրկնակի դեղաչափ։ Սա հաշվի առեք շարունակական խնամքը պլանավորելիս և հաճախակի վերագնահատեք հիվանդի վիճակը։</li><li><a href=\"#/p/s-Giveoxygen\" class=\"xref\">Տվեք թթվածին։</a></li><li>Անհրաժեշտության դեպքում աջակցեք շնչառությանը՝ <a href=\"#/p/s-BagValveMaskVentilation\" class=\"xref\">տոպրակ-փական-դիմակով (ՏՓԴ)։</a></li></ul>","text":"Ափիոնային դեղորայքը (ինչպես օրինակ՝ մորֆինը, պետիդինը և հերոինը) կարող է նվազեցնել օրգանիզմի շնչառական մղումը։ Նշաններ և ախտանշաններ Գիտակցության փոփոխություն Շնչառության ցածր հաճախականություն Թթվածնաքաղց Շատ նեղացած բիբեր Վարման հիմնական որոշումներ Տվեք նալոքսոն՝ ափիոնային ազդեցությանը հակազդելու համար։ Նալոքսոնի ազդեցությունը տևում է մոտավորապես 1 ժամ։ Ափիոնների մեծ մասի ազդեցությունը տևում է ավելի երկար, ուստի հիվանդին կարող է անհրաժեշտ լինել նալոքսոնի կրկնակի դեղաչափ։ Սա հաշվի առեք շարունակական խնամքը պլանավորելիս և հաճախակի վերագնահատեք հիվանդի վիճակը։ Տվեք թթվածին։ Անհրաժեշտության դեպքում աջակցեք շնչառությանը՝ տոպրակ-փական-դիմակով (ՏՓԴ)։"},{"id":"c-Increasedpressureonthebrain","cat":"conditions","title":"Բարձր ներգանգային ճնշում","keywords":"Increased pressure on the brain","html":"<p>Գանգուղեղի վրա ճնշման բարձրացումը կարող է առաջանալ վնասվածքից, ուռուցքներից, ավելացած հեղուկից, արյունահոսությունից կամ վարակիչ հիվանդություններից։ Քանի որ գանգը կարծր է, ցանկացած այտուցվածություն, հեղուկ, կամ այլ զանգված բարձրացնում է ուղեղի վրա ճնշումը, սահմանափակելով արյան հոսքը և վնասելով ուղեղի հյուսվածքները՝ պատճառելով մահ։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Գլխացավ</li><li>Նոպաներ/ցնցումներ</li><li>Սրտխառնոց/փսխում</li><li>Գիտակցության փոփոխություն</li><li>Անհավասար բիբեր</li><li>Թուլություն մարմնի մի կողմում</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Մահճակալի գլուխը բարձրացրեք 30 աստիճանով, եթե վնասվածքի կասկած չկա և հիվանդը չունի հիպոտենզիա։</li><li>Ստուգեք գլյուկոզայի մակարդակը։</li><li>Ցնցումների/նոպաների առկայության դեպքում տվեք <a href=\"#/p/m-Benzodiazepines_diazepam_\" class=\"xref\">բենզոդիազեպին, օրինակ՝ </a><a href=\"#/p/m-Benzodiazepines_diazepam_\" class=\"xref\">դիազեպամ։</a></li><li>Ճնշումը պետք է իջեցնել հնարավորինս արագ։ Կազմակերպեք հիվանդի շուտափույթ <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցումը/հանձնումը</a> վիրաբուժական կենտրոն։</li></ul>","text":"Գանգուղեղի վրա ճնշման բարձրացումը կարող է առաջանալ վնասվածքից, ուռուցքներից, ավելացած հեղուկից, արյունահոսությունից կամ վարակիչ հիվանդություններից։ Քանի որ գանգը կարծր է, ցանկացած այտուցվածություն, հեղուկ, կամ այլ զանգված բարձրացնում է ուղեղի վրա ճնշումը, սահմանափակելով արյան հոսքը և վնասելով ուղեղի հյուսվածքները՝ պատճառելով մահ։ Նշաններ և ախտանշաններ Գլխացավ Նոպաներ/ցնցումներ Սրտխառնոց/փսխում Գիտակցության փոփոխություն Անհավասար բիբեր Թուլություն մարմնի մի կողմում Վարման հիմնական որոշումներ Մահճակալի գլուխը բարձրացրեք 30 աստիճանով, եթե վնասվածքի կասկած չկա և հիվանդը չունի հիպոտենզիա։ Ստուգեք գլյուկոզայի մակարդակը։ Ցնցումների/նոպաների առկայության դեպքում տվեք բենզոդիազեպին, օրինակ՝ դիազեպամ։ Ճնշումը պետք է իջեցնել հնարավորինս արագ։ Կազմակերպեք հիվանդի շուտափույթ փոխանցումը/հանձնումը վիրաբուժական կենտրոն։"},{"id":"c-Openfracture","cat":"conditions","title":"Բաց կոտրվածք","keywords":"Open fracture","html":"<p>Համարեք ցանկացած կոտրվածք բաց, եթե կոտրվածքի մոտ առկա է վերք (մաշկի քերծվածքից ավելի խորը)։ Բաց կոտրվածքները անհետաձգելի իրավիճակ են, քանի որ կարող են հանգեցնել ոսկրի ծանր վարակի։ Բաց կոտրվածքի հատվածը հաճախ կարող է աղտոտված լինել և պահանջել մաքրում, հնարավոր է՝ նաև վիրաբուժական խորը մաքրում՝ նախքան կոտրվածքի բուժումը։ Եթե կասկածվում է բաց կոտրվածք, բեկակալ դնելուց հետո պլանավորեք հանձնում/փոխանցում վիրաբուժական կամ օրթոպեդիկ բաժանմունք։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Ոսկրի դեֆորմացիա կամ կրեպիտացիա, որն ուղեկցվում է մաշկի վերքով</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Բեկակալ դնելուց առաջ տվեք ցավազրկող։</li><li><a href=\"#/p/s-Externalbleedingcontrol\" class=\"xref\">Արյունահոսությունը վերահսկեք անմիջական ճնշմամբ։</a></li><li>Անհապաղ ուղղեք (ռեդուկցիա) կոտրվածքը, եթե առկա է <a href=\"#/p/c-Extremityfracturewithpoorperfusion\" class=\"xref\">թույլ պերֆուզիա։</a></li><li>Հեռացրեք ցանկացած կեղտ և ողողեք վերքը 2 լիտր ֆիզիոլոգիական լուծույթով</li><li>Ծածկեք վերքը ֆիզիոլոգիական լուծույթով թրջված թանզիֆով</li><li>Տվեք <a href=\"#/p/m-Antibiotics\" class=\"xref\">հակաբիոտիկներ</a> և <a href=\"#/p/m-Tetanusvaccination\" class=\"xref\">փայտացման դեմ պատվաստում։</a></li><li><a href=\"#/p/s-Fractureimmobilization\" class=\"xref\">Բեկակալ դրեք վերքին։</a></li><li>Պլանավորեք <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցում/հանձնում</a> մասնագիտացված բաժանմունք։</li></ul>","text":"Համարեք ցանկացած կոտրվածք բաց, եթե կոտրվածքի մոտ առկա է վերք (մաշկի քերծվածքից ավելի խորը)։ Բաց կոտրվածքները անհետաձգելի իրավիճակ են, քանի որ կարող են հանգեցնել ոսկրի ծանր վարակի։ Բաց կոտրվածքի հատվածը հաճախ կարող է աղտոտված լինել և պահանջել մաքրում, հնարավոր է՝ նաև վիրաբուժական խորը մաքրում՝ նախքան կոտրվածքի բուժումը։ Եթե կասկածվում է բաց կոտրվածք, բեկակալ դնելուց հետո պլանավորեք հանձնում/փոխանցում վիրաբուժական կամ օրթոպեդիկ բաժանմունք։ Նշաններ և ախտանշաններ Ոսկրի դեֆորմացիա կամ կրեպիտացիա, որն ուղեկցվում է մաշկի վերքով Վարման հիմնական որոշումներ Բեկակալ դնելուց առաջ տվեք ցավազրկող։ Արյունահոսությունը վերահսկեք անմիջական ճնշմամբ։ Անհապաղ ուղղեք (ռեդուկցիա) կոտրվածքը, եթե առկա է թույլ պերֆուզիա։ Հեռացրեք ցանկացած կեղտ և ողողեք վերքը 2 լիտր ֆիզիոլոգիական լուծույթով Ծածկեք վերքը ֆիզիոլոգիական լուծույթով թրջված թանզիֆով Տվեք հակաբիոտիկներ և փայտացման դեմ պատվաստում։ Բեկակալ դրեք վերքին։ Պլանավորեք փոխանցում/հանձնում մասնագիտացված բաժանմունք։"},{"id":"c-Openpneumothorax","cat":"conditions","title":"Բաց պնևմոթորաքս (կրծքավանդակի ներծծող վերք)","keywords":"Open pneumothorax (sucking chest wound)","html":"<p>Կրծքավանդակի ներծծող վերքերը կարևոր է ճանաչել, քանի որ դրանք կարող են արագ լարված պնևմոթորաքս առաջացնել։ Ամեն անգամ, երբ հիվանդը ներշունչ է կատարում, օդը կրծքավանդակի պատի վերքի միջով մտնում է կրծքավանդակի խոռոչ (թոքերի և կրծքավանդակի պատի միջև գտնվող տարածություն)։ Եվ եթե օդը դուրս գալ չկարողանա՝ թոքի վրա ճնշումը կավելանա։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Կրծքավանդակի պատի բաց վերքի միջով անցնող օդի կլկլոց կամ «սուլոց» հիշեցնող ձայներ</li><li>Դժվարացած շնչառություն</li><li>Կրծքավանդակի ցավ</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li><a href=\"#/p/s-Giveoxygen\" class=\"xref\">Տվեք թթվածին։</a></li><li><a href=\"#/p/s-Suckingchestwoundmanagement\" class=\"xref\">Դրեք եռակողմ վիրակապ,</a> որը թույլ կտա օդի դուրս մղումը արտաշնչելիս և կկանխի օդի մուտքը ներշնչելիս։</li><li>Վտանգ կա, որ վիրակապը մակարդված արյան պատճառով կարող է կպչել կրծքավանդակի պատին՝ առաջացնելով լարված պնևմոթորաքս։</li><li>Եռակողմ վիրակապը դնելուց հետո հիվանդին պետք է անընդհատ վերահսկել։</li><li>Հեռացրեք վիրակապը՝ շնչառության կամ պերֆուզիայի վատթարացման նշաններ հայտնաբերելու դեպքում։</li><li>Պլանավորեք հիվանդի արագ <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցումը/հանձնումը</a> առավել բարձր կարգի սպասարկողի, որն ունակ է տեղադրել պլևրալ խողովակ կամ իրականացնել շնչուղիների և շնչառության առավել բարձր կարգի կառավարում։</li></ul>","text":"Կրծքավանդակի ներծծող վերքերը կարևոր է ճանաչել, քանի որ դրանք կարող են արագ լարված պնևմոթորաքս առաջացնել։ Ամեն անգամ, երբ հիվանդը ներշունչ է կատարում, օդը կրծքավանդակի պատի վերքի միջով մտնում է կրծքավանդակի խոռոչ (թոքերի և կրծքավանդակի պատի միջև գտնվող տարածություն)։ Եվ եթե օդը դուրս գալ չկարողանա՝ թոքի վրա ճնշումը կավելանա։ Նշաններ և ախտանշաններ Կրծքավանդակի պատի բաց վերքի միջով անցնող օդի կլկլոց կամ «սուլոց» հիշեցնող ձայներ Դժվարացած շնչառություն Կրծքավանդակի ցավ Վարման հիմնական որոշումներ Տվեք թթվածին։ Դրեք եռակողմ վիրակապ, որը թույլ կտա օդի դուրս մղումը արտաշնչելիս և կկանխի օդի մուտքը ներշնչելիս։ Վտանգ կա, որ վիրակապը մակարդված արյան պատճառով կարող է կպչել կրծքավանդակի պատին՝ առաջացնելով լարված պնևմոթորաքս։ Եռակողմ վիրակապը դնելուց հետո հիվանդին պետք է անընդհատ վերահսկել։ Հեռացրեք վիրակապը՝ շնչառության կամ պերֆուզիայի վատթարացման նշաններ հայտնաբերելու դեպքում։ Պլանավորեք հիվանդի արագ փոխանցումը/հանձնումը առավել բարձր կարգի սպասարկողի, որն ունակ է տեղադրել պլևրալ խողովակ կամ իրականացնել շնչուղիների և շնչառության առավել բարձր կարգի կառավարում։"},{"id":"c-Openwound","cat":"conditions","title":"Բաց վերք","keywords":"Open wound","html":"<p>Վերքի խնամքի նպատակն է արյունահոսությունը դադարեցնելը, վարակը կանխարգելելը, վնասվածքի տակ գտնվող հյուսվածքների վիճակը գնահատելը և առողջացմանն օգնելը։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Պատռվածք</li><li>Քերծվածք</li><li>Կծածներ</li><li>Թևատակերի, սեռական օրգանների, հետույքի կամ մեջքի շրջանում առկա վերքերը կարող են հեշտությամբ աննկատ մնալ</li><li>Արյան ցայտելը կամ շիթով հոսելը կարող է վկայել զարկերակային արյունահոսության մասին</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li><a href=\"#/p/s-Externalbleedingcontrol\" class=\"xref\">Դադարեցրեք արյունահոսությունը։</a></li><li>Հիմնովին մաքրեք վերքը օճառով և մաքուր ջրով կամ հականեխիչ միջոցով, հեռացրեք ցանկացած կեղտ, օտար մարմին կամ մեռուկացած/մահացող հյուսվածք։ (Նախքան վերքը մաքրելը տեղային անզգայացրում կատարեք, եթե ձեռքի տակ միջոցներ ունեք)։</li><li>Վիրակապեք վերքը մանրէազերծ թանզիֆով, եթե հասանելի է։</li><li>Ստուգեք պերֆուզիան (մազանոթների վերալցումը և/կամ ծայրամասային անոթազարկը) վերքից դեպի ծայրամաս՝ վիրակապելուց առաջ և հետո։</li><li><a href=\"#/p/s-Fractureimmobilization\" class=\"xref\">Մեծ պատռվածքներով վերջույթներին բեկակալ տեղադրեք՝ վերքի առողջացմանն օգնելու և ցավի վերահսկման նպատակով։</a></li><li>Ներթափանցած առարկաները կայունացրեք, սակայն մի հեռացրեք։</li><li><a href=\"#/p/c-Snakebite\" class=\"xref\">Օձի կծածի դեպքում անշարժացրեք վերջույթը։</a></li><li>Կենդանիների կծածների դեպքում խորհրդակցեք առավել բարձր կարգի սպասարկողի հետ՝ վարակման և կատաղության ռիսկերը գնահատելու համար։ Պատվաստման կարգավիճակից ելնելով՝ ժամանակի գործոնը կարող է լինել չափազանց կարևոր։</li><li>Անհրաժեշտության դեպքում տվեք <a href=\"#/p/m-Tetanusvaccination\" class=\"xref\">փայտացման դեմ պատվաստում։</a></li></ul>","text":"Վերքի խնամքի նպատակն է արյունահոսությունը դադարեցնելը, վարակը կանխարգելելը, վնասվածքի տակ գտնվող հյուսվածքների վիճակը գնահատելը և առողջացմանն օգնելը։ Նշաններ և ախտանշաններ Պատռվածք Քերծվածք Կծածներ Թևատակերի, սեռական օրգանների, հետույքի կամ մեջքի շրջանում առկա վերքերը կարող են հեշտությամբ աննկատ մնալ Արյան ցայտելը կամ շիթով հոսելը կարող է վկայել զարկերակային արյունահոսության մասին Վարման հիմնական որոշումներ Դադարեցրեք արյունահոսությունը։ Հիմնովին մաքրեք վերքը օճառով և մաքուր ջրով կամ հականեխիչ միջոցով, հեռացրեք ցանկացած կեղտ, օտար մարմին կամ մեռուկացած/մահացող հյուսվածք։ (Նախքան վերքը մաքրելը տեղային անզգայացրում կատարեք, եթե ձեռքի տակ միջոցներ ունեք)։ Վիրակապեք վերքը մանրէազերծ թանզիֆով, եթե հասանելի է։ Ստուգեք պերֆուզիան (մազանոթների վերալցումը և/կամ ծայրամասային անոթազարկը) վերքից դեպի ծայրամաս՝ վիրակապելուց առաջ և հետո։ Մեծ պատռվածքներով վերջույթներին բեկակալ տեղադրեք՝ վերքի առողջացմանն օգնելու և ցավի վերահսկման նպատակով։ Ներթափանցած առարկաները կայունացրեք, սակայն մի հեռացրեք։ Օձի կծածի դեպքում անշարժացրեք վերջույթը։ Կենդանիների կծածների դեպքում խորհրդակցեք առավել բարձր կարգի սպասարկողի հետ՝ վարակման և կատաղության ռիսկերը գնահատելու համար։ Պատվաստման կարգավիճակից ելնելով՝ ժամանակի գործոնը կարող է լինել չափազանց կարևոր։ Անհրաժեշտության դեպքում տվեք փայտացման դեմ պատվաստում։"},{"id":"c-HeadInjury","cat":"conditions","title":"Գլխի ծանր վնասվածք","keywords":"Severe Head Injury","html":"<p>Ուղեղի վնասվածքները կարող են տատանվել թեթև կապտուկից մինչև ուղեղում կամ նրա շուրջ առաջացած ծանր արյունահոսությունը։ Քանի որ գանգը կոշտ է, արյունահոսությունը չի կարող ընդարձակվել, որի պատճառով առաջացնում է <a href=\"#/p/c-Increasedpressureonthebrain\" class=\"xref\">ուղեղի վրա ճնշման ավելացում։</a> Եթե ճնշումը դառնում է չափազանց բարձր, այն կխոչընդոտի արյան մուտքը գանգի մեջ և ուղեղի պերֆուզիան, և կարող է ուղեղի մի հատվածը սեղմել գանգի հիմքով դուրս՝ հանգեցնելով մահվան։ Ուղեղի ցանկացած վնասվածք կարող է էական ազդեցություն ունենալ գործառույթի վրա։</p><p>Ուղեղում կամ նրա շուրջ արյունահոսությունը կարող է գիտակցության փոփոխություն առաջացնել վնասվածքից մի քանի օր անց։ Հիշեք, որ քրոնիկ ալկոհոլամոլները և տարեցներն ավելի հակված են ուղեղային արյունահոսության և կարող են չհիշել անկումը։ Միշտ դիտարկեք ուղեղի շուրջ դանդաղ արյունահոսությունը որպես հնարավոր պատճառ, նույնիսկ մի քանի օր անց, և դիտարկեք չգիտակցված վնասվածքի հավանականությունը այն հիվանդի մոտ, ով հայտնաբերվել է փոփոխված գիտակցությամբ՝ առանց հայտնի պատճառի։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Տեսողության փոփոխություններ</li><li>Հիշողության կորուստ</li><li>Նոպաներ/ցնցումներ</li><li>Փսխում</li><li>Գլխացավ</li><li>Գիտակցության փոփոխություն կամ այլ նյարդաբանական խանգարում</li><li>Գլխամաշկի վերք և/կամ գանգի դեֆորմացիա</li><li>Կապտուկներ գլխի վրա (հատկապես աչքերի շուրջ կամ ականջների հետևում)</li><li>Արյուն կամ հեղուկ ականջներից կամ քթից</li><li>Բիբերի անհավասարություն</li><li>Մարմնի մեկ կողմի թուլություն</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Միշտ հիշեք, որ գլխի վնասվածքները կարող են զուգակցվել ողնաշարի վնասվածքների հետ։ <a href=\"#/p/s-Spinalimmobilization\" class=\"xref\">Անշարժացրեք ողնաշարը և օգտագործեք «գերանի գլորում» մեթոդը՝ մարմնի մեջքային մասը զննելու համար։</a></li><li>Հիվանդի վիճակը գնահատելու և մշտադիտարկելու համար օգտագործեք <a href=\"#/p/s-GCSAVPU\" class=\"xref\">Գլազգոյի կոմայի սանդղակը (կամ AVPU-ն՝ երեխաների մոտ)։</a></li><li><a href=\"#/p/s-ABCDE\" class=\"xref\">Հաճախակի կրկնեք հիվանդի վիճակի գնահատումը՝ «ABCDE» սկզբունքով։</a></li><li>Եթե կասկածվում է գանգի բաց կոտրվածք, տվեք ն/ե <a href=\"#/p/m-Antibiotics\" class=\"xref\">հակաբիոտիկներ</a> տեղական գործելակարգի համաձայն։</li><li>Գլխի զգալի վնասվածքներ ունեցող ցանկացած հիվանդի մոտ կա նաև ողնաշարի վնասվածքի ռիսկ։</li><li>Միշտ ստուգեք գլյուկոզան և <a href=\"#/p/m-Glucose_dextrose_\" class=\"xref\">տվեք գլյուկոզա,</a> եթե <3,5 մմոլ/լ կամ հնարավոր չէ չափել։</li><li>Բերանով կերակուր կամ հեղուկ մի տվեք։</li><li>Միշտ հետևեք անշարժացված հիվանդների մոտ փսխման առաջացմանը՝ շնչահեղձությունից խուսափելու համար։</li><li>Պլանավորեք վաղ <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցում/հանձնում</a> մասնագիտացված բուժման հաստատություն։</li><li>ԳԿՍ-ի սանդղակով 9-ից ցածր ցուցանիծ ունեցող ցանկացած հիվանդ պետք է, հնարավորության դեպքում, փոխանցվի համակարգչային տոմոգրաֆիայի հետազոտության՝ վնասվածքից հետո 2 ժամվա ընթացքում։</li></ul><p>ՀԻՇԵ՛Ք. Հիվանդները, ովքեր սկզբում լավ տեսք ունեն, կարող են ունենալ թաքնված, կյանքին սպառնացող վնասվածքներ, ինչպիսին է ներքին արյունահոսությունը։ Շատ կարևոր է հաճախ կրկնել վնասվածքով հիվանդների գնահատումը՝ օգտագործելով առաջնային զննման սկղբունքները։ Երբ հայտնաբերում եք առաջնային զննման խնդիր և կարգավորում եք այն, վերադարձեք և նորից սկսեք առաջնային զննումը՝ նոր խնդիրներ հայտնաբերելու և համոզվելու, որ բուժումն արդյունավետ է եղել։ Լավագույն մոտեցումը <a href=\"#/p/s-ABCDE\" class=\"xref\">«ABCDE» մոտեցումով</a> հիվանդի գնահատումն է յուրաքանչյուր 15 րոպեն մեկ և վիճակի ցանկացած փոփոխության դեպքում։</p>","text":"Ուղեղի վնասվածքները կարող են տատանվել թեթև կապտուկից մինչև ուղեղում կամ նրա շուրջ առաջացած ծանր արյունահոսությունը։ Քանի որ գանգը կոշտ է, արյունահոսությունը չի կարող ընդարձակվել, որի պատճառով առաջացնում է ուղեղի վրա ճնշման ավելացում։ Եթե ճնշումը դառնում է չափազանց բարձր, այն կխոչընդոտի արյան մուտքը գանգի մեջ և ուղեղի պերֆուզիան, և կարող է ուղեղի մի հատվածը սեղմել գանգի հիմքով դուրս՝ հանգեցնելով մահվան։ Ուղեղի ցանկացած վնասվածք կարող է էական ազդեցություն ունենալ գործառույթի վրա։ Ուղեղում կամ նրա շուրջ արյունահոսությունը կարող է գիտակցության փոփոխություն առաջացնել վնասվածքից մի քանի օր անց։ Հիշեք, որ քրոնիկ ալկոհոլամոլները և տարեցներն ավելի հակված են ուղեղային արյունահոսության և կարող են չհիշել անկումը։ Միշտ դիտարկեք ուղեղի շուրջ դանդաղ արյունահոսությունը որպես հնարավոր պատճառ, նույնիսկ մի քանի օր անց, և դիտարկեք չգիտակցված վնասվածքի հավանականությունը այն հիվանդի մոտ, ով հայտնաբերվել է փոփոխված գիտակցությամբ՝ առանց հայտնի պատճառի։ Նշաններ և ախտանշաններ Տեսողության փոփոխություններ Հիշողության կորուստ Նոպաներ/ցնցումներ Փսխում Գլխացավ Գիտակցության փոփոխություն կամ այլ նյարդաբանական խանգարում Գլխամաշկի վերք և/կամ գանգի դեֆորմացիա Կապտուկներ գլխի վրա (հատկապես աչքերի շուրջ կամ ականջների հետևում) Արյուն կամ հեղուկ ականջներից կամ քթից Բիբերի անհավասարություն Մարմնի մեկ կողմի թուլություն Վարման հիմնական որոշումներ Միշտ հիշեք, որ գլխի վնասվածքները կարող են զուգակցվել ողնաշարի վնասվածքների հետ։ Անշարժացրեք ողնաշարը և օգտագործեք «գերանի գլորում» մեթոդը՝ մարմնի մեջքային մասը զննելու համար։ Հիվանդի վիճակը գնահատելու և մշտադիտարկելու համար օգտագործեք Գլազգոյի կոմայի սանդղակը (կամ AVPU-ն՝ երեխաների մոտ)։ Հաճախակի կրկնեք հիվանդի վիճակի գնահատումը՝ «ABCDE» սկզբունքով։ Եթե կասկածվում է գանգի բաց կոտրվածք, տվեք ն/ե հակաբիոտիկներ տեղական գործելակարգի համաձայն։ Գլխի զգալի վնասվածքներ ունեցող ցանկացած հիվանդի մոտ կա նաև ողնաշարի վնասվածքի ռիսկ։ Միշտ ստուգեք գլյուկոզան և տվեք գլյուկոզա, եթե <3,5 մմոլ/լ կամ հնարավոր չէ չափել։ Բերանով կերակուր կամ հեղուկ մի տվեք։ Միշտ հետևեք անշարժացված հիվանդների մոտ փսխման առաջացմանը՝ շնչահեղձությունից խուսափելու համար։ Պլանավորեք վաղ փոխանցում/հանձնում մասնագիտացված բուժման հաստատություն։ ԳԿՍ-ի սանդղակով 9-ից ցածր ցուցանիծ ունեցող ցանկացած հիվանդ պետք է, հնարավորության դեպքում, փոխանցվի համակարգչային տոմոգրաֆիայի հետազոտության՝ վնասվածքից հետո 2 ժամվա ընթացքում։ ՀԻՇԵ՛Ք. Հիվանդները, ովքեր սկզբում լավ տեսք ունեն, կարող են ունենալ թաքնված, կյանքին սպառնացող վնասվածքներ, ինչպիսին է ներքին արյունահոսությունը։ Շատ կարևոր է հաճախ կրկնել վնասվածքով հիվանդների գնահատումը՝ օգտագործելով առաջնային զննման սկղբունքները։ Երբ հայտնաբերում եք առաջնային զննման խնդիր և կարգավորում եք այն, վերադարձեք և նորից սկսեք առաջնային զննումը՝ նոր խնդիրներ հայտնաբերելու և համոզվելու, որ բուժումն արդյունավետ է եղել։ Լավագույն մոտեցումը «ABCDE» մոտեցումով հիվանդի գնահատումն է յուրաքանչյուր 15 րոպեն մեկ և վիճակի ցանկացած փոփոխության դեպքում։"},{"id":"c-Diabeticketoacidosis","cat":"conditions","title":"Դիաբետիկ կետոացիդոզ (ԴԿԱ)","keywords":"Diabetic ketoacidosis (DKA)","html":"<p>ԴԿԱ-ն վիճակ է, որը զարգանում է շաքարային դիաբետով հիվանդների մոտ, երբ ինսուլինի պակասը հանգեցնում է արյան շաքարի բարձրացման՝ բերելով ծանր ջրազրկման և արյան մեջ թթվի կուտակման։</p><p>Շաքարի բարձր մակարդակը կարող է հանգեցնել քիմիական անհավասարակշռության, որը օրգանիզմը փորձում է հաղթահարել ավելի արագ կամ խորը շնչառությամբ։ Հիվանդները կարող են նշել շնչառության դժվարացում։ Այս վիճակը կարող է նաև դրսևորվել քաղցր կամ «մրգային» հոտով շնչառությամբ։ Քանի որ արյան գլյուկոզայի բարձր մակարդակը առաջացնում է հաճախացած միզարձակում, կարող են զարգանալ ծանր ջրազրկում և <a href=\"#/p/c-Shock\" class=\"xref\">շոկ։</a></p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Հնարավոր է հայտնի շաքարային դիաբետի պատմություն</li><li>Հաճախացած կամ խորացած շնչառություն</li><li>Հաճախակի միզարձակում</li><li>Քաղցր հոտով շնչառություն</li><li>Արյան կամ մեզի մեջ գլյուկոզայի բարձր մակարդակ</li><li>Ջրազրկում</li><li>Գիտակցության փոփոխություն</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li><a href=\"#/p/s-PlaceIV\" class=\"xref\">Տվեք ն/ե հեղուկներ։</a></li><li>Դիաբետիկ կետոացիդոզով հիվանդը չափազանց ծանր վիճակում է և պահանջում է անհապաղ <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցում/հանձնում</a> այնպիսի մասնագիտացված սպասարկողի կամ բաժանմունք, որտեղ հնարավոր են ն/ե ինֆուզիա և մշտադիտարկում։</li></ul>","text":"ԴԿԱ-ն վիճակ է, որը զարգանում է շաքարային դիաբետով հիվանդների մոտ, երբ ինսուլինի պակասը հանգեցնում է արյան շաքարի բարձրացման՝ բերելով ծանր ջրազրկման և արյան մեջ թթվի կուտակման։ Շաքարի բարձր մակարդակը կարող է հանգեցնել քիմիական անհավասարակշռության, որը օրգանիզմը փորձում է հաղթահարել ավելի արագ կամ խորը շնչառությամբ։ Հիվանդները կարող են նշել շնչառության դժվարացում։ Այս վիճակը կարող է նաև դրսևորվել քաղցր կամ «մրգային» հոտով շնչառությամբ։ Քանի որ արյան գլյուկոզայի բարձր մակարդակը առաջացնում է հաճախացած միզարձակում, կարող են զարգանալ ծանր ջրազրկում և շոկ։ Նշաններ և ախտանշաններ Հնարավոր է հայտնի շաքարային դիաբետի պատմություն Հաճախացած կամ խորացած շնչառություն Հաճախակի միզարձակում Քաղցր հոտով շնչառություն Արյան կամ մեզի մեջ գլյուկոզայի բարձր մակարդակ Ջրազրկում Գիտակցության փոփոխություն Վարման հիմնական որոշումներ Տվեք ն/ե հեղուկներ։ Դիաբետիկ կետոացիդոզով հիվանդը չափազանց ծանր վիճակում է և պահանջում է անհապաղ փոխանցում/հանձնում այնպիսի մասնագիտացված սպասարկողի կամ բաժանմունք, որտեղ հնարավոր են ն/ե ինֆուզիա և մշտադիտարկում։"},{"id":"c-Facialfractures","cat":"conditions","title":"Դիմային ոսկորների կոտրվածքներ","keywords":"Facial fractures","html":"<h3>Նշաններ և ախտանշաններ</h3><ul><li>Ձևախախտումներ կամ դիմային ոսկորների անսովոր շարժունություն</li><li>Հիվանդը հայտնում է, որ չի կարողանում նորմալ փակել ծնոտը կամ ատամների դիրքը խախտված է</li><li>Աչքերի շարժումների խախտում</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Տվեք <a href=\"#/p/m-Antibiotics\" class=\"xref\">հակաբիոտիկներ՝</a> դիմային բաց կոտրվածքների դեպքում (պատռված վերքեր՝ կոտրված ոսկորի վրա)։</li><li><a href=\"#/p/m-Tetanusvaccination\" class=\"xref\">Թարմացրեք փայտացման դեմ պատվաստումը։</a></li><li>Կասկածեք ողնաշարի պարանոցի հատվածի վնասվածք և անհրաժեշտության դեպքում <a href=\"#/p/s-Spinalimmobilization\" class=\"xref\">անշարժացրեք պարանոցային հատվածը։</a></li><li>Հիշեք, որ հիվանդը պետք է այնպիսի դիրք ունենա, որի դեպքում արյունը չի հոսի շնչուղիներ։</li><li>Խուսափեք քիթ-ըմպանային օդուղիների և քիթ-ստամոքսային խողովակների օգտագործումից՝ դիմային ոսկորների կոտրվածքի կասկածի դեպքում։</li></ul>","text":"Նշաններ և ախտանշաններ Ձևախախտումներ կամ դիմային ոսկորների անսովոր շարժունություն Հիվանդը հայտնում է, որ չի կարողանում նորմալ փակել ծնոտը կամ ատամների դիրքը խախտված է Աչքերի շարժումների խախտում Վարման հիմնական որոշումներ Տվեք հակաբիոտիկներ՝ դիմային բաց կոտրվածքների դեպքում (պատռված վերքեր՝ կոտրված ոսկորի վրա)։ Թարմացրեք փայտացման դեմ պատվաստումը։ Կասկածեք ողնաշարի պարանոցի հատվածի վնասվածք և անհրաժեշտության դեպքում անշարժացրեք պարանոցային հատվածը։ Հիշեք, որ հիվանդը պետք է այնպիսի դիրք ունենա, որի դեպքում արյունը չի հոսի շնչուղիներ։ Խուսափեք քիթ-ըմպանային օդուղիների և քիթ-ստամոքսային խողովակների օգտագործումից՝ դիմային ոսկորների կոտրվածքի կասկածի դեպքում։"},{"id":"c-Malnourishment","cat":"conditions","title":"Թերսնուցում","keywords":"Malnourishment","html":"<p>Թերսնուցված երեխաների մոտ հիպոգլիկեմիայի ռիսկը բարձր է, և նրանց, բացի հեղուկներից, անհրաժեշտ է նաև շաքար։ Եթե հիվանդը թերսնուցված տեսք ունի, հեղուկները պետք է հարմարեցվեն։ Թերսնուցված երեխաների մոտ տարբեր են և՛ հեղուկի ներարկման արագությունը, և՛ հեղուկի տեսակը։ Հարցրեք քաշի վերջին փոփոխությունների մասին։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Տեսանելի հյուծվածություն. Երեխան ուժեղ թերսնուցման ժամանակ միայն պարզապես նիհար չի երևում։ Նա տեսանելի ոսկրոտ է, կարծես մաշկն անմիջապես ոսկրի վրա լինի, և այնպիսի տպավորություն է, թե ոսկորները մարմնի համեմատ չափազանց մեծ են։ Թևերը, ոտքերը և հետույքը կարող են նիհար լինել, իսկ գլուխը՝ մարմնի հյուծվածության պատճառով, կարող է համեմատաբար մեծ երևալ։</li><li>Մաշկը մարմնի համեմատ շատ և կախված տպավորություն է թողնում</li><li>Երեխայի վրա ճարպ չկա</li><li>Կողերի գծերը երևում են</li><li>Ձեռքերի, ոտքերի և հետույքի խորը հյուծվածություն</li><li>Գլուխը կարող է համեմատաբար մեծ երևալ՝ մարմնի հյուծվածության պատճառով (տես նկարը)</li><li>Երկու ոտքերի այտուց. Հանեք կոշիկները և գուլպաները և գնահատեք երկու ոտքերի այտուցը։ Ոտնաթաթի վերևի հատվածը մի քանի վայրկյան սեղմեք բութ մատով և տեսեք՝ արդյոք հյուսվածքում սեղմված հետքը մնում է, թե ոչ։ Հիշեք, որ ծանր թերսնուցում ունեցող երեխան կարող է այնքան էլ նիհար չերևալ, եթե առկա է շատ այտուց։</li><li>Բութ մատով թույլ սեղմեք ոտնաթաթի առջևից մի քանի վայրկյան։ Եթե մատը հեռացնելուց հետո սեղմված տեղը մնում է, ապա երեխայի մոտ առկա է այտուց</li><li>Կրկնեք նույնը մյուս ոտքին (տես նկարը)</li></ul><h3>Վարման հիմնական որոշումներ</h3><p>Ծանր թերսնուցման նշանների առկայության դեպքում անհրաժեշտ է կարգավորել հեղուկները։ Առկայության դեպքում տվեք մասնագիտացված հեղուկներ։</p><ul><li>Նախընտրելի է բերանային հեղուկը, եթե հիվանդը կարող է այն տանել։ Իրականացրեք բերանային ռեհիդրացիա \"ReSoMal\"-ով (բացառությամբ այն դեպքի, երբ երեխայի շոկը խոլերայի հետևանք է, այդ դեպքում օգտագործեք բերանային ռեհիդրատացիոն լուծույթներ - ԲՌԼ)։</li><li>Հատուկ հրահանգների համար տե՛ս <a href=\"#/p/s-IVFluidAdministrationChild\" class=\"xref\">«Ն/ե հեղուկի ներարկում. երեխա» բաժինը</a>։</li><li>Ավելացրե՛ք <a href=\"#/p/m-Glucose_dextrose_\" class=\"xref\">դեքստրոզա</a>՝ օգտագործեք հեղուկներ, որոնք պարունակում են դեքստրոզա, կամ տվեք դեքստրոզայի դեղաչափ՝ ն/ե հեղուկների հետ միասին։ Դանդաղեցրե՛ք հեղուկի ներարկման արագությունը։</li><li>Տվեք ավելի քիչ ն/ե հեղուկ՝ ավելի դանդաղ, և ստուգեք թոքերը խզզոցների համար (հեղուկային գերբեռնվածության նշան)՝ ամեն 5 րոպեն մեկ։</li><li>ԶԳՈՒՇԱՑՈՒՄ! Ներերակային հեղուկի ներարկումը կարող է վտանգավոր լինել թերսնուցված երեխաների մոտ։ Ցանկացած եղանակով հեղուկ տալիս՝ պետք է ամեն 5 րոպեն մեկ ստուգել հետևյալ վտանգի նշանները՝ նոր կամ վատթարացող դժվարացած շնչառություն (ԴՇ), շնչառության հաճախականության բարձրացում՝ րոպեում 5-ից ավելի, կամ սրտի կծկումների հաճախականության բարձրացում՝ րոպեում 15-ից ավելի զարկով։ Եթե զարգանում է որևէ վտանգի նշան, դադարեցրե՛ք հեղուկները։</li><li>Դադարեցրեք ն/ե հեղուկները, եթե զարգանում է հեղուկային գերբեռնվածություն (թոքերում խզզոցներ, շնչառության հաճախականության կամ սրտի կծկումների հաճախականության բարձրացում)։</li><li>Անցեք բերանային հեղուկների՝ հենց որ թույլ պերֆուզիայի նշանները բարելավվեն։</li><li>Այս հիվանդներին անհրաժեշտ է արագ <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցում/հանձնում</a> այնպիսի կենտրոնի առավել մասնագիտացված սպասարկողի, որտեղ հնարավոր է արյան փոխներարկում։</li></ul>","text":"Թերսնուցված երեխաների մոտ հիպոգլիկեմիայի ռիսկը բարձր է, և նրանց, բացի հեղուկներից, անհրաժեշտ է նաև շաքար։ Եթե հիվանդը թերսնուցված տեսք ունի, հեղուկները պետք է հարմարեցվեն։ Թերսնուցված երեխաների մոտ տարբեր են և՛ հեղուկի ներարկման արագությունը, և՛ հեղուկի տեսակը։ Հարցրեք քաշի վերջին փոփոխությունների մասին։ Նշաններ և ախտանշաններ Տեսանելի հյուծվածություն. Երեխան ուժեղ թերսնուցման ժամանակ միայն պարզապես նիհար չի երևում։ Նա տեսանելի ոսկրոտ է, կարծես մաշկն անմիջապես ոսկրի վրա լինի, և այնպիսի տպավորություն է, թե ոսկորները մարմնի համեմատ չափազանց մեծ են։ Թևերը, ոտքերը և հետույքը կարող են նիհար լինել, իսկ գլուխը՝ մարմնի հյուծվածության պատճառով, կարող է համեմատաբար մեծ երևալ։ Մաշկը մարմնի համեմատ շատ և կախված տպավորություն է թողնում Երեխայի վրա ճարպ չկա Կողերի գծերը երևում են Ձեռքերի, ոտքերի և հետույքի խորը հյուծվածություն Գլուխը կարող է համեմատաբար մեծ երևալ՝ մարմնի հյուծվածության պատճառով (տես նկարը) Երկու ոտքերի այտուց. Հանեք կոշիկները և գուլպաները և գնահատեք երկու ոտքերի այտուցը։ Ոտնաթաթի վերևի հատվածը մի քանի վայրկյան սեղմեք բութ մատով և տեսեք՝ արդյոք հյուսվածքում սեղմված հետքը մնում է, թե ոչ։ Հիշեք, որ ծանր թերսնուցում ունեցող երեխան կարող է այնքան էլ նիհար չերևալ, եթե առկա է շատ այտուց։ Բութ մատով թույլ սեղմեք ոտնաթաթի առջևից մի քանի վայրկյան։ Եթե մատը հեռացնելուց հետո սեղմված տեղը մնում է, ապա երեխայի մոտ առկա է այտուց Կրկնեք նույնը մյուս ոտքին (տես նկարը) Վարման հիմնական որոշումներ Ծանր թերսնուցման նշանների առկայության դեպքում անհրաժեշտ է կարգավորել հեղուկները։ Առկայության դեպքում տվեք մասնագիտացված հեղուկներ։ Նախընտրելի է բերանային հեղուկը, եթե հիվանդը կարող է այն տանել։ Իրականացրեք բերանային ռեհիդրացիա \"ReSoMal\"-ով (բացառությամբ այն դեպքի, երբ երեխայի շոկը խոլերայի հետևանք է, այդ դեպքում օգտագործեք բերանային ռեհիդրատացիոն լուծույթներ - ԲՌԼ)։ Հատուկ հրահանգների համար տե՛ս «Ն/ե հեղուկի ներարկում. երեխա» բաժինը։ Ավելացրե՛ք դեքստրոզա՝ օգտագործեք հեղուկներ, որոնք պարունակում են դեքստրոզա, կամ տվեք դեքստրոզայի դեղաչափ՝ ն/ե հեղուկների հետ միասին։ Դանդաղեցրե՛ք հեղուկի ներարկման արագությունը։ Տվեք ավելի քիչ ն/ե հեղուկ՝ ավելի դանդաղ, և ստուգեք թոքերը խզզոցների համար (հեղուկային գերբեռնվածության նշան)՝ ամեն 5 րոպեն մեկ։ ԶԳՈՒՇԱՑՈՒՄ! Ներերակային հեղուկի ներարկումը կարող է վտանգավոր լինել թերսնուցված երեխաների մոտ։ Ցանկացած եղանակով հեղուկ տալիս՝ պետք է ամեն 5 րոպեն մեկ ստուգել հետևյալ վտանգի նշանները՝ նոր կամ վատթարացող դժվարացած շնչառություն (ԴՇ), շնչառության հաճախականության բարձրացում՝ րոպեում 5-ից ավելի, կամ սրտի կծկումների հաճախականության բարձրացում՝ րոպեում 15-ից ավելի զարկով։ Եթե զարգանում է որևէ վտանգի նշան, դադարեցրե՛ք հեղուկները։ Դադարեցրեք ն/ե հեղուկները, եթե զարգանում է հեղուկային գերբեռնվածություն (թոքերում խզզոցներ, շնչառության հաճախականության կամ սրտի կծկումների հաճախականության բարձրացում)։ Անցեք բերանային հեղուկների՝ հենց որ թույլ պերֆուզիայի նշանները բարելավվեն։ Այս հիվանդներին անհրաժեշտ է արագ փոխանցում/հանձնում այնպիսի կենտրոնի առավել մասնագիտացված սպասարկողի, որտեղ հնարավոր է արյան փոխներարկում։"},{"id":"c-Inhalationinjury","cat":"conditions","title":"Ինհալացիոն վնասվածք","keywords":"Inhalation injury","html":"<p>Այրվածքներից առաջացած ինհալացիոն վնասվածքները կարող են առաջացնել շնչուղիների այտուց և խցանում։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Գլխի և պարանոցի այրվածքներ</li><li>Խանձված քթի մազիկներ կամ մուր՝ քթի կամ բերանի շուրջ</li><li>Շնչուղիներից անսովոր ձայներ (օրինակ՝ ստրիդոր)</li><li>Ձայնի փոփոխություն</li><li>Կրծքավանդակի անբավարար բարձրացում շնչառության ժամանակ</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Հանգստացրեք հիվանդներին։</li><li><a href=\"#/p/s-Giveoxygen\" class=\"xref\">Տվեք թթվածին </a>շնչուղիների այրվածքի կասկածով ԲՈԼՈՐ հիվանդներին, նույնիսկ եթե նրանք հիպոքսիայի նշաններ չունեն։</li><li>Բացեք շնչուղիները՝ օգտագործելով համապատասխան հնարք, և <a href=\"#/p/s-Basicairwaydeviceinsertion\" class=\"xref\">անհրաժեշտության դեպքում տեղադրեք բերան-ըմպանային կամ քիթ-ըմպանային օդուղի։</a></li><li>Եթե կան վնասվածքի նշաններ, ապա կատարեք <a href=\"#/p/s-Spinalimmobilization\" class=\"xref\">պարանոցային ողնաշարի անշարժացումը։</a></li><li>Այրվածք ունեցող հիվանդների մոտ շնչուղիները կարող են արագ այտուցվել և փակվել։ Պլանավորեք արագ <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցում/հանձնում</a> այնպիսի սպասարկողի, ով ունակ է կատարել շնչուղիների ընդլայնված կառավարում։</li><li>Շնչուղիներից ցանկացած անսովոր ձայների դեպքում հաճախակի վերագնահատեք շնչուղիները, քանի որ մասնակի խցանումը կարող է արագ վատթարանալ և ամբողջությամբ փակել շնչուղիները։</li></ul>","text":"Այրվածքներից առաջացած ինհալացիոն վնասվածքները կարող են առաջացնել շնչուղիների այտուց և խցանում։ Նշաններ և ախտանշաններ Գլխի և պարանոցի այրվածքներ Խանձված քթի մազիկներ կամ մուր՝ քթի կամ բերանի շուրջ Շնչուղիներից անսովոր ձայներ (օրինակ՝ ստրիդոր) Ձայնի փոփոխություն Կրծքավանդակի անբավարար բարձրացում շնչառության ժամանակ Վարման հիմնական որոշումներ Հանգստացրեք հիվանդներին։ Տվեք թթվածին շնչուղիների այրվածքի կասկածով ԲՈԼՈՐ հիվանդներին, նույնիսկ եթե նրանք հիպոքսիայի նշաններ չունեն։ Բացեք շնչուղիները՝ օգտագործելով համապատասխան հնարք, և անհրաժեշտության դեպքում տեղադրեք բերան-ըմպանային կամ քիթ-ըմպանային օդուղի։ Եթե կան վնասվածքի նշաններ, ապա կատարեք պարանոցային ողնաշարի անշարժացումը։ Այրվածք ունեցող հիվանդների մոտ շնչուղիները կարող են արագ այտուցվել և փակվել։ Պլանավորեք արագ փոխանցում/հանձնում այնպիսի սպասարկողի, ով ունակ է կատարել շնչուղիների ընդլայնված կառավարում։ Շնչուղիներից ցանկացած անսովոր ձայների դեպքում հաճախակի վերագնահատեք շնչուղիները, քանի որ մասնակի խցանումը կարող է արագ վատթարանալ և ամբողջությամբ փակել շնչուղիները։"},{"id":"c-Tensionpneumothorax","cat":"conditions","title":"Լարված պնևմոթորաքս","keywords":"Tension pneumothorax","html":"<p>Ցանկացած պնևմոթորաքս կարող է վերածվել լարված պնևմոթորաքսի։ Թոքերի և կրծքավանդակի միջև գտնվող խոռոչում օդը կարող է հանգեցնել թոքի կոլապսի (պարզ պնևմոթորաքս)։ Ծավալուն պնևմոթորաքսից ավելացող ճնշումը (լարվածությունը) կարող է տեղաշարժել հիմնական անոթները և խցանել դրանցից արյան հետհոսքը դեպի սիրտ՝ առաջացնելով շոկ (լարված պնևմոթորաքս), քանի որ սիրտը չի կարողանում ստանալ և մղել բավականաչափ արյուն դեպի օրգանիզմ։ Լարված պնևմոթորաքսի դեպքում պերֆուզիան վտանգված է։</p><p>Լարված պնևմոթորաքսը բուժվում է առաջնային հետազոտության ընթացքում, սակայն կրծքավանդակի վնասվածքը կարող է համակցվել նաև պարզ պնևմոթորաքսի հետ, որը կարող է զարգանալ և վերածվել լարված պնևմոթորաքսի։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Հիպոտենզիա՝ դժվարացած շնչառության ՀԱՄԱԿՑՎԱԾ  հետևյալներից որևէ մեկի հետ.</li><li>պարանոցի փքված երակներ (որը կարող է վկայել լարված պնևմոթորաքսի կամ տամպոնադայի մասին)</li><li>վնասված կողմում շնչառության ձայների բացակայություն</li><li>հիպեռեզոնանս՝ <a href=\"#/p/s-Needledecompression\" class=\"xref\">պերկուսիայի ժամանակ՝ վնասված կողմում</a></li><li>շնչափողի տեղաշարժ՝ վնասված կողմին հակառակ ուղղությամբ</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Լարված պնևմոթորաքսի կասկածի դեպքում <a href=\"#/p/s-Needledecompression\" class=\"xref\">կատարեք անհետաձգելի ասեղային դեկոմպրեսիա։</a></li><li>Այնուհետև՝ <a href=\"#/p/s-Giveoxygen\" class=\"xref\">տվեք թթվածին։</a></li><li><a href=\"#/p/s-PlaceIV\" class=\"xref\">Տվեք ն/ե հեղուկներ։</a></li><li>Կազմակերպեք հիվանդի արագ <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցումը/հանձնումը</a> առավել բարձր կարգի սպասարկողի, որն ունակ է տեղադրել պլևրալ խողովակ կամ իրականացնել շնչուղիների և շնչառության առավել բարձր կարգի կառավարում։</li></ul>","text":"Ցանկացած պնևմոթորաքս կարող է վերածվել լարված պնևմոթորաքսի։ Թոքերի և կրծքավանդակի միջև գտնվող խոռոչում օդը կարող է հանգեցնել թոքի կոլապսի (պարզ պնևմոթորաքս)։ Ծավալուն պնևմոթորաքսից ավելացող ճնշումը (լարվածությունը) կարող է տեղաշարժել հիմնական անոթները և խցանել դրանցից արյան հետհոսքը դեպի սիրտ՝ առաջացնելով շոկ (լարված պնևմոթորաքս), քանի որ սիրտը չի կարողանում ստանալ և մղել բավականաչափ արյուն դեպի օրգանիզմ։ Լարված պնևմոթորաքսի դեպքում պերֆուզիան վտանգված է։ Լարված պնևմոթորաքսը բուժվում է առաջնային հետազոտության ընթացքում, սակայն կրծքավանդակի վնասվածքը կարող է համակցվել նաև պարզ պնևմոթորաքսի հետ, որը կարող է զարգանալ և վերածվել լարված պնևմոթորաքսի։ Նշաններ և ախտանշաններ Հիպոտենզիա՝ դժվարացած շնչառության ՀԱՄԱԿՑՎԱԾ  հետևյալներից որևէ մեկի հետ. պարանոցի փքված երակներ (որը կարող է վկայել լարված պնևմոթորաքսի կամ տամպոնադայի մասին) վնասված կողմում շնչառության ձայների բացակայություն հիպեռեզոնանս՝ պերկուսիայի ժամանակ՝ վնասված կողմում շնչափողի տեղաշարժ՝ վնասված կողմին հակառակ ուղղությամբ Վարման հիմնական որոշումներ Լարված պնևմոթորաքսի կասկածի դեպքում կատարեք անհետաձգելի ասեղային դեկոմպրեսիա։ Այնուհետև՝ տվեք թթվածին։ Տվեք ն/ե հեղուկներ։ Կազմակերպեք հիվանդի արագ փոխանցումը/հանձնումը առավել բարձր կարգի սպասարկողի, որն ունակ է տեղադրել պլևրալ խողովակ կամ իրականացնել շնչուղիների և շնչառության առավել բարձր կարգի կառավարում։"},{"id":"c-Flailchest","cat":"conditions","title":"Ծփացող կող","keywords":"Flail chest","html":"<p>«Ծփացող կող» առաջանում է, երբ կողերը կոտրվում են մեկից ավելի կետերում, որի պատճառով կողերի մի ամբողջ հատված «պոկվում» է կրծքավանդակի պատի մնացած մասից։ Կրծքավանդակի պատից պոկված լինելու պատճառով այս հատվածը շնչելիս շարժվում է ոչ նորմալ՝ խանգարելով թոքի մի մասի բնականոն լայնանալուն։ Ծփացող կողերը սովորաբար կապակցված են այդ հատվածի տակ գտնվող թոքի հյուսվածքների վնասվածքի հետ։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Դժվարացած շնչառություն</li><li>Ցավ կրծքավանդակում</li><li>Շնչելիս կրծքավանդակի վնասված հատվածը շարժվում է կրծքավանդակի առողջ մասին հակառակ</li><li>Կրծքավանդակի անհամաչափ շարժում</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li><a href=\"#/p/s-Giveoxygen\" class=\"xref\">Տվեք թթվածին</a> և վերահսկեք ցավը։</li><li>Շատ բարձր է դժվարացած շնչառության և թթվածնաքաղցի զարգացման հավանականությունը։</li><li><a href=\"#/p/s-Transferandhandover\" class=\"xref\">Պլանավորեք հիվանդի արագ փոխանցումը/հանձնումը</a> այնպիսի սպասարկողի, որն ունակ է տեղադրել պլևրալ խողովակ, առավել բարձր կարգի օդուղի և իրականացնել արհեստական շնչառություն։</li></ul>","text":"«Ծփացող կող» առաջանում է, երբ կողերը կոտրվում են մեկից ավելի կետերում, որի պատճառով կողերի մի ամբողջ հատված «պոկվում» է կրծքավանդակի պատի մնացած մասից։ Կրծքավանդակի պատից պոկված լինելու պատճառով այս հատվածը շնչելիս շարժվում է ոչ նորմալ՝ խանգարելով թոքի մի մասի բնականոն լայնանալուն։ Ծփացող կողերը սովորաբար կապակցված են այդ հատվածի տակ գտնվող թոքի հյուսվածքների վնասվածքի հետ։ Նշաններ և ախտանշաններ Դժվարացած շնչառություն Ցավ կրծքավանդակում Շնչելիս կրծքավանդակի վնասված հատվածը շարժվում է կրծքավանդակի առողջ մասին հակառակ Կրծքավանդակի անհամաչափ շարժում Վարման հիմնական որոշումներ Տվեք թթվածին և վերահսկեք ցավը։ Շատ բարձր է դժվարացած շնչառության և թթվածնաքաղցի զարգացման հավանականությունը։ Պլանավորեք հիվանդի արագ փոխանցումը/հանձնումը այնպիսի սպասարկողի, որն ունակ է տեղադրել պլևրալ խողովակ, առավել բարձր կարգի օդուղի և իրականացնել արհեստական շնչառություն։"},{"id":"c-Pelvicfracture","cat":"conditions","title":"Կոնքի կոտրվածք","keywords":"Pelvic fracture","html":"<h3>Նշաններ և ախտանշաններ</h3><ul><li>Ցավ կոնքի շրջանի պալպացիայի ժամանակ</li><li>Կոնքի ոսկորների անկայունություն կամ ոչ բնորոշ շարժունակություն</li><li>Արյուն միզասեռական բացվածքից կամ ուղիղ աղիքից</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li><a href=\"#/p/s-PlaceIV\" class=\"xref\">Տվեք ն/ե հեղուկներ</a> և ցավի վերահսկում։</li><li>Թեթև սեղմեք կոնքը՝ կայունությունը ստուգելու համար։</li><li>Մի բացեք և մի ճոճեք կոնքը և մի կրկնեք զննումը, քանի որ դա կարող է վատթարացնել ներքին արյունահոսությունը։</li><li><a href=\"#/p/s-Pelvicbinderapplication\" class=\"xref\">Կայունացրեք կոնքը սավանով կամ գոտևորող կապով։</a></li><li>Պլանավորեք վաղ <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցում/հանձնում</a> արյան փոխներարկման հնարավորություն ունեցող բաժանմունք։</li></ul>","text":"Նշաններ և ախտանշաններ Ցավ կոնքի շրջանի պալպացիայի ժամանակ Կոնքի ոսկորների անկայունություն կամ ոչ բնորոշ շարժունակություն Արյուն միզասեռական բացվածքից կամ ուղիղ աղիքից Վարման հիմնական որոշումներ Տվեք ն/ե հեղուկներ և ցավի վերահսկում։ Թեթև սեղմեք կոնքը՝ կայունությունը ստուգելու համար։ Մի բացեք և մի ճոճեք կոնքը և մի կրկնեք զննումը, քանի որ դա կարող է վատթարացնել ներքին արյունահոսությունը։ Կայունացրեք կոնքը սավանով կամ գոտևորող կապով։ Պլանավորեք վաղ փոխանցում/հանձնում արյան փոխներարկման հնարավորություն ունեցող բաժանմունք։"},{"id":"c-Haemothoraxpleuraleffusion","cat":"conditions","title":"Հեմոթորաքս/Պլևրալ էֆուզիա","keywords":"Haemothorax/ Pleural effusion","html":"<p>Հեմոթորաքսը արյան կուտակում է կրծքավանդակի պատի և թոքերի միջև։</p><p>Պլևրալ էֆուզիան առաջանում է, երբ թոքի և կրծքավանդակի պատի կամ ստոծանու միջև հեղուկ է կուտակվում։ Հեղուկի կուտակումը սահմանափակում է թոքերի լայնանալը։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Դժվարացած շնչառություն</li><li>Ախտահարված կողմում թուլացած կամ բացակայող շնչառական ձայներ</li><li>Ախտահարված կողմում բթացած ձայներ՝ պերկուսիայի ժամանակ</li><li>Ծավալուն հեմոթորաքսը կարող է առաջացնել <a href=\"#/p/c-Shock\" class=\"xref\">շոկ։</a></li><li>Եթե մի կողմում շնչառական ձայներ չկան և առկա է հիպոտենզիա, ստուգեք պարանոցի փքված երակների առկայությունը կամ շնչափողի տեղաշարժը (<a href=\"#/p/c-Tensionpneumothorax\" class=\"xref\">լարված պնևմոթորաքս։</a>)</li><li>Հասանելիության դեպքում ստուգեք թթվածնի հագեցվածությունը պուլսօքսիմետրով։</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li><a href=\"#/p/s-Giveoxygen\" class=\"xref\">Տվեք թթվածին</a> և <a href=\"#/p/s-PlaceIV\" class=\"xref\">ն/ե հեղուկներ։</a></li><li>Պլանավորեք հիվանդի արագ <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցումը/հանձնումը</a> վիրաբուժական կարողություններով հաստատություն (այս հիվանդներից շատերին անհրաժեշտ կլինի կրծքավանդակում կուտակված հեղուկի հեռացման միջամտություն)։</li><li>Եթե վիճակի պատճառն անհայտ է, հիշեք վնասվածքի հավանականության մասին։</li></ul>","text":"Հեմոթորաքսը արյան կուտակում է կրծքավանդակի պատի և թոքերի միջև։ Պլևրալ էֆուզիան առաջանում է, երբ թոքի և կրծքավանդակի պատի կամ ստոծանու միջև հեղուկ է կուտակվում։ Հեղուկի կուտակումը սահմանափակում է թոքերի լայնանալը։ Նշաններ և ախտանշաններ Դժվարացած շնչառություն Ախտահարված կողմում թուլացած կամ բացակայող շնչառական ձայներ Ախտահարված կողմում բթացած ձայներ՝ պերկուսիայի ժամանակ Ծավալուն հեմոթորաքսը կարող է առաջացնել շոկ։ Եթե մի կողմում շնչառական ձայներ չկան և առկա է հիպոտենզիա, ստուգեք պարանոցի փքված երակների առկայությունը կամ շնչափողի տեղաշարժը (լարված պնևմոթորաքս։) Հասանելիության դեպքում ստուգեք թթվածնի հագեցվածությունը պուլսօքսիմետրով։ Վարման հիմնական որոշումներ Տվեք թթվածին և ն/ե հեղուկներ։ Պլանավորեք հիվանդի արագ փոխանցումը/հանձնումը վիրաբուժական կարողություններով հաստատություն (այս հիվանդներից շատերին անհրաժեշտ կլինի կրծքավանդակում կուտակված հեղուկի հեռացման միջամտություն)։ Եթե վիճակի պատճառն անհայտ է, հիշեք վնասվածքի հավանականության մասին։"},{"id":"c-Postpartumhaemorrhage","cat":"conditions","title":"Հետծննդաբերական արյունահոսություն","keywords":"Post-partum haemorrhage","html":"<p>Յուրաքանչյուր ծննդաբերության ժամանակ տեղի է ունենում որոշակի արյունահոսություն ։ Ծննդաբերությունից հետո արգանդը պետք է կծկվի, ինչը սեղմում է անոթները և սահմանափակում արյունահոսությունը։ Արգանդի չկծկվելը ծննդաբերությունից հետո աննորմալ արյունահոսության (հետծննդաբերական արյունահոսության) ամենահաճախ հանդիպող պատճառն է։ Եթե ծննդաբերությունից հետո հեշտոցային արյունահոսությունը (հետծննդաբերական արյունահոսությունը) կասկածվում է որպես շոկի պատճառ՝ ԲՈԼՈՐ հիվանդներին անհրաժեշտ է արագ <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցում/հանձնում</a> մասնագիտացված մանկաբարձական սպասարկողի մոտ։ Տեղափոխումը կազմակերպելիս և դրա ընթացքում կարևոր է փորձել դադարեցնել արյունահոսությունը։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Վերջերս իրականացած ծննդաբերություն</li><li>Ուժեղ հեշտոցային արյունահոսություն.</li><li>Տակդիրը կամ կտորը թրջվում է 5 րոպեից պակաս ժամանակում</li><li>Արյան մշտական հոսք՝ կաթիլներով</li><li>Արյունահոսություն՝ 250 մլ-ից ավելի</li><li>Փափուկ արգանդ/ստորին որովայն</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Պատրաստվեք անհապաղ փոխանցման որակավորված մանկաբարձական սպասարկողի մոտ։</li><li>Տվեք ն/ե հեղուկներ</li><li>Արյունահոսությունը դադարեցնելու համար օգտագործեք ԵՎ′ <a href=\"#/p/s-Uterinemassage\" class=\"xref\">արգանդի մերսում</a>, ԵՎ′ <a href=\"#/p/m-Oxytocin\" class=\"xref\">օքսիտոցին։</a></li><li>Արյունահոսությունը հաճախ տեղի է ունենում, երբ արգանդը լրիվ կծկված չէ (շոշափելիս կարծր չի զգացվում)։ <a href=\"#/p/s-Uterinemassage\" class=\"xref\">Կատարեք արգանդի մերսում</a>, մինչև արգանդը կարծրանա։</li><li>Եթե ընկերքն անջատվում է, հավաքեք այն հերմետիկ տարայի մեջ և պահեք հիվանդի մոտ, որպեսզի մասնագիտացված մանկաբարձական սպասարկողը կարողանա զննել այն։</li><li>Արտաքինից դիտելով ստուգեք պերինեալ կամ հեշտոցային պատռվածքի առկայությունը։ Հայտնաբերելու դեպքում կիրառեք անմիջական ճնշում ստերիլ թանզիֆով և մոտեցրեք ոտքերը։</li><li>Նույնիսկ եթե արյունահոսությունը դադարում է, այդ հիվանդներին դեռ անհրաժեշտ է արագ <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցում/հանձնում</a> մասնագիտացված մանկաբարձական սպասարկողի մոտ (տե՛ս ստորև պատկերը)։</li></ul>","text":"Յուրաքանչյուր ծննդաբերության ժամանակ տեղի է ունենում որոշակի արյունահոսություն ։ Ծննդաբերությունից հետո արգանդը պետք է կծկվի, ինչը սեղմում է անոթները և սահմանափակում արյունահոսությունը։ Արգանդի չկծկվելը ծննդաբերությունից հետո աննորմալ արյունահոսության (հետծննդաբերական արյունահոսության) ամենահաճախ հանդիպող պատճառն է։ Եթե ծննդաբերությունից հետո հեշտոցային արյունահոսությունը (հետծննդաբերական արյունահոսությունը) կասկածվում է որպես շոկի պատճառ՝ ԲՈԼՈՐ հիվանդներին անհրաժեշտ է արագ փոխանցում/հանձնում մասնագիտացված մանկաբարձական սպասարկողի մոտ։ Տեղափոխումը կազմակերպելիս և դրա ընթացքում կարևոր է փորձել դադարեցնել արյունահոսությունը։ Նշաններ և ախտանշաններ Վերջերս իրականացած ծննդաբերություն Ուժեղ հեշտոցային արյունահոսություն. Տակդիրը կամ կտորը թրջվում է 5 րոպեից պակաս ժամանակում Արյան մշտական հոսք՝ կաթիլներով Արյունահոսություն՝ 250 մլ-ից ավելի Փափուկ արգանդ/ստորին որովայն Վարման հիմնական որոշումներ Պատրաստվեք անհապաղ փոխանցման որակավորված մանկաբարձական սպասարկողի մոտ։ Տվեք ն/ե հեղուկներ Արյունահոսությունը դադարեցնելու համար օգտագործեք ԵՎ′ արգանդի մերսում, ԵՎ′ օքսիտոցին։ Արյունահոսությունը հաճախ տեղի է ունենում, երբ արգանդը լրիվ կծկված չէ (շոշափելիս կարծր չի զգացվում)։ Կատարեք արգանդի մերսում, մինչև արգանդը կարծրանա։ Եթե ընկերքն անջատվում է, հավաքեք այն հերմետիկ տարայի մեջ և պահեք հիվանդի մոտ, որպեսզի մասնագիտացված մանկաբարձական սպասարկողը կարողանա զննել այն։ Արտաքինից դիտելով ստուգեք պերինեալ կամ հեշտոցային պատռվածքի առկայությունը։ Հայտնաբերելու դեպքում կիրառեք անմիջական ճնշում ստերիլ թանզիֆով և մոտեցրեք ոտքերը։ Նույնիսկ եթե արյունահոսությունը դադարում է, այդ հիվանդներին դեռ անհրաժեշտ է արագ փոխանցում/հանձնում մասնագիտացված մանկաբարձական սպասարկողի մոտ (տե՛ս ստորև պատկերը)։"},{"id":"c-Hypoglycaemia","cat":"conditions","title":"Հիպոգլիկեմիա","keywords":"Hypoglycaemia","html":"<p>Արյան շաքարի ցածր մակարդակ։ Արյան գլյուկոզա՝ 3,5 մմոլ/լ-ից պակաս։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Քրտնարտադրություն (դիաֆորեզ)</li><li>Գիտակցության փոփոխություն (շփոթվածությունից մինչև գիտակցության կորուստ)</li><li>Նոպաներ/ցնցումներ</li><li>Շաքարային դիաբետի, մալարիայի կամ ծանր վարակի պատմություն</li><li>Արագ արձագանքում է գլյուկոզայի ընդունմանը</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Անհրաժեշտ է անհապաղ տալ <a href=\"#/p/m-Glucose_dextrose_\" class=\"xref\">գլյուկոզա</a></li><li>Եթե հիվանդը կարող է խոսել և կուլ տալ, տվեք բերանային գլյուկոզա։</li><li>Եթե հիվանդը չի կարող խոսել կամ անգիտակից է, հնարավորության դեպքում տվեք ն/ե գլյուկոզա։</li><li>Եթե ն/ե գլյուկոզա հնարավոր կամ հասանելի չէ, տվեք բուկալ գլյուկոզա (այտի ներսի կողմում)։</li></ul>","text":"Արյան շաքարի ցածր մակարդակ։ Արյան գլյուկոզա՝ 3,5 մմոլ/լ-ից պակաս։ Նշաններ և ախտանշաններ Քրտնարտադրություն (դիաֆորեզ) Գիտակցության փոփոխություն (շփոթվածությունից մինչև գիտակցության կորուստ) Նոպաներ/ցնցումներ Շաքարային դիաբետի, մալարիայի կամ ծանր վարակի պատմություն Արագ արձագանքում է գլյուկոզայի ընդունմանը Վարման հիմնական որոշումներ Անհրաժեշտ է անհապաղ տալ գլյուկոզա Եթե հիվանդը կարող է խոսել և կուլ տալ, տվեք բերանային գլյուկոզա։ Եթե հիվանդը չի կարող խոսել կամ անգիտակից է, հնարավորության դեպքում տվեք ն/ե գլյուկոզա։ Եթե ն/ե գլյուկոզա հնարավոր կամ հասանելի չէ, տվեք բուկալ գլյուկոզա (այտի ներսի կողմում)։"},{"id":"c-GunshotStabwounds","cat":"conditions","title":"Հրազենային/դանակահարման վերք","keywords":"Gunshot/Stab wounds","html":"<p>Երբ հայտնի է դանակահարության կամ հրազենային վնասվածքի պատմություն, կարող են լինել բազմաթիվ վերքեր։ Միշտ ստուգեք ամբողջ մարմինը՝ վերքերի առկայության համար։ Մարմին մտնելուց հետո գնդակը կարող է չշարժվել ուղիղ ուղղությամբ և պտտվել ամբողջ մարմնով։ Մեկ գնդակը կարող է վնասել բազմաթիվ ներքին օրգաններ։ Դանակահարման ծակող-կտրող վերքը ստեղծում է ուղիղ հետագիծ (կարևոր է իմանալ օգտագործված դանակի շեղբի երկարությունը)։ Հիշեք, որ փայտերի կամ մահակների նման առարկաներից ստացված բութ հարվածային վնասվածքները, ակնհայտ վնասվածքներից (կոտրվածքներ, կապտուկներ, պատռվածքներ) բացի, կարող են վնասել նաև ներքին օրգանները։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li><a href=\"#/p/c-Penetratingneckwound\" class=\"xref\">Պարանոցի վերքերը կարող են առաջացնել ընդարձակվող հեմատոմաներ։</a></li><li>Բաց կամ արյունահոսող վերք։</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Արյունահոսող վերքերին կիրառեք անմիջական ճնշում։</li><li>Երբ հայտնի է դանակահարության կամ հրազենային վնասվածքի պատմություն, կարող են լինել բազմաթիվ վերքեր։ Միշտ ստուգեք ամբողջ մարմինը՝ վերքերի առկայության համար։</li><li>Ներթափանցած ցանկացած առարկա թողեք տեղում և ամրացրեք այն՝ վիրաբուժական թիմին <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցման/հանձնման</a> համար։</li><li>Ամրացրեք, բայց մի հեռացրեք ներթափանցած առարկաները։</li></ul>","text":"Երբ հայտնի է դանակահարության կամ հրազենային վնասվածքի պատմություն, կարող են լինել բազմաթիվ վերքեր։ Միշտ ստուգեք ամբողջ մարմինը՝ վերքերի առկայության համար։ Մարմին մտնելուց հետո գնդակը կարող է չշարժվել ուղիղ ուղղությամբ և պտտվել ամբողջ մարմնով։ Մեկ գնդակը կարող է վնասել բազմաթիվ ներքին օրգաններ։ Դանակահարման ծակող-կտրող վերքը ստեղծում է ուղիղ հետագիծ (կարևոր է իմանալ օգտագործված դանակի շեղբի երկարությունը)։ Հիշեք, որ փայտերի կամ մահակների նման առարկաներից ստացված բութ հարվածային վնասվածքները, ակնհայտ վնասվածքներից (կոտրվածքներ, կապտուկներ, պատռվածքներ) բացի, կարող են վնասել նաև ներքին օրգանները։ Նշաններ և ախտանշաններ Պարանոցի վերքերը կարող են առաջացնել ընդարձակվող հեմատոմաներ։ Բաց կամ արյունահոսող վերք։ Վարման հիմնական որոշումներ Արյունահոսող վերքերին կիրառեք անմիջական ճնշում։ Երբ հայտնի է դանակահարության կամ հրազենային վնասվածքի պատմություն, կարող են լինել բազմաթիվ վերքեր։ Միշտ ստուգեք ամբողջ մարմինը՝ վերքերի առկայության համար։ Ներթափանցած ցանկացած առարկա թողեք տեղում և ամրացրեք այն՝ վիրաբուժական թիմին փոխանցման/հանձնման համար։ Ամրացրեք, բայց մի հեռացրեք ներթափանցած առարկաները։"},{"id":"c-CrushInjury","cat":"conditions","title":"Ճզմված վնասվածք","keywords":"Crush Injury","html":"<p>Դիտարկեք ճզմված վնասվածքի հնարավորությունը մարդու մոտ, ով եղել է թակարդված (սեղմված)։</p><p>Ճզմված վնասվածքները կարող են վնասել մաշկը, մկանները, արյունատար անոթները և ոսկորները։ Վնասված մկանը կարող է արտազատել մկանային սպիտակուց (միոգլոբին), որը կուտակվելու դեպքում կարող է վնասել երիկամները։ Կարևոր է իմանալ, թե որքան երկար է սեղմված եղել մարմնի մասը։ Նույնիսկ փոքր ճզմված հատվածը կարող է արտազատել միոգլոբինի վտանգավոր քանակ (օրինակ՝ երբ վերջույթը երկար ժամանակ մնում է փլատակների տակ)։ Եթե ճզմված վնասվածքով հիվանդն ունի մուգ գույնի մեզ, դա կարող է վկայել երիկամներում միոգլոբինի կուտակման մասին։ Ճզմված վնասվածքից հյուսվածքի վնասվածքը և այտուցը կարող են նաև ճնշման կուտակում առաջացնել (մասնավորապես վերջույթների ճզմման վնասվածքների դեպքում), որը կարող է սահմանափակել արյան հոսքը դեպի մկաններն ու նյարդերը (փակեղային (կոմպարտմենտ) համախտանիշ)։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Կոտրվածքներ, կապտուկներ, փափուկ հյուսվածքների վնասվածք</li><li>Փակեղային (կոմպարտմենտ) համախտանիշի նշաններ (ցավ, ձիգ մկանային կոմպարտմենտներ, թմրածություն, թուլացած անոթազարկ կամ մաշկի գունատություն)</li><li>Կարմրաշագանակագույն մեզ՝ քիչ քանակությամբ</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li><a href=\"#/p/s-PlaceIV\" class=\"xref\">Տվեք ն/ե հեղուկներ</a>՝ երիկամներին մեզի արտադրությունը պահպանելու համար։</li><li>Հետևեք մեզի քանակին և ուշադիր եղեք կարմրաշագանակագույն մեզի նկատմամբ (հնարավոր երիկամային վնասվածքի մտահոգիչ նշան)։</li><li><a href=\"#/p/s-Fractureimmobilization\" class=\"xref\">Դրեք բեկակալ կոտրվածքների վրա </a>՝ կանխելու համար ոսկրի ծայրերով նոր վնասվածք առաջացնելը։</li><li>Եթե զարգանում է փակեղային (կոմպարտմենտ) համախտանիշ, պլանավորեք վաղ վիրաբուժական խորհրդատվություն՝ ճնշումը նվազեցնելու համար։</li><li>Հիվանդների մոտ կարող են լինել մկանային վնասվածքի հետ կապված բազմաթիվ համակարգային խնդիրներ, ուստի նրանք միշտ պետք է <a href=\"#/p/s-Transferandhandover\" class=\"xref\">հանձնվեն</a> մասնագիտացված սպասարկողի։</li></ul>","text":"Դիտարկեք ճզմված վնասվածքի հնարավորությունը մարդու մոտ, ով եղել է թակարդված (սեղմված)։ Ճզմված վնասվածքները կարող են վնասել մաշկը, մկանները, արյունատար անոթները և ոսկորները։ Վնասված մկանը կարող է արտազատել մկանային սպիտակուց (միոգլոբին), որը կուտակվելու դեպքում կարող է վնասել երիկամները։ Կարևոր է իմանալ, թե որքան երկար է սեղմված եղել մարմնի մասը։ Նույնիսկ փոքր ճզմված հատվածը կարող է արտազատել միոգլոբինի վտանգավոր քանակ (օրինակ՝ երբ վերջույթը երկար ժամանակ մնում է փլատակների տակ)։ Եթե ճզմված վնասվածքով հիվանդն ունի մուգ գույնի մեզ, դա կարող է վկայել երիկամներում միոգլոբինի կուտակման մասին։ Ճզմված վնասվածքից հյուսվածքի վնասվածքը և այտուցը կարող են նաև ճնշման կուտակում առաջացնել (մասնավորապես վերջույթների ճզմման վնասվածքների դեպքում), որը կարող է սահմանափակել արյան հոսքը դեպի մկաններն ու նյարդերը (փակեղային (կոմպարտմենտ) համախտանիշ)։ Նշաններ և ախտանշաններ Կոտրվածքներ, կապտուկներ, փափուկ հյուսվածքների վնասվածք Փակեղային (կոմպարտմենտ) համախտանիշի նշաններ (ցավ, ձիգ մկանային կոմպարտմենտներ, թմրածություն, թուլացած անոթազարկ կամ մաշկի գունատություն) Կարմրաշագանակագույն մեզ՝ քիչ քանակությամբ Վարման հիմնական որոշումներ Տվեք ն/ե հեղուկներ՝ երիկամներին մեզի արտադրությունը պահպանելու համար։ Հետևեք մեզի քանակին և ուշադիր եղեք կարմրաշագանակագույն մեզի նկատմամբ (հնարավոր երիկամային վնասվածքի մտահոգիչ նշան)։ Դրեք բեկակալ կոտրվածքների վրա ՝ կանխելու համար ոսկրի ծայրերով նոր վնասվածք առաջացնելը։ Եթե զարգանում է փակեղային (կոմպարտմենտ) համախտանիշ, պլանավորեք վաղ վիրաբուժական խորհրդատվություն՝ ճնշումը նվազեցնելու համար։ Հիվանդների մոտ կարող են լինել մկանային վնասվածքի հետ կապված բազմաթիվ համակարգային խնդիրներ, ուստի նրանք միշտ պետք է հանձնվեն մասնագիտացված սպասարկողի։"},{"id":"c-Respiratorydistresspaediatric","cat":"conditions","title":"Մանկահասակ հիվանդների շնչառական խանգարում","keywords":"Respiratory distress in paediatric patients","html":"<p>Քթանցքերի եզրերի լայնացումը, գլխի վերև-ներքև շարժումը, հևոցը և կրծքավանդակի ներքաշումը ԿԱՄ ետքաշումները երեխաների մոտ շնչառական խանգարման նշաններ են։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>ՑԻԱՆՈԶԸ՝ շրթունքների, բերանի կամ մատների ծայրերի շուրջ կապտամոխրագույն երանգն է, որը վկայում է թթվածնի պակասի մասին և վտանգավոր նշան է։</li><li>ԿՐԾՔԱՎԱՆԴԱԿԻ ՆԵՐՔԱՇՈՒՄԸ երեխաների մոտ օժանդակ շնչառական մկանների մասնակցության տարածված դրսևորում է։</li><li>Նայեք կրծքավանդակի ստորին հատվածին (ստորին կողերին)։ Երեխայի մոտ կրծքավանդակի ներքաշում է նկատվում, երբ կրծքավանդակի պատի ստորին հատվածը ՆԵՐՍ է քաշվում, երբ երեխան ՆԵՐշնչում է։</li><li>Նորմալ շնչառության ժամանակ կրծքավանդակի ամբողջ պատը (վերին և ստորին) և որովայնը շարժվում են ԴՈՒՐՍ, երբ երեխան ՆԵՐշնչում է։</li><li>ԱՆՁԱՅՆ ԿՐԾՔԱՎԱՆԴԱԿԸ (շնչառության ձայների բացակայությունը՝ կրծքավանդակը լսելիս) երեխայի մոտ ծանր շնչառական խանգարման նշան է։ Ուժեղ սպազմի և շնչուղիների նեղացման դեպքում կարելի է լսել օդի սահմանափակ շարժում և մի քանի շնչառական ձայն։ Տվեք <a href=\"#/p/m-Salbutamol_albuterol_\" class=\"xref\">սալբուտամոլ</a> և թթվածին, և կրկին ու հաճախակի գնահատեք վիճակը։</li><li>ՍՏՐԻԴՈՐԸ մատնանշում է շնչառական ուղիներում առկա ծանր խնդիր, որի հնարավոր պատճառները բազմաթիվ են։ Ստրիդորի դեպքում անհրաժեշտ է երեխային թույլ տալ մնալ հարմարավետ դիրքով և անմիջապես փոխանցել առավել բարձր կարգի սպասարկողի։ Հետագա բուժումը հաճախ ներառում է <a href=\"#/p/m-Adrenaline_Epinephrine_\" class=\"xref\">ադրենալինի</a> ներմուծում նեբուլայզերով։ Եթե անմիջապես փոխանցումը հնարավոր չէ, դիտարկեք մ/մ ադրենալին՝ ինչպես ծանր ալերգիկ ռեակցիայի բուժման ժամանակ։</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Տվեք <a href=\"#/p/m-Salbutamol_albuterol_\" class=\"xref\">սալբուտամոլ</a> և <a href=\"#/p/s-Giveoxygen\" class=\"xref\">թթվածին,</a> և կրկին ու հաճախակի գնահատեք վիճակը։</li><li>Ստրիդորով երեխաներին պետք է թույլ տալ մնալ հարմարավետ դիրքով և <a href=\"#/p/s-Transferandhandover\" class=\"xref\">անմիջապես փոխանցել</a> առավել բարձր կարգի սպասարկողի։</li><li>Հետագա բուժումը հաճախ ներառում է <a href=\"#/p/m-Adrenaline_Epinephrine_\" class=\"xref\">ադրենալինի</a> ներմուծում նեբուլայզերով։</li><li>Եթե անմիջապես փոխանցումը հնարավոր չէ, դիտարկեք մ/մ ադրենալին՝ ինչպես <a href=\"#/p/c-Allergicreaction\" class=\"xref\">ծանր ալերգիկ ռեակցիայի </a>բուժման ժամանակ։</li></ul>","text":"Քթանցքերի եզրերի լայնացումը, գլխի վերև-ներքև շարժումը, հևոցը և կրծքավանդակի ներքաշումը ԿԱՄ ետքաշումները երեխաների մոտ շնչառական խանգարման նշաններ են։ Նշաններ և ախտանշաններ ՑԻԱՆՈԶԸ՝ շրթունքների, բերանի կամ մատների ծայրերի շուրջ կապտամոխրագույն երանգն է, որը վկայում է թթվածնի պակասի մասին և վտանգավոր նշան է։ ԿՐԾՔԱՎԱՆԴԱԿԻ ՆԵՐՔԱՇՈՒՄԸ երեխաների մոտ օժանդակ շնչառական մկանների մասնակցության տարածված դրսևորում է։ Նայեք կրծքավանդակի ստորին հատվածին (ստորին կողերին)։ Երեխայի մոտ կրծքավանդակի ներքաշում է նկատվում, երբ կրծքավանդակի պատի ստորին հատվածը ՆԵՐՍ է քաշվում, երբ երեխան ՆԵՐշնչում է։ Նորմալ շնչառության ժամանակ կրծքավանդակի ամբողջ պատը (վերին և ստորին) և որովայնը շարժվում են ԴՈՒՐՍ, երբ երեխան ՆԵՐշնչում է։ ԱՆՁԱՅՆ ԿՐԾՔԱՎԱՆԴԱԿԸ (շնչառության ձայների բացակայությունը՝ կրծքավանդակը լսելիս) երեխայի մոտ ծանր շնչառական խանգարման նշան է։ Ուժեղ սպազմի և շնչուղիների նեղացման դեպքում կարելի է լսել օդի սահմանափակ շարժում և մի քանի շնչառական ձայն։ Տվեք սալբուտամոլ և թթվածին, և կրկին ու հաճախակի գնահատեք վիճակը։ ՍՏՐԻԴՈՐԸ մատնանշում է շնչառական ուղիներում առկա ծանր խնդիր, որի հնարավոր պատճառները բազմաթիվ են։ Ստրիդորի դեպքում անհրաժեշտ է երեխային թույլ տալ մնալ հարմարավետ դիրքով և անմիջապես փոխանցել առավել բարձր կարգի սպասարկողի։ Հետագա բուժումը հաճախ ներառում է ադրենալինի ներմուծում նեբուլայզերով։ Եթե անմիջապես փոխանցումը հնարավոր չէ, դիտարկեք մ/մ ադրենալին՝ ինչպես ծանր ալերգիկ ռեակցիայի բուժման ժամանակ։ Վարման հիմնական որոշումներ Տվեք սալբուտամոլ և թթվածին, և կրկին ու հաճախակի գնահատեք վիճակը։ Ստրիդորով երեխաներին պետք է թույլ տալ մնալ հարմարավետ դիրքով և անմիջապես փոխանցել առավել բարձր կարգի սպասարկողի։ Հետագա բուժումը հաճախ ներառում է ադրենալինի ներմուծում նեբուլայզերով։ Եթե անմիջապես փոխանցումը հնարավոր չէ, դիտարկեք մ/մ ադրենալին՝ ինչպես ծանր ալերգիկ ռեակցիայի բուժման ժամանակ։"},{"id":"c-InternalBleeding","cat":"conditions","title":"Ներքին արյունահոսություն","keywords":"Internal Bleeding","html":"<p>Արյան մեծ քանակություն կարող է կորչել կրծքավանդակում, կոնքում, ազդրում և որովայնում՝ նախքան արյունահոսությունը նկատելը։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Պորտի շուրջ կամ որովայնի կողմնային շրջանում կապտուկները կարող են վկայել ներքին արյունահոսության մասին</li><li>Կոնքի կոտրվածք</li><li>Ազդրոսկրի կոտրվածք</li><li>Թուլացած շնչառական ձայներ կրծքավանդակի մի կողմում (հեմոթորաքս)</li><li>Թույլ պերֆուզիայի նշաններ (հիպոտենզիա, տախիկարդիա, գունատ մաշկ, դիաֆորեզ)</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Հնարավորության դեպքում դադարեցրեք արյունահոսությունը՝ <a href=\"#/p/s-Pelvicbinderapplication\" class=\"xref\">կոնքին գոտևորող կապ դրեք</a> կամ <a href=\"#/p/s-Fractureimmobilization\" class=\"xref\">ազդրոսկրին բեկակալ դրեք։</a></li><li><a href=\"#/p/s-IVFluidAdministrationAdult\" class=\"xref\">Տվեք ն/ե հեղուկ։</a></li><li>Անհրաժեշտության դեպքում ուղեգրեք արյան փոխներարկման և շարունակական վիրաբուժական վարման համար։</li></ul><p>ՀԻՇԵ՛Ք. Արյան մակարդման վրա ազդող դեղերը (օրինակ՝ ասպիրին, վարֆարին, կլոպիդոգրել) կարող են դժվարացնել արյունահոսության վերահսկումը և մեծացնել ուշացած արյունահոսության ռիսկը։ Արյան ճնշումը նվազեցնող դեղերը կարող են դժվարացնել շոկի վարումը։ Հնարավորության դեպքում ստացեք հիվանդի ընդունած դեղերի ամբողջական ցանկը կամ խնդրեք ընտանիքի անդամներին բերել դեղերը։</p>","text":"Արյան մեծ քանակություն կարող է կորչել կրծքավանդակում, կոնքում, ազդրում և որովայնում՝ նախքան արյունահոսությունը նկատելը։ Նշաններ և ախտանշաններ Պորտի շուրջ կամ որովայնի կողմնային շրջանում կապտուկները կարող են վկայել ներքին արյունահոսության մասին Կոնքի կոտրվածք Ազդրոսկրի կոտրվածք Թուլացած շնչառական ձայներ կրծքավանդակի մի կողմում (հեմոթորաքս) Թույլ պերֆուզիայի նշաններ (հիպոտենզիա, տախիկարդիա, գունատ մաշկ, դիաֆորեզ) Վարման հիմնական որոշումներ Հնարավորության դեպքում դադարեցրեք արյունահոսությունը՝ կոնքին գոտևորող կապ դրեք կամ ազդրոսկրին բեկակալ դրեք։ Տվեք ն/ե հեղուկ։ Անհրաժեշտության դեպքում ուղեգրեք արյան փոխներարկման և շարունակական վիրաբուժական վարման համար։ ՀԻՇԵ՛Ք. Արյան մակարդման վրա ազդող դեղերը (օրինակ՝ ասպիրին, վարֆարին, կլոպիդոգրել) կարող են դժվարացնել արյունահոսության վերահսկումը և մեծացնել ուշացած արյունահոսության ռիսկը։ Արյան ճնշումը նվազեցնող դեղերը կարող են դժվարացնել շոկի վարումը։ Հնարավորության դեպքում ստացեք հիվանդի ընդունած դեղերի ամբողջական ցանկը կամ խնդրեք ընտանիքի անդամներին բերել դեղերը։"},{"id":"c-Seizureconvulsion","cat":"conditions","title":"Նոպաներ/ցնցումներ","keywords":"Seizure/Convulsion","html":"<p>Կոչվում է նաև կոնվուլսիա կամ ջղաձգում։ Ուղեղում աննորմալ էլեկտրական ակտիվություն է, որը հաճախ դրսևորվում է գիտակցության փոփոխությամբ՝ ուղեկցվող աննորմալ կրկնվող շարժումներով։ Նոպաները կարող են լինել առաջնային վիճակ կամ կարող են առաջանալ վարակի, վնասվածքի, թունավոր նյութերի կամ քիմիական հավասարակշռության խնդիրների հետևանքով։</p><p>Գիտակցության խանգարումը նոպաների/ցնցումների պատմություն ունեցող հիվանդի մոտ կարող է լինել ընթացիկ ցնցումների կամ դրանից վերականգնվելու նշան։ Եթե հիվանդն ունի էպիլեպսիայի (առաջնային նոպաներով/ցնցումներով ուղեկցվող խանգարում), հարցրեք պարբերաբար օգտագործվող դեղորայքի մասին, դեղաչափի վերջերս կատարված ցանկացած փոփոխության կամ դեղորայքի ընդունումը բաց թողնելու մասին։ Եթե ցնցումների պահին եղել են ականատեսներ, հարցրեք հիվանդի ընկնելու կամ գլխի վնասվածքի մասին։ Միշտ հարցրեք արդյոք ցնցումները նույնն են եղել ինչ նախորդ անգամ, թե տարբերվել են։ Հիշե՛ք, որ գիտակցության վերականգնումը ցնցումներից հետո տևում է կես ժամից մինչև մի քանի ժամ (ամենաշատը), չնայած հոգնածության զգացողությունը հիվանդի մոտ կարող է ավելի երկար տևել։ Գիտակցության խանգարման ավելի երկարաժամկետ վիճակը ենթադրում է այլ պատճառ։</p><h3>Նշաններ և ախտանշաններ</h3><h3>Ակտիվ նոպայի նշաններ և ախտանշաններ.</h3><ul><li>Կրկնվող աննորմալ շարժումներ կամ ցնցումներ՝ մարմնի մեկ կամ երկու կողմում</li><li>Ստուգեք բոլոր չորս վերջույթների շարժողական և զգայական գործունեությունը։</li><li>Հայացք՝ ուղղված մեկ կողմ կամ ռիթմիկորեն փոփոխվող</li><li>Չի արձագանքում</li></ul><h3>Վերջերս տեղի ունեցած նոպայի նշաններ և ախտանշաններ.</h3><ul><li>Կծած լեզու</li><li>Ակամա միզարձակում</li><li>Նոպաների/ցնցումների հայտնի պատմություն</li><li>Գիտակցության խառնաշփոթ, որն աստիճանաբար բարելավվում է րոպեներից մինչև ժամերի ընթացքում</li></ul><h3>Վարման հիմնական որոշումներ</h3><p>Նոպաների/ցնցումների բուժման նպատակը թթվածնաքաղցի և վնասվածքների կանխարգելումն է։</p><ul><li>Պաշտպանեք հիվանդին վնասումից կամ հետագա վնասվածքից։</li><li>Պաշտպանեք նոպայի մեջ գտնվող հիվանդին ընկնելուց և շուրջը գտնվող կոշտ կամ սուր առարկաներով վնասվելուց։</li><li><a href=\"#/p/s-ABCDE\" class=\"xref\">Ստուգեք «ABCDE»-ով։</a></li><li>Պահպանեք շնչուղիները՝ ակտիվ նոպայի ժամանակ հիվանդի բերանը ոչինչ մի դրեք, բացառությամբ շնչուղիների արտածծման սարքի։</li><li><a href=\"#/p/s-Giveoxygen\" class=\"xref\">Տվեք թթվածին,</a> եթե առկա է թթվածնաքաղցի կասկած կամ երկարատև նոպա/ցնցում։</li><li>Ակտիվ նոպայի ժամանակ հիվանդի բերանը ոչինչ մի դրեք, բացառությամբ շնչուղիների արտածծման սարքի։</li><li>Միշտ ստուգեք գլյուկոզայի մակարդակը շփոթված կամ անգիտակից հիվանդի մոտ։ Տվեք <a href=\"#/p/m-Glucose_dextrose_\" class=\"xref\">գլյուկոզա,</a> եթե այն 3,5մմոլ/լ-ից ցածր է։</li><li>Գնահատեք գիտակցության մակարդակը ԶԽՑԱ (AVPU) սանդղակով (զգոնություն, խոսք, ցավ, անարձագանք), իսկ վնասվածքի դեպքում՝ Գլազգոյի կոմայի սանդղակով (ԳԿՍ)։</li><li>Ակտիվ նոպաների դեպքում բուժեք <a href=\"#/p/m-Benzodiazepines_diazepam_\" class=\"xref\">բենզոդիազեպինով</a> և ուշադիր հետևեք շնչառության դանդաղեցմանը կամ դժվարացմանը։</li><li>Եթե ցնցումները/նոպաները դադարում են, հիվանդին տեղադրեք <a href=\"#/p/s-Spinalimmobilization\" class=\"xref\">կողքի </a><a href=\"#/p/s-Spinalimmobilization\" class=\"xref\">ապահովության դիրքում,</a><a href=\"#/p/s-Spinalimmobilization\" class=\"xref\"> եթե վնասվածք չի կասկածվում։</a></li><li>Եթե հիվանդը չի արթնանում նոպաների/ցնցումների միջև, դիտարկեք սա որպես կյանքին վտանգ սպառնացող վիճակ։ Կազմակերպեք հիվանդի շուտափույթ <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցումը/հանձնումը</a> առավել բարձր կարգի սպասարկողի։</li></ul><h3>Այլ հատուկ նկատառումներ.</h3><ul><li>Եթե հիվանդը ՀՂԻ է կամ վերջերս է ծննդաբերել, տվեք <a href=\"#/p/m-Magnesiumsulphate\" class=\"xref\">մագնեզիումի սուլֆատ։</a> Սա կարող է լինել էկլամպսիա։</li><li>Կազմակերպեք հիվանդի արագ փոխանցումը/հանձնումը մասնագիտացված բաժանմունք։ Ուշադիր հետևեք հիվանդի վիճակին՝ մագնեզիումի թունավորման նշանների համար։</li><li>Եթե բիբերը նեղացած են, իսկ շնչառությունը դանդաղ, <a href=\"#/p/c-Opioidoverdose\" class=\"xref\">դիտարկեք ԱՓԻՈՆԱՅԻՆ գերդոզավորումը </a></li><li>Տվեք <a href=\"#/p/m-Naloxone\" class=\"xref\">նալոքսոն։</a></li><li>Եթե բիբերի չափերը տարբեր են, դիտարկեք <a href=\"#/p/c-Increasedpressureonthebrain\" class=\"xref\">ուղեղի վրա ավելացած ճնշման</a> հավանականությունը և բարձրացրեք գլուխը մահճակալից 30 աստիճանով, եթե ողնաշարի վնասվածքի կասկած չկա։</li><li>Պլանավորեք հիվանդի արագ <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցումը/հանձնումը</a> առավել բարձր կարգի սպասարկողի կամ նեյրովիրաբուժական հնարավորություններով կենտրոն։</li><li>Եթե պատճառն անհայտ է, հիշեք ՎՆԱՍՎԱԾՔԻ հավանականության մասին՝ <a href=\"#/p/s-Spinalimmobilization\" class=\"xref\">անշարժացրեք ողնաշարի պարանոցային հատվածը,</a> եթե վնասվածք է կասկածվում։</li><li>Հիվանդին տեղադրեք <a href=\"#/p/s-Spinalimmobilization\" class=\"xref\">կողքի ապահովության դիրքում,</a> եթե վնասվածք չի կասկածվում։</li><li>Մալարիան երեխաների մոտ կարող է ավելի ծանր ընթանալ, քան մեծահասակների մոտ։ Ծանր մալարիայով երեխաների մոտ կարող են դրսևորվել ծանր անեմիա, նոպաներ/ցնցումներ, կոմա և հիպոգլիկեմիա։</li></ul>","text":"Կոչվում է նաև կոնվուլսիա կամ ջղաձգում։ Ուղեղում աննորմալ էլեկտրական ակտիվություն է, որը հաճախ դրսևորվում է գիտակցության փոփոխությամբ՝ ուղեկցվող աննորմալ կրկնվող շարժումներով։ Նոպաները կարող են լինել առաջնային վիճակ կամ կարող են առաջանալ վարակի, վնասվածքի, թունավոր նյութերի կամ քիմիական հավասարակշռության խնդիրների հետևանքով։ Գիտակցության խանգարումը նոպաների/ցնցումների պատմություն ունեցող հիվանդի մոտ կարող է լինել ընթացիկ ցնցումների կամ դրանից վերականգնվելու նշան։ Եթե հիվանդն ունի էպիլեպսիայի (առաջնային նոպաներով/ցնցումներով ուղեկցվող խանգարում), հարցրեք պարբերաբար օգտագործվող դեղորայքի մասին, դեղաչափի վերջերս կատարված ցանկացած փոփոխության կամ դեղորայքի ընդունումը բաց թողնելու մասին։ Եթե ցնցումների պահին եղել են ականատեսներ, հարցրեք հիվանդի ընկնելու կամ գլխի վնասվածքի մասին։ Միշտ հարցրեք արդյոք ցնցումները նույնն են եղել ինչ նախորդ անգամ, թե տարբերվել են։ Հիշե՛ք, որ գիտակցության վերականգնումը ցնցումներից հետո տևում է կես ժամից մինչև մի քանի ժամ (ամենաշատը), չնայած հոգնածության զգացողությունը հիվանդի մոտ կարող է ավելի երկար տևել։ Գիտակցության խանգարման ավելի երկարաժամկետ վիճակը ենթադրում է այլ պատճառ։ Նշաններ և ախտանշաններ Ակտիվ նոպայի նշաններ և ախտանշաններ. Կրկնվող աննորմալ շարժումներ կամ ցնցումներ՝ մարմնի մեկ կամ երկու կողմում Ստուգեք բոլոր չորս վերջույթների շարժողական և զգայական գործունեությունը։ Հայացք՝ ուղղված մեկ կողմ կամ ռիթմիկորեն փոփոխվող Չի արձագանքում Վերջերս տեղի ունեցած նոպայի նշաններ և ախտանշաններ. Կծած լեզու Ակամա միզարձակում Նոպաների/ցնցումների հայտնի պատմություն Գիտակցության խառնաշփոթ, որն աստիճանաբար բարելավվում է րոպեներից մինչև ժամերի ընթացքում Վարման հիմնական որոշումներ Նոպաների/ցնցումների բուժման նպատակը թթվածնաքաղցի և վնասվածքների կանխարգելումն է։ Պաշտպանեք հիվանդին վնասումից կամ հետագա վնասվածքից։ Պաշտպանեք նոպայի մեջ գտնվող հիվանդին ընկնելուց և շուրջը գտնվող կոշտ կամ սուր առարկաներով վնասվելուց։ Ստուգեք «ABCDE»-ով։ Պահպանեք շնչուղիները՝ ակտիվ նոպայի ժամանակ հիվանդի բերանը ոչինչ մի դրեք, բացառությամբ շնչուղիների արտածծման սարքի։ Տվեք թթվածին, եթե առկա է թթվածնաքաղցի կասկած կամ երկարատև նոպա/ցնցում։ Ակտիվ նոպայի ժամանակ հիվանդի բերանը ոչինչ մի դրեք, բացառությամբ շնչուղիների արտածծման սարքի։ Միշտ ստուգեք գլյուկոզայի մակարդակը շփոթված կամ անգիտակից հիվանդի մոտ։ Տվեք գլյուկոզա, եթե այն 3,5մմոլ/լ-ից ցածր է։ Գնահատեք գիտակցության մակարդակը ԶԽՑԱ (AVPU) սանդղակով (զգոնություն, խոսք, ցավ, անարձագանք), իսկ վնասվածքի դեպքում՝ Գլազգոյի կոմայի սանդղակով (ԳԿՍ)։ Ակտիվ նոպաների դեպքում բուժեք բենզոդիազեպինով և ուշադիր հետևեք շնչառության դանդաղեցմանը կամ դժվարացմանը։ Եթե ցնցումները/նոպաները դադարում են, հիվանդին տեղադրեք կողքի ապահովության դիրքում, եթե վնասվածք չի կասկածվում։ Եթե հիվանդը չի արթնանում նոպաների/ցնցումների միջև, դիտարկեք սա որպես կյանքին վտանգ սպառնացող վիճակ։ Կազմակերպեք հիվանդի շուտափույթ փոխանցումը/հանձնումը առավել բարձր կարգի սպասարկողի։ Այլ հատուկ նկատառումներ. Եթե հիվանդը ՀՂԻ է կամ վերջերս է ծննդաբերել, տվեք մագնեզիումի սուլֆատ։ Սա կարող է լինել էկլամպսիա։ Կազմակերպեք հիվանդի արագ փոխանցումը/հանձնումը մասնագիտացված բաժանմունք։ Ուշադիր հետևեք հիվանդի վիճակին՝ մագնեզիումի թունավորման նշանների համար։ Եթե բիբերը նեղացած են, իսկ շնչառությունը դանդաղ, դիտարկեք ԱՓԻՈՆԱՅԻՆ գերդոզավորումը Տվեք նալոքսոն։ Եթե բիբերի չափերը տարբեր են, դիտարկեք ուղեղի վրա ավելացած ճնշման հավանականությունը և բարձրացրեք գլուխը մահճակալից 30 աստիճանով, եթե ողնաշարի վնասվածքի կասկած չկա։ Պլանավորեք հիվանդի արագ փոխանցումը/հանձնումը առավել բարձր կարգի սպասարկողի կամ նեյրովիրաբուժական հնարավորություններով կենտրոն։ Եթե պատճառն անհայտ է, հիշեք ՎՆԱՍՎԱԾՔԻ հավանականության մասին՝ անշարժացրեք ողնաշարի պարանոցային հատվածը, եթե վնասվածք է կասկածվում։ Հիվանդին տեղադրեք կողքի ապահովության դիրքում, եթե վնասվածք չի կասկածվում։ Մալարիան երեխաների մոտ կարող է ավելի ծանր ընթանալ, քան մեծահասակների մոտ։ Ծանր մալարիայով երեխաների մոտ կարող են դրսևորվել ծանր անեմիա, նոպաներ/ցնցումներ, կոմա և հիպոգլիկեմիա։"},{"id":"c-Airwayobstructionduetotrauma","cat":"conditions","title":"Շնչուղիների խցանում՝ վնասվածքի հետևանքով","keywords":"Airway obstruction due to trauma","html":"<p>Շնչուղիների խցանում կարող է առաջանալ գլխի կամ պարանոցի վնասվածքների արդյունքում։ Արյունը, արտազատուկները, փսխունքը, այտուցը, ոսկորը կամ վնասված հյուսվածքը կարող են խցանել շնչուղիները։ Պարանոցի ծակող վերքերը նույնպես կարող են առաջացնել խցանում՝ այտուցվածության կամ ընդլայնվող հեմատոմայի արդյունքում։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Պարանոցի հեմատոմա կամ գլխի և պարանոցի վնասվածք</li><li>Ոչ բնորոշ ձայներ շնչուղիներից (ստրիդոր, խռխռոց, կլկլոց)</li><li>Ձայնի փոփոխություն</li><li>Կրծքավանդակի թույլ բարձրացում</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Պահպանեք <a href=\"#/p/s-Spinalimmobilization\" class=\"xref\">ողնաշարի պարանոցային հատվածի անշարժացումը՝</a> վնասվածքի առկայության դեպքում։</li><li>Բացեք շնչուղիները՝ <a href=\"#/p/s-Jawthrust\" class=\"xref\">կիրառելով միայն ծնոտի առաջ հրումը</a> (ՉԻ ԿԱՐԵԼԻ կիրառել գլխի հետթեքում/կզակի բարձրացում); և <a href=\"#/p/s-Basicairwaydeviceinsertion\" class=\"xref\">տեղադրեք բերանային օդուղի ըստ անհրաժեշտության </a>(մի օգտագործեք քիթ-ըմպանային օդուղի, եթե առկա է դեմքի վնասվածք)։</li><li>Կատարեք արտածծում՝ հեռացնելով շնչուղիները խցանող արյունը։</li><li>Պլանավորեք հիվանդի արագ <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցումը/հանձնումը</a> շնչուղիների վարման գծով առավել բարձր կարգի կամ վիրահատական միջամտություն կատարելու հնարավորություն ունեցող սպասարկողի։</li><li>Ոչ բնորոշ ձայների առկայության դեպքում հաճախակի վերագնահատեք շնչուղիները, քանի որ մասնակի խցանումը կարող է արագ վատթարանալ և ամբողջությամբ խցանել շնչուղիները։</li></ul>","text":"Շնչուղիների խցանում կարող է առաջանալ գլխի կամ պարանոցի վնասվածքների արդյունքում։ Արյունը, արտազատուկները, փսխունքը, այտուցը, ոսկորը կամ վնասված հյուսվածքը կարող են խցանել շնչուղիները։ Պարանոցի ծակող վերքերը նույնպես կարող են առաջացնել խցանում՝ այտուցվածության կամ ընդլայնվող հեմատոմայի արդյունքում։ Նշաններ և ախտանշաններ Պարանոցի հեմատոմա կամ գլխի և պարանոցի վնասվածք Ոչ բնորոշ ձայներ շնչուղիներից (ստրիդոր, խռխռոց, կլկլոց) Ձայնի փոփոխություն Կրծքավանդակի թույլ բարձրացում Վարման հիմնական որոշումներ Պահպանեք ողնաշարի պարանոցային հատվածի անշարժացումը՝ վնասվածքի առկայության դեպքում։ Բացեք շնչուղիները՝ կիրառելով միայն ծնոտի առաջ հրումը (ՉԻ ԿԱՐԵԼԻ կիրառել գլխի հետթեքում/կզակի բարձրացում); և տեղադրեք բերանային օդուղի ըստ անհրաժեշտության (մի օգտագործեք քիթ-ըմպանային օդուղի, եթե առկա է դեմքի վնասվածք)։ Կատարեք արտածծում՝ հեռացնելով շնչուղիները խցանող արյունը։ Պլանավորեք հիվանդի արագ փոխանցումը/հանձնումը շնչուղիների վարման գծով առավել բարձր կարգի կամ վիրահատական միջամտություն կատարելու հնարավորություն ունեցող սպասարկողի։ Ոչ բնորոշ ձայների առկայության դեպքում հաճախակի վերագնահատեք շնչուղիները, քանի որ մասնակի խցանումը կարող է արագ վատթարանալ և ամբողջությամբ խցանել շնչուղիները։"},{"id":"c-Airwayobstructionduetoforeignbody","cat":"conditions","title":"Շնչուղիների խցանում՝ օտար մարմնի պատճառով","keywords":"Airway obstruction due to foreign body","html":"<p>Շնչուղիները կարող են խցանվել արտազատուկներով, փսխունքով կամ օտար մարմնով։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Տեսանելի արտազատուկներ, փսխունք, կամ օտար մարմին՝ շնչուղիներում</li><li>Ձայնի փոփոխություն</li><li>Ոչ բնորոշ ձայներ շնչուղիներից (ստրիդոր, խռխռոց, կլկլոց)</li><li>Գիտակցության փոփոխություններ, որոնք հանգեցնում են լեզվով շնչուղիների խցանման</li><li>Կրծքավանդակի թույլ բարձրացում</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Հեռացրեք օտար մարմինը, եթե հնարավոր է, և կատարեք հեղուկի արտածծում։ Զգույշ եղեք, որպեսզի օտար մարմինն ավելի խորը չհրեք։ Մի՛ փորձեք հեռացնել օտար մարմինը, եթե այն պարզ չի երևում։ Արտազատուկների կամ փսխունքի առկայության դեպքում կատարեք արտածծում, եթե հասանելի է, կամ մաքրեք սրբելով։ Հաշվի առեք հիվանդին <a href=\"#/p/s-Spinalimmobilization\" class=\"xref\">կողքի ապահովության դիրքում </a> տեղադրելու հնարավորությունը, եթե <a href=\"#/p/s-ABCDE\" class=\"xref\">«ABCDE»-ի մնացած մասը նորմալ է </a>և վնասվածք չի կասկածվում։</li><li>Եթե հիվանդը կարողանում է հազալ կամ ձայներ արձակել, հանգստացրեք հիվանդին և խրախուսեք հազալը։</li><li>Եթե հիվանդը շնչահեղձվում է (չի կարողանում հազալ, ձայներ չի արձակում), կատարեք <a href=\"#/p/s-ManagementofChoking\" class=\"xref\">հիվանդի տարիքին համապատասխան կրծքավանդակի/որովայնի սեղմումներ/հարվածներ</a> թիկունքին։</li><li>Համեմատած մեծահասակների հետ՝ երեխաների լեզուն ավելի մեծ է, ուստի երեխային պառկեցրեք «հոտ քաշելու» դիրքով (<a href=\"#/p/s-Paediatricheadtiltandchinlift\" class=\"xref\">մոդիֆիկացված գլխի հետթեքում, կզակի բարձրացում՝ </a>ինչպես գլխի մի փոքր վերև և առաջ թեքում՝ ծաղիկ հոտոտելիս)։</li><li>Համեմատած մեծահասակների հետ՝ երեխաների պարանոցը կարճ է, իսկ շնչուղիներն ավելի փափուկ են և հեշտությամբ խցանվող, ուստի խուսափեք պարանոցի գերձգումից կամ կորացումից։</li><li>Համեմատած մեծահասակների հետ՝ երեխաների գլուխն ավելի մեծ է՝ համեմատած մարմնի հետ, ուստի կիրառեք ծնոտի առաջ հրումը, եթե շնչուղիները բաց չեն, և դիրքավորեք գլուխը (շատ փոքր երեխաների դեպքում՝ ուսերի տակ բարձիկ օգտագործելով), որպեսզի շնչուղիները բացվեն, եթե վնասվածք չի կասկածվում։</li><li>Գիտակցության մակարդակի անկման պարագայում լեզուն կարող է խոչընդոտել օդի հոսքը դեպի շնչուղիներ։</li><li>Բացեք շնչուղիները <a href=\"#/p/s-Adultheadtiltandchinlift\" class=\"xref\">գլխի հետթեքում և կզակի բարձրացման հնարք</a><a href=\"#/p/s-Adultheadtiltandchinlift\" class=\"xref\">ով՝ մեծահասակների</a> կամ <a href=\"#/p/s-Paediatricheadtiltandchinlift\" class=\"xref\">մանկահասակ հիվանդների մոտ</a>, կամ <a href=\"#/p/s-Jawthrust\" class=\"xref\">կիրառեք ծնոտի առաջ հրում</a> (եթե կասկածվում է վնասվածք); և <a href=\"#/p/s-Basicairwaydeviceinsertion\" class=\"xref\">անհրաժեշտության դեպքում տեղադրեք բերան-ըմպանային կամ քիթ-ըմպանային օդուղի։ </a></li><li>Այս հիվանդները կարող են նաև ի վիճակի չլինել պաշտպանել իրենց շնչուղիները և պետք է հետևել նրանց՝ փսխելու կամ ասպիրացիայի դեպքում։</li><li><a href=\"#/p/s-Transferandhandover\" class=\"xref\">Պլանավորեք </a><a href=\"#/p/s-Transferandhandover\" class=\"xref\">հիվանդի արագ փոխանցումը/հանձնումը</a> շնչուղիների կառավարման գծով առավել բարձր կարգի սպասարկողի, եթե խցանումը հնարավոր չէ վերացնել։</li><li>Ոչ բնորոշ ձայների առկայության դեպքում հաճախակի վերագնահատեք շնչուղիները, քանի որ մասնակի խցանումը կարող է արագ վատթարանալ և ամբողջությամբ խցանել շնչուղիները։</li><li>Եթե հիվանդը կորցնում է գիտակցությունը շնչահեղձության ընթացքում, հետևեք համապատասխան ՍԹՎ արձանագրություններին։</li></ul>","text":"Շնչուղիները կարող են խցանվել արտազատուկներով, փսխունքով կամ օտար մարմնով։ Նշաններ և ախտանշաններ Տեսանելի արտազատուկներ, փսխունք, կամ օտար մարմին՝ շնչուղիներում Ձայնի փոփոխություն Ոչ բնորոշ ձայներ շնչուղիներից (ստրիդոր, խռխռոց, կլկլոց) Գիտակցության փոփոխություններ, որոնք հանգեցնում են լեզվով շնչուղիների խցանման Կրծքավանդակի թույլ բարձրացում Վարման հիմնական որոշումներ Հեռացրեք օտար մարմինը, եթե հնարավոր է, և կատարեք հեղուկի արտածծում։ Զգույշ եղեք, որպեսզի օտար մարմինն ավելի խորը չհրեք։ Մի՛ փորձեք հեռացնել օտար մարմինը, եթե այն պարզ չի երևում։ Արտազատուկների կամ փսխունքի առկայության դեպքում կատարեք արտածծում, եթե հասանելի է, կամ մաքրեք սրբելով։ Հաշվի առեք հիվանդին կողքի ապահովության դիրքում  տեղադրելու հնարավորությունը, եթե «ABCDE»-ի մնացած մասը նորմալ է և վնասվածք չի կասկածվում։ Եթե հիվանդը կարողանում է հազալ կամ ձայներ արձակել, հանգստացրեք հիվանդին և խրախուսեք հազալը։ Եթե հիվանդը շնչահեղձվում է (չի կարողանում հազալ, ձայներ չի արձակում), կատարեք հիվանդի տարիքին համապատասխան կրծքավանդակի/որովայնի սեղմումներ/հարվածներ թիկունքին։ Համեմատած մեծահասակների հետ՝ երեխաների լեզուն ավելի մեծ է, ուստի երեխային պառկեցրեք «հոտ քաշելու» դիրքով (մոդիֆիկացված գլխի հետթեքում, կզակի բարձրացում՝ ինչպես գլխի մի փոքր վերև և առաջ թեքում՝ ծաղիկ հոտոտելիս)։ Համեմատած մեծահասակների հետ՝ երեխաների պարանոցը կարճ է, իսկ շնչուղիներն ավելի փափուկ են և հեշտությամբ խցանվող, ուստի խուսափեք պարանոցի գերձգումից կամ կորացումից։ Համեմատած մեծահասակների հետ՝ երեխաների գլուխն ավելի մեծ է՝ համեմատած մարմնի հետ, ուստի կիրառեք ծնոտի առաջ հրումը, եթե շնչուղիները բաց չեն, և դիրքավորեք գլուխը (շատ փոքր երեխաների դեպքում՝ ուսերի տակ բարձիկ օգտագործելով), որպեսզի շնչուղիները բացվեն, եթե վնասվածք չի կասկածվում։ Գիտակցության մակարդակի անկման պարագայում լեզուն կարող է խոչընդոտել օդի հոսքը դեպի շնչուղիներ։ Բացեք շնչուղիները գլխի հետթեքում և կզակի բարձրացման հնարքով՝ մեծահասակների կամ մանկահասակ հիվանդների մոտ, կամ կիրառեք ծնոտի առաջ հրում (եթե կասկածվում է վնասվածք); և անհրաժեշտության դեպքում տեղադրեք բերան-ըմպանային կամ քիթ-ըմպանային օդուղի։ Այս հիվանդները կարող են նաև ի վիճակի չլինել պաշտպանել իրենց շնչուղիները և պետք է հետևել նրանց՝ փսխելու կամ ասպիրացիայի դեպքում։ Պլանավորեք հիվանդի արագ փոխանցումը/հանձնումը շնչուղիների կառավարման գծով առավել բարձր կարգի սպասարկողի, եթե խցանումը հնարավոր չէ վերացնել։ Ոչ բնորոշ ձայների առկայության դեպքում հաճախակի վերագնահատեք շնչուղիները, քանի որ մասնակի խցանումը կարող է արագ վատթարանալ և ամբողջությամբ խցանել շնչուղիները։ Եթե հիվանդը կորցնում է գիտակցությունը շնչահեղձության ընթացքում, հետևեք համապատասխան ՍԹՎ արձանագրություններին։"},{"id":"c-Shock","cat":"conditions","title":"Շոկ","keywords":"Shock","html":"<p>Թույլ պերֆուզիան այն է, երբ օրգանիզմը չի կարողանում կենսական օրգաններին մատակարարել բավարար քանակությամբ թթվածնով հագեցած արյուն։ Երբ վնասվում է օրգանի ֆունկցիան, դա կոչվում է շոկ, ինչը կարող է արագ հանգեցնել հիվանդի մահվան։ Շոկի բազմաթիվ պատճառներ կան, այդ թվում՝ կարդիոգեն, սեպտիկ, դիստրիբուտիվ, անաֆիլակտիկ և նեյրոգեն շոկ։</p><p>ՀԻՇԵ՛Ք. <a href=\"#/p/c-Spinalcordinjury\" class=\"xref\">Ողնաշարի վնասվածքները նույնպես կարող են շոկ առաջացնել։ </a>Սա կարող է տեղի ունենալ, երբ վնասվում են օրգանիզմի արյունատար անոթների կծկումը կարգավորող նյարդերը։ Երբ արյունատար անոթների պատերը թուլանում են, անոթները լայնանում են, իսկ արյան ճնշումն ընկնում է՝ հանգեցնելով թույլ պերֆուզիայի և շոկի։ Ռիսկն էլ ավելի է բարձրանում ուղեկցող արյունահոսության առկայությամբ, ուստի հիվանդներին պետք է ուշադիր մշտադիտարկել։ Միշտ կասկածե՛ք ողնաշարի վնասվածք, եթե շոկային վիճակում գտնվող հիվանդի բուժման միջոցառումները արդյունավետ չեն։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Սրտի կծկումների արագացում (տախիկարդիա)</li><li>Շնչառության արագացում (տախիպնոէ)</li><li>Գունատ և սառը մաշկ</li><li>Անկախ մարդու մաշկի գույնից՝ կոպի ներքին մակերեսը պետք է վարդագույն և խոնավ լինի։ Եթե կոպի ներքին հատվածը (կոնյուկտիվա) գունատ է, դա կարող է վկայել զգալի արյան կորստի մասին։</li><li>Մազանոթների վերալցում՝ 3 վայրկյանից ավելի</li><li>Քրտնարտադրություն (դիաֆորեզ)</li><li>Հնարավոր է գլխապտույտ, շփոթվածություն, գիտակցության խանգարումներ</li><li>Հնարավոր է հիպոտենզիա</li><li>Սակայն արյան ճնշման անկում կարող է չլինել՝ մինչև վիճակը դառնա անմիջապես կյանքին սպառնացող։</li><li>Նույնիսկ երբ սիստոլիկ զարկերակային ճնշումը 90 մմ ս.ս.-ից բարձր է, կասկածեք հիպովոլեմիկ շոկի, եթե առկա է ծանր արյունահոսություն կամ թույլ պերֆուզիայի որևէ նշան։</li><li>Հնարավոր է արտաքին արյունահոսություն կամ ներքին արյունահոսություն (կրծքավանդակ, որովայն, կոնք, ազդր)</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Շոկի սկզբնական բուժումը ներառում է հիվանդին հարթ մակերևույթի վրա պառկեցնելը (եթե հանդուրժելի է)։</li><li><a href=\"#/p/s-Giveoxygen\" class=\"xref\">Տվեք թթվածին։</a></li><li><a href=\"#/p/s-Externalbleedingcontrol\" class=\"xref\">Դադարեցրեք արյունահոսությունը։</a></li><li><a href=\"#/p/s-IVFluidAdministrationAdult\" class=\"xref\">Տեղադրեք 2 մեծ տրամաչափի ն/ե կատետր</a> և <a href=\"#/p/s-IVFluidAdministrationAdult\" class=\"xref\">տվեք ն/ե հեղուկներ։</a></li><li>ԶԳՈՒՇԱՑՈՒՄ! Ծանր թերսնուցում կամ ծանր անեմիա ունեցող, ինչպես նաև հիպերվոլեմիայի նշաններ ունեցող ցանկացած մարդու համար ՄԻ՛ հետևեք ստորև նշված հեղուկների արձանագրությանը։</li><li>Այս հիվանդների համար օգտագործեք <a href=\"#/p/s-IVFluidAdministrationAdult\" class=\"xref\">հարմարեցված արձանագրությունը։</a></li><li>Վարակի նշանների առկայության դեպքում, հասանելիության դեպքում, տվեք <a href=\"#/p/m-Antibiotics\" class=\"xref\">հակաբիոտիկներ։</a></li><li>Պատրաստվեք հիվանդի արագ <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցմանը/հանձնմանը։</a></li></ul><p><strong>ՀԻՇԵ՛Ք. Հատուկ նկատառումներ ՄԱՆԿԱՀԱՍԱԿ հիվանդների վերաբերյալ</strong></p><p>Երեխաների մոտ շոկը կարող է զարգանալ շատ արագ և կյանքին վտանգ ներկայացնել։ Երեխաներն ունեն մարմնի համեմատաբար ավելի մեծ մակերես (համեմատած դրա ծավալի հետ) և արագ ջրազրկման հավանականությունն ավելի մեծ է։ Վտանգն հատկապես մեծ է նորածինների և մանկահասակ երեխաների դեպքում, քանի որ նրանք չեն կարողանում ասել, որ ծարավ են և չեն կարողանում ինքնուրույն ավելի շատ խմել։</p><p>Շոկի գնահատումը երեխաների մոտ. Երեխաների մոտ շոկի կլինիկական սահմանումը տարբեր է։ 2016 թվականի ԱՀԿ ուղեցույցում, ծայրահեղ ծանր վիճակում գտնվող երեխաների խնամքում օգտագործվում է երեք կլինիկական բնութագրերի առկայությունը՝ սառը վերջույթներ, մազանոթների վերալցում՝ 3 վայրկյանից ավելի, թույլ և արագացած անոթազարկ։ Կան նաև թույլ պերֆուզիայի այլ կարևոր նշաններ, ինչպիսիք են արյան ցածր ճնշումը, հաճախացած շնչառությունը, գիտակցության խանգարումները և պակասած միզարձակությունը (միշտ հարցրեք երեխայի ծնողներին նրա մեզի քանակի մասին)։</p><ul><li>Երեխաների մոտ <a href=\"#/p/s-PlaceIV\" class=\"xref\">թույլ պերֆուզիայի</a> բուժումը կարող է տարբերվել՝ կախված պատճառից և երեխայի վիճակից։</li><li>Երեխայի մոտ արյան ցածր ճնշումը ծանր շոկի նշան է։</li><li>Շոկի ժամանակ երեխաները կարողանում են ավելի երկար պահպանել արյան նորմալ ճնշումը, քան մեծահասակները։ Ուշադիր հետևեք թույլ պերֆուզիայի այլ նշաններին, ինչպիսիք են նվազած միզարձակումը և գիտակցության խանգարումները։</li><li>Երեխաներին տրվող ներերակային հեղուկի քանակը տարբերվում է մեծահասակներից։</li><li><a href=\"#/p/c-Malnourishment\" class=\"xref\">Թերսնուցված երեխաների </a>մոտ տարբեր են և՛ հեղուկի ներարկման արագությունը, և՛ հեղուկի տեսակը։</li><li>Ջրազրկման ծանր նշաններ.</li><li>Բերանի խոռոչի և շրթունքների խիստ չորություն</li><li>Լեթարգիա (չափից շատ քնկոտություն և դանդաղացած ռեակցիաներ), երեխան չի հաղորդակցվում</li><li>Փոս ընկած աչքեր</li><li>Քիչ քանակությամբ մուգ գույնի մեզ (նորածինների դեպքում հարցրեք տակդիրների քանակի մասին)</li><li>Ներս ընկած գաղթուն՝ մինչև մեկ տարեկան մանկահասակ երեխաների մոտ</li><li>Մազանոթների դանդաղացած վերալցում (մազանոթների վերալցման նորման 3 վայրկյանից ցածրն է)</li><li>Գունատություն (ջրազրկման բուժումը շատ ավելի դժվար է դառնում սակավարյունության ժամանակ)</li><li>Մաշկի կսմթոցի անբավարար արդյունք</li></ul><p>ՀԻՇԵ՛Ք. հեղուկները լուծում են միայն պերֆուզիայի անմիջական խնդիրը։ Շոկային վիճակում գտնվող հիվանդներին անհրաժեշտ է արագ <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցում/հանձնում</a> այնպիսի բաժանմունք, որն ունակ է հասցեագրել շոկի պատճառները և տրամադրել առավել բարձր կարգի բուժում, այդ թվում՝ արյան փոխներարկում։</p><p>ՀԻՇԵ՛Ք. հեղուկային կարգավիճակի գնահատումը կարևոր է։ Հիվանդներն, ովքեր ունեն թույլ պերֆուզիայի նշաններ, սակայն ընդհանուր առմամբ՝ հիպերվոլեմիա, կարող են հատկապես դժվար կառավարվող լինել։ Այսպես կարող են դրսևորվել թերսնուցում և ծանր անեմիա ունեցող հիվանդները, ինչպես նաև սրտի, լյարդի կամ երիկամների անբավարարության հետևանքով թոքերում հեղուկի ավելցուկ ունեցողները։ Այս հիվանդներին դեռ անհրաժեշտ են հեղուկներ, սակայն դրանք պետք է տրվեն զգուշությամբ, և հատկապես թերսնուցված երեխաների դեպքում՝ <a href=\"#/p/c-Malnourishment\" class=\"xref\">ըստ</a><a href=\"#/p/c-Malnourishment\" class=\"xref\"> հատուկ արձանագրության։</a></p><p>ՀԻՇԵ՛Ք. <a href=\"#/p/c-Hypoglycaemia\" class=\"xref\">հիպոգլիկեմիան</a> կարող է նմանվել շոկի։</p><h3>Տեղափոխման/հանձնման նկատառումներ՝ բոլոր հիվանդների համար</h3><ul><li>Շոկային վիճակում գտնվող մարդիկ կարող են արագ վատթարանալ և մահանալ։ Նրանք պետք է շատ ուշադիր հսկվեն։</li><li>Բացի այդ, շոկ առաջացնող նույն հիվանդությունները խոչընդոտում են օրգանիզմի՝ հեղուկները կառավարելու ունակությանը, ուստի այս հիվանդները պետք է շատ ուշադիր հսկվեն դժվարացած շնչառության նշանների համար։</li><li>Շոկային վիճակում գտնվող հիվանդները կարող են շփոթված և տագնապած լինել։ Համոզվեք, որ փոխադրման ընթացքում նրանք անվտանգ են և վերահսկվող։</li><li>Շոկային վիճակում գտնվող հիվանդները հաճախ փոխանցվում են արյան փոխներարկման կամ ընդհանուր կամ մանկաբարձական վիրահատության համար։ Միշտ ուղղակիորեն կապ հաստատեք ընդունող հաստատության հետ՝ համոզվելու համար, որ այդ ռեսուրսները իսկապես հասանելի են փոխանցման պահին։</li></ul>","text":"Թույլ պերֆուզիան այն է, երբ օրգանիզմը չի կարողանում կենսական օրգաններին մատակարարել բավարար քանակությամբ թթվածնով հագեցած արյուն։ Երբ վնասվում է օրգանի ֆունկցիան, դա կոչվում է շոկ, ինչը կարող է արագ հանգեցնել հիվանդի մահվան։ Շոկի բազմաթիվ պատճառներ կան, այդ թվում՝ կարդիոգեն, սեպտիկ, դիստրիբուտիվ, անաֆիլակտիկ և նեյրոգեն շոկ։ ՀԻՇԵ՛Ք. Ողնաշարի վնասվածքները նույնպես կարող են շոկ առաջացնել։ Սա կարող է տեղի ունենալ, երբ վնասվում են օրգանիզմի արյունատար անոթների կծկումը կարգավորող նյարդերը։ Երբ արյունատար անոթների պատերը թուլանում են, անոթները լայնանում են, իսկ արյան ճնշումն ընկնում է՝ հանգեցնելով թույլ պերֆուզիայի և շոկի։ Ռիսկն էլ ավելի է բարձրանում ուղեկցող արյունահոսության առկայությամբ, ուստի հիվանդներին պետք է ուշադիր մշտադիտարկել։ Միշտ կասկածե՛ք ողնաշարի վնասվածք, եթե շոկային վիճակում գտնվող հիվանդի բուժման միջոցառումները արդյունավետ չեն։ Նշաններ և ախտանշաններ Սրտի կծկումների արագացում (տախիկարդիա) Շնչառության արագացում (տախիպնոէ) Գունատ և սառը մաշկ Անկախ մարդու մաշկի գույնից՝ կոպի ներքին մակերեսը պետք է վարդագույն և խոնավ լինի։ Եթե կոպի ներքին հատվածը (կոնյուկտիվա) գունատ է, դա կարող է վկայել զգալի արյան կորստի մասին։ Մազանոթների վերալցում՝ 3 վայրկյանից ավելի Քրտնարտադրություն (դիաֆորեզ) Հնարավոր է գլխապտույտ, շփոթվածություն, գիտակցության խանգարումներ Հնարավոր է հիպոտենզիա Սակայն արյան ճնշման անկում կարող է չլինել՝ մինչև վիճակը դառնա անմիջապես կյանքին սպառնացող։ Նույնիսկ երբ սիստոլիկ զարկերակային ճնշումը 90 մմ ս.ս.-ից բարձր է, կասկածեք հիպովոլեմիկ շոկի, եթե առկա է ծանր արյունահոսություն կամ թույլ պերֆուզիայի որևէ նշան։ Հնարավոր է արտաքին արյունահոսություն կամ ներքին արյունահոսություն (կրծքավանդակ, որովայն, կոնք, ազդր) Վարման հիմնական որոշումներ Շոկի սկզբնական բուժումը ներառում է հիվանդին հարթ մակերևույթի վրա պառկեցնելը (եթե հանդուրժելի է)։ Տվեք թթվածին։ Դադարեցրեք արյունահոսությունը։ Տեղադրեք 2 մեծ տրամաչափի ն/ե կատետր և տվեք ն/ե հեղուկներ։ ԶԳՈՒՇԱՑՈՒՄ! Ծանր թերսնուցում կամ ծանր անեմիա ունեցող, ինչպես նաև հիպերվոլեմիայի նշաններ ունեցող ցանկացած մարդու համար ՄԻ՛ հետևեք ստորև նշված հեղուկների արձանագրությանը։ Այս հիվանդների համար օգտագործեք հարմարեցված արձանագրությունը։ Վարակի նշանների առկայության դեպքում, հասանելիության դեպքում, տվեք հակաբիոտիկներ։ Պատրաստվեք հիվանդի արագ փոխանցմանը/հանձնմանը։ ՀԻՇԵ՛Ք. Հատուկ նկատառումներ ՄԱՆԿԱՀԱՍԱԿ հիվանդների վերաբերյալ Երեխաների մոտ շոկը կարող է զարգանալ շատ արագ և կյանքին վտանգ ներկայացնել։ Երեխաներն ունեն մարմնի համեմատաբար ավելի մեծ մակերես (համեմատած դրա ծավալի հետ) և արագ ջրազրկման հավանականությունն ավելի մեծ է։ Վտանգն հատկապես մեծ է նորածինների և մանկահասակ երեխաների դեպքում, քանի որ նրանք չեն կարողանում ասել, որ ծարավ են և չեն կարողանում ինքնուրույն ավելի շատ խմել։ Շոկի գնահատումը երեխաների մոտ. Երեխաների մոտ շոկի կլինիկական սահմանումը տարբեր է։ 2016 թվականի ԱՀԿ ուղեցույցում, ծայրահեղ ծանր վիճակում գտնվող երեխաների խնամքում օգտագործվում է երեք կլինիկական բնութագրերի առկայությունը՝ սառը վերջույթներ, մազանոթների վերալցում՝ 3 վայրկյանից ավելի, թույլ և արագացած անոթազարկ։ Կան նաև թույլ պերֆուզիայի այլ կարևոր նշաններ, ինչպիսիք են արյան ցածր ճնշումը, հաճախացած շնչառությունը, գիտակցության խանգարումները և պակասած միզարձակությունը (միշտ հարցրեք երեխայի ծնողներին նրա մեզի քանակի մասին)։ Երեխաների մոտ թույլ պերֆուզիայի բուժումը կարող է տարբերվել՝ կախված պատճառից և երեխայի վիճակից։ Երեխայի մոտ արյան ցածր ճնշումը ծանր շոկի նշան է։ Շոկի ժամանակ երեխաները կարողանում են ավելի երկար պահպանել արյան նորմալ ճնշումը, քան մեծահասակները։ Ուշադիր հետևեք թույլ պերֆուզիայի այլ նշաններին, ինչպիսիք են նվազած միզարձակումը և գիտակցության խանգարումները։ Երեխաներին տրվող ներերակային հեղուկի քանակը տարբերվում է մեծահասակներից։ Թերսնուցված երեխաների մոտ տարբեր են և՛ հեղուկի ներարկման արագությունը, և՛ հեղուկի տեսակը։ Ջրազրկման ծանր նշաններ. Բերանի խոռոչի և շրթունքների խիստ չորություն Լեթարգիա (չափից շատ քնկոտություն և դանդաղացած ռեակցիաներ), երեխան չի հաղորդակցվում Փոս ընկած աչքեր Քիչ քանակությամբ մուգ գույնի մեզ (նորածինների դեպքում հարցրեք տակդիրների քանակի մասին) Ներս ընկած գաղթուն՝ մինչև մեկ տարեկան մանկահասակ երեխաների մոտ Մազանոթների դանդաղացած վերալցում (մազանոթների վերալցման նորման 3 վայրկյանից ցածրն է) Գունատություն (ջրազրկման բուժումը շատ ավելի դժվար է դառնում սակավարյունության ժամանակ) Մաշկի կսմթոցի անբավարար արդյունք ՀԻՇԵ՛Ք. հեղուկները լուծում են միայն պերֆուզիայի անմիջական խնդիրը։ Շոկային վիճակում գտնվող հիվանդներին անհրաժեշտ է արագ փոխանցում/հանձնում այնպիսի բաժանմունք, որն ունակ է հասցեագրել շոկի պատճառները և տրամադրել առավել բարձր կարգի բուժում, այդ թվում՝ արյան փոխներարկում։ ՀԻՇԵ՛Ք. հեղուկային կարգավիճակի գնահատումը կարևոր է։ Հիվանդներն, ովքեր ունեն թույլ պերֆուզիայի նշաններ, սակայն ընդհանուր առմամբ՝ հիպերվոլեմիա, կարող են հատկապես դժվար կառավարվող լինել։ Այսպես կարող են դրսևորվել թերսնուցում և ծանր անեմիա ունեցող հիվանդները, ինչպես նաև սրտի, լյարդի կամ երիկամների անբավարարության հետևանքով թոքերում հեղուկի ավելցուկ ունեցողները։ Այս հիվանդներին դեռ անհրաժեշտ են հեղուկներ, սակայն դրանք պետք է տրվեն զգուշությամբ, և հատկապես թերսնուցված երեխաների դեպքում՝ ըստ հատուկ արձանագրության։ ՀԻՇԵ՛Ք. հիպոգլիկեմիան կարող է նմանվել շոկի։ Տեղափոխման/հանձնման նկատառումներ՝ բոլոր հիվանդների համար Շոկային վիճակում գտնվող մարդիկ կարող են արագ վատթարանալ և մահանալ։ Նրանք պետք է շատ ուշադիր հսկվեն։ Բացի այդ, շոկ առաջացնող նույն հիվանդությունները խոչընդոտում են օրգանիզմի՝ հեղուկները կառավարելու ունակությանը, ուստի այս հիվանդները պետք է շատ ուշադիր հսկվեն դժվարացած շնչառության նշանների համար։ Շոկային վիճակում գտնվող հիվանդները կարող են շփոթված և տագնապած լինել։ Համոզվեք, որ փոխադրման ընթացքում նրանք անվտանգ են և վերահսկվող։ Շոկային վիճակում գտնվող հիվանդները հաճախ փոխանցվում են արյան փոխներարկման կամ ընդհանուր կամ մանկաբարձական վիրահատության համար։ Միշտ ուղղակիորեն կապ հաստատեք ընդունող հաստատության հետ՝ համոզվելու համար, որ այդ ռեսուրսները իսկապես հասանելի են փոխանցման պահին։"},{"id":"c-Spinalcordinjury","cat":"conditions","title":"Ողնուղեղի վնասվածք","keywords":"Spinal cord injury","html":"<p>Ողնաշարի վնասվածքը միշտ ակնհայտ չէ։ Ողնաշարի կոտրված ոսկորները կարող են վնասել ողնուղեղը՝ առաջացնելով կաթված։ Եթե ողնուղեղի վնասվածքը պարանոցային հատվածում է, կաթվածը կարող է ներառել շնչառությունը կարգավորող մկանները և հանգեցնել մահվան։ Զննման արդյունքները պետք է ուշադիր փաստաթղթավորվեն, որպեսզի հետագա սպասարկողները կարողանան գնահատել՝ արդյոք հիվանդի վիճակը փոխվել է։</p><p><a href=\"#/p/c-Shock\" class=\"xref\">Ողնաշարի վնասվածքները նույնպես կարող են շոկ առաջացնել։</a> Սա կարող է տեղի ունենալ, երբ վնասվում են օրգանիզմի արյունատար անոթների կծկումը կարգավորող նյարդերը։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Ցավ/ցավազգայունություն՝ ողնաշարի միջին գծով</li><li>Շարժման խնդիրներ՝ կաթված, թուլություն, ոչ բնորոշ ռեֆլեքսներ</li><li>Զգայունության խնդիրներ՝ թմրածություն («ասեղի ծակոցներ»), զգայունության կորուստ</li><li>Մեզի կամ կղանքի վերահսկողության կորուստ</li><li>Պրիապիզմ</li><li>Հնարավոր է հիպոտենզիա, բրադիկարդիա</li><li>Կրեպիտացիա՝ ողնաշարի ոսկորներին դիպչելիս</li><li>Ողնաշարի ոսկորների շեղում առանցքից</li><li>Դժվարացած շնչառություն (ողնաշարի վերին պարանոցային հատվածի վնասվածք)</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li><a href=\"#/p/s-Spinalimmobilization\" class=\"xref\">Ապահովեք ողնաշարի անշարժացում</a> վնասվածքի պատմությամբ ցանկացած անգիտակից անձի, կամ գիտակից անձի, ով ունի պարանոցի ցավ, ողնաշարի պարանոցային հատվածի ցավազգայունություն, թմրածություն կամ թուլություն։</li><li>Օգտագործեք ոլորած սավան կամ պարանոցի բեկակալ՝ ողնաշարի պարանոցային հատվածն անշարժացնելու համար։</li><li>Հիվանդին պառկեցրեք հարթ մակերևույթի վրա՝ ողնաշարի մնացած հատվածն անշարժացնելու համար։</li><li>Վնասվածքով հիվանդին զննելիս կամ տեղափոխելիս ողնաշարը պետք է պաշտպանվի՝ կիրառելով <a href=\"#/p/s-Spinalimmobilization\" class=\"xref\">«գերանի գլորում»</a> մեթոդը։</li><li>Տվեք <a href=\"#/p/s-IVFluidAdministrationAdult\" class=\"xref\">ն/ե հեղուկներ։</a></li><li>Ողնաշարի հնարավոր վնասվածքով ցանկացած հիվանդ կարիք ունի <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցման/հանձնման</a> մասնագիտացված բաժանմունք։</li></ul><h3>Նշումներ.</h3><ul><li>Ողնաշարի տախտակները պետք է օգտագործվեն միայն հիվանդներին տեղափոխելու ժամանակ։</li><li>Հիվանդներին ողնաշարի տախտակների վրա երկար ժամանակ թողնելը կարող է պառկելախոցեր առաջացնել։ Հանեք հիվանդներին տախտակից հնարավորինս շուտ, հենց որ հասնեն հաստատություն և կարող են պառկել հարթ մակերևույթի վրա։</li></ul>","text":"Ողնաշարի վնասվածքը միշտ ակնհայտ չէ։ Ողնաշարի կոտրված ոսկորները կարող են վնասել ողնուղեղը՝ առաջացնելով կաթված։ Եթե ողնուղեղի վնասվածքը պարանոցային հատվածում է, կաթվածը կարող է ներառել շնչառությունը կարգավորող մկանները և հանգեցնել մահվան։ Զննման արդյունքները պետք է ուշադիր փաստաթղթավորվեն, որպեսզի հետագա սպասարկողները կարողանան գնահատել՝ արդյոք հիվանդի վիճակը փոխվել է։ Ողնաշարի վնասվածքները նույնպես կարող են շոկ առաջացնել։ Սա կարող է տեղի ունենալ, երբ վնասվում են օրգանիզմի արյունատար անոթների կծկումը կարգավորող նյարդերը։ Նշաններ և ախտանշաններ Ցավ/ցավազգայունություն՝ ողնաշարի միջին գծով Շարժման խնդիրներ՝ կաթված, թուլություն, ոչ բնորոշ ռեֆլեքսներ Զգայունության խնդիրներ՝ թմրածություն («ասեղի ծակոցներ»), զգայունության կորուստ Մեզի կամ կղանքի վերահսկողության կորուստ Պրիապիզմ Հնարավոր է հիպոտենզիա, բրադիկարդիա Կրեպիտացիա՝ ողնաշարի ոսկորներին դիպչելիս Ողնաշարի ոսկորների շեղում առանցքից Դժվարացած շնչառություն (ողնաշարի վերին պարանոցային հատվածի վնասվածք) Վարման հիմնական որոշումներ Ապահովեք ողնաշարի անշարժացում վնասվածքի պատմությամբ ցանկացած անգիտակից անձի, կամ գիտակից անձի, ով ունի պարանոցի ցավ, ողնաշարի պարանոցային հատվածի ցավազգայունություն, թմրածություն կամ թուլություն։ Օգտագործեք ոլորած սավան կամ պարանոցի բեկակալ՝ ողնաշարի պարանոցային հատվածն անշարժացնելու համար։ Հիվանդին պառկեցրեք հարթ մակերևույթի վրա՝ ողնաշարի մնացած հատվածն անշարժացնելու համար։ Վնասվածքով հիվանդին զննելիս կամ տեղափոխելիս ողնաշարը պետք է պաշտպանվի՝ կիրառելով «գերանի գլորում» մեթոդը։ Տվեք ն/ե հեղուկներ։ Ողնաշարի հնարավոր վնասվածքով ցանկացած հիվանդ կարիք ունի փոխանցման/հանձնման մասնագիտացված բաժանմունք։ Նշումներ. Ողնաշարի տախտակները պետք է օգտագործվեն միայն հիվանդներին տեղափոխելու ժամանակ։ Հիվանդներին ողնաշարի տախտակների վրա երկար ժամանակ թողնելը կարող է պառկելախոցեր առաջացնել։ Հանեք հիվանդներին տախտակից հնարավորինս շուտ, հենց որ հասնեն հաստատություն և կարող են պառկել հարթ մակերևույթի վրա։"},{"id":"c-Abdominalinjury","cat":"conditions","title":"Որովայնի վնասվածք","keywords":"Abdominal injury","html":"<h3>Նշաններ և ախտանշաններ</h3><ul><li>Որովայնի ցավ կամ փսխում</li><li>Փափուկ, լարված կամ փքված որովայն</li><li>Որովայնի պատի մկանների կտրուկ կծկումներ՝ որովայնին դիպչելիս («պաշտպանություն»)</li><li>Զննության ժամանակ աղիների խլացած կամ բացակայող ձայներ</li><li>Արյունահոսություն ուղիղ աղիքից</li><li>Որովայնի պատի տեսանելի վերք</li><li>Պորտի կամ իրանի կողքերի շրջանում արյան կապտուկները կարող են լինել ներքին արյունահոսության նշան</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Որովայնի շրջանում ուժեղ ցավը կամ կապտուկները կարող են վկայել օրգանների վնասման կամ ներքին արյունահոսության մասին։</li><li>Եթե կասկածում եք որովայնի վնասվածք, <a href=\"#/p/s-PlaceIV\" class=\"xref\">տվեք ն/ե հեղուկներ </a>։</li><li>Հիվանդին ուտելու կամ խմելու ոչինչ մի տվեք։</li><li>Եթե աղիները տեսանելի են.</li><li>Թողեք այն մարմնից դուրս՝ ներս մի հրեք։</li><li>Ծածկեք այն մանրէազերծ թանզիֆով, թրջված մանրէազերծ ֆիզիոլոգիական լուծույթով։</li><li>Տվեք <a href=\"#/p/m-Antibiotics\" class=\"xref\">հակաբիոտիկներ։</a></li><li>Որովայնի վնասվածքի ցանկացած կասկածի դեպքում պլանավորեք հիվանդի <a href=\"#/p/s-Transferandhandover\" class=\"xref\">արագ փոխանցումը/հանձնումը</a> վիրաբուժական հնարավորություններով հաստատություն։</li></ul>","text":"Նշաններ և ախտանշաններ Որովայնի ցավ կամ փսխում Փափուկ, լարված կամ փքված որովայն Որովայնի պատի մկանների կտրուկ կծկումներ՝ որովայնին դիպչելիս («պաշտպանություն») Զննության ժամանակ աղիների խլացած կամ բացակայող ձայներ Արյունահոսություն ուղիղ աղիքից Որովայնի պատի տեսանելի վերք Պորտի կամ իրանի կողքերի շրջանում արյան կապտուկները կարող են լինել ներքին արյունահոսության նշան Վարման հիմնական որոշումներ Որովայնի շրջանում ուժեղ ցավը կամ կապտուկները կարող են վկայել օրգանների վնասման կամ ներքին արյունահոսության մասին։ Եթե կասկածում եք որովայնի վնասվածք, տվեք ն/ե հեղուկներ ։ Հիվանդին ուտելու կամ խմելու ոչինչ մի տվեք։ Եթե աղիները տեսանելի են. Թողեք այն մարմնից դուրս՝ ներս մի հրեք։ Ծածկեք այն մանրէազերծ թանզիֆով, թրջված մանրէազերծ ֆիզիոլոգիական լուծույթով։ Տվեք հակաբիոտիկներ։ Որովայնի վնասվածքի ցանկացած կասկածի դեպքում պլանավորեք հիվանդի արագ փոխանցումը/հանձնումը վիրաբուժական հնարավորություններով հաստատություն։"},{"id":"c-Blastinjury","cat":"conditions","title":"Պայթյունային վնասվածք","keywords":"Blast Injury","html":"<p>Պայթյունի հետևանքով առաջացած վնասվածքը կարող է ազդել օրգանիզմի բոլոր համակարգերի վրա, հատկապես խոռոչային օրգանների։ Պայթյունային վնասվածքները հաճախ ներառում են թոքերի, աղիների և ականջների վնասվածքներ։</p><p>Պայթյունը կարող է վնասվածք առաջացնել երեք եղանակով.</p><ul><li>Տեսանելի վնասվածքներ բեկորներից (պայթուցիկ սարքից արձակված մետաղի կտորտանքներ) կամ այրվածքներ՝ արձակված ջերմությունից կամ քիմիական նյութերից.</li><li>Ներքին (հաճախ թաքնված) վնասվածքներ՝ պայթյունից առաջացած ճնշման փոփոխության հետևանքով։ Հաճախ վնասվում են ստամոքսը և աղիները, թոքերը և ականջները. և</li><li>Լրացուցիչ բութ վնասվածքներ, որոնք առաջանում են, երբ մարմինը պայթյունից շպրտվում է։</li></ul><p>Պայթյունում ներգրավված հիվանդները պետք է մանրամասն և կրկնակի ստուգվեն, քանի որ այս վնասվածքները հեշտությամբ կարող են աչքից վրիպել։ Պայթյունների հետ կապված կարող են լինել նաև մաշկի և աչքերի մեջ օտար մարմիններ, այրվածքներ կամ քիմիական վնասվածք, ինչպես նաև տոքսինների կամ ճառագայթման ազդեցություն։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Օդով լցված օրգանների վնասվածք (ինչպիսիք են թոքերը, ստամոքսը և աղիները)</li><li>Ուշացած ախտանշաններ՝ տախիպնոէ, հիպօքսիա, կրծքավանդակի ցավ, հազ՝ արյունախխումով կամ առանց արյան</li><li>Որովայնի ցավ, սրտխառնոց, փսխում՝ արյունով կամ առանց արյան</li><li>Թմբկաթաղանթի պատռվածք. լսողության կորուստ, զնգոց ականջներում, ցավ, արյունահոսություն ականջից</li><li>Այլ վնասվածքներ, այրվածքներ, քիմիական նյութերի կամ տոքսինների ազդեցություն</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li><a href=\"#/p/c-Tensionpneumothorax\" class=\"xref\">Ուշադիր զննեք պնևմոթորաքսի առկայության համար։</a></li><li><a href=\"#/p/s-Giveoxygen\" class=\"xref\">Շնչառության դժվարացման դեպքում տվեք թթվածին։ </a></li><li>Թարմացրեք <a href=\"#/p/m-Tetanusvaccination\" class=\"xref\">փայտացման դեմ պատվաստումը։</a></li><li><a href=\"#/p/c-Burns\" class=\"xref\">Այրվածքները պետք է վիրակապվեն, իսկ անհրաժեշտ հեղուկի քանակը հաշվարկվի՝ ըստ մարմնի այրված մակերեսի։</a></li><li><a href=\"#/p/c-Abdominalinjury\" class=\"xref\">Եթե հիվանդն ունի որովայնի ցավ, դիտարկեք աղիների թափածակման հավանականությունը,</a> տվեք <a href=\"#/p/s-PlaceIV\" class=\"xref\">ն/ե </a>հեղուկներ։</li><li>Պատրաստվեք արագ <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցման/հանձնման </a>՝ վիրաբուժական խորհրդատվության համար։</li></ul>","text":"Պայթյունի հետևանքով առաջացած վնասվածքը կարող է ազդել օրգանիզմի բոլոր համակարգերի վրա, հատկապես խոռոչային օրգանների։ Պայթյունային վնասվածքները հաճախ ներառում են թոքերի, աղիների և ականջների վնասվածքներ։ Պայթյունը կարող է վնասվածք առաջացնել երեք եղանակով. Տեսանելի վնասվածքներ բեկորներից (պայթուցիկ սարքից արձակված մետաղի կտորտանքներ) կամ այրվածքներ՝ արձակված ջերմությունից կամ քիմիական նյութերից. Ներքին (հաճախ թաքնված) վնասվածքներ՝ պայթյունից առաջացած ճնշման փոփոխության հետևանքով։ Հաճախ վնասվում են ստամոքսը և աղիները, թոքերը և ականջները. և Լրացուցիչ բութ վնասվածքներ, որոնք առաջանում են, երբ մարմինը պայթյունից շպրտվում է։ Պայթյունում ներգրավված հիվանդները պետք է մանրամասն և կրկնակի ստուգվեն, քանի որ այս վնասվածքները հեշտությամբ կարող են աչքից վրիպել։ Պայթյունների հետ կապված կարող են լինել նաև մաշկի և աչքերի մեջ օտար մարմիններ, այրվածքներ կամ քիմիական վնասվածք, ինչպես նաև տոքսինների կամ ճառագայթման ազդեցություն։ Նշաններ և ախտանշաններ Օդով լցված օրգանների վնասվածք (ինչպիսիք են թոքերը, ստամոքսը և աղիները) Ուշացած ախտանշաններ՝ տախիպնոէ, հիպօքսիա, կրծքավանդակի ցավ, հազ՝ արյունախխումով կամ առանց արյան Որովայնի ցավ, սրտխառնոց, փսխում՝ արյունով կամ առանց արյան Թմբկաթաղանթի պատռվածք. լսողության կորուստ, զնգոց ականջներում, ցավ, արյունահոսություն ականջից Այլ վնասվածքներ, այրվածքներ, քիմիական նյութերի կամ տոքսինների ազդեցություն Վարման հիմնական որոշումներ Ուշադիր զննեք պնևմոթորաքսի առկայության համար։ Շնչառության դժվարացման դեպքում տվեք թթվածին։ Թարմացրեք փայտացման դեմ պատվաստումը։ Այրվածքները պետք է վիրակապվեն, իսկ անհրաժեշտ հեղուկի քանակը հաշվարկվի՝ ըստ մարմնի այրված մակերեսի։ Եթե հիվանդն ունի որովայնի ցավ, դիտարկեք աղիների թափածակման հավանականությունը, տվեք ն/ե հեղուկներ։ Պատրաստվեք արագ փոխանցման/հանձնման ՝ վիրաբուժական խորհրդատվության համար։"},{"id":"c-Penetratingneckwound","cat":"conditions","title":"Պարանոցի ներթափանցող վերք","keywords":"Penetrating neck wound","html":"<h3>Նշաններ և ախտանշաններ</h3><ul><li>Փոքր պատռվածքները կամ ծակվածքային վերքերը կարող են լինել ծանր վնասվածքի միակ նշանը</li><li>Այտուց (հուշում է հեմատոմայի մասին)</li><li>Ուշադիր զննեք ներթափանցած առարկաների առկայության համար։</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Պարանոցի ներթափանցող վերքեր ունեցող հիվանդների մոտ կա շնչուղիների խցանման ռիսկ, ուստի ուշադիր հետևեք շնչուղիներին։</li><li>Պարանոցի վերքերի դեպքում կարող է լինել նաև զգալի արյունահոսություն։</li><li><a href=\"#/p/s-Spinalimmobilization\" class=\"xref\">Պահպանեք պարանոցային ողնաշարի անշարժացման նախազգուշական միջոցները։</a></li><li>Ամրացրեք, բայց մի հեռացրեք ներթափանցած առարկաները։</li><li><a href=\"#/p/s-Externalbleedingcontrol\" class=\"xref\">Արյունահոսող հատվածին կիրառեք ամուր ճնշում</a>՝ զգուշանալով չխցանել շնչուղիները։</li><li>Վերքի խորությունը ստուգելու համար դրա մեջ ոչինչ մի մտցրեք՝ սա կարող է լրացուցիչ վնաս հասցնել։</li><li>Նախաձեռնեք արագ <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցում/հանձնում</a> այնպիսի բաժանմունք, որտեղ հնարավոր են վիրաբուժական խնամք և շնչուղիների ընդլայնված կառավարում։</li></ul>","text":"Նշաններ և ախտանշաններ Փոքր պատռվածքները կամ ծակվածքային վերքերը կարող են լինել ծանր վնասվածքի միակ նշանը Այտուց (հուշում է հեմատոմայի մասին) Ուշադիր զննեք ներթափանցած առարկաների առկայության համար։ Վարման հիմնական որոշումներ Պարանոցի ներթափանցող վերքեր ունեցող հիվանդների մոտ կա շնչուղիների խցանման ռիսկ, ուստի ուշադիր հետևեք շնչուղիներին։ Պարանոցի վերքերի դեպքում կարող է լինել նաև զգալի արյունահոսություն։ Պահպանեք պարանոցային ողնաշարի անշարժացման նախազգուշական միջոցները։ Ամրացրեք, բայց մի հեռացրեք ներթափանցած առարկաները։ Արյունահոսող հատվածին կիրառեք ամուր ճնշում՝ զգուշանալով չխցանել շնչուղիները։ Վերքի խորությունը ստուգելու համար դրա մեջ ոչինչ մի մտցրեք՝ սա կարող է լրացուցիչ վնաս հասցնել։ Նախաձեռնեք արագ փոխանցում/հանձնում այնպիսի բաժանմունք, որտեղ հնարավոր են վիրաբուժական խնամք և շնչուղիների ընդլայնված կառավարում։"},{"id":"c-Pericardialtamponade","cat":"conditions","title":"Պերիկարդի տամպոնադա","keywords":"Pericardial tamponade","html":"<p>Պերիկարդի տամպոնադան առաջանում է, երբ հեղուկը կուտակվում է սրտի շուրջը գտնվող պարկում (պերիկարդում)։ Այս հեղուկից առաջացած ճնշումը կարող է սեղմել սրտի խցերը և խոչընդոտել դրանց բնականոն լցվելուն, սահմանափակելով սրտի կողմից հյուսվածքներին մղվող արյան քանակը և առաջացնելով շոկ։ Բուժումը իրականացվում է պերիկարդիոցենտեզով՝ հեղուկը դուրս բերելով։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Թույլ պերֆուզիայի նշաններ (տախիկարդիա, տախիպնոէ, հիպոտենզիա, գունատ մաշկ, սառը վերջույթներ, մազանոթների վերալցում՝ 3 վայրկյանից ավելի)</li><li>Պարանոցի փքված երակներ</li><li>Սրտի խլացած ձայներ</li><li>Հնարավոր է գլխապտույտ, շփոթվածություն, գիտակցության խանգարումներ</li><li>Տուբերկուլոզի, վնասվածքի, չարորակ նորագոյացության, երիկամային անբավարարության պատմություն</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Մինչև սրտի շուրջը գտնվող հեղուկի դուրսբերումը հիվանդին կենսունակ պահելու համար՝ <a href=\"#/p/s-PlaceIV\" class=\"xref\">տվեք ն/ե հեղուկներ </a>, որպեսզի հնարավորինս շատ ծավալ մտնի սիրտ և օգնի սրտին լցվել՝ դիմադրելով սրտապարկում կուտակվող ճնշմանը։</li><li>Արագ<strong> </strong><a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցում/հանձնում</a> այնպիսի սպասարկողի, ով կարող է պերիկարդի հեղուկը դուրս բերել պերիկարդիոցենտեզով։</li></ul>","text":"Պերիկարդի տամպոնադան առաջանում է, երբ հեղուկը կուտակվում է սրտի շուրջը գտնվող պարկում (պերիկարդում)։ Այս հեղուկից առաջացած ճնշումը կարող է սեղմել սրտի խցերը և խոչընդոտել դրանց բնականոն լցվելուն, սահմանափակելով սրտի կողմից հյուսվածքներին մղվող արյան քանակը և առաջացնելով շոկ։ Բուժումը իրականացվում է պերիկարդիոցենտեզով՝ հեղուկը դուրս բերելով։ Նշաններ և ախտանշաններ Թույլ պերֆուզիայի նշաններ (տախիկարդիա, տախիպնոէ, հիպոտենզիա, գունատ մաշկ, սառը վերջույթներ, մազանոթների վերալցում՝ 3 վայրկյանից ավելի) Պարանոցի փքված երակներ Սրտի խլացած ձայներ Հնարավոր է գլխապտույտ, շփոթվածություն, գիտակցության խանգարումներ Տուբերկուլոզի, վնասվածքի, չարորակ նորագոյացության, երիկամային անբավարարության պատմություն Վարման հիմնական որոշումներ Մինչև սրտի շուրջը գտնվող հեղուկի դուրսբերումը հիվանդին կենսունակ պահելու համար՝ տվեք ն/ե հեղուկներ , որպեսզի հնարավորինս շատ ծավալ մտնի սիրտ և օգնի սրտին լցվել՝ դիմադրելով սրտապարկում կուտակվող ճնշմանը։ Արագ փոխանցում/հանձնում այնպիսի սպասարկողի, ով կարող է պերիկարդի հեղուկը դուրս բերել պերիկարդիոցենտեզով։"},{"id":"c-Heartfailure","cat":"conditions","title":"Սրտային անբավարարություն","keywords":"Heart failure","html":"<p>Երբ սիրտը ի վիճակի չէ բավարար քանակությամբ արյուն մղել օրգանները ողողելու համար, դա սովորաբար հանգեցնում է այտուցի՝ թոքերում կամ վերջույթներում։ Սրտի անբավարարությամբ հիվանդները կարող են գտնվել շոկի մեջ՝ հեղուկային գերբեռնվածությամբ, և կարող են ունենալ մարմնի ստորին հատվածի այտուց (սովորաբար երկու ոտքերում), խզզոցներ թոքերում և պարանոցի փքված երակներ։ Որոշ հիվանդների մոտ կարող է լինել ավելցուկային հեղուկ հյուսվածքներում (օրինակ՝ թոքերում կամ ոտքերի փափուկ հյուսվածքներում)։ Այս հիվանդները կարող են լինել հեղուկային «գերբեռնված» անգամ թույլ պերֆուզիայի դեպքում (քանի որ ավելցուկային հեղուկը անոթներում չէ)։ Այս հիվանդներին դեռ անհրաժեշտ է ն/ե հեղուկ, եթե նրանք շոկի մեջ են, սակայն ն/ե հեղուկը պետք է տրվի ավելի դանդաղ՝ զգուշավոր մշտադիտարկմամբ, որպեսզի հեղուկային գերբեռնվածությունը չվատթարանա։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Ֆիզիկական ծանրաբեռնվածությամբ վատթարացող շնչառության դժվարացում</li><li>Հարթ պառկած դիրքում վատթարացող շնչառության դժվարացում</li><li>Երկու ոտքերի այտուց</li><li>Պարանոցի փքված երակներ</li><li>Թոքերում կարող են լսվել խզզոցներ</li><li>Հնարավոր է կրծքավանդակի ցավ</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Տվեք <a href=\"#/p/s-PlaceIV\" class=\"xref\">ն/ե</a> հեղուկներ ավելի դանդաղ՝ հաճախակի ստուգելով թոքերը՝ խզզոցների համար (հեղուկային գերբեռնվածության նշան)։</li><li>Դադարեցրեք ն/ե հեղուկները, եթե զարգանում է հեղուկային գերբեռնվածություն (շնչառության դժվարացում, խզզոցներ թոքերում, շնչառության կամ սրտի կծկումների հաճախականության բարձրացում)։</li><li>Պլանավորեք արագ <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցում/հանձնում</a> մասնագիտացված սպասարկողի։</li></ul>","text":"Երբ սիրտը ի վիճակի չէ բավարար քանակությամբ արյուն մղել օրգանները ողողելու համար, դա սովորաբար հանգեցնում է այտուցի՝ թոքերում կամ վերջույթներում։ Սրտի անբավարարությամբ հիվանդները կարող են գտնվել շոկի մեջ՝ հեղուկային գերբեռնվածությամբ, և կարող են ունենալ մարմնի ստորին հատվածի այտուց (սովորաբար երկու ոտքերում), խզզոցներ թոքերում և պարանոցի փքված երակներ։ Որոշ հիվանդների մոտ կարող է լինել ավելցուկային հեղուկ հյուսվածքներում (օրինակ՝ թոքերում կամ ոտքերի փափուկ հյուսվածքներում)։ Այս հիվանդները կարող են լինել հեղուկային «գերբեռնված» անգամ թույլ պերֆուզիայի դեպքում (քանի որ ավելցուկային հեղուկը անոթներում չէ)։ Այս հիվանդներին դեռ անհրաժեշտ է ն/ե հեղուկ, եթե նրանք շոկի մեջ են, սակայն ն/ե հեղուկը պետք է տրվի ավելի դանդաղ՝ զգուշավոր մշտադիտարկմամբ, որպեսզի հեղուկային գերբեռնվածությունը չվատթարանա։ Նշաններ և ախտանշաններ Ֆիզիկական ծանրաբեռնվածությամբ վատթարացող շնչառության դժվարացում Հարթ պառկած դիրքում վատթարացող շնչառության դժվարացում Երկու ոտքերի այտուց Պարանոցի փքված երակներ Թոքերում կարող են լսվել խզզոցներ Հնարավոր է կրծքավանդակի ցավ Վարման հիմնական որոշումներ Տվեք ն/ե հեղուկներ ավելի դանդաղ՝ հաճախակի ստուգելով թոքերը՝ խզզոցների համար (հեղուկային գերբեռնվածության նշան)։ Դադարեցրեք ն/ե հեղուկները, եթե զարգանում է հեղուկային գերբեռնվածություն (շնչառության դժվարացում, խզզոցներ թոքերում, շնչառության կամ սրտի կծկումների հաճախականության բարձրացում)։ Պլանավորեք արագ փոխանցում/հանձնում մասնագիտացված սպասարկողի։"},{"id":"c-Heartattack","cat":"conditions","title":"Սրտի ինֆարկտ","keywords":"Heart attack","html":"<p>Կոչվում է նաև միոկարդի ինֆարկտ, դա սրտամկանի մահն է՝ թթվածնով հարուստ արյան դեպի սիրտ հասնելու անբավարարության պատճառով։ Կրծքավանդակի ցավը կարող է հուշել, որ մարդը սրտի ինֆարկտ է ունեցել։ Սրտի ինֆարկտի սրտամկանին հասցված վնասը կարող է նվազեցնել օրգանիզմով արյուն մղելու ունակությունը, ինչը կարող է շոկ առաջացնել։ (Սրտի՝ արդյունավետ կերպով արյուն չմղելու հետևանքով առաջացած շոկը երբեմն կոչվում է կարդիոգեն շոկ։)</p><p>Սրտամկանի՝ արդյունավետ կերպով արյուն չմղելու պատճառ կարող են լինել սրտի ինֆարկտը (անոթի խցանում, որն առաջացնում է սրտամկանի սուր վնասվածք), սրտամկանի բորբոքումը կամ այլ հիվանդություն, ռիթմի խանգարումը կամ փականների խնդիրները։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Կրծքավանդակում ճնշման, սեղմման կամ ճզմման զգացողություն</li><li>Դիաֆորեզ և խայտաբղետ (մարմարանման) մաշկ</li><li>Շնչառության դժվարացում</li><li>Սրտխառնոց կամ փսխում</li><li>Ցավի ճառագայթում դեպի ծնոտ կամ թևեր</li><li>Սրտի անբավարարության նշաններ</li><li>Ծխելու, սրտային հիվանդության, հիպերտոնիայի, շաքարային դիաբետի, խոլեստերինի բարձր մակարդակի պատմություն, սրտային խնդիրների ընտանեկան պատմություն</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Ցուցման առկայության դեպքում տվեք <a href=\"#/p/m-Acetylsalicylicacid_Aspirin_\" class=\"xref\">ասպիրին։</a></li><li>Թեև թթվածինը այլևս խորհուրդ չի տրվում սրտի ինֆարկտով բոլոր հիվանդներին, այն պետք է սկզբնապես տրվի շոկ կամ շնչառության դժվարացում ունեցող հիվանդներին, նույնիսկ երբ կասկածվում է սրտի ինֆարկտ։</li><li>Այն հիվանդների համար, ովքեր արդեն ունեն նիտրոգլիցերին, կարող եք օգնել նրանց ընդունել այն, եթե պերֆուզիան բավարար է։</li><li><a href=\"#/p/s-PlaceIV\" class=\"xref\">Տեղադրեք ն/ե կատետր</a>, և շոկի դրսևորման դեպքում տվեք հեղուկներ՝ հաճախակի վերագնահատելով հիվանդին։</li><li>Պլանավորեք արագ <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցում/հանձնում</a> մասնագիտացված սպասարկողի։</li></ul>","text":"Կոչվում է նաև միոկարդի ինֆարկտ, դա սրտամկանի մահն է՝ թթվածնով հարուստ արյան դեպի սիրտ հասնելու անբավարարության պատճառով։ Կրծքավանդակի ցավը կարող է հուշել, որ մարդը սրտի ինֆարկտ է ունեցել։ Սրտի ինֆարկտի սրտամկանին հասցված վնասը կարող է նվազեցնել օրգանիզմով արյուն մղելու ունակությունը, ինչը կարող է շոկ առաջացնել։ (Սրտի՝ արդյունավետ կերպով արյուն չմղելու հետևանքով առաջացած շոկը երբեմն կոչվում է կարդիոգեն շոկ։) Սրտամկանի՝ արդյունավետ կերպով արյուն չմղելու պատճառ կարող են լինել սրտի ինֆարկտը (անոթի խցանում, որն առաջացնում է սրտամկանի սուր վնասվածք), սրտամկանի բորբոքումը կամ այլ հիվանդություն, ռիթմի խանգարումը կամ փականների խնդիրները։ Նշաններ և ախտանշաններ Կրծքավանդակում ճնշման, սեղմման կամ ճզմման զգացողություն Դիաֆորեզ և խայտաբղետ (մարմարանման) մաշկ Շնչառության դժվարացում Սրտխառնոց կամ փսխում Ցավի ճառագայթում դեպի ծնոտ կամ թևեր Սրտի անբավարարության նշաններ Ծխելու, սրտային հիվանդության, հիպերտոնիայի, շաքարային դիաբետի, խոլեստերինի բարձր մակարդակի պատմություն, սրտային խնդիրների ընտանեկան պատմություն Վարման հիմնական որոշումներ Ցուցման առկայության դեպքում տվեք ասպիրին։ Թեև թթվածինը այլևս խորհուրդ չի տրվում սրտի ինֆարկտով բոլոր հիվանդներին, այն պետք է սկզբնապես տրվի շոկ կամ շնչառության դժվարացում ունեցող հիվանդներին, նույնիսկ երբ կասկածվում է սրտի ինֆարկտ։ Այն հիվանդների համար, ովքեր արդեն ունեն նիտրոգլիցերին, կարող եք օգնել նրանց ընդունել այն, եթե պերֆուզիան բավարար է։ Տեղադրեք ն/ե կատետր, և շոկի դրսևորման դեպքում տվեք հեղուկներ՝ հաճախակի վերագնահատելով հիվանդին։ Պլանավորեք արագ փոխանցում/հանձնում մասնագիտացված սպասարկողի։"},{"id":"c-Extremityfracturewithpoorperfusion","cat":"conditions","title":"Վերջույթի կոտրվածք՝ թույլ պերֆուզիայով","keywords":"Extremity fracture with poor perfusion","html":"<p>Կոտրվածքները կարող են տեղաշարժել արյունատար անոթները և սահմանափակել կոտրվածքից ներքև գտնվող վերջույթի արյունամատակարարումը։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Վնասվածքի պատմություն</li><li>Ոսկրի դեֆորմացիա կամ կրեպիտացիա (վնասվածքի կողմում ոտքի կրճատում՝ <a href=\"#/p/c-Femurfracture\" class=\"xref\">ազդրոսկրի կոտրվածքի</a> դեպքում)</li><li>Բացակայող անոթազարկ՝ կոտրվածքից ներքև</li><li>Մազանոթների վերալցման ժամանակը կոտրվածքից ներքև՝ 3 վայրկյանից ավելի</li><li>Սառը վերջույթներ կոտրվածքից ներքև՝ կապույտ կամ մոխրագույն մաշկով</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Փնտրեք թույլ պերֆուզիայի նշաններ՝ կոտրվածքից ներքև։</li><li>Շոշափեք անոթազարկը։</li><li>Ստուգեք մազանոթների վերալցումը։</li><li>Փնտրեք մաշկի գունատություն։</li><li>Եթե կոտրվածքը հայտնաբերվում է թույլ անոթազարկով կամ թույլ պերֆուզիայով, վերականգնեք պերֆուզիան՝ ուղղում (ռեդուկցիա) կատարելով (ոսկրի ծայրերը ձեռքով վերադասավորելով՝ վերջույթը նորմալ դիրքի վերադարձնելու համար) և <a href=\"#/p/s-Fractureimmobilization\" class=\"xref\">բեկակալ դնելով։</a></li><li>Միշտ ստուգեք և փաստաթղթավորեք անոթազարկը, մազանոթների վերալցումը և զգայունությունը՝ ցանկացած ռեդուկցիայից առաջ և հետո։</li><li>Պլանավորեք հրատապ <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցում/հանձնում</a> մասնագիտացված բաժանմունք։</li></ul>","text":"Կոտրվածքները կարող են տեղաշարժել արյունատար անոթները և սահմանափակել կոտրվածքից ներքև գտնվող վերջույթի արյունամատակարարումը։ Նշաններ և ախտանշաններ Վնասվածքի պատմություն Ոսկրի դեֆորմացիա կամ կրեպիտացիա (վնասվածքի կողմում ոտքի կրճատում՝ ազդրոսկրի կոտրվածքի դեպքում) Բացակայող անոթազարկ՝ կոտրվածքից ներքև Մազանոթների վերալցման ժամանակը կոտրվածքից ներքև՝ 3 վայրկյանից ավելի Սառը վերջույթներ կոտրվածքից ներքև՝ կապույտ կամ մոխրագույն մաշկով Վարման հիմնական որոշումներ Փնտրեք թույլ պերֆուզիայի նշաններ՝ կոտրվածքից ներքև։ Շոշափեք անոթազարկը։ Ստուգեք մազանոթների վերալցումը։ Փնտրեք մաշկի գունատություն։ Եթե կոտրվածքը հայտնաբերվում է թույլ անոթազարկով կամ թույլ պերֆուզիայով, վերականգնեք պերֆուզիան՝ ուղղում (ռեդուկցիա) կատարելով (ոսկրի ծայրերը ձեռքով վերադասավորելով՝ վերջույթը նորմալ դիրքի վերադարձնելու համար) և բեկակալ դնելով։ Միշտ ստուգեք և փաստաթղթավորեք անոթազարկը, մազանոթների վերալցումը և զգայունությունը՝ ցանկացած ռեդուկցիայից առաջ և հետո։ Պլանավորեք հրատապ փոխանցում/հանձնում մասնագիտացված բաժանմունք։"},{"id":"c-Traumainpregnancy","cat":"conditions","title":"Վնասվածք հղիության ժամանակ","keywords":"Trauma in pregnancy","html":"<p>Հղիությունն առաջացնում է բազմաթիվ ֆիզիոլոգիական փոփոխություններ, ինչպես նաև կան պտղի առողջության հետ կապված լրացուցիչ նկատառումներ։ Նույնիսկ աննշան վնասվածքը կարող է վնասել մորը և պտղին։ Հղիության երրորդ եռամսյակում վնասվածք ստացած կանայք ենթակա են ընկերքի անջատման ռիսկի (երբ ընկերքը անջատվում է արգանդի պատից, ինչը հանգեցնում է արյունահոսության), արգանդի պատռվածքի և վաղաժամկետ ծննդաբերության ռիսկի։ Հիշեք, որ մոր վերակենդանացումը վերակենդանացնում է նաև պտուղը։</p><p>Նշում. Իգական սեռի 10-50 տարեկան ցանկացած բուժառու պետք է անցնի հղիության թեստ։</p><h3>Հիվանդի պատմության հիմնական տարրերը</h3><p>Գեստացիոն/ներարգանդային տարիքը (պտղի տարիքը կամ մոր վերջին դաշտանից սկսած շաբաթների թիվը)։</p><p>Հղիության ցանկացած բարդություն։</p><h3>Առաջնային հետազոտություն</h3><ul><li>A - Շնչուղիներ. հղիության ընթացքում առաջացած այտուցվածությունն ավելի հավանական է դարձնում շնչուղիների խցանումը, հետևաբար պետք է հետևել հղի կնոջ վիճակին։</li><li>B - Շնչառություն. հղիության ընթացքում պտուղը ստոծանին հրում է դեպի վերև՝ թողնելով թոքերի շնչելու համար առավել փոքր տարածություն։</li><li>C - Արյան շրջանառություն. ստուգեք, արդյո՞ք առկա է հեշտոցային արյունահոսություն. պտուղը նաև կարող է սեղմել մեծ արյունատար անոթները՝ պատճառելով հիպոտենզիա։ <a href=\"#/p/s-Spinalimmobilization\" class=\"xref\">Հիվանդին շրջեք ձախ կողքի վրա՝ ողնաշարը պաշտպանելով։</a></li><li>D - Գիտակցություն/ԿՆՀ. նոպաների/ցնցումների առաջացման դեպքում միշտ դիտարկեք էկլամպսիայի հնարավորությունը։</li><li>E - Բացահայտում/վտանգավոր արտաքին ազդեցություն. հիվանդին տաք պահեք։</li></ul><h3>Վնասվածքի հետևանքով հանդիպող տարածված վիճակներ</h3><ul><li>Վաղաժամկետ ծննդաբերություն՝ պտղապարկի վաղաժամկետ պատռմամբ (պղաջրերի արտահոսք) կամ առանց դրա։</li><li>Ընկերքի անջատում կամ արգանդի պատռում, որը պատճառում է արյան կորուստ և շոկ։</li><li><a href=\"#/p/c-Seizureconvulsion\" class=\"xref\">Նոպաներ/ցնցումներ։</a></li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Պլանավորեք վաղ <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցում/հանձնում</a> մասնագիտացված մանկաբարձական բաժանմունք։</li><li>Եթե արգանդը շոշափվում է պորտի մակարդակի վրա, դա ընդհանուր առմամբ նշանակում է, որ բուժառուն առնվազն 20 շաբաթական հղի է։</li><li>Եթե կնոջ հղիությունը 20 շաբաթից (5 ամսից) ավելի է, ապա հղի արգանդը կարող է սեղմել ստորին սիներակը՝ արյան հետհոսքը դեպի սիրտ ապահովող մեծ արյունատար անոթը, և առաջացնել շոկ։ Հղի հիվանդին ուղիղ պառկեցնելիս՝ <a href=\"#/p/s-Spinalimmobilization\" class=\"xref\">միշտ պառկեցրեք ձախ կողքի վրա (անհրաժեշտության դեպքում ողնաշարային տախտակի վրա)։</a></li><li>Ուշ ժամկետներում վնասվածքը կարող է հանգեցնել վաղաժամկետ ծննդաբերության։ Պատրաստվեք նեոնատալ վերակենդանացման, եթե վնասվածքն առաջացել է հղիության ուշ փուլերի ընթացքում։</li></ul>","text":"Հղիությունն առաջացնում է բազմաթիվ ֆիզիոլոգիական փոփոխություններ, ինչպես նաև կան պտղի առողջության հետ կապված լրացուցիչ նկատառումներ։ Նույնիսկ աննշան վնասվածքը կարող է վնասել մորը և պտղին։ Հղիության երրորդ եռամսյակում վնասվածք ստացած կանայք ենթակա են ընկերքի անջատման ռիսկի (երբ ընկերքը անջատվում է արգանդի պատից, ինչը հանգեցնում է արյունահոսության), արգանդի պատռվածքի և վաղաժամկետ ծննդաբերության ռիսկի։ Հիշեք, որ մոր վերակենդանացումը վերակենդանացնում է նաև պտուղը։ Նշում. Իգական սեռի 10-50 տարեկան ցանկացած բուժառու պետք է անցնի հղիության թեստ։ Հիվանդի պատմության հիմնական տարրերը Գեստացիոն/ներարգանդային տարիքը (պտղի տարիքը կամ մոր վերջին դաշտանից սկսած շաբաթների թիվը)։ Հղիության ցանկացած բարդություն։ Առաջնային հետազոտություն A - Շնչուղիներ. հղիության ընթացքում առաջացած այտուցվածությունն ավելի հավանական է դարձնում շնչուղիների խցանումը, հետևաբար պետք է հետևել հղի կնոջ վիճակին։ B - Շնչառություն. հղիության ընթացքում պտուղը ստոծանին հրում է դեպի վերև՝ թողնելով թոքերի շնչելու համար առավել փոքր տարածություն։ C - Արյան շրջանառություն. ստուգեք, արդյո՞ք առկա է հեշտոցային արյունահոսություն. պտուղը նաև կարող է սեղմել մեծ արյունատար անոթները՝ պատճառելով հիպոտենզիա։ Հիվանդին շրջեք ձախ կողքի վրա՝ ողնաշարը պաշտպանելով։ D - Գիտակցություն/ԿՆՀ. նոպաների/ցնցումների առաջացման դեպքում միշտ դիտարկեք էկլամպսիայի հնարավորությունը։ E - Բացահայտում/վտանգավոր արտաքին ազդեցություն. հիվանդին տաք պահեք։ Վնասվածքի հետևանքով հանդիպող տարածված վիճակներ Վաղաժամկետ ծննդաբերություն՝ պտղապարկի վաղաժամկետ պատռմամբ (պղաջրերի արտահոսք) կամ առանց դրա։ Ընկերքի անջատում կամ արգանդի պատռում, որը պատճառում է արյան կորուստ և շոկ։ Նոպաներ/ցնցումներ։ Վարման հիմնական որոշումներ Պլանավորեք վաղ փոխանցում/հանձնում մասնագիտացված մանկաբարձական բաժանմունք։ Եթե արգանդը շոշափվում է պորտի մակարդակի վրա, դա ընդհանուր առմամբ նշանակում է, որ բուժառուն առնվազն 20 շաբաթական հղի է։ Եթե կնոջ հղիությունը 20 շաբաթից (5 ամսից) ավելի է, ապա հղի արգանդը կարող է սեղմել ստորին սիներակը՝ արյան հետհոսքը դեպի սիրտ ապահովող մեծ արյունատար անոթը, և առաջացնել շոկ։ Հղի հիվանդին ուղիղ պառկեցնելիս՝ միշտ պառկեցրեք ձախ կողքի վրա (անհրաժեշտության դեպքում ողնաշարային տախտակի վրա)։ Ուշ ժամկետներում վնասվածքը կարող է հանգեցնել վաղաժամկետ ծննդաբերության։ Պատրաստվեք նեոնատալ վերակենդանացման, եթե վնասվածքն առաջացել է հղիության ուշ փուլերի ընթացքում։"},{"id":"c-Compartmentsyndrome","cat":"conditions","title":"Փակեղային  (կոմպարտմենտ) համախտանիշ","keywords":"Compartment syndrome","html":"<p>Վիճակ, երբ օրգանիզմի մի հատվածում, որը չի կարող ընդարձակվել, այտուցից առաջացած ճնշումն ավելանում է, օրինակ՝ նախաբազկի կամ սրունքի հատվածներում։ Հատվածային համախտանիշը նվազեցնում է այդ հատվածի արյան մատակարարումը և կարող է հանգեցնել ուժեղ ցավի, ինչպես նաև նյարդերի և այլ հյուսվածքների վնասման։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Վերջույթների ոչ բնորոշ կոշտ, ցավոտ մկանային հատվածներ</li><li>Թմրածություն</li><li>Նվազած անոթազարկ</li><li>Գունատ մաշկ</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Պլանավորեք արագ <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցում/հանձնում</a>՝ ճնշումը նվազեցնելու վիրաբուժական խորհրդատվության համար, եթե զարգանում է փակեղային համախտանիշ։</li></ul>","text":"Վիճակ, երբ օրգանիզմի մի հատվածում, որը չի կարող ընդարձակվել, այտուցից առաջացած ճնշումն ավելանում է, օրինակ՝ նախաբազկի կամ սրունքի հատվածներում։ Հատվածային համախտանիշը նվազեցնում է այդ հատվածի արյան մատակարարումը և կարող է հանգեցնել ուժեղ ցավի, ինչպես նաև նյարդերի և այլ հյուսվածքների վնասման։ Նշաններ և ախտանշաններ Վերջույթների ոչ բնորոշ կոշտ, ցավոտ մկանային հատվածներ Թմրածություն Նվազած անոթազարկ Գունատ մաշկ Վարման հիմնական որոշումներ Պլանավորեք արագ փոխանցում/հանձնում՝ ճնշումը նվազեցնելու վիրաբուժական խորհրդատվության համար, եթե զարգանում է փակեղային համախտանիշ։"},{"id":"c-ChemicalInjury","cat":"conditions","title":"Քիմիական վնասվածք","keywords":"Chemical Injury","html":"<p>ՀԻՇԵ՛Ք. Եթե առկա է քիմիական նյութի հետ կոնտակտի պատմություն, պաշտպանեք ինքներդ ձեզ անհատական պաշտպանիչ միջոցներով (ԱՊՄ) և համոզվեք, որ նյութը ճիշտ հեռացված է մաշկից։</p><p>Քիմիական այրվածքների դեպքում կարող է անհրաժեշտ լինել տեղեկություն կոնկրետ քիմիական նյութի մասին՝ այն ճիշտ հեռացնելու համար։ Կարևոր է իմանալ՝ արդյոք այրման ընթացքը դադարեցվել է, և քիմիական նյութի հետ կոնտակտի դեպքում՝ արդյոք կատարվել է ախտահանում։ Եթե այրվածք ստանալուց դեռևս չի անցել 3 ժամ և առաջին օգնություն չի տրամադրվել, վերքը պետք է լվանալ մաքուր ջրով՝ այրման ընթացքը դադարեցնելու համար։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Քիմիական նյութի հետ կոնտակտի կամ թունաքիմիկատների օգտագործման պատմություն</li><li>Աղտոտված հագուստ</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Ախտահանումը կարող է անհրաժեշտ լինել թունաքիմիկատների կամ այլ քիմիական նյութերի հետ կոնտակտից հետո (չոր կամ թաց), և կախված նյութից, կարող է ներառել լվացում կամ խոզանակով մաքրում՝ նյութը հեռացնելու համար։</li><li>Սրա համար դուք պետք է կրեք համապատասխան ԱՊՄ։ Օգտվեք ախտահանման տեղական գործելակարգերից՝ մարդկանց և սարքավորումների համար։</li><li>Ոչ բոլոր քիմիական նյութերը կարելի է լվանալով անվտանգ հեռացնել․ որոշները պետք է հեռացվեն հատուկ եղանակներով՝ նոր վնասվածքից խուսափելու համար։</li><li>Իմացեք, թե որ տեղական գերատեսչություններին դիմել կասկածելի բռնկումների կամ վտանգավոր ազդեցությունների դեպքում, ինչպիսիք են քիմիական նյութերի արտահոսքը կամ ճառագայթումը։ Հաճախ հասանելի է աջակցություն և ուղեցույցներ՝ զսպման և վարակազերծման համար։</li></ul>","text":"ՀԻՇԵ՛Ք. Եթե առկա է քիմիական նյութի հետ կոնտակտի պատմություն, պաշտպանեք ինքներդ ձեզ անհատական պաշտպանիչ միջոցներով (ԱՊՄ) և համոզվեք, որ նյութը ճիշտ հեռացված է մաշկից։ Քիմիական այրվածքների դեպքում կարող է անհրաժեշտ լինել տեղեկություն կոնկրետ քիմիական նյութի մասին՝ այն ճիշտ հեռացնելու համար։ Կարևոր է իմանալ՝ արդյոք այրման ընթացքը դադարեցվել է, և քիմիական նյութի հետ կոնտակտի դեպքում՝ արդյոք կատարվել է ախտահանում։ Եթե այրվածք ստանալուց դեռևս չի անցել 3 ժամ և առաջին օգնություն չի տրամադրվել, վերքը պետք է լվանալ մաքուր ջրով՝ այրման ընթացքը դադարեցնելու համար։ Նշաններ և ախտանշաններ Քիմիական նյութի հետ կոնտակտի կամ թունաքիմիկատների օգտագործման պատմություն Աղտոտված հագուստ Վարման հիմնական որոշումներ Ախտահանումը կարող է անհրաժեշտ լինել թունաքիմիկատների կամ այլ քիմիական նյութերի հետ կոնտակտից հետո (չոր կամ թաց), և կախված նյութից, կարող է ներառել լվացում կամ խոզանակով մաքրում՝ նյութը հեռացնելու համար։ Սրա համար դուք պետք է կրեք համապատասխան ԱՊՄ։ Օգտվեք ախտահանման տեղական գործելակարգերից՝ մարդկանց և սարքավորումների համար։ Ոչ բոլոր քիմիական նյութերը կարելի է լվանալով անվտանգ հեռացնել․ որոշները պետք է հեռացվեն հատուկ եղանակներով՝ նոր վնասվածքից խուսափելու համար։ Իմացեք, թե որ տեղական գերատեսչություններին դիմել կասկածելի բռնկումների կամ վտանգավոր ազդեցությունների դեպքում, ինչպիսիք են քիմիական նյութերի արտահոսքը կամ ճառագայթումը։ Հաճախ հասանելի է աջակցություն և ուղեցույցներ՝ զսպման և վարակազերծման համար։"},{"id":"c-Snakebite","cat":"conditions","title":"Օձի կծած","keywords":"Snake bite","html":"<h3>Նշաններ և ախտանշաններ</h3><ul><li>Օձի կծածի պատմություն</li><li>Կծածի հետքերը կարող են երևալ</li><li>Այտուց</li><li>Մաշկի բշտիկային ախտահարումներ</li><li>Կապտուկներ</li><li>Հիպոտենզիա</li><li>Կաթված</li><li>Ցնցումներ</li><li>Արյունահոսություն վերքերից</li></ul><h3>Վարման հիմնական որոշումներ</h3><p>Օձերի կծածների վարման նպատակն է սահմանափակել թույնի տարածումը և ազդեցությունը օրգանիզմի վրա։</p><ul><li>Ամբողջությամբ զննեք հիվանդի մարմինը՝ թաքնված վնասվածքների, ցանավորման, կծածի և այլ վնասվածքների և ախտահարումների առկայության համար։</li><li><a href=\"#/p/s-SnakeBiteWoundManagement\" class=\"xref\">Անշարժացրեք ախտահարված վերջույթը։</a></li><li>Հնարավորության դեպքում լուսանկարեք օձին որոշակի հեռավորությունից և ուղարկեք նկարը հիվանդի հետ (օրինակ՝ հիվանդի հեռախոսով)։</li><li>Շոկի նշանների դեպքում <a href=\"#/p/s-IVFluidAdministrationAdult\" class=\"xref\">տվեք ն/ե հեղուկներ։</a></li><li>Նման հիվանդների մոտ կարող է սկսվել ուշացած շոկ կամ շնչուղիների հետ կապված խնդիրներ։ Ուշադիր հետևեք հիվանդի վիճակին և վաղաժամ պլանավորեք հիվանդի արագ <a href=\"#/p/s-Transferandhandover\" class=\"xref\">փոխանցումը/հանձնումը։</a></li></ul>","text":"Նշաններ և ախտանշաններ Օձի կծածի պատմություն Կծածի հետքերը կարող են երևալ Այտուց Մաշկի բշտիկային ախտահարումներ Կապտուկներ Հիպոտենզիա Կաթված Ցնցումներ Արյունահոսություն վերքերից Վարման հիմնական որոշումներ Օձերի կծածների վարման նպատակն է սահմանափակել թույնի տարածումը և ազդեցությունը օրգանիզմի վրա։ Ամբողջությամբ զննեք հիվանդի մարմինը՝ թաքնված վնասվածքների, ցանավորման, կծածի և այլ վնասվածքների և ախտահարումների առկայության համար։ Անշարժացրեք ախտահարված վերջույթը։ Հնարավորության դեպքում լուսանկարեք օձին որոշակի հեռավորությունից և ուղարկեք նկարը հիվանդի հետ (օրինակ՝ հիվանդի հեռախոսով)։ Շոկի նշանների դեպքում տվեք ն/ե հեղուկներ։ Նման հիվանդների մոտ կարող է սկսվել ուշացած շոկ կամ շնչուղիների հետ կապված խնդիրներ։ Ուշադիր հետևեք հիվանդի վիճակին և վաղաժամ պլանավորեք հիվանդի արագ փոխանցումը/հանձնումը։"},{"id":"c-CircumferentialBurn","cat":"conditions","title":"Օղակող այրվածք","keywords":"Circumferential burn","html":"<p>Այրվածքները, որոնք օղակում են մարմնի որևէ հատված, կարող են գործել որպես կոշտ կապ և կարող են սահմանափակել արյունամատակարարումը (վերջույթի դեպքում) կամ շնչառությունը (կրծքավանդակի կամ որովայնի գոտևորման դեպքում)։</p><h3>Նշաններ և ախտանշաններ</h3><ul><li>Կախված տեղակայումից՝ դրանք</li><li>Կարող են առաջացնել դժվարացած շնչառություն (պարանոցի, կրծքավանդակի կամ որովայնի դեպքում) կամ փակեղային համախտանիշ (վերջույթների դեպքում)</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Սկսեք ն/ե հեղուկներ՝ <a href=\"#/p/c-Burns\" class=\"xref\">այրվածքի չափին</a> համապատասխան։</li><li>Այրվածքները պետք է վիրակապվեն</li><li>Շնչառությունը սահմանափակող կրծքավանդակի կամ որովայնի այրվածքների դեպքում <a href=\"#/p/s-Transferandhandover\" class=\"xref\">պլանավորեք փոխանցում/հանձնում</a> էսխարոտոմիայի համար (վիրաբուժական միջամտություն, որի ժամանակ այրված հյուսվածքի վրա կատարվում են կտրվածքներ և այն ազատում են շնչառությունը սահմանափակելու կամ վերջույթի արյունամատակարարումը խաթարելու վտանգից)։</li></ul>","text":"Այրվածքները, որոնք օղակում են մարմնի որևէ հատված, կարող են գործել որպես կոշտ կապ և կարող են սահմանափակել արյունամատակարարումը (վերջույթի դեպքում) կամ շնչառությունը (կրծքավանդակի կամ որովայնի գոտևորման դեպքում)։ Նշաններ և ախտանշաններ Կախված տեղակայումից՝ դրանք Կարող են առաջացնել դժվարացած շնչառություն (պարանոցի, կրծքավանդակի կամ որովայնի դեպքում) կամ փակեղային համախտանիշ (վերջույթների դեպքում) Վարման հիմնական որոշումներ Սկսեք ն/ե հեղուկներ՝ այրվածքի չափին համապատասխան։ Այրվածքները պետք է վիրակապվեն Շնչառությունը սահմանափակող կրծքավանդակի կամ որովայնի այրվածքների դեպքում պլանավորեք փոխանցում/հանձնում էսխարոտոմիայի համար (վիրաբուժական միջամտություն, որի ժամանակ այրված հյուսվածքի վրա կատարվում են կտրվածքներ և այն ազատում են շնչառությունը սահմանափակելու կամ վերջույթի արյունամատակարարումը խաթարելու վտանգից)։"},{"id":"s-Burnwoundmanagement","cat":"skills","title":"Այրվածքի վարում","keywords":"Burn wound management","html":"<p>Կարևոր է այրվածքները ծածկել վաղ փուլում, որպեսզի այրված հատվածում խոնավություն պահպանվի և վարակի վտանգը նվազի։ Այրվածքները կարող են շատ ցավոտ լինել, ուստի տվեք ցավազրկող։</p><ul><li>Այրվածքը մաքրելու համար օգտագործեք ստերիլ տեխնիկա և սովորական ֆիզիոլոգիական լուծույթ։</li><li>Զգուշությամբ հեռացրեք անջատված, մահացած մաշկը և պատռված, ձիգ կամ բորբոքված բշտերը։</li><li>Այրվածքը ծածկեք ոչ կպչուն վիրակապով՝ խոնավ և ապաքինման համար բարենպաստ միջավայր ապահովելու համար։ Երբ հիվանդին շուտով պետք է տեղափոխել վիրաբուժական բաժանմունք, որպես միջանկյալ միջոց կարելի է այրվածքը փաթաթել մաքուր թափանցիկ պլաստիկ թաղանթով։</li><li>Համոզվեք, որ ամբողջ այրվածքը ծածկված է վիրակապով։</li><li>Եթե հիվանդը դիմել է հին, արդեն վարակված այրվածքով, կիրառեք տեղային հակաբիոտիկ (օրինակ՝ բացիտրացին կամ արծաթի սուլֆադիազին)։ Այդ հիվանդին կարող են անհրաժեշտ լինել նաև ն/ե կամ մ/մ հակաբիոտիկներ։</li><li>Եթե հանձնումը կամ փոխանցումը ձգձգվում է, ապահովեք, որ վիրակապերը փոխվեն ամեն օր։ Վիրակապը փոխելիս միշտ տվեք ցավազրկող։</li></ul>","text":"Կարևոր է այրվածքները ծածկել վաղ փուլում, որպեսզի այրված հատվածում խոնավություն պահպանվի և վարակի վտանգը նվազի։ Այրվածքները կարող են շատ ցավոտ լինել, ուստի տվեք ցավազրկող։ Այրվածքը մաքրելու համար օգտագործեք ստերիլ տեխնիկա և սովորական ֆիզիոլոգիական լուծույթ։ Զգուշությամբ հեռացրեք անջատված, մահացած մաշկը և պատռված, ձիգ կամ բորբոքված բշտերը։ Այրվածքը ծածկեք ոչ կպչուն վիրակապով՝ խոնավ և ապաքինման համար բարենպաստ միջավայր ապահովելու համար։ Երբ հիվանդին շուտով պետք է տեղափոխել վիրաբուժական բաժանմունք, որպես միջանկյալ միջոց կարելի է այրվածքը փաթաթել մաքուր թափանցիկ պլաստիկ թաղանթով։ Համոզվեք, որ ամբողջ այրվածքը ծածկված է վիրակապով։ Եթե հիվանդը դիմել է հին, արդեն վարակված այրվածքով, կիրառեք տեղային հակաբիոտիկ (օրինակ՝ բացիտրացին կամ արծաթի սուլֆադիազին)։ Այդ հիվանդին կարող են անհրաժեշտ լինել նաև ն/ե կամ մ/մ հակաբիոտիկներ։ Եթե հանձնումը կամ փոխանցումը ձգձգվում է, ապահովեք, որ վիրակապերը փոխվեն ամեն օր։ Վիրակապը փոխելիս միշտ տվեք ցավազրկող։"},{"id":"s-Burnfluids","cat":"skills","title":"Այրվածքի վարում. իննի կանոն","keywords":"Burn fluids Rule of Nines Parkland formula","html":"<p>Սա կիրառվում է Փարքլանդի բանաձևով անհրաժեշտ հեղուկների քանակը հաշվարկելու համար։ Մեծահասակների համար օգտվեք իննի կանոնի մարմնի սխեմայից, իսկ երեխաների և կրծքի տարիքի երեխաների համար՝ հարմարեցված սխեմայից (տես ստորև նկարը)։</p><p>Մարմինը բաժանված է հատվածների, որոնցից յուրաքանչյուրը կազմում է մարմնի ընդհանուր մակերեսի 9%-ը։ Երեխաների տոկոսները տարբեր են՝ մարմնի համաչափությունների տարբերության պատճառով, օրինակ՝ ավելի մեծ գլուխ և ավելի փոքր վերջույթներ (տես ստորև նկարները)։</p><ul><li>Գնահատեք հիվանդին՝ օգտվելով ստորև ներկայացված սխեմայից։</li><li>Նշեք այրվածքի հատվածները և ստվերեք դրանք սխեմայի վրա։</li><li>Ստվերած հատվածի կողքին գրեք այրվածքի խորությունը (տես ստորև՝ այրվածքի խորության գնահատումը)։</li><li>Երբ սխեմայի վրա (դիմացից և հետևից) նշել եք հիվանդի մոտ գնահատված բոլոր այրվածքները, գումարեք տոկոսները։</li><li>Սա ձեզ կտա այրվածքի ընդհանուր մակերեսը (ԱԸՄ)։</li></ul><figure><img class=\"fig\" src=\"img/burn-adult.webp\" alt=\"Մեծահասակի մարմնի այրված մակերեսը\"><figcaption>Մեծահասակի մարմնի այրված մակերեսը</figcaption></figure><figure><img class=\"fig\" src=\"img/burn-child.webp\" alt=\"Երեխայի մարմնի այրված մակերեսը\"><figcaption>Երեխայի մարմնի այրված մակերեսը</figcaption></figure><h2>Այրվածքի վարում. հեղուկային վերակենդանացում այրվածքային վնասվածքի դեպքում</h2><p>Այրվածքային վնասվածք ունեցող մեծահասակին կամ երեխային կարող է անհրաժեշտ լինել հեղուկային վերակենդանացում։ Սկսեք հեղուկային վերակենդանացումը հետևյալ դեպքերում՝</p><ul><li>Մասնակի կամ ամբողջ խորությամբ այրվածք՝ մարմնի ընդհանուր մակերեսի 15%-ին հավասար կամ ավելի՝ մեծահասակների մոտ։</li><li>Մասնակի կամ ամբողջ խորությամբ այրվածք՝ մարմնի ընդհանուր մակերեսի 10%-ին հավասար կամ ավելի՝ երեխաների մոտ։</li></ul><h2>Այրվածքի վարում. Փարքլանդի բանաձևով հաշվարկը՝ առաջին 24 ժամվա համար</h2><p>4 մլ ն/ե հեղուկ × քաշը կգ-ներով × այրվածքի ընդհանուր մակերեսի %*</p><p>*Այրվածքի ընդհանուր մակերեսի % = մասնակի խորությամբ այրվածքի % + ամբողջ խորությամբ այրվածքի % (մակերեսային այրվածքի %-ը հաշվարկի մեջ ՉԻ մտնում)</p><p>Փարքլանդի բանաձևը հեղուկային վերականգնման մարտավարություն է այրվածքից հետո առաջին 24 ժամվա համար։ Այրվածքից 24 ժամ անց դիմած հիվանդներին նույնպես անհրաժեշտ կլինի հեղուկային վերականգնում, սակայն Փարքլանդի բանաձևը 24 ժամից հետո չի օգտագործվում։</p><ul><li>Հեղուկի առաջին կեսը պետք է ներարկվի այրվածքից հետո առաջին 8 ժամվա ընթացքում (ՈՉ թե բուժօգնության հասնելուց հետո)։</li><li>Երկրորդ կեսը պետք է ներարկվի հաջորդ 16 ժամվա ընթացքում։</li><li>Մեծահասակներին տվեք նորմալ ֆիզիոլոգիական լուծույթ կամ Ռինգերի լակտացված լուծույթ։</li><li>Երեխաների դեպքում օգտագործեք դեքստրոզա պարունակող հեղուկ (սկզբնական վերակենդանացման ժամանակ՝ Ռինգերի լակտացված լուծույթ 5%-անոց դեքստրոզայով կամ նորմալ ֆիզիոլոգիական լուծույթ 5%-անոց դեքստրոզայով)։ Եթե դեքստրոզա պարունակող հեղուկներ առկա չեն, ն/ե հեղուկների հետ տվեք դեքստրոզայի լրացուցիչ դեղաչափ (ներերակային կամ բերանով)։</li></ul><p>Երեխաների շարունակական խնամքի դեպքում վերը հաշվարկված Փարքլանդի անհետաձգելի հեղուկային վերակենդանացման հեղուկները ՊԵՏՔ Է ԳՈՒՄԱՐՎԵՆ հիվանդանոցային խնամքի գործելակարգերով անհրաժեշտ պահպանման հեղուկներին (տե՛ս «ԱՀԿ գրպանի ձեռնարկ երեխաների հիվանդանոցային խնամքի համար», 2013)։</p>","text":"Սա կիրառվում է Փարքլանդի բանաձևով անհրաժեշտ հեղուկների քանակը հաշվարկելու համար։ Մեծահասակների համար օգտվեք իննի կանոնի մարմնի սխեմայից, իսկ երեխաների և կրծքի տարիքի երեխաների համար՝ հարմարեցված սխեմայից (տես ստորև նկարը)։ Մարմինը բաժանված է հատվածների, որոնցից յուրաքանչյուրը կազմում է մարմնի ընդհանուր մակերեսի 9%-ը։ Երեխաների տոկոսները տարբեր են՝ մարմնի համաչափությունների տարբերության պատճառով, օրինակ՝ ավելի մեծ գլուխ և ավելի փոքր վերջույթներ (տես ստորև նկարները)։ Գնահատեք հիվանդին՝ օգտվելով ստորև ներկայացված սխեմայից։ Նշեք այրվածքի հատվածները և ստվերեք դրանք սխեմայի վրա։ Ստվերած հատվածի կողքին գրեք այրվածքի խորությունը (տես ստորև՝ այրվածքի խորության գնահատումը)։ Երբ սխեմայի վրա (դիմացից և հետևից) նշել եք հիվանդի մոտ գնահատված բոլոր այրվածքները, գումարեք տոկոսները։ Սա ձեզ կտա այրվածքի ընդհանուր մակերեսը (ԱԸՄ)։ Մեծահասակի մարմնի այրված մակերեսը Երեխայի մարմնի այրված մակերեսը Այրվածքի վարում. հեղուկային վերակենդանացում այրվածքային վնասվածքի դեպքում Այրվածքային վնասվածք ունեցող մեծահասակին կամ երեխային կարող է անհրաժեշտ լինել հեղուկային վերակենդանացում։ Սկսեք հեղուկային վերակենդանացումը հետևյալ դեպքերում՝ Մասնակի կամ ամբողջ խորությամբ այրվածք՝ մարմնի ընդհանուր մակերեսի 15%-ին հավասար կամ ավելի՝ մեծահասակների մոտ։ Մասնակի կամ ամբողջ խորությամբ այրվածք՝ մարմնի ընդհանուր մակերեսի 10%-ին հավասար կամ ավելի՝ երեխաների մոտ։ Այրվածքի վարում. Փարքլանդի բանաձևով հաշվարկը՝ առաջին 24 ժամվա համար 4 մլ ն/ե հեղուկ × քաշը կգ-ներով × այրվածքի ընդհանուր մակերեսի %* *Այրվածքի ընդհանուր մակերեսի % = մասնակի խորությամբ այրվածքի % + ամբողջ խորությամբ այրվածքի % (մակերեսային այրվածքի %-ը հաշվարկի մեջ ՉԻ մտնում) Փարքլանդի բանաձևը հեղուկային վերականգնման մարտավարություն է այրվածքից հետո առաջին 24 ժամվա համար։ Այրվածքից 24 ժամ անց դիմած հիվանդներին նույնպես անհրաժեշտ կլինի հեղուկային վերականգնում, սակայն Փարքլանդի բանաձևը 24 ժամից հետո չի օգտագործվում։ Հեղուկի առաջին կեսը պետք է ներարկվի այրվածքից հետո առաջին 8 ժամվա ընթացքում (ՈՉ թե բուժօգնության հասնելուց հետո)։ Երկրորդ կեսը պետք է ներարկվի հաջորդ 16 ժամվա ընթացքում։ Մեծահասակներին տվեք նորմալ ֆիզիոլոգիական լուծույթ կամ Ռինգերի լակտացված լուծույթ։ Երեխաների դեպքում օգտագործեք դեքստրոզա պարունակող հեղուկ (սկզբնական վերակենդանացման ժամանակ՝ Ռինգերի լակտացված լուծույթ 5%-անոց դեքստրոզայով կամ նորմալ ֆիզիոլոգիական լուծույթ 5%-անոց դեքստրոզայով)։ Եթե դեքստրոզա պարունակող հեղուկներ առկա չեն, ն/ե հեղուկների հետ տվեք դեքստրոզայի լրացուցիչ դեղաչափ (ներերակային կամ բերանով)։ Երեխաների շարունակական խնամքի դեպքում վերը հաշվարկված Փարքլանդի անհետաձգելի հեղուկային վերակենդանացման հեղուկները ՊԵՏՔ Է ԳՈՒՄԱՐՎԵՆ հիվանդանոցային խնամքի գործելակարգերով անհրաժեշտ պահպանման հեղուկներին (տե՛ս «ԱՀԿ գրպանի ձեռնարկ երեխաների հիվանդանոցային խնամքի համար», 2013)։"},{"id":"s-Needledecompression","cat":"skills","title":"Ասեղային դեկոմպրեսիա","keywords":"Needle decompression tension pneumothorax","html":"<p>Կրծքավանդակի ասեղային դեկոմպրեսիան կյանքը փրկող անհետաձգելի միջամտություն է՝ լարված պնևմոթորաքսի կասկածի դեպքում (թոքերի և կրծքավանդակի պատի միջև եղած խոռոչում օդի կամ գազի առկայությունը, որը չափազանց ճնշում է առաջացնում հակառակ թոքի, մեծ արյունատար անոթների և սրտի վրա)։ Հիվանդները լարված պնևմոթորաքսից կարող են շատ արագ մահանալ։ Նրանց անհրաժեշտ է կրծքավանդակի խողովակի (պլևրալ դրենաժի) անհետաձգելի տեղադրում, սակայն անհետաձգելի ասեղային դեկոմպրեսիան կթուլացնի անմիջական ճնշումը և ժամանակ կտա կրծքավանդակի խողովակի տեղադրման նպատակով հիվանդի հանձնման/փոխանցման համար։</p><ul><li>Բացեք հիվանդի կրծքավանդակը և գնահատեք շնչառությունը։</li><li>Լարված պնևմոթորաքսը ախտորոշվում է, եթե առկա են շոկ և հետևյալ նշանները՝<ul><li>Դժվարացած շնչառություն</li><li>Շնչառական ձայների բացակայություն՝ ախտահարված կողմում</li><li>Հիպոտենզիա</li><li>Պարանոցի լայնացած երակներ</li><li>Հիպերռեզոնանս՝ ախտահարված կողմը մատնաբախելիս և շնչափողի տեղաշարժ՝ ախտահարված կողմից հակառակ ուղղությամբ</li></ul></li><li>Տեղադրեք մեծ տրամաչափի (ցանկալի է 14–16G) ն/ե կատետր ախտահարված կողմում՝ անրակի միջին կետին համապատասխան, երրորդ կողի վերին եզրի երկայնքով՝ երկրորդ միջկողային տարածության միջով։<ul><li>Լարված պնևմոթորաքսի դեպքում կլսվի դուրս ազատվող օդի ձայն։</li></ul></li><li>Տվեք բարձր կոնցենտրացիայով թթվածին (մեկուսացնող պարկով թթվածնային դիմակով)։</li><li>Դրեք ն/ե կատետրեր և տվեք ն/ե հեղուկներ։</li><li>Անմիջապես ուղղորդեք և տեղափոխեք հիվանդին վերջնական խնամք ապահովող բաժանմունք։</li></ul><p>Կրծքավանդակի խողովակը պետք է տեղադրել հնարավորինս արագ՝ ասեղային դեկոմպրեսիայից հետո (նույնիսկ եթե օդի ուժեղ հոսանք չի եղել) կամ ցանկացած ժամանակ հեմոթորաքսի կասկածի դեպքում։</p><figure><img class=\"fig\" src=\"img/needle-decompression.webp\" alt=\"Ասեղային դեկոմպրեսիա\"><figcaption>Ասեղային դեկոմպրեսիա</figcaption></figure>","text":"Կրծքավանդակի ասեղային դեկոմպրեսիան կյանքը փրկող անհետաձգելի միջամտություն է՝ լարված պնևմոթորաքսի կասկածի դեպքում (թոքերի և կրծքավանդակի պատի միջև եղած խոռոչում օդի կամ գազի առկայությունը, որը չափազանց ճնշում է առաջացնում հակառակ թոքի, մեծ արյունատար անոթների և սրտի վրա)։ Հիվանդները լարված պնևմոթորաքսից կարող են շատ արագ մահանալ։ Նրանց անհրաժեշտ է կրծքավանդակի խողովակի (պլևրալ դրենաժի) անհետաձգելի տեղադրում, սակայն անհետաձգելի ասեղային դեկոմպրեսիան կթուլացնի անմիջական ճնշումը և ժամանակ կտա կրծքավանդակի խողովակի տեղադրման նպատակով հիվանդի հանձնման/փոխանցման համար։ Բացեք հիվանդի կրծքավանդակը և գնահատեք շնչառությունը։ Լարված պնևմոթորաքսը ախտորոշվում է, եթե առկա են շոկ և հետևյալ նշանները՝ Դժվարացած շնչառություն Շնչառական ձայների բացակայություն՝ ախտահարված կողմում Հիպոտենզիա Պարանոցի լայնացած երակներ Հիպերռեզոնանս՝ ախտահարված կողմը մատնաբախելիս և շնչափողի տեղաշարժ՝ ախտահարված կողմից հակառակ ուղղությամբ Տեղադրեք մեծ տրամաչափի (ցանկալի է 14–16G) ն/ե կատետր ախտահարված կողմում՝ անրակի միջին կետին համապատասխան, երրորդ կողի վերին եզրի երկայնքով՝ երկրորդ միջկողային տարածության միջով։ Լարված պնևմոթորաքսի դեպքում կլսվի դուրս ազատվող օդի ձայն։ Տվեք բարձր կոնցենտրացիայով թթվածին (մեկուսացնող պարկով թթվածնային դիմակով)։ Դրեք ն/ե կատետրեր և տվեք ն/ե հեղուկներ։ Անմիջապես ուղղորդեք և տեղափոխեք հիվանդին վերջնական խնամք ապահովող բաժանմունք։ Կրծքավանդակի խողովակը պետք է տեղադրել հնարավորինս արագ՝ ասեղային դեկոմպրեսիայից հետո (նույնիսկ եթե օդի ուժեղ հոսանք չի եղել) կամ ցանկացած ժամանակ հեմոթորաքսի կասկածի դեպքում։ Ասեղային դեկոմպրեսիա"},{"id":"s-Uterinemassage","cat":"skills","title":"Արգանդի մերսում հետծննդաբերական արյունահոսության դեպքում","keywords":"Uterine massage postpartum haemorrhage","html":"<ul><li>Բացատրեք կնոջը, թե ինչ եք անելու և ինչու։</li><li>Նպատակը արգանդը սեղմելն է ձեր ձեռքի և արգանդի հետևում գտնվող ոսկրային կառուցվածքների (օրինակ՝ սրբոսկրի/մեջքի ստորին հատվածի) միջև։</li><li>Ձեր ձեռքը դրեք կնոջ որովայնի վրա։ Որովայնի պատի միջով շոշափեք արգանդը և վերցրեք այն ձեռքի մեջ՝ բաժակի նման։ Սա կապահովի, որ մերսելիս արգանդը մնա ձեր ձեռքի տակ։ Պարզապես մի սեղմեք արգանդը, այլ համոզվեք, որ շրջանաձև շարժումներով մերսելիս ուժեղ ճնշում եք գործադրում դեպի հիվանդի մեջքը։</li><li>Մերսեք արգանդը, մինչև այն շատ պինդ դառնա։ Կրճատված վիճակում այն պետք է հիշեցնի 10 սմ-անոց քար հիվանդի ստորին որովայնում։</li><li>Մի դադարեցրեք մերսումը, քանի դեռ արգանդը չի կրճատվել (պինդ չի դարձել)։</li><li>Համոզվեք, որ մերսումը դադարեցնելուց հետո արգանդը չի թուլանում (չի փափկում)։ Եթե թուլանա, վերսկսեք մերսումը։</li><li>Անընդհատ վերագնահատեք վագինալ արյունահոսությունը։</li><li>Հաճախակի ստուգեք կենսացուցանիշները։</li></ul><figure><img class=\"fig\" src=\"img/uterine-massage.webp\" alt=\"Արգանդի մերսում հետծննդաբերական արյունահոսության դեպքում\"><figcaption>Արգանդի մերսում հետծննդաբերական արյունահոսության դեպքում</figcaption></figure>","text":"Բացատրեք կնոջը, թե ինչ եք անելու և ինչու։ Նպատակը արգանդը սեղմելն է ձեր ձեռքի և արգանդի հետևում գտնվող ոսկրային կառուցվածքների (օրինակ՝ սրբոսկրի/մեջքի ստորին հատվածի) միջև։ Ձեր ձեռքը դրեք կնոջ որովայնի վրա։ Որովայնի պատի միջով շոշափեք արգանդը և վերցրեք այն ձեռքի մեջ՝ բաժակի նման։ Սա կապահովի, որ մերսելիս արգանդը մնա ձեր ձեռքի տակ։ Պարզապես մի սեղմեք արգանդը, այլ համոզվեք, որ շրջանաձև շարժումներով մերսելիս ուժեղ ճնշում եք գործադրում դեպի հիվանդի մեջքը։ Մերսեք արգանդը, մինչև այն շատ պինդ դառնա։ Կրճատված վիճակում այն պետք է հիշեցնի 10 սմ-անոց քար հիվանդի ստորին որովայնում։ Մի դադարեցրեք մերսումը, քանի դեռ արգանդը չի կրճատվել (պինդ չի դարձել)։ Համոզվեք, որ մերսումը դադարեցնելուց հետո արգանդը չի թուլանում (չի փափկում)։ Եթե թուլանա, վերսկսեք մերսումը։ Անընդհատ վերագնահատեք վագինալ արյունահոսությունը։ Հաճախակի ստուգեք կենսացուցանիշները։ Արգանդի մերսում հետծննդաբերական արյունահոսության դեպքում"},{"id":"s-Externalbleedingcontrol","cat":"skills","title":"Արտաքին արյունահոսություն","keywords":"External bleeding direct pressure tourniquet wound packing","html":"<ul><li><strong>Անմիջական ճնշում արտաքին արյունահոսության դեպքում</strong></li><li><strong>Խորը վերքի տամպոնավորում արտաքին արյունահոսության դեպքում</strong></li><li><strong>Լարանի կիրառման տեխնիկան՝ անկառավարելի արտաքին արյունահոսության դեպքում</strong></li></ul><h2>1. Անմիջական ճնշում արտաքին արյունահոսության դեպքում</h2><p>Խորը և ուժեղ արյունահոսող վերքի արյունահոսությունը կարող է ինքնուրույն չդադարել։ Անմիջական ճնշում գործադրելը մաքուր վիրակապով, օրինակ՝ թանզիֆե վիրախծուծով, կարող է օգնել դանդաղեցնել կամ դադարեցնել արյունահոսությունը (տես նկարը)։</p><ul><li>Ձեռնոցներ կրեք։</li><li>Օգտագործեք թանզիֆե վիրախծուծ կամ այլ մաքուր, ոչ կպչուն վիրակապ։</li><li>Մի օգտագործեք ծավալուն վիրակապեր, քանի որ դրանք կարող են դժվարացնել բավարար ճնշման կիրառումը ճիշտ տեղում։</li><li>Հնարավորինս պինդ ուղղակիորեն սեղմեք արյունահոսության աղբյուրը, սովորաբար երկու կամ երեք մատով։</li><li>Եթե վերքը վերջույթի վրա է, վերջույթը բարձրացրեք սրտի մակարդակից վերև։</li><li>Եթե առաջին վիրակապը ներծծվում է արյամբ, մի հեռացրեք այն, քանի որ դա կարող է հեռացնել ձևավորված մակարդուկները։ Փոխարենը ավելացրեք ևս մեկ շերտ և ամուր ճնշում գործադրեք։</li><li>Արյունահոսությունը դադարեցնելուց հետո դրեք վիրակապ՝ թանզիֆը/բարձիկը տեղում պահելու համար։</li><li>Եթե արյունահոսությունը չի դադարում, դիտարկեք խորը վերքի տամպոնավորումը կամ լարանի կիրառումը (տես հաջորդ բաժինը)։</li></ul><figure><img class=\"fig\" src=\"img/direct-pressure.webp\" alt=\"Վերքին անմիջական ճնշում\"><figcaption>Վերքին անմիջական ճնշում</figcaption></figure><h2>2. Խորը վերքի տամպոնավորում արտաքին արյունահոսության դեպքում</h2><p>Եթե վերքը խորն է կամ լայն բացվածքով է, և սովորական ճնշումը չի դադարեցնում արյունահոսությունը, հնարավոր է՝ խորը վերքի տամպոնավորումն օգնի։ Սակայն տամպոնավորումը ժամանակավոր միջամտություն է՝ արյունահոսությունը դադարեցնելու համար, քանի որ 24 ժամից ավելի թողնելու դեպքում այն կարող է հանգեցնել վարակի։</p><ul><li>Ձեռնոցներ կրեք։</li><li>Միշտ գնահատեք վերջույթի անոթազարկը, մազանոթների վերալցումը և զգայունությունը՝ ցանկացած վերք վիրակապելուց կամ բեկակալ դնելուց առաջ և հետո։</li><li>Լավ լվացեք վերքը՝ առնվազն մեկ լիտր մաքուր ջրով (հնարավորության դեպքում՝ ճնշման տակ. տե՛ս հաջորդ բաժինը)։</li><li>Օգտագործեք թանզիֆ կամ այլ մաքուր, կոմպակտ նյութ՝ վերքի խոռոչն ամբողջությամբ լցնելու համար։</li><li>Վերքի մակերեսին օգտագործեք լրացուցիչ թանզիֆ և անմիջական ճնշում գործադրեք ձեռնոցով ձեռքով կամ վերքի/վերջույթի շուրջ ամուր կապած վիրակապով։</li><li>Տամպոնավորում պահանջող վերջույթի վերքերի դեպքում տեղադրեք բեկակալ՝ կրկնակի արյունահոսության ռիսկը նվազեցնելու համար։</li><li>Խորը վերքի տամպոնը չի կարելի վերքում պահել 24 ժամից ավելի՝ վարակի ռիսկի պատճառով։</li><li>Եթե արյունահոսությունը չդադարի, դիտարկեք լարանի օգտագործումը (տես հաջորդ բաժինը)։</li></ul><h2>3. Լարանի կիրառման տեխնիկան՝ անկառավարելի արտաքին արյունահոսության դեպքում</h2><p>Ձեզանից չի պահանջվում կատարել լարանի տեղադրման մեթոդը, ԲԱՅՑ դուք պետք է իմանաք, թե կյանքին սպառնացող որ իրավիճակներում այն կարող է օգտագործվել, որոնք են դրա օգտագործման հետ կապված հատուկ նկատառումները և ինչպիսին պետք է լինի հիվանդի ընթացիկ խնամքը։</p><p>Այս մեթոդը կիրառեք ՄԻԱՅՆ եթե արյունահոսության կասեցման մնացած միջոցառումները արդյունք չեն տվել ԵՎ արյունահոսությունը կյանքին սպառնացող է։ Եթե լարան դնեք, հնարավոր է, որ լարանից ներքև գտնվող հյուսվածքները մշտապես վնասվեն և նույնիսկ անդամահատման կարիք առաջանա։ Եթե դիտարկում եք լարանի օգտագործումը, ԱՆՄԻՋԱՊԵՍ ՕԳՆՈՒԹՅՈՒՆ ԿԱՆՉԵՔ և պլանավորեք հիվանդի հանձնում/փոխանցում վիրահատության հնարավորություն ունեցող բաժանմունք։</p><ul><li>Առկայության դեպքում օգտագործեք պնևմատիկ լարան (օրինակ՝ արյան ճնշումը չափելու մանժետ)՝ պաշտպանված մաշկի վրա, և փչեք մինչև արյունահոսությունը դադարի։ Եթե ոչ, օգտագործեք հաստ ժապավեն, գործվածքի կտոր կամ գոտի (որքան լայն, այնքան լավ)՝ պաշտպանված մաշկի վրա։</li><li>Լարանը դրեք վերքին հնարավորինս մոտ, սակայն ոչ վերքի կամ կոտրվածքի վրա։</li><li>Կիրառեք այնքան ճնշում, որ դիստալ անոթազարկերը անհետանան, և կրկին գնահատեք արյունահոսությունը։</li><li>Եթե արյունահոսությունը դադարի, թողեք վիրակապն իր տեղում, եթե այն արդեն առկա է, կամ վիրակապեք վերքը, և պատրաստվեք հիվանդի հանձնմանը/փոխանցմանը վիրաբուժական խնամքի բաժանմունք։</li><li>Եթե արյունահոսությունը չդադարի, ավելացրեք լարանի ճնշումը, մինչև որ ուժեղ արյունահոսությունը դադարի։</li><li>Գրանցեք լարանի տեղադրման ճշգրիտ ժամը ձեր նշումներում ԵՎ գրեք այն հիվանդի մաշկի կամ հենց լարանի վրա։</li><li>Հնարավորինս շուտ (և երբեք ոչ ուշ, քան լարան դնելուց հետո 2 ժամվա ընթացքում) հանձնեք հիվանդին առավել բարձր կարգի սպասարկողի։</li><li>Լարանը պետք է թուլացնել յուրաքանչյուր 2 ժամը մեկ՝ առնվազն 10 րոպեով։ Այդ ընթացքում արյունահոսող հատվածին անմիջական ճնշում գործադրեք։ Լարանը նորից մի կիրառեք, եթե չկա արյունահոսության շարունակվելու ակնհայտ նշան։</li><li>Լարանի տեղադրման վայրը. լարաններ դրվում են միայն վերջույթների վրա՝ արյունահոսության մակարդակից վերև։ Ոսկորների և արյունատար անոթների փոխդասավորության պատճառով բազուկի կամ ազդրի վրա դրված լարանը հաճախ ավելի արդյունավետ է, քան արմունկից կամ ծնկից ներքև դրվածը։</li><li>Համոզվեք, որ լարանը պարզորոշ երևում է։</li><li>Հիշեք, որ լարանը պետք է դնել որպես վերջին միջոց։ Եթե լարան եք դնում, դուք կանգնեցնում եք վերջույթի արյան մատակարարումը, ուստի դա կատարեք միայն կյանքին սպառնացող արյունահոսության դեպքում։ Լարանի օգտագործման բացարձակ ցուցման դեպքում, օգտագործեք լայն, սակայն սեղմող ժապավեն։</li></ul>","text":"Անմիջական ճնշում արտաքին արյունահոսության դեպքում Խորը վերքի տամպոնավորում արտաքին արյունահոսության դեպքում Լարանի կիրառման տեխնիկան՝ անկառավարելի արտաքին արյունահոսության դեպքում 1. Անմիջական ճնշում արտաքին արյունահոսության դեպքում Խորը և ուժեղ արյունահոսող վերքի արյունահոսությունը կարող է ինքնուրույն չդադարել։ Անմիջական ճնշում գործադրելը մաքուր վիրակապով, օրինակ՝ թանզիֆե վիրախծուծով, կարող է օգնել դանդաղեցնել կամ դադարեցնել արյունահոսությունը (տես նկարը)։ Ձեռնոցներ կրեք։ Օգտագործեք թանզիֆե վիրախծուծ կամ այլ մաքուր, ոչ կպչուն վիրակապ։ Մի օգտագործեք ծավալուն վիրակապեր, քանի որ դրանք կարող են դժվարացնել բավարար ճնշման կիրառումը ճիշտ տեղում։ Հնարավորինս պինդ ուղղակիորեն սեղմեք արյունահոսության աղբյուրը, սովորաբար երկու կամ երեք մատով։ Եթե վերքը վերջույթի վրա է, վերջույթը բարձրացրեք սրտի մակարդակից վերև։ Եթե առաջին վիրակապը ներծծվում է արյամբ, մի հեռացրեք այն, քանի որ դա կարող է հեռացնել ձևավորված մակարդուկները։ Փոխարենը ավելացրեք ևս մեկ շերտ և ամուր ճնշում գործադրեք։ Արյունահոսությունը դադարեցնելուց հետո դրեք վիրակապ՝ թանզիֆը/բարձիկը տեղում պահելու համար։ Եթե արյունահոսությունը չի դադարում, դիտարկեք խորը վերքի տամպոնավորումը կամ լարանի կիրառումը (տես հաջորդ բաժինը)։ Վերքին անմիջական ճնշում 2. Խորը վերքի տամպոնավորում արտաքին արյունահոսության դեպքում Եթե վերքը խորն է կամ լայն բացվածքով է, և սովորական ճնշումը չի դադարեցնում արյունահոսությունը, հնարավոր է՝ խորը վերքի տամպոնավորումն օգնի։ Սակայն տամպոնավորումը ժամանակավոր միջամտություն է՝ արյունահոսությունը դադարեցնելու համար, քանի որ 24 ժամից ավելի թողնելու դեպքում այն կարող է հանգեցնել վարակի։ Ձեռնոցներ կրեք։ Միշտ գնահատեք վերջույթի անոթազարկը, մազանոթների վերալցումը և զգայունությունը՝ ցանկացած վերք վիրակապելուց կամ բեկակալ դնելուց առաջ և հետո։ Լավ լվացեք վերքը՝ առնվազն մեկ լիտր մաքուր ջրով (հնարավորության դեպքում՝ ճնշման տակ. տե՛ս հաջորդ բաժինը)։ Օգտագործեք թանզիֆ կամ այլ մաքուր, կոմպակտ նյութ՝ վերքի խոռոչն ամբողջությամբ լցնելու համար։ Վերքի մակերեսին օգտագործեք լրացուցիչ թանզիֆ և անմիջական ճնշում գործադրեք ձեռնոցով ձեռքով կամ վերքի/վերջույթի շուրջ ամուր կապած վիրակապով։ Տամպոնավորում պահանջող վերջույթի վերքերի դեպքում տեղադրեք բեկակալ՝ կրկնակի արյունահոսության ռիսկը նվազեցնելու համար։ Խորը վերքի տամպոնը չի կարելի վերքում պահել 24 ժամից ավելի՝ վարակի ռիսկի պատճառով։ Եթե արյունահոսությունը չդադարի, դիտարկեք լարանի օգտագործումը (տես հաջորդ բաժինը)։ 3. Լարանի կիրառման տեխնիկան՝ անկառավարելի արտաքին արյունահոսության դեպքում Ձեզանից չի պահանջվում կատարել լարանի տեղադրման մեթոդը, ԲԱՅՑ դուք պետք է իմանաք, թե կյանքին սպառնացող որ իրավիճակներում այն կարող է օգտագործվել, որոնք են դրա օգտագործման հետ կապված հատուկ նկատառումները և ինչպիսին պետք է լինի հիվանդի ընթացիկ խնամքը։ Այս մեթոդը կիրառեք ՄԻԱՅՆ եթե արյունահոսության կասեցման մնացած միջոցառումները արդյունք չեն տվել ԵՎ արյունահոսությունը կյանքին սպառնացող է։ Եթե լարան դնեք, հնարավոր է, որ լարանից ներքև գտնվող հյուսվածքները մշտապես վնասվեն և նույնիսկ անդամահատման կարիք առաջանա։ Եթե դիտարկում եք լարանի օգտագործումը, ԱՆՄԻՋԱՊԵՍ ՕԳՆՈՒԹՅՈՒՆ ԿԱՆՉԵՔ և պլանավորեք հիվանդի հանձնում/փոխանցում վիրահատության հնարավորություն ունեցող բաժանմունք։ Առկայության դեպքում օգտագործեք պնևմատիկ լարան (օրինակ՝ արյան ճնշումը չափելու մանժետ)՝ պաշտպանված մաշկի վրա, և փչեք մինչև արյունահոսությունը դադարի։ Եթե ոչ, օգտագործեք հաստ ժապավեն, գործվածքի կտոր կամ գոտի (որքան լայն, այնքան լավ)՝ պաշտպանված մաշկի վրա։ Լարանը դրեք վերքին հնարավորինս մոտ, սակայն ոչ վերքի կամ կոտրվածքի վրա։ Կիրառեք այնքան ճնշում, որ դիստալ անոթազարկերը անհետանան, և կրկին գնահատեք արյունահոսությունը։ Եթե արյունահոսությունը դադարի, թողեք վիրակապն իր տեղում, եթե այն արդեն առկա է, կամ վիրակապեք վերքը, և պատրաստվեք հիվանդի հանձնմանը/փոխանցմանը վիրաբուժական խնամքի բաժանմունք։ Եթե արյունահոսությունը չդադարի, ավելացրեք լարանի ճնշումը, մինչև որ ուժեղ արյունահոսությունը դադարի։ Գրանցեք լարանի տեղադրման ճշգրիտ ժամը ձեր նշումներում ԵՎ գրեք այն հիվանդի մաշկի կամ հենց լարանի վրա։ Հնարավորինս շուտ (և երբեք ոչ ուշ, քան լարան դնելուց հետո 2 ժամվա ընթացքում) հանձնեք հիվանդին առավել բարձր կարգի սպասարկողի։ Լարանը պետք է թուլացնել յուրաքանչյուր 2 ժամը մեկ՝ առնվազն 10 րոպեով։ Այդ ընթացքում արյունահոսող հատվածին անմիջական ճնշում գործադրեք։ Լարանը նորից մի կիրառեք, եթե չկա արյունահոսության շարունակվելու ակնհայտ նշան։ Լարանի տեղադրման վայրը. լարաններ դրվում են միայն վերջույթների վրա՝ արյունահոսության մակարդակից վերև։ Ոսկորների և արյունատար անոթների փոխդասավորության պատճառով բազուկի կամ ազդրի վրա դրված լարանը հաճախ ավելի արդյունավետ է, քան արմունկից կամ ծնկից ներքև դրվածը։ Համոզվեք, որ լարանը պարզորոշ երևում է։ Հիշեք, որ լարանը պետք է դնել որպես վերջին միջոց։ Եթե լարան եք դնում, դուք կանգնեցնում եք վերջույթի արյան մատակարարումը, ուստի դա կատարեք միայն կյանքին սպառնացող արյունահոսության դեպքում։ Լարանի օգտագործման բացարձակ ցուցման դեպքում, օգտագործեք լայն, սակայն սեղմող ժապավեն։"},{"id":"s-Basicairwaydeviceinsertion","cat":"skills","title":"Բերան-ըմպանային օդուղու տեղադրում (ԲԸՕ)","keywords":"Oropharyngeal airway OPA nasopharyngeal airway NPA insertion","html":"<ul><li>Բերան-ըմպանային օդուղին (ԲԸՕ) տեղադրում են միայն այն ժամանակ, երբ հիվանդը անգիտակից վիճակում է։ Գիտակից հիվանդը չի դիմանա ԲԸՕ-ին և դուրս կհրի այն։ Եթե հիվանդը դիմադրում է, որձկում է կամ փսխում է, անմիջապես հեռացրեք սարքը։</li><li>Վնասվածքի պատմության դեպքում միշտ ապահովեք ողնաշարի պարանոցային հատվածի անշարժությունը։</li><li>Որոշեք ԲԸՕ-ի ճիշտ չափը՝ չափելով ականջի բլթակի ծայրից մինչև բերանի անկյունը։</li><li>Բացեք հիվանդի բերանը զգուշությամբ՝ փորձելով մատները չթողնել ատամների արանքում (որպեսզի հիվանդը պատահաբար չկծի ձեր մատները)։</li><li>Տեղադրեք ԲԸՕ-ն կոր հատվածը դեպի կողք՝ ծայրը դեպի այտը։</li><li>Զգուշորեն հրեք ԲԸՕ-ն բերանի մեջ և, երբ այլևս չեք կարողանում հրել, շրջեք ԲԸՕ-ն 90 աստիճան, այնպես որ ծայրն ուղղված լինի ներքև՝ դեպի կոկորդ, և համապատասխանի լեզվի կորին (տես նկարը)։</li><li>Անհրաժեշտության դեպքում հրեք ԲԸՕ-ի մնացած մասը, որպեսզի կցապռունկը (լայն, տափակ եզրը) նստի հիվանդի շրթունքներին։ Սա անելիս, համոզվեք, որ ԲԸՕ-ի ծայրը լեզուն դեպի ներքև չի սեղմում՝ խցանելով կոկորդի հետին հատվածը։</li><li>Նորից ստուգեք, որ ԲԸՕ-ն լեզուն դեպի ներքև չի հրել և շնչուղիները չի խցանել։</li><li>Հնարավորության դեպքում հիվանդին տվեք թթվածին:</li></ul><figure><img class=\"fig\" src=\"img/opa.webp\" alt=\"Բերան-ըմպանային օդուղու (ԲԸՕ) տեղադրում\"><figcaption>Բերան-ըմպանային օդուղու (ԲԸՕ) տեղադրում</figcaption></figure><h2>Քիթ-ըմպանային օդուղու տեղադրում (ՔԸՕ)</h2><p>Քիթ-ըմպանային օդուղիները (ՔԸՕ) առավել տանելի են այն հիվանդների համար, ովքեր կիսագիտակից վիճակում են, կամ երբ բերան-ըմպանային օդուղի տեղադրելիս որձկալու հավանականություն կա։ ՄԻ ԴՐԵՔ ՔԸՕ այն հիվանդներին, ովքեր գլխի կամ դեմքի վնասվածք ունեն։</p><ul><li>Գնահատեք քթի անցանելիությունը՝ շնչուղիների ցանկացած ակնհայտ խցանում հայտնաբերելու համար։</li><li>Որոշեք տեղադրման համար ՔԸՕ-ի համապատասխան չափը։ Չափեք քթանցքների հիմքից մինչև ականջի բլթակ։ Բուն ՔԸՕ-ի տրամագիծը պետք է լինի հիվանդի քթանցքից ավելի փոքր։</li><li>ՔԸՕ-ին առատ քսանյութ քսեք և տեղադրեք քթանցքի մեջ՝ ուղղելով այն քթի խոռոչի հատակով դեպի հետ՝ կոկորդի կողմ, մինչև խողովակի լայն, տափակ հատվածը (կցապռունկը) նստի քթանցքին։</li><li>Տվեք թթվածին, եթե առկա է։</li></ul><figure><img class=\"fig\" src=\"img/npa.webp\" alt=\"Քիթ-ըմպանային օդուղու (ՔԸՕ) տեղադրում\"><figcaption>Քիթ-ըմպանային օդուղու (ՔԸՕ) տեղադրում</figcaption></figure>","text":"Բերան-ըմպանային օդուղին (ԲԸՕ) տեղադրում են միայն այն ժամանակ, երբ հիվանդը անգիտակից վիճակում է։ Գիտակից հիվանդը չի դիմանա ԲԸՕ-ին և դուրս կհրի այն։ Եթե հիվանդը դիմադրում է, որձկում է կամ փսխում է, անմիջապես հեռացրեք սարքը։ Վնասվածքի պատմության դեպքում միշտ ապահովեք ողնաշարի պարանոցային հատվածի անշարժությունը։ Որոշեք ԲԸՕ-ի ճիշտ չափը՝ չափելով ականջի բլթակի ծայրից մինչև բերանի անկյունը։ Բացեք հիվանդի բերանը զգուշությամբ՝ փորձելով մատները չթողնել ատամների արանքում (որպեսզի հիվանդը պատահաբար չկծի ձեր մատները)։ Տեղադրեք ԲԸՕ-ն կոր հատվածը դեպի կողք՝ ծայրը դեպի այտը։ Զգուշորեն հրեք ԲԸՕ-ն բերանի մեջ և, երբ այլևս չեք կարողանում հրել, շրջեք ԲԸՕ-ն 90 աստիճան, այնպես որ ծայրն ուղղված լինի ներքև՝ դեպի կոկորդ, և համապատասխանի լեզվի կորին (տես նկարը)։ Անհրաժեշտության դեպքում հրեք ԲԸՕ-ի մնացած մասը, որպեսզի կցապռունկը (լայն, տափակ եզրը) նստի հիվանդի շրթունքներին։ Սա անելիս, համոզվեք, որ ԲԸՕ-ի ծայրը լեզուն դեպի ներքև չի սեղմում՝ խցանելով կոկորդի հետին հատվածը։ Նորից ստուգեք, որ ԲԸՕ-ն լեզուն դեպի ներքև չի հրել և շնչուղիները չի խցանել։ Հնարավորության դեպքում հիվանդին տվեք թթվածին: Բերան-ըմպանային օդուղու (ԲԸՕ) տեղադրում Քիթ-ըմպանային օդուղու տեղադրում (ՔԸՕ) Քիթ-ըմպանային օդուղիները (ՔԸՕ) առավել տանելի են այն հիվանդների համար, ովքեր կիսագիտակից վիճակում են, կամ երբ բերան-ըմպանային օդուղի տեղադրելիս որձկալու հավանականություն կա։ ՄԻ ԴՐԵՔ ՔԸՕ այն հիվանդներին, ովքեր գլխի կամ դեմքի վնասվածք ունեն։ Գնահատեք քթի անցանելիությունը՝ շնչուղիների ցանկացած ակնհայտ խցանում հայտնաբերելու համար։ Որոշեք տեղադրման համար ՔԸՕ-ի համապատասխան չափը։ Չափեք քթանցքների հիմքից մինչև ականջի բլթակ։ Բուն ՔԸՕ-ի տրամագիծը պետք է լինի հիվանդի քթանցքից ավելի փոքր։ ՔԸՕ-ին առատ քսանյութ քսեք և տեղադրեք քթանցքի մեջ՝ ուղղելով այն քթի խոռոչի հատակով դեպի հետ՝ կոկորդի կողմ, մինչև խողովակի լայն, տափակ հատվածը (կցապռունկը) նստի քթանցքին։ Տվեք թթվածին, եթե առկա է։ Քիթ-ըմպանային օդուղու (ՔԸՕ) տեղադրում"},{"id":"s-GCSAVPU","cat":"skills","title":"Գլազգոյի կոմայի սանդղակ (ԳԿՍ)","keywords":"Glasgow Coma Scale GCS AVPU consciousness","html":"<p>ԳԿՍ-ն 15 միավորանոց սանդղակ է, որն օգտագործվում է գլխի վնասվածքով հիվանդների գնահատման և մշտադիտարկման համար։ Հիվանդին գնահատում են աչքերը բացելու, խոսքային և շարժողական արձագանքի հիման վրա՝ յուրաքանչյուր խմբում տալով գործունեության ամենաբարձր մակարդակին համապատասխան միավոր։ Միավորները գումարվում են՝ ընդհանուր գնահատականը որոշելու համար։ Որքան ցածր է գնահատականը, այնքան ավելի ծանր կարող է լինել գլխի վնասվածքը։ Ուշադրություն դարձրեք, որ ամենացածր գնահատականը 3 է։</p><p>Գլխի ծանր վնասվածք՝ ԳԿՍ 8 կամ ավելի ցածր</p><p>Միջին ծանրության գլխի վնասվածք՝ ԳԿՍ 9–12</p><p>Գլխի թեթև վնասվածք՝ ԳԿՍ 13–15</p><h3>Գլազգոյի կոմայի սանդղակի (ԳԿՍ) հաշվարկը</h3><div class=\"tw\"><table class=\"grouped\"><thead><tr><th scope=\"col\">Արձագանք</th><th scope=\"col\">Գնահատական</th></tr></thead><tbody><tr class=\"grp\"><th colspan=\"2\" scope=\"colgroup\">Աչքեր (4)</th></tr><tr><td>Ինքնաբուխ բացում է</td><td>4</td></tr><tr><td>Բացում է հրահանգի ժամանակ</td><td>3</td></tr><tr><td>Բացում է ցավային գրգռիչին ի պատասխան</td><td>2</td></tr><tr><td>Արձագանք չկա</td><td>1</td></tr><tr class=\"grp\"><th colspan=\"2\" scope=\"colgroup\">Խոսք (5)</th></tr><tr><td>Նորմալ</td><td>5</td></tr><tr><td>Շփոթված</td><td>4</td></tr><tr><td>Ոչ համարժեք բառեր</td><td>3</td></tr><tr><td>Ոչ համարժեք հնչյուններ</td><td>2</td></tr><tr><td>Արձագանք չկա</td><td>1</td></tr><tr class=\"grp\"><th colspan=\"2\" scope=\"colgroup\">Հենաշարժողական գործունեություն (6)</th></tr><tr><td>Կատարում է հրահանգները</td><td>6</td></tr><tr><td>Նշում է, թե որտեղ է ցավը տեղակայված</td><td>5</td></tr><tr><td>Ցավի դեպքում վերջույթը ծալում է բնորոշ ձևով</td><td>4</td></tr><tr><td>Ի պատասխան ցավի ոչ բնորոշ ձևով է ծալում վերջույթը</td><td>3</td></tr><tr><td>Ձգում է վերջույթները՝ ցավին ի պատասխան</td><td>2</td></tr><tr><td>Արձագանք չկա</td><td>1</td></tr></tbody></table></div><h2>«AVPU» (ԶԽՑԱ) սանդղակ</h2><p>AVPU սանդղակը պարզեցված գնահատման գործիք է, որը կարող է հուշել հիվանդի գիտակցության մակարդակի մասին՝ ըստ գրգռիչներին արձագանքման։ AVPU-ն հատկապես օգտակար է երեխաների և նորածինների հետ աշխատելիս։ Այն անձը, որը թունավորված չէ և որի գլխուղեղի վրա ազդող հիվանդություն կամ վնասվածք չկա, սովորաբար զգոն է՝ առանց գրգռիչի։ Այն հիվանդները, որոնք արձագանքում են միայն խոսքային կամ ցավային գրգռիչին, պահանջում են նյարդաբանական համակարգի լրացուցիչ գնահատում։</p><ul><li>A = Զգոնություն (Alert). Լիովին արթուն և փոխներգործուն զգոն մարդիկ (նույնիսկ եթե լիարժեք կողմնորոշված չեն)։</li><li>V = Խոսքի գրգռիչ (Verbal). Նրանք, ովքեր մինչև գրգռիչը լիովին զգոն չեն (կարող են աչքերը փակած լինել կամ քնկոտ երևալ), սակայն արձագանքում են խոսքին՝ առանց դիպչելու (արձագանքը կարող է լինել բառեր, տնքոց կամ շարժում)։</li><li>P = Ցավային գրգռիչ (Pain). Նրանք, ովքեր չեն արձագանքում ձայնին/խոսքին, սակայն արձագանքում են ցավին՝ մեծահասակների մոտ կրծքավանդակի (կրծոսկրի) ուժեղ տրորում, երեխաների մոտ՝ ոտնաթաթի կսմթոց, կամ ողնաշարի վնասվածքի կասկածի դեպքում՝ քթի մեջքի կսմթոց։ Արձագանքը կարող է լինել բառեր, տնքոց կամ շարժում։</li><li>U = Անարձագանք (Unresponsive). Նրանք, ովքեր ցավային գրգռիչին որևէ շարժումով կամ խոսքային արձագանք չեն տալիս՝ անարձագանք են։</li><li>AVPU սանդղակով «P» կամ «U» գնահատականով ցանկացած հիվանդի դեպքում դադարեցրեք զննումը և վերադարձեք «ABCDE»-ին, քանի որ շնչուղիները պաշտպանելու համար կարող է անհրաժեշտ լինել արագ միջամտություն։</li></ul>","text":"ԳԿՍ-ն 15 միավորանոց սանդղակ է, որն օգտագործվում է գլխի վնասվածքով հիվանդների գնահատման և մշտադիտարկման համար։ Հիվանդին գնահատում են աչքերը բացելու, խոսքային և շարժողական արձագանքի հիման վրա՝ յուրաքանչյուր խմբում տալով գործունեության ամենաբարձր մակարդակին համապատասխան միավոր։ Միավորները գումարվում են՝ ընդհանուր գնահատականը որոշելու համար։ Որքան ցածր է գնահատականը, այնքան ավելի ծանր կարող է լինել գլխի վնասվածքը։ Ուշադրություն դարձրեք, որ ամենացածր գնահատականը 3 է։ Գլխի ծանր վնասվածք՝ ԳԿՍ 8 կամ ավելի ցածր Միջին ծանրության գլխի վնասվածք՝ ԳԿՍ 9–12 Գլխի թեթև վնասվածք՝ ԳԿՍ 13–15 Գլազգոյի կոմայի սանդղակի (ԳԿՍ) հաշվարկը Գործունեություն Արձագանք Գնահատական Աչքեր (4) Ինքնաբուխ բացում է 4 Աչքեր (4) Բացում է հրահանգի ժամանակ 3 Աչքեր (4) Բացում է ցավային գրգռիչին ի պատասխան 2 Աչքեր (4) Արձագանք չկա 1 Խոսք (5) Նորմալ 5 Խոսք (5) Շփոթված 4 Խոսք (5) Ոչ համարժեք բառեր 3 Խոսք (5) Ոչ համարժեք հնչյուններ 2 Խոսք (5) Արձագանք չկա 1 Հենաշարժողական գործունեություն (6) Կատարում է հրահանգները 6 Հենաշարժողական գործունեություն (6) Նշում է, թե որտեղ է ցավը տեղակայված 5 Հենաշարժողական գործունեություն (6) Ցավի դեպքում վերջույթը ծալում է բնորոշ ձևով 4 Հենաշարժողական գործունեություն (6) Ի պատասխան ցավի ոչ բնորոշ ձևով է ծալում վերջույթը 3 Հենաշարժողական գործունեություն (6) Ձգում է վերջույթները՝ ցավին ի պատասխան 2 Հենաշարժողական գործունեություն (6) Արձագանք չկա 1 «AVPU» (ԶԽՑԱ) սանդղակ AVPU սանդղակը պարզեցված գնահատման գործիք է, որը կարող է հուշել հիվանդի գիտակցության մակարդակի մասին՝ ըստ գրգռիչներին արձագանքման։ AVPU-ն հատկապես օգտակար է երեխաների և նորածինների հետ աշխատելիս։ Այն անձը, որը թունավորված չէ և որի գլխուղեղի վրա ազդող հիվանդություն կամ վնասվածք չկա, սովորաբար զգոն է՝ առանց գրգռիչի։ Այն հիվանդները, որոնք արձագանքում են միայն խոսքային կամ ցավային գրգռիչին, պահանջում են նյարդաբանական համակարգի լրացուցիչ գնահատում։ A = Զգոնություն (Alert). Լիովին արթուն և փոխներգործուն զգոն մարդիկ (նույնիսկ եթե լիարժեք կողմնորոշված չեն)։ V = Խոսքի գրգռիչ (Verbal). Նրանք, ովքեր մինչև գրգռիչը լիովին զգոն չեն (կարող են աչքերը փակած լինել կամ քնկոտ երևալ), սակայն արձագանքում են խոսքին՝ առանց դիպչելու (արձագանքը կարող է լինել բառեր, տնքոց կամ շարժում)։ P = Ցավային գրգռիչ (Pain). Նրանք, ովքեր չեն արձագանքում ձայնին/խոսքին, սակայն արձագանքում են ցավին՝ մեծահասակների մոտ կրծքավանդակի (կրծոսկրի) ուժեղ տրորում, երեխաների մոտ՝ ոտնաթաթի կսմթոց, կամ ողնաշարի վնասվածքի կասկածի դեպքում՝ քթի մեջքի կսմթոց։ Արձագանքը կարող է լինել բառեր, տնքոց կամ շարժում։ U = Անարձագանք (Unresponsive). Նրանք, ովքեր ցավային գրգռիչին որևէ շարժումով կամ խոսքային արձագանք չեն տալիս՝ անարձագանք են։ AVPU սանդղակով «P» կամ «U» գնահատականով ցանկացած հիվանդի դեպքում դադարեցրեք զննումը և վերադարձեք «ABCDE»-ին, քանի որ շնչուղիները պաշտպանելու համար կարող է անհրաժեշտ լինել արագ միջամտություն։"},{"id":"s-Paediatricheadtiltandchinlift","cat":"skills","title":"Երեխայի գլխի հետթեքում և կզակի բարձրացում","keywords":"Paediatric head tilt and chin lift airway sniffing position","html":"<p>Կիրառեք փոփոխված գիտակցությամբ հիվանդների մոտ, ովքեր ՉՈՒՆԵՆ վնասվածքի պատմության, բայց ի վիճակի չեն պաշտպանելու իրենց շնչուղիները:</p><ul><li>Երեխաների գլուխը մարմնի չափերի համեմատ մեծահասակների գլխից ավելի մեծ է, ուստի՝<ul><li>ուշադիր հետևեք շնչուղիների խցանմանը։<ul><li>Զննեք բերանը և հեռացրեք տեսանելի օտար մարմինները։ Զգույշ եղեք, որպեսզի օտար մարմինը ավելի խորը չներհրեք շնչուղիների մեջ։</li><li>Իրականացրեք արտածծում՝ շնչուղիներից ցանկացած հեղուկի կամ արտազատուկի հեռացման համար։</li></ul></li><li>Եթե շնչուղիները բաց չեն, կիրառեք <a class=\"xref\" href=\"#/p/s-Jawthrust\">ծնոտի առաջ հրում</a>։</li><li>Եթե վնասվածքի կասկած չկա, շնչուղիները բացելու համար ճիշտ դիրքավորեք հիվանդի գլուխը (շատ փոքր երեխաների ուսերի տակ բարձիկ օգտագործելով)։</li></ul></li><li>Կրծքի տարիքի երեխաների գլուխը մարմնի չափերի համեմատ ամենամեծն է։ Նրանց գլուխը պետք է պահել չեզոք («հոտ քաշելու») դիրքով (տես նկարը)։</li><li>Մեծահասակների համեմատ երեխաների պարանոցը կարճ է, իսկ շնչուղիները՝ ավելի փափուկ և հեշտ խցանվող, երբ պարանոցը կորացված է։<ul><li>Ավելի մեծ երեխաների մոտ շնչուղիները կարող են բացվել գլուխը թեթևակի հետ թեքելով (տես նկարը)։</li><li>Խուսափեք պարանոցը գերձգելուց կամ կորացնելուց։</li></ul></li><li>Մեծահասակների համեմատ երեխաների լեզուն ավելի մեծ է։<ul><li>Երեխային պառկեցրեք «հոտ քաշելու» դիրքով (փոփոխված գլխի հետթեքում և կզակի բարձրացում՝ ինչպես ծաղիկ հոտոտելիս գլխի թեթև թեքումը վերև և առաջ)։</li></ul></li><li>Հիվանդի գլուխը պահեք ինչպես նկարում է՝ շնչուղիները բաց պահելու համար։</li></ul><figure><img class=\"fig\" src=\"img/paed-head-tilt.webp\" alt=\"Չեզոք դիրք կրծքի տարիքի երեխաների հետ աշխատելիս\"><figcaption>Չեզոք դիրք կրծքի տարիքի երեխաների հետ աշխատելիս<br>Երեխայի գլխի հետթեքում՝ կզակը դեպի վեր (եթե վնասվածք չունի)</figcaption></figure><ul><li><a class=\"xref\" href=\"#/p/s-ManagementofChoking\">Շնչահեղձության դեպքում կատարեք հարվածներ թիկունքին / կրծքավանդակի կամ որովայնի սեղմումներ՝ հաշվի առնելով երեխայի տարիքը։</a></li></ul>","text":"Կիրառեք փոփոխված գիտակցությամբ հիվանդների մոտ, ովքեր ՉՈՒՆԵՆ վնասվածքի պատմության, բայց ի վիճակի չեն պաշտպանելու իրենց շնչուղիները: Երեխաների գլուխը մարմնի չափերի համեմատ մեծահասակների գլխից ավելի մեծ է, ուստի՝ ուշադիր հետևեք շնչուղիների խցանմանը։ Զննեք բերանը և հեռացրեք տեսանելի օտար մարմինները։ Զգույշ եղեք, որպեսզի օտար մարմինը ավելի խորը չներհրեք շնչուղիների մեջ։ Իրականացրեք արտածծում՝ շնչուղիներից ցանկացած հեղուկի կամ արտազատուկի հեռացման համար։ Եթե շնչուղիները բաց չեն, կիրառեք ծնոտի առաջ հրում։ Եթե վնասվածքի կասկած չկա, շնչուղիները բացելու համար ճիշտ դիրքավորեք հիվանդի գլուխը (շատ փոքր երեխաների ուսերի տակ բարձիկ օգտագործելով)։ Կրծքի տարիքի երեխաների գլուխը մարմնի չափերի համեմատ ամենամեծն է։ Նրանց գլուխը պետք է պահել չեզոք («հոտ քաշելու») դիրքով (տես նկարը)։ Մեծահասակների համեմատ երեխաների պարանոցը կարճ է, իսկ շնչուղիները՝ ավելի փափուկ և հեշտ խցանվող, երբ պարանոցը կորացված է։ Ավելի մեծ երեխաների մոտ շնչուղիները կարող են բացվել գլուխը թեթևակի հետ թեքելով (տես նկարը)։ Խուսափեք պարանոցը գերձգելուց կամ կորացնելուց։ Մեծահասակների համեմատ երեխաների լեզուն ավելի մեծ է։ Երեխային պառկեցրեք «հոտ քաշելու» դիրքով (փոփոխված գլխի հետթեքում և կզակի բարձրացում՝ ինչպես ծաղիկ հոտոտելիս գլխի թեթև թեքումը վերև և առաջ)։ Հիվանդի գլուխը պահեք ինչպես նկարում է՝ շնչուղիները բաց պահելու համար։ Չեզոք դիրք կրծքի տարիքի երեխաների հետ աշխատելիս Երեխայի գլխի հետթեքում՝ կզակը դեպի վեր (եթե վնասվածք չունի) Շնչահեղձության դեպքում կատարեք հարվածներ թիկունքին / կրծքավանդակի կամ որովայնի սեղմումներ՝ հաշվի առնելով երեխայի տարիքը։"},{"id":"s-Jawthrust","cat":"skills","title":"Ծնոտի առաջ հրում՝ մեծահասակների և երեխաների մոտ","keywords":"Adult and Paediatric jaw thrust airway trauma","html":"<p>Կիրառեք փոփոխված գիտակցությամբ հիվանդների մոտ, ովքեր ի վիճակի չեն պաշտպանելու իրենց շնչուղիները և ՈՒՆԵՆ վնասվածքի պատմություն (հնարավոր է ողնաշարի պարանոցային հատվածի կոտրվածք):</p><ul><li>Խնդրեք օգնականին անշարժ պահել ողնաշարի պարանոցային հատվածը, մինչ դուք կատարում եք ծնոտի առաջ հրումը։</li><li>Մատները դրեք ստորին ծնոտի անկյունների հետևում (ծնոտի ոսկորի կորության հատվածում)՝ ծնոտի երկու կողմերից, և հրեք դեպի վեր այնպես, որ ստորին ծնոտը շարժվի դեպի առաջ։ Գլուխը և պարանոցը ՉՊԵՏՔ Է շարժվեն։</li><li>Զննեք բերանի խոռոչը և հեռացրեք տեսանելի օտար մարմինները։</li><li>Անհրաժեշտության դեպքում արտածծման եղանակով հեռացրեք շնչուղիներից ցանկացած հեղուկ կամ արտազատուկ։</li><li>Պահեք ծնոտը այդ դիրքով՝ շնչուղիները բաց պահելու համար. թույլ մի տվեք, որ ծնոտը վերադառնա իր դիրքին, քանի որ դա կփակի շնչուղիները։</li></ul><figure><img class=\"fig\" src=\"img/jaw-thrust.webp\" alt=\"Ծնոտի առաջ հրումը երեխաների մոտ\"><figcaption>Ծնոտի առաջ հրումը երեխաների մոտ<br>Ծնոտի առաջ հրումը մեծահասակների մոտ</figcaption></figure>","text":"Կիրառեք փոփոխված գիտակցությամբ հիվանդների մոտ, ովքեր ի վիճակի չեն պաշտպանելու իրենց շնչուղիները և ՈՒՆԵՆ վնասվածքի պատմություն (հնարավոր է ողնաշարի պարանոցային հատվածի կոտրվածք): Խնդրեք օգնականին անշարժ պահել ողնաշարի պարանոցային հատվածը, մինչ դուք կատարում եք ծնոտի առաջ հրումը։ Մատները դրեք ստորին ծնոտի անկյունների հետևում (ծնոտի ոսկորի կորության հատվածում)՝ ծնոտի երկու կողմերից, և հրեք դեպի վեր այնպես, որ ստորին ծնոտը շարժվի դեպի առաջ։ Գլուխը և պարանոցը ՉՊԵՏՔ Է շարժվեն։ Զննեք բերանի խոռոչը և հեռացրեք տեսանելի օտար մարմինները։ Անհրաժեշտության դեպքում արտածծման եղանակով հեռացրեք շնչուղիներից ցանկացած հեղուկ կամ արտազատուկ։ Պահեք ծնոտը այդ դիրքով՝ շնչուղիները բաց պահելու համար. թույլ մի տվեք, որ ծնոտը վերադառնա իր դիրքին, քանի որ դա կփակի շնչուղիները։ Ծնոտի առաջ հրումը երեխաների մոտ Ծնոտի առաջ հրումը մեծահասակների մոտ"},{"id":"s-Pelvicbinderapplication","cat":"skills","title":"Կոնքի կապի կիրառում","keywords":"Pelvic binder application pelvic fracture","html":"<p>Կոնքոսկրի կոտրվածքները կարող են առաջացնել կյանքին սպառնացող արյունահոսություն՝ կոտրվածքին կից արյունատար անոթները վնասելու պատճառով։ Եթե հիվանդը վնասվածք է ստացել և ցավ ունի կոնքի շրջանում, տեղադրեք գոտևորող կապ (տես նկարը)։ Քանի որ կոնքը օղակի ձև ունի, գոտևորող կապը կհավաքի տեղաշարժված ոսկորները և կօգնի սահմանափակել ներքին արյունահոսությունը։ Հիվանդին զննելիս կարող եք հայտանբերել կոնքի կոտրվածքի նշաններ, օրինակ՝ ցավ կամ կոնքի ոչ նորմալ շարժունակություն, կապտուկներ ազդրերի վերին մասում, կոնքազդրային հոդերի, կամ սեռական օրգանների շրջանում, ինչպես նաև շոկի նշաններ և ախտանշաններ։</p><ul><li>Կոնքի տակ դրեք սավան կամ նմանատիպ այլ բան։ Եթե սավանը լայն է, ծալեք այնպես, որ այն ընդգրկի մեջքի ստորին հատվածից մինչև հետույքի ստորին մասը։</li><li>Կոնքի կապը ճիշտ դիրքավորելու համար կարող եք կիրառել «գերանի գլորում» մեթոդը։</li><li>Սավանի կենտրոնը պետք է գրկի մեծ տամբիոնները (կոնքազդրային ոսկորները, ինչպես ցուցադրվում է հրահանգչի կողմից), իսկ եզրերը ամուր խաչվեն դիմացից։</li><li>Ամուր ձգեք և կապեք, բայց հիվանդին ավելորդ ցավ մի պատճառեք։ Կապը պետք է ամուր զգացվի, սակայն չափազանց ցավոտ չլինի։</li><li>Փաստաթղթավորեք կոնքի կապը դնելու ժամը։</li><li>Ստուգեք կապը յուրաքանչյուր ժամը մեկ։ Համոզվեք, որ այն դեռ ճնշում է գործադրում կոնքի շուրջ։ Համոզվեք, որ մաշկը կապի տակ և սեռական օրգանների շրջանում վնասված չէ։</li></ul><figure><img class=\"fig\" src=\"img/pelvis-fracture.webp\" alt=\"Նորմալ կոնք\"><figcaption>Նորմալ կոնք<br>Կոնքի կոտրվածք</figcaption></figure><figure><img class=\"fig\" src=\"img/pelvic-binder.webp\" alt=\"Կոնքի անշարժացում\"><figcaption>Կոնքի անշարժացում</figcaption></figure>","text":"Կոնքոսկրի կոտրվածքները կարող են առաջացնել կյանքին սպառնացող արյունահոսություն՝ կոտրվածքին կից արյունատար անոթները վնասելու պատճառով։ Եթե հիվանդը վնասվածք է ստացել և ցավ ունի կոնքի շրջանում, տեղադրեք գոտևորող կապ (տես նկարը)։ Քանի որ կոնքը օղակի ձև ունի, գոտևորող կապը կհավաքի տեղաշարժված ոսկորները և կօգնի սահմանափակել ներքին արյունահոսությունը։ Հիվանդին զննելիս կարող եք հայտանբերել կոնքի կոտրվածքի նշաններ, օրինակ՝ ցավ կամ կոնքի ոչ նորմալ շարժունակություն, կապտուկներ ազդրերի վերին մասում, կոնքազդրային հոդերի, կամ սեռական օրգանների շրջանում, ինչպես նաև շոկի նշաններ և ախտանշաններ։ Կոնքի տակ դրեք սավան կամ նմանատիպ այլ բան։ Եթե սավանը լայն է, ծալեք այնպես, որ այն ընդգրկի մեջքի ստորին հատվածից մինչև հետույքի ստորին մասը։ Կոնքի կապը ճիշտ դիրքավորելու համար կարող եք կիրառել «գերանի գլորում» մեթոդը։ Սավանի կենտրոնը պետք է գրկի մեծ տամբիոնները (կոնքազդրային ոսկորները, ինչպես ցուցադրվում է հրահանգչի կողմից), իսկ եզրերը ամուր խաչվեն դիմացից։ Ամուր ձգեք և կապեք, բայց հիվանդին ավելորդ ցավ մի պատճառեք։ Կապը պետք է ամուր զգացվի, սակայն չափազանց ցավոտ չլինի։ Փաստաթղթավորեք կոնքի կապը դնելու ժամը։ Ստուգեք կապը յուրաքանչյուր ժամը մեկ։ Համոզվեք, որ այն դեռ ճնշում է գործադրում կոնքի շուրջ։ Համոզվեք, որ մաշկը կապի տակ և սեռական օրգանների շրջանում վնասված չէ։ Նորմալ կոնք Կոնքի կոտրվածք Կոնքի անշարժացում"},{"id":"s-Fractureimmobilization","cat":"skills","title":"Կոտրվածքների անշարժացում","keywords":"Fracture immobilization splint open fracture","html":"<p>Վերջույթների վնասվածքի կասկածի դեպքում տեղադրվում է բեկակալ, որը կանխում է կոտրված ոսկորների շարժումից առաջացող ցավը և նվազեցնում է հետագա արյունահոսությունը և վնասումը։ Միշտ գնահատեք և գրանցեք պերֆուզիան վերջույթի՝ կոտրվածքից ներքև գտնվող հատվածում՝ անոթազարկը գնահատելու և մազանոթների վերալցման արագությունը ստուգելու միջոցով։ Միշտ գնահատեք վերջույթի անոթազարկը, մազանոթների վերալցման արագությունը և զգայունությունը որևէ վերք վիրակապելուց կամ բեկակալ տեղադրելուց առաջ ԵՎ հետո։</p><ul><li>Պերֆուզիայի բացակայության դեպքում (վերջույթը սառն է, գունատ, անոթազարկ չկա, մազանոթների վերալցումը դանդաղ է կամ բացակայում է) վերջույթը պետք է արագ ուղղել («ռեդուկցիա»)՝ արյան շրջանառությունը վերականգնելու համար։</li><li>Եթե վերջույթն ուղղելուց հետո պերֆուզիան դեռ բացակայում է, տեղադրեք բեկակալ և պլանավորեք արագ փոխանցում/հանձնում մասնագիտացված բաժանմունք։</li><li>Եթե չեք կարողանում վերջույթն ուղղել, արագ փոխանցեք/հանձնեք հիվանդին առավել բարձր կարգի սպասարկողի։</li></ul><p class=\"label\">Կոտրվածքի վարման նպատակն է.</p><ul><li>Արյան շրջանառության վերականգնումը</li><li>Ցավի կառավարումը և թուլացումը</li><li>Հետագա վնասվածքի և արյունահոսության կանխարգելումը</li><li>Ոսկրային բեկորների ուղղումը՝ ապաքինման և ոսկորների կպչելու համար, և գործունեության վերականգնումը</li></ul><p class=\"label\">Բեկակալի տեղադրման նյութերն են.</p><ul><li>Խծուծ՝ մաշկը պաշտպանելու և այտուցվածությունը չսահմանափակելու համար</li><li>Պատրաստի կամ տեղում հարմարեցված բեկակալ; վիրակապեր՝ բեկակալը ֆիքսելու համար</li><li>Կպչուն ժապավեն (սպեղանի)</li></ul><p>Նախքան բեկակալ տեղադրելը ասեք հիվանդին, թե ինչ եք անում, և տվեք ցավազրկող։</p><ul><li>Հանեք հագուստը՝ վնասվածքը պարզորոշ տեսնելու համար։</li><li>Հանեք բոլոր զարդերը։</li></ul><p class=\"label\">Քայլերը:</p><ul><li>Ստուգեք վերջույթի անոթազարկը, մազանոթների վերալցումը, զգայունությունը և շարժունակությունը։ Այս տվյալները փաստաթղթավորեք բեկակալ դնելուց առաջ և հետո։</li><li>Բեկակալի չափը ընտրեք այնպես, որ այն անշարժացնի կոտրվածքի վերևի և ներքևի հոդերը։</li><li>Եթե վերջույթը տեսանելիորեն ձևախախտված է, իսկ կոտրվածքից ներքև անոթազարկերը թույլ են կամ բացակայում են, նախ ուղղեք կոտրվածքը («ռեդուկցիա»)՝ նախքան բեկակալ դնելը։ Ուժով մի ուղղեք ձևախախտված վերջույթը, եթե վերջույթի անոթազարկը լավ է։</li><li>Հոդը պահեք ցանկալի դիրքում, և եթե վնասվածքը ներառում է մատները (ձեռքի կամ ոտքի), մատների արանքում խծուծ դրեք։</li><li>Եթե առկա է վիրախծուծ (գուլպայաձև թանզիֆ), հնարավորինս առանց ծալքերի փաթաթեք վերջույթը՝ մաշկի վնասումից խուսափելու համար։</li><li>Խծուծով փաթաթեք նաև բեկակալի՝ մաշկի հետ շփվող կողմը, և վերջույթը, հատկապես ոսկրային ելուստները (օրինակ՝ արմունկը)։</li><li>Վերջույթը և բեկակալը փաթաթեք վիրակապով՝ բեկակալը պահելու համար։ Հարցրեք հիվանդին, թե ինչպես է զգում, որպեսզի համոզվեք, որ վիրակապը շատ ամուր չէ։ Բեկակալը պետք է ապահով ֆիքսված լինի, սակայն հիշեք, որ վերջույթը կայտուցվի, ուստի կարևոր է, որ բեկակալը և վիրակապը շատ ձիգ չլինեն։</li><li>Բեկակալը դնելուց հետո և հետագայում յուրաքանչյուր ժամը մեկ ստուգեք վերջույթի անոթազարկը, զգայունությունը և շարժումները։</li></ul><h2>Բաց կոտրվածքների անշարժացում</h2><p>Եթե կոտրվածքի մոտ վերք կա, համարեք այն բաց կոտրվածք։ Բաց կոտրվածքի հատվածը հաճախ կարող է աղտոտված լինել, ինչը կպահանջի դրա մաքրում և հնարավոր վիրաբուժական խորը մաքրում՝ նախքան կոտրվածքի բուժումը։ Եթե կասկածում եք բաց կոտրվածքի, բեկակալ դնելուց հետո պլանավորեք հիվանդի փոխանցում/հանձնում վիրաբուժական կամ օրթոպեդիկ բաժանմունք։</p><ul><li>Բեկակալ դնելուց առաջ տվեք ցավազրկող։</li><li>Արյունահոսությունը վերահսկեք անմիջական ճնշմամբ։ Վերջույթի անդամահատման դեպքում, եթե արյունահոսությունը անվերահսկելի է, դրեք լարան (տե՛ս վերևում), սկսեք հեղուկային վերականգնում և պլանավորեք արագ փոխանցում/հանձնում։</li><li>Ուղղեք վերջույթը («ռեդուկցիա»), եթե առկա են թույլ պերֆուզիայի նշաններ կամ վերջույթում անոթազարկը բացակայում է։</li><li>Վերքից հեռացրեք ցանկացած կեղտ, խոտ, տեսանելի ապակի կամ այլ բեկորներ և լվացեք վերքը 2 լիտր ֆիզիոլոգիական լուծույթով։</li><li>Ծածկեք վերքը ֆիզիոլոգիական լուծույթով թրջված թանզիֆով։</li><li>Բեկակալ դրեք վերը նկարագրված եղանակով, սակայն փոքր բացվածք թողեք, որպեսզի կարողանաք շարունակել վերքի հսկողությունը։</li><li>Անդամահատման դեպքում ծածկեք վերքը մանրէազերծված, ֆիզիոլոգիական լուծույթով թրջված թանզիֆով կամ սրբիչով։</li><li>Կատարեք փայտացման դեմ պատվաստում։</li><li>Սկսեք ն/ե հակաբիոտիկների ներմուծում։</li></ul>","text":"Վերջույթների վնասվածքի կասկածի դեպքում տեղադրվում է բեկակալ, որը կանխում է կոտրված ոսկորների շարժումից առաջացող ցավը և նվազեցնում է հետագա արյունահոսությունը և վնասումը։ Միշտ գնահատեք և գրանցեք պերֆուզիան վերջույթի՝ կոտրվածքից ներքև գտնվող հատվածում՝ անոթազարկը գնահատելու և մազանոթների վերալցման արագությունը ստուգելու միջոցով։ Միշտ գնահատեք վերջույթի անոթազարկը, մազանոթների վերալցման արագությունը և զգայունությունը որևէ վերք վիրակապելուց կամ բեկակալ տեղադրելուց առաջ ԵՎ հետո։ Պերֆուզիայի բացակայության դեպքում (վերջույթը սառն է, գունատ, անոթազարկ չկա, մազանոթների վերալցումը դանդաղ է կամ բացակայում է) վերջույթը պետք է արագ ուղղել («ռեդուկցիա»)՝ արյան շրջանառությունը վերականգնելու համար։ Եթե վերջույթն ուղղելուց հետո պերֆուզիան դեռ բացակայում է, տեղադրեք բեկակալ և պլանավորեք արագ փոխանցում/հանձնում մասնագիտացված բաժանմունք։ Եթե չեք կարողանում վերջույթն ուղղել, արագ փոխանցեք/հանձնեք հիվանդին առավել բարձր կարգի սպասարկողի։ Կոտրվածքի վարման նպատակն է. Արյան շրջանառության վերականգնումը Ցավի կառավարումը և թուլացումը Հետագա վնասվածքի և արյունահոսության կանխարգելումը Ոսկրային բեկորների ուղղումը՝ ապաքինման և ոսկորների կպչելու համար, և գործունեության վերականգնումը Բեկակալի տեղադրման նյութերն են. Խծուծ՝ մաշկը պաշտպանելու և այտուցվածությունը չսահմանափակելու համար Պատրաստի կամ տեղում հարմարեցված բեկակալ; վիրակապեր՝ բեկակալը ֆիքսելու համար Կպչուն ժապավեն (սպեղանի) Նախքան բեկակալ տեղադրելը ասեք հիվանդին, թե ինչ եք անում, և տվեք ցավազրկող։ Հանեք հագուստը՝ վնասվածքը պարզորոշ տեսնելու համար։ Հանեք բոլոր զարդերը։ Քայլերը: Ստուգեք վերջույթի անոթազարկը, մազանոթների վերալցումը, զգայունությունը և շարժունակությունը։ Այս տվյալները փաստաթղթավորեք բեկակալ դնելուց առաջ և հետո։ Բեկակալի չափը ընտրեք այնպես, որ այն անշարժացնի կոտրվածքի վերևի և ներքևի հոդերը։ Եթե վերջույթը տեսանելիորեն ձևախախտված է, իսկ կոտրվածքից ներքև անոթազարկերը թույլ են կամ բացակայում են, նախ ուղղեք կոտրվածքը («ռեդուկցիա»)՝ նախքան բեկակալ դնելը։ Ուժով մի ուղղեք ձևախախտված վերջույթը, եթե վերջույթի անոթազարկը լավ է։ Հոդը պահեք ցանկալի դիրքում, և եթե վնասվածքը ներառում է մատները (ձեռքի կամ ոտքի), մատների արանքում խծուծ դրեք։ Եթե առկա է վիրախծուծ (գուլպայաձև թանզիֆ), հնարավորինս առանց ծալքերի փաթաթեք վերջույթը՝ մաշկի վնասումից խուսափելու համար։ Խծուծով փաթաթեք նաև բեկակալի՝ մաշկի հետ շփվող կողմը, և վերջույթը, հատկապես ոսկրային ելուստները (օրինակ՝ արմունկը)։ Վերջույթը և բեկակալը փաթաթեք վիրակապով՝ բեկակալը պահելու համար։ Հարցրեք հիվանդին, թե ինչպես է զգում, որպեսզի համոզվեք, որ վիրակապը շատ ամուր չէ։ Բեկակալը պետք է ապահով ֆիքսված լինի, սակայն հիշեք, որ վերջույթը կայտուցվի, ուստի կարևոր է, որ բեկակալը և վիրակապը շատ ձիգ չլինեն։ Բեկակալը դնելուց հետո և հետագայում յուրաքանչյուր ժամը մեկ ստուգեք վերջույթի անոթազարկը, զգայունությունը և շարժումները։ Բաց կոտրվածքների անշարժացում Եթե կոտրվածքի մոտ վերք կա, համարեք այն բաց կոտրվածք։ Բաց կոտրվածքի հատվածը հաճախ կարող է աղտոտված լինել, ինչը կպահանջի դրա մաքրում և հնարավոր վիրաբուժական խորը մաքրում՝ նախքան կոտրվածքի բուժումը։ Եթե կասկածում եք բաց կոտրվածքի, բեկակալ դնելուց հետո պլանավորեք հիվանդի փոխանցում/հանձնում վիրաբուժական կամ օրթոպեդիկ բաժանմունք։ Բեկակալ դնելուց առաջ տվեք ցավազրկող։ Արյունահոսությունը վերահսկեք անմիջական ճնշմամբ։ Վերջույթի անդամահատման դեպքում, եթե արյունահոսությունը անվերահսկելի է, դրեք լարան (տե՛ս վերևում), սկսեք հեղուկային վերականգնում և պլանավորեք արագ փոխանցում/հանձնում։ Ուղղեք վերջույթը («ռեդուկցիա»), եթե առկա են թույլ պերֆուզիայի նշաններ կամ վերջույթում անոթազարկը բացակայում է։ Վերքից հեռացրեք ցանկացած կեղտ, խոտ, տեսանելի ապակի կամ այլ բեկորներ և լվացեք վերքը 2 լիտր ֆիզիոլոգիական լուծույթով։ Ծածկեք վերքը ֆիզիոլոգիական լուծույթով թրջված թանզիֆով։ Բեկակալ դրեք վերը նկարագրված եղանակով, սակայն փոքր բացվածք թողեք, որպեսզի կարողանաք շարունակել վերքի հսկողությունը։ Անդամահատման դեպքում ծածկեք վերքը մանրէազերծված, ֆիզիոլոգիական լուծույթով թրջված թանզիֆով կամ սրբիչով։ Կատարեք փայտացման դեմ պատվաստում։ Սկսեք ն/ե հակաբիոտիկների ներմուծում։"},{"id":"s-Suckingchestwoundmanagement","cat":"skills","title":"Կրծքավանդակի ներծծող վերքի վարում","keywords":"Sucking chest wound three-sided dressing open pneumothorax","html":"<p>Բաց պնևմոթորաքսը կրծքավանդակի պատի բաց վերք է, որը ներշնչելիս օդ է ներծծում։ Սովորաբար, երբ կրծքավանդակի պատը լայնանում է, օդը շնչուղիներով (վակուումային էֆեկտի շնորհիվ) ներթափանցում է թոքեր։ Եթե կրծքավանդակի պատում կա այլ անցք (վնասվածքի պատճառով), օդը ներծծվում է նաև այդ անցքով, սակայն թոքեր գնալու փոխարեն այն անցնում է կրծքավանդակի պատի և թոքերի միջև տարածություն՝ առաջացնելով պնևմոթորաքս։ Եռակողմ վիրակապը դրվում է՝ ներշնչելիս օդի հետագա ներթափանցումը կանխելու համար, բայց թույլ տալու համար, որ պնևմոթորաքսի օդը դուրս գա արտաշնչելիս, որպեսզի լարված պնևմոթորաքս չզարգանա։ Կրծքավանդակի ներծծող վերքը (բաց պնևմոթորաքս) վարելու համար՝</p><ul><li>Տվեք բարձր հոսքով թթվածին։</li><li>Ծածկեք ներծծող վերքը օկլուզիոն (պարաֆինային) թանզիֆով կամ այլ ոչ կպչուն վիրակապով, օրինակ՝ թանզիֆի փաթեթի պլաստիկով։</li><li>Կպչուն ժապավենով ամրացրեք վիրակապի երեք կողմը՝ մի կողմը չամրացրած թողնելով, որպեսզի այն ծառայի որպես եզրային փական։</li><li>Այդպիսի հիվանդներին պետք է հնարավորինս շուտ փոխանցել այն կենտրոն, որտեղ հնարավոր է կրծքավանդակի խողովակ տեղադրել։ (ՄԻ ՏԵՂԱԴՐԵՔ կրծքավանդակի խողովակը վնասվածքի միջով։)</li></ul><div class=\"callout caution\"><strong>Զգուշացում!</strong> Վտանգ կա, որ վիրակապը մակարդված արյան պատճառով կկպչի կրծքավանդակի պատին։ Երբ դա տեղի ունենա, օդը չի կարողանա դուրս գալ կրծքավանդակի խոռոչից, ճնշումը կարող է աճել, ինչը կհանգեցնի լարված պնևմոթորաքսի։ <strong>Վիրակապն ամբողջությամբ հեռացրեք, եթե շնչառական վիճակը կամ պերֆուզիան վատթարանում է։ Եթե հնարավոր չէ հիվանդին անընդհատ հսկել, եռակողմ վիրակապ ՉՊԵՏՔ Է դնել։</strong></div>","text":"Բաց պնևմոթորաքսը կրծքավանդակի պատի բաց վերք է, որը ներշնչելիս օդ է ներծծում։ Սովորաբար, երբ կրծքավանդակի պատը լայնանում է, օդը շնչուղիներով (վակուումային էֆեկտի շնորհիվ) ներթափանցում է թոքեր։ Եթե կրծքավանդակի պատում կա այլ անցք (վնասվածքի պատճառով), օդը ներծծվում է նաև այդ անցքով, սակայն թոքեր գնալու փոխարեն այն անցնում է կրծքավանդակի պատի և թոքերի միջև տարածություն՝ առաջացնելով պնևմոթորաքս։ Եռակողմ վիրակապը դրվում է՝ ներշնչելիս օդի հետագա ներթափանցումը կանխելու համար, բայց թույլ տալու համար, որ պնևմոթորաքսի օդը դուրս գա արտաշնչելիս, որպեսզի լարված պնևմոթորաքս չզարգանա։ Կրծքավանդակի ներծծող վերքը (բաց պնևմոթորաքս) վարելու համար՝ Տվեք բարձր հոսքով թթվածին։ Ծածկեք ներծծող վերքը օկլուզիոն (պարաֆինային) թանզիֆով կամ այլ ոչ կպչուն վիրակապով, օրինակ՝ թանզիֆի փաթեթի պլաստիկով։ Կպչուն ժապավենով ամրացրեք վիրակապի երեք կողմը՝ մի կողմը չամրացրած թողնելով, որպեսզի այն ծառայի որպես եզրային փական։ Այդպիսի հիվանդներին պետք է հնարավորինս շուտ փոխանցել այն կենտրոն, որտեղ հնարավոր է կրծքավանդակի խողովակ տեղադրել։ (ՄԻ ՏԵՂԱԴՐԵՔ կրծքավանդակի խողովակը վնասվածքի միջով։) Զգուշացում! Վտանգ կա, որ վիրակապը մակարդված արյան պատճառով կկպչի կրծքավանդակի պատին։ Երբ դա տեղի ունենա, օդը չի կարողանա դուրս գալ կրծքավանդակի խոռոչից, ճնշումը կարող է աճել, ինչը կհանգեցնի լարված պնևմոթորաքսի։ Վիրակապն ամբողջությամբ հեռացրեք, եթե շնչառական վիճակը կամ պերֆուզիան վատթարանում է։ Եթե հնարավոր չէ հիվանդին անընդհատ հսկել, եռակողմ վիրակապ ՉՊԵՏՔ Է դնել։"},{"id":"s-Giveoxygen","cat":"skills","title":"Հավելյալ թթվածնի տրամադրում","keywords":"Giving oxygen nasal cannula simple facemask non-rebreather","html":"<p>Հավելյալ թթվածին պետք է տալ, երբ հիվանդի մոտ առկա են թթվածնաքաղցի նշաններ և ախտանշաններ՝ արագացած շնչառություն, տագնապ, առատ քրտնարտադրություն, ցիանոզ կամ կրծքավանդակի ցավ։ Հնարավորության դեպքում պետք է պուլսօքսիմետրով չափել թթվածնային հագեցումը։</p><ul><li>Եթե թթվածնաքաղցն ուժեղ չէ, երեխաներին և մեծահասակներին կարելի է տալ թթվածնի ավելի ցածր տոկոսներ (24–40%)՝ քթային կատետրի միջոցով, սակայն ուշադիր հետևեք, քանի որ կարող է դիմակ պետք գա։ (Հիշեք, որ սովորական օդում թթվածինը շուրջ 21% է։)<ul><li>Քթային կատետրը պետք է լինի քթանցքի կեսի չափ։</li><li>Տեղադրեք կատետրը յուրաքանչյուր քթանցքում՝ ապահովելով, որ այն շատ խորը չմտնի և հյուսվածքները չսեղմի։</li><li>Ամրացրեք խողովակը այտերին կամ անցկացրեք այն ականջների վրայով այնպես, որ քթային ճյուղերը և խողովակը լինեն հիվանդի մարմնի առջևի մասում (երբեք գլուխը չանցկացնեք խողովակի օղակի մեջ. եթե հիվանդի մոտ խառնաշփոթ և թթվածնաքաղց զարգանա, նա կարող է պատահաբար խեղդվել)։</li><li>Թթվածինը մատակարարվում է ցածր արագությամբ՝ առավելագույնը 5 լ/րոպե։</li></ul></li><li>Եթե թթվածնաքաղցն ավելի ուժեղ է (կամ եթե թթվածնաքաղցի նշանները շարունակվում են անգամ քթային կատետրով թթվածնի առավելագույն հոսքի դեպքում), կարելի է օգտագործել հասարակ թթվածնային դիմակ։ Հասարակ դիմակը սովորաբար օգտագործվում է թթվածնի հոսքի 6–10 լ/րոպե արագությամբ և կարող է ապահովել մոտավորապես 40–60% թթվածին։<ul><li>Դիմակը դրվում է դեմքին՝ ապահովելով, որ քթի մեջքը ծածկվի, և կողքերից հնարավորինս քիչ օդ արտահոսի։ Դիմակը պետք է նստի ստորին շրթունքից ներքև, սակայն կզակից չանցնի (կախված դիմակի տիպից)։ Էլաստիկ գոտին պետք է անցկացնել գլխի հետևով՝ դիմակը ամրացնելու համար։</li></ul></li><li>Եթե հիվանդի մոտ թթվածնաքաղցը շատ ուժեղ է կամ հասարակ դիմակի դեպքում թթվածնաքաղցի նշանները պահպանվում են, թթվածինը կարելի է մատակարարել մեկուսացնող պարկով թթվածնային դիմակով։ Լիքը շնչառական պարկի դեպքում սա ապահովում է 100%-ին մոտ թթվածին։<ul><li>Մեկուսացնող պարկով դիմակը նախապատրաստելու համար մեկ մատը դրեք դիմակի ներսում գտնվող պարկի վերին մասի փականի վրա՝ պարկը լցնելու համար։ Այնուհետև դիմակը տեղադրեք նույն կերպ, ինչ հասարակ դիմակը՝ ապահովելով հնարավորինս քիչ արտահոսք։</li><li>Նախապես համոզվեք, որ թթվածինը միացված է պատի համակարգին կամ բալոնին, և հոսքի արագությունը 10–15 լ/րոպե է՝ կախված թթվածնային համակարգի ճնշումից և հիվանդի շնչառության արագությունից ու խորությունից։ Եթե թթվածնաքաղցը դեռ առկա է կամ պարկով դիմակի պարկը չի լցվում, ավելացրեք թթվածնի հոսքի արագությունը։</li><li>ԵՐԲԵՔ մեկուսացնող պարկով դիմակը մի դրեք, քանի դեռ այն միացված չէ թթվածնին։ Իսկական մեկուսացնող դիմակը թույլ չի տալիս դրսի օդին ներթափանցել և կարող է վատթարացնել դժվարացած շնչառությունը և թթվածնաքաղցը, եթե խողովակով թթվածին չի հոսում։</li></ul></li></ul><figure><img class=\"fig\" src=\"img/oxygen-devices.webp\" alt=\"Քթային կատետր\"><figcaption>Քթային կատետր<br>Հասարակ թթվածնային դիմակ<br>Մեկուսացնող պարկով թթվածնային դիմակ</figcaption></figure>","text":"Հավելյալ թթվածին պետք է տալ, երբ հիվանդի մոտ առկա են թթվածնաքաղցի նշաններ և ախտանշաններ՝ արագացած շնչառություն, տագնապ, առատ քրտնարտադրություն, ցիանոզ կամ կրծքավանդակի ցավ։ Հնարավորության դեպքում պետք է պուլսօքսիմետրով չափել թթվածնային հագեցումը։ Եթե թթվածնաքաղցն ուժեղ չէ, երեխաներին և մեծահասակներին կարելի է տալ թթվածնի ավելի ցածր տոկոսներ (24–40%)՝ քթային կատետրի միջոցով, սակայն ուշադիր հետևեք, քանի որ կարող է դիմակ պետք գա։ (Հիշեք, որ սովորական օդում թթվածինը շուրջ 21% է։) Քթային կատետրը պետք է լինի քթանցքի կեսի չափ։ Տեղադրեք կատետրը յուրաքանչյուր քթանցքում՝ ապահովելով, որ այն շատ խորը չմտնի և հյուսվածքները չսեղմի։ Ամրացրեք խողովակը այտերին կամ անցկացրեք այն ականջների վրայով այնպես, որ քթային ճյուղերը և խողովակը լինեն հիվանդի մարմնի առջևի մասում (երբեք գլուխը չանցկացնեք խողովակի օղակի մեջ. եթե հիվանդի մոտ խառնաշփոթ և թթվածնաքաղց զարգանա, նա կարող է պատահաբար խեղդվել)։ Թթվածինը մատակարարվում է ցածր արագությամբ՝ առավելագույնը 5 լ/րոպե։ Եթե թթվածնաքաղցն ավելի ուժեղ է (կամ եթե թթվածնաքաղցի նշանները շարունակվում են անգամ քթային կատետրով թթվածնի առավելագույն հոսքի դեպքում), կարելի է օգտագործել հասարակ թթվածնային դիմակ։ Հասարակ դիմակը սովորաբար օգտագործվում է թթվածնի հոսքի 6–10 լ/րոպե արագությամբ և կարող է ապահովել մոտավորապես 40–60% թթվածին։ Դիմակը դրվում է դեմքին՝ ապահովելով, որ քթի մեջքը ծածկվի, և կողքերից հնարավորինս քիչ օդ արտահոսի։ Դիմակը պետք է նստի ստորին շրթունքից ներքև, սակայն կզակից չանցնի (կախված դիմակի տիպից)։ Էլաստիկ գոտին պետք է անցկացնել գլխի հետևով՝ դիմակը ամրացնելու համար։ Եթե հիվանդի մոտ թթվածնաքաղցը շատ ուժեղ է կամ հասարակ դիմակի դեպքում թթվածնաքաղցի նշանները պահպանվում են, թթվածինը կարելի է մատակարարել մեկուսացնող պարկով թթվածնային դիմակով։ Լիքը շնչառական պարկի դեպքում սա ապահովում է 100%-ին մոտ թթվածին։ Մեկուսացնող պարկով դիմակը նախապատրաստելու համար մեկ մատը դրեք դիմակի ներսում գտնվող պարկի վերին մասի փականի վրա՝ պարկը լցնելու համար։ Այնուհետև դիմակը տեղադրեք նույն կերպ, ինչ հասարակ դիմակը՝ ապահովելով հնարավորինս քիչ արտահոսք։ Նախապես համոզվեք, որ թթվածինը միացված է պատի համակարգին կամ բալոնին, և հոսքի արագությունը 10–15 լ/րոպե է՝ կախված թթվածնային համակարգի ճնշումից և հիվանդի շնչառության արագությունից ու խորությունից։ Եթե թթվածնաքաղցը դեռ առկա է կամ պարկով դիմակի պարկը չի լցվում, ավելացրեք թթվածնի հոսքի արագությունը։ ԵՐԲԵՔ մեկուսացնող պարկով դիմակը մի դրեք, քանի դեռ այն միացված չէ թթվածնին։ Իսկական մեկուսացնող դիմակը թույլ չի տալիս դրսի օդին ներթափանցել և կարող է վատթարացնել դժվարացած շնչառությունը և թթվածնաքաղցը, եթե խողովակով թթվածին չի հոսում։ Քթային կատետր Հասարակ թթվածնային դիմակ Մեկուսացնող պարկով թթվածնային դիմակ"},{"id":"s-Transferandhandover","cat":"skills","title":"Հիվանդի փոխանցում և հանձնում","keywords":"Transfer and handover SBAR checklist transport","html":"<p>Հիվանդներին դեպքի վայրից առաջին հաստատություն, կամ մի հաստատությունից մեկ այլ հաստատություն փոխանցելիս պահանջվում է հատուկ ուշադրություն՝ (1) նպատակակետի պլանավորմանը, (2) հիվանդի վիճակի շարունակական վարմանը և (3) հանձնմանը։</p><h2>(1) ՆՊԱՏԱԿԱԿԵՏԻ ՊԼԱՆԱՎՈՐՈՒՄ</h2><p>Դեպքի վայրում բուժված շատ հիվանդների անհրաժեշտ կլինի տեղափոխել բժշկական հաստատություն՝ հետագա բուժման համար։ Բացի այդ, մի հաստատությունում գտնվող հիվանդներին կարող է անհրաժեշտ լինել փոխանցել մեկ այլ հաստատություն՝ առավել բարձր կարգի բուժման համար։</p><p>Ցանկացած տեղափոխում պլանավորելիս համոզվեք, որ՝</p><ul><li>նպատակակետ հաստատության ծառայությունների մակարդակը համապատասխանում է հիվանդի կարիքներին (օրինակ՝ առկա է վիրահատարան, եթե անհրաժեշտ է վիրահատություն);</li><li>ակնկալվող ռեսուրսներն այս պահին հասանելի են (օրինակ՝ վիրահատարանն աշխատում է, և արյան փոխներարկման համար արյուն կա);</li><li>և նպատակակետին հնարավոր է հասնել հիվանդի վիճակին համապատասխան անհրաժեշտ ժամանակահատվածում։</li></ul><p>Մի ձգձգեք տեղափոխումը այնպիսի հետազոտությունների կամ միջամտությունների համար, որոնք կարևոր չեն հիվանդի անվտանգության համար, եթե դրանք կարող են իրականացվել ընդունող հաստատությունում։</p><p>Առկայության դեպքում հետևեք տեղափոխման և նպատակակետի վերաբերյալ տեղական գործելակարգերին։ Այնտեղ, որտեղ հստակ գործելակարգեր չկան, համադրեք տեղափոխման ժամանակը և հաստատությունների հնարավորությունները. նպատակը անհրաժեշտ խնամքին հնարավորինս շուտ հասնելն է։ Սովորաբար ավելի լավ է երկար սկզբնական տեղափոխման ժամանակ ունենալ, քան կազմակերպել երկրորդ փոխանցումը՝ այն պատճառով, որ առաջին նպատակակետում համապատասխան բուժումը հասանելի չի եղել։</p><p>Նպատակային հաստատությունը որոշելուց հետո պետք է կապվել ընդունող հաստատության գործընկերների հետ (տե՛ս ստորև «Հանձնում» բաժինը)։ Սա թույլ կտա ընդունող կենտրոնին պատրաստվել հիվանդի ժամանմանը և նախապատրաստել ռեսուրսները (օրինակ՝ արյուն, վիրահատարանի պատրաստում)։ Հետևեք հաղորդակցության տեղական գործելակարգերին, եթե դրանք առկա են։</p><p>Հնարավորության դեպքում պետք է առկա լինեն և՛ նախահիվանդանոցային տեղափոխման, և՛ հաստատությունների միջև փոխանցման պաշտոնական գործելակարգեր։ Դրանք պետք է ներառեն հստակ չափանիշներ այն մասին, թե երբ պետք է հիվանդին փոխանցել։</p><h2>Ստուգաթերթ. Փոխանցման կազմակերպում</h2><ul><li>Ստուգեք, որ հիվանդի կարիքները համապատասխանում են նպատակակետ հաստատության հասանելի ծառայություններին (օրինակ՝ վիրահատարանը բաց է, արյուն կա)</li><li>Նախքան ուղևորվելը անմիջականորեն կապ հաստատեք ընդունող հաստատության՝ հիվանդին ընդունող սպասարկողի հետ</li><li>Համոզվեք, որ հիվանդի վիճակը թույլ կտա նրան հասցնել նպատակակետ հաստատություն դրա համար անհրաժեշտ ժամանակահատվածում</li><li>Համոզվեք, որ հիվանդը և նրա ընտանիքը տեղյակ են տեղափոխման պատճառների, պլանի և նպատակակետի մասին</li><li>Գրանցեք ընտանիքի անդամի կոնտակտային անունը և հեռախոսահամարը ուղարկող հաստատությունում հիվանդի քարտում և հիվանդի հետ ուղարկվող փաստաթղթերում</li><li>Ապահովեք հիվանդի արժեքավոր իրերի անվտանգությունը տեղափոխման համար (հնարավորության դեպքում հանձնեք ընտանիքին)</li><li>Ամփոփ գրավոր արձանագրությունը (ներառյալ անունը, ծննդյան ամսաթիվը, կլինիկական պատկերը և բոլոր միջամտությունները) պետք է ՄԻՇՏ ուղեկցի հիվանդին։</li></ul><h2>(2) ՏԵՂԱՓՈԽՈՒՄ</h2><p>Փոխանցումը ներառում է երկու գործոն՝ հիվանդի տեղափոխում մեկ վայրից մյուսը և տեղափոխման ընթացքում անընդհատ խնամքի ապահովում։ Մեկ անձը չի կարող կատարել երկուսը միաժամանակ։ Տեղափոխման ընթացքում գոնե մեկ բուժաշխատող պետք է միշտ գտնվի մեքենայի նույն հատվածում, ինչ հիվանդը, որպեսզի իրականացնի ընթացիկ մշտադիտարկում, գնահատում և վարում։ Տեղափոխման ընթացքում ԲՈԼՈՐ հիվանդների վիճակը գնահատելու և վերագնահատելու համար պետք է կիրառել <a class=\"xref\" href=\"#/p/s-ABCDE\">«ABCDE» մոտեցումը</a>. կենսացուցանիշները (ներառյալ AVPU-ն կամ ԳԿՍ-ն) պետք է ստուգել յուրաքանչյուր 15 րոպեն մեկ, և հիվանդին պետք է ուշադիր մշտադիտարկել՝ բուժմանն արձագանքելու և վատթարացման նշանների համար։</p><div class=\"callout remember\"><strong>ՀԻՇԵ՛Ք.</strong> Պլանավորեք տեղափոխման ընդհանուր ժամանակը և երթուղին, ստուգեք ճանապարհների վիճակը և եղանակը։ Սա էական է տեղափոխման ընթացքում հիվանդի կարիքները կանխատեսելու համար (օրինակ՝ ն/ե հեղուկի և դեղերի կարիք)։ Համոզվեք, որ հիվանդը և նրա ընտանիքը տեղյակ են տեղափոխման պլանի մասին։ Հնարավորության դեպքում թույլ տվեք ընտանիքի անդամին ուղեկցել երեխաներին։</div><h2>Ստուգաթերթ. Տեղափոխման ընթացքում կարիքներին պատրաստվելը</h2><ul><li>ԱՊՄ՝ աշխատակիցների համար</li><li>Շնչուղիների սարքավորումներ և արտածծման հարմարանք (ուղևորվելուց առաջ ստուգեք՝ արդյոք սարքին են)</li><li>Բավարար քանակի թթվածին (անհրաժեշտության դեպքում՝ թթվածնի փոխարինող բալոնով) և տոպրակ-փական-դիմակ (ՏՓԴ)</li><li>Ներերակային մուտք. նախքան տեղափոխումը ստուգեք, որ ն/ե կատետրը ապահով ամրացված է. մտածեք երկրորդ կատետր կամ պահուստային պաշար ունենալու մասին</li><li>Դեղորայք. վերցրեք դեղերի և հեղուկների լրացուցիչ դեղաչափեր և դիտարկեք այլ դեղերի հնարավոր անհրաժեշտությունը; պատրաստ եղեք նոր կամ կրկնվող ախտանշանների համար</li><li>Նոպաներով/ցնցումներով հիվանդներ. հիվանդի շուրջը դրեք բարձիկներ/բարձեր՝ տեղափոխման ընթացքում նոպայի դեպքում վնասվածքը սահմանափակելու համար։</li><li>Հետևեք փսխմանը և ապահովեք, որ շնչուղիները մնան ազատ, հատկապես ողնաշարի պարանոցային հատվածն անշարժացված հիվանդների մոտ։</li><li>Ստուգեք, որ տրանսպորտային միջոցում բավարար վառելիք կա։</li><li>Համոզվեք, որ մեքենայում հեռախոսակապը կամ ռադիոկապը առկա է և աշխատում է</li></ul><h2>Ստուգաթերթ. Հիվանդի դիրքը</h2><ul><li>Հիվանդին տեղավորեք այնպես, որ շնչուղիները և շնչառությունը լավագույնս անցանելի լինեն։</li><li>Վնասվածքի բացակայության դեպքում կիրառեք կողքի ապահովության դիրքը։</li><li>Եթե հղիությունը &gt;20 շաբաթ է և ողնաշարի վնասվածք ՉԿԱ. հիվանդի մեջքի աջ կողմի երկայնքով բարձեր դրեք՝ հիվանդին դեպի ձախ թեքելու համար։ Սա կանխում է հղի արգանդի կողմից մեծ արյունատար անոթների սեղմումը։</li><li>Ստուգեք ողնաշարի պարանոցային հատվածի անշարժությունը, եթե առկա է դրա ցուցում։</li><li>Հնարավոր ողնաշարային վնասվածք. հիվանդներին տեղաշարժելու համար օգտագործեք ողնաշարի տախտակ և «գերանի գլորում» մեթոդը։ Ճնշման կետերը ստուգեք յուրաքանչյուր 2 ժամը մեկ. անհրաժեշտության դեպքում այդ հատվածների տակ փափուկ գործվածք դրեք։ Եթե հղիությունը &gt;20 շաբաթ է՝ սեպի կամ այլ նյութերի օգնությամբ տախտակը փոքր-ինչ թեքեք դեպի ձախ։</li><li>Բեկակալով անշարժացրեք կոտրվածքները՝ փափուկ հյուսվածքները պաշտպանելու և ցավը ու արյունահոսությունը նվազեցնելու համար։</li></ul><h2>Ստուգաթերթ. Ընթացիկ խնամքը տեղափոխման ժամանակ</h2><ul><li>Առնվազն յուրաքանչյուր 15 րոպեն մեկ կրկնեք «ABCDE» մոտեցումը՝ ներառյալ կենսացուցանիշների կրկնակի ստուգումը և գլյուկոզայի մակարդակի ստուգումը, եթե հիվանդի մոտ եղել է հիպոգլիկեմիա</li><li>Վերահսկեք արյունահոսությունը նախքան տեղափոխումը և հետևեք վերքի հատվածին՝ նոր արյունահոսության հայտնաբերման համար</li><li>Կանոնավոր կերպով վերագնահատեք բեկակալով անշարժացված ցանկացած վերջույթի վիճակը</li><li>Շարունակեք անհրաժեշտ բուժումները (օրինակ՝ թթվածին, ն/ե հեղուկներ, օքսիտոցին, գլյուկոզա)</li><li>Թույլ մի տվեք, որ հիվանդը տեղափոխման ընթացքում շոգի կամ մրսի։</li></ul><p>Մանկաբուժական նկատառումներ</p><ul><li>Պատրաստեք համապատասխան չափի սարքավորումներ և կրիտիկական դեղերի՝ քաշին համապատասխան դեղաչափեր</li><li>Վերցրեք ընտանիքի անդամի կամ ընկերոջ ձեզ հետ և ասեք ընդունող հաստատությանը, թե ով է ուղեկցում երեխային</li><li>Հիշեք, որ ծայրահեղ ծանր հիվանդ կամ վնասված երեխաները սկզբում կարող են լավ տեսք ունենալ, իսկ հետո արագ վատթարանալ։ Ուշադիր մշտադիտարկեք։</li><li>Երեխաների մոտ հաճախ առաջանում են հիպոթերմիա և հիպոգլիկեմիա։ Ուշադիր մշտադիտարկեք։</li></ul><h2>(3) ՀԱՆՁՆՈՒՄ</h2><p>Ֆորմալ հանձնում պետք է իրականացվի խնամքի նոր սպասարկողին փոխանցելու բոլոր դեպքերում, ներառյալ՝ հաստատության ներսում սպասարկողների միջև, տեղափոխում կատարողներին կամ նրանցից ընդունելիս, կամ հեռահար կերպով՝ ուղարկող հաստատությունից ընդունող հաստատության սպասարկողին։ Հիվանդին նոր սպասարկողի հանձնելու պահին բանավոր զեկույցից բացի, հիվանդին միշտ պետք է ուղեկցի կլինիկական վիճակի և բուժման գրավոր փաստաթուղթ՝</p><h2>SBAR («ԻՆԳԱ») հանձնում</h2><p><strong>Ի</strong>րավիճակ (<strong>S</strong>ituation)</p><ul><li>Հիվանդի մասին հիմնական տվյալներ (օրինակ՝ տարիք, սեռ)։</li><li>Հիմնական գանգատ (խնդրի նախնական նկարագրությունը հիվանդի կողմից, օրինակ՝ դժվարացած շնչառություն 3 օր շարունակ, կամ ընկնելուց հետո ցավ բազուկում և այլն)։</li></ul><p><strong>Ն</strong>ախադրյալներ (<strong>B</strong>ackground)</p><ul><li>Հիվանդի դեպքի և/կամ վիճակի 2–4 ամենակարևոր և համապատասխան ասպեկտները (դրանք, ըստ դեպքի, կարող են լինել հիվանդության պատմության, ֆիզիկական զննման կամ հետազոտությունների արդյունքների տարրեր)։</li><li>Ներառեք «ABCDE»-ի ցանկացած կարևոր տվյալ/միջամտություն։</li></ul><p><strong>Գ</strong>նահատում (<strong>A</strong>ssessment)</p><ul><li>Ըստ ձեզ՝ ինչ է պատահել հիվանդին։ Հանձնման/փոխանցման պատճառը։</li></ul><p><strong>Ա</strong>ռաջարկություններ (<strong>R</strong>ecommendations)</p><ul><li>Հատուկ նկատառումներ, որոնց նոր սպասարկողը պետք է պատրաստ լինի՝<ul><li>բուժման պլանի հաջորդ քայլերը;</li><li>հիվանդի վիճակի հնարավոր վատթարացումը (օրինակ՝ շնչուղիների ուշադիր հսկողության կարիք, եթե կասկածվում է ինհալացիոն այրվածք);</li><li>զգուշացումներ նախկին բուժումների կամ միջամտությունների վերաբերյալ (օրինակ՝ ադրենալինի վերջին դեղաչափի ժամը՝ ախտանշանների վերադարձը կանխատեսելու համար, գիտակցության մշտադիտարկման կարիք, եթե տրվել են հանգստացնող դեղեր, եռակողմ վիրակապի մշտադիտարկում՝ մակարդման համար և այլն)։</li></ul></li></ul>","text":"Հիվանդներին դեպքի վայրից առաջին հաստատություն, կամ մի հաստատությունից մեկ այլ հաստատություն փոխանցելիս պահանջվում է հատուկ ուշադրություն՝ (1) նպատակակետի պլանավորմանը, (2) հիվանդի վիճակի շարունակական վարմանը և (3) հանձնմանը։ (1) ՆՊԱՏԱԿԱԿԵՏԻ ՊԼԱՆԱՎՈՐՈՒՄ Դեպքի վայրում բուժված շատ հիվանդների անհրաժեշտ կլինի տեղափոխել բժշկական հաստատություն՝ հետագա բուժման համար։ Բացի այդ, մի հաստատությունում գտնվող հիվանդներին կարող է անհրաժեշտ լինել փոխանցել մեկ այլ հաստատություն՝ առավել բարձր կարգի բուժման համար։ Ցանկացած տեղափոխում պլանավորելիս համոզվեք, որ՝ նպատակակետ հաստատության ծառայությունների մակարդակը համապատասխանում է հիվանդի կարիքներին (օրինակ՝ առկա է վիրահատարան, եթե անհրաժեշտ է վիրահատություն); ակնկալվող ռեսուրսներն այս պահին հասանելի են (օրինակ՝ վիրահատարանն աշխատում է, և արյան փոխներարկման համար արյուն կա); և նպատակակետին հնարավոր է հասնել հիվանդի վիճակին համապատասխան անհրաժեշտ ժամանակահատվածում։ Մի ձգձգեք տեղափոխումը այնպիսի հետազոտությունների կամ միջամտությունների համար, որոնք կարևոր չեն հիվանդի անվտանգության համար, եթե դրանք կարող են իրականացվել ընդունող հաստատությունում։ Առկայության դեպքում հետևեք տեղափոխման և նպատակակետի վերաբերյալ տեղական գործելակարգերին։ Այնտեղ, որտեղ հստակ գործելակարգեր չկան, համադրեք տեղափոխման ժամանակը և հաստատությունների հնարավորությունները. նպատակը անհրաժեշտ խնամքին հնարավորինս շուտ հասնելն է։ Սովորաբար ավելի լավ է երկար սկզբնական տեղափոխման ժամանակ ունենալ, քան կազմակերպել երկրորդ փոխանցումը՝ այն պատճառով, որ առաջին նպատակակետում համապատասխան բուժումը հասանելի չի եղել։ Նպատակային հաստատությունը որոշելուց հետո պետք է կապվել ընդունող հաստատության գործընկերների հետ (տե՛ս ստորև «Հանձնում» բաժինը)։ Սա թույլ կտա ընդունող կենտրոնին պատրաստվել հիվանդի ժամանմանը և նախապատրաստել ռեսուրսները (օրինակ՝ արյուն, վիրահատարանի պատրաստում)։ Հետևեք հաղորդակցության տեղական գործելակարգերին, եթե դրանք առկա են։ Հնարավորության դեպքում պետք է առկա լինեն և՛ նախահիվանդանոցային տեղափոխման, և՛ հաստատությունների միջև փոխանցման պաշտոնական գործելակարգեր։ Դրանք պետք է ներառեն հստակ չափանիշներ այն մասին, թե երբ պետք է հիվանդին փոխանցել։ Ստուգաթերթ. Փոխանցման կազմակերպում Ստուգեք, որ հիվանդի կարիքները համապատասխանում են նպատակակետ հաստատության հասանելի ծառայություններին (օրինակ՝ վիրահատարանը բաց է, արյուն կա) Նախքան ուղևորվելը անմիջականորեն կապ հաստատեք ընդունող հաստատության՝ հիվանդին ընդունող սպասարկողի հետ Համոզվեք, որ հիվանդի վիճակը թույլ կտա նրան հասցնել նպատակակետ հաստատություն դրա համար անհրաժեշտ ժամանակահատվածում Համոզվեք, որ հիվանդը և նրա ընտանիքը տեղյակ են տեղափոխման պատճառների, պլանի և նպատակակետի մասին Գրանցեք ընտանիքի անդամի կոնտակտային անունը և հեռախոսահամարը ուղարկող հաստատությունում հիվանդի քարտում և հիվանդի հետ ուղարկվող փաստաթղթերում Ապահովեք հիվանդի արժեքավոր իրերի անվտանգությունը տեղափոխման համար (հնարավորության դեպքում հանձնեք ընտանիքին) Ամփոփ գրավոր արձանագրությունը (ներառյալ անունը, ծննդյան ամսաթիվը, կլինիկական պատկերը և բոլոր միջամտությունները) պետք է ՄԻՇՏ ուղեկցի հիվանդին։ (2) ՏԵՂԱՓՈԽՈՒՄ Փոխանցումը ներառում է երկու գործոն՝ հիվանդի տեղափոխում մեկ վայրից մյուսը և տեղափոխման ընթացքում անընդհատ խնամքի ապահովում։ Մեկ անձը չի կարող կատարել երկուսը միաժամանակ։ Տեղափոխման ընթացքում գոնե մեկ բուժաշխատող պետք է միշտ գտնվի մեքենայի նույն հատվածում, ինչ հիվանդը, որպեսզի իրականացնի ընթացիկ մշտադիտարկում, գնահատում և վարում։ Տեղափոխման ընթացքում ԲՈԼՈՐ հիվանդների վիճակը գնահատելու և վերագնահատելու համար պետք է կիրառել «ABCDE» մոտեցումը. կենսացուցանիշները (ներառյալ AVPU-ն կամ ԳԿՍ-ն) պետք է ստուգել յուրաքանչյուր 15 րոպեն մեկ, և հիվանդին պետք է ուշադիր մշտադիտարկել՝ բուժմանն արձագանքելու և վատթարացման նշանների համար։ ՀԻՇԵ՛Ք. Պլանավորեք տեղափոխման ընդհանուր ժամանակը և երթուղին, ստուգեք ճանապարհների վիճակը և եղանակը։ Սա էական է տեղափոխման ընթացքում հիվանդի կարիքները կանխատեսելու համար (օրինակ՝ ն/ե հեղուկի և դեղերի կարիք)։ Համոզվեք, որ հիվանդը և նրա ընտանիքը տեղյակ են տեղափոխման պլանի մասին։ Հնարավորության դեպքում թույլ տվեք ընտանիքի անդամին ուղեկցել երեխաներին։ Ստուգաթերթ. Տեղափոխման ընթացքում կարիքներին պատրաստվելը ԱՊՄ՝ աշխատակիցների համար Շնչուղիների սարքավորումներ և արտածծման հարմարանք (ուղևորվելուց առաջ ստուգեք՝ արդյոք սարքին են) Բավարար քանակի թթվածին (անհրաժեշտության դեպքում՝ թթվածնի փոխարինող բալոնով) և տոպրակ-փական-դիմակ (ՏՓԴ) Ներերակային մուտք. նախքան տեղափոխումը ստուգեք, որ ն/ե կատետրը ապահով ամրացված է. մտածեք երկրորդ կատետր կամ պահուստային պաշար ունենալու մասին Դեղորայք. վերցրեք դեղերի և հեղուկների լրացուցիչ դեղաչափեր և դիտարկեք այլ դեղերի հնարավոր անհրաժեշտությունը; պատրաստ եղեք նոր կամ կրկնվող ախտանշանների համար Նոպաներով/ցնցումներով հիվանդներ. հիվանդի շուրջը դրեք բարձիկներ/բարձեր՝ տեղափոխման ընթացքում նոպայի դեպքում վնասվածքը սահմանափակելու համար։ Հետևեք փսխմանը և ապահովեք, որ շնչուղիները մնան ազատ, հատկապես ողնաշարի պարանոցային հատվածն անշարժացված հիվանդների մոտ։ Ստուգեք, որ տրանսպորտային միջոցում բավարար վառելիք կա։ Համոզվեք, որ մեքենայում հեռախոսակապը կամ ռադիոկապը առկա է և աշխատում է Ստուգաթերթ. Հիվանդի դիրքը Հիվանդին տեղավորեք այնպես, որ շնչուղիները և շնչառությունը լավագույնս անցանելի լինեն։ Վնասվածքի բացակայության դեպքում կիրառեք կողքի ապահովության դիրքը։ Եթե հղիությունը >20 շաբաթ է և ողնաշարի վնասվածք ՉԿԱ. հիվանդի մեջքի աջ կողմի երկայնքով բարձեր դրեք՝ հիվանդին դեպի ձախ թեքելու համար։ Սա կանխում է հղի արգանդի կողմից մեծ արյունատար անոթների սեղմումը։ Ստուգեք ողնաշարի պարանոցային հատվածի անշարժությունը, եթե առկա է դրա ցուցում։ Հնարավոր ողնաշարային վնասվածք. հիվանդներին տեղաշարժելու համար օգտագործեք ողնաշարի տախտակ և «գերանի գլորում» մեթոդը։ Ճնշման կետերը ստուգեք յուրաքանչյուր 2 ժամը մեկ. անհրաժեշտության դեպքում այդ հատվածների տակ փափուկ գործվածք դրեք։ Եթե հղիությունը >20 շաբաթ է՝ սեպի կամ այլ նյութերի օգնությամբ տախտակը փոքր-ինչ թեքեք դեպի ձախ։ Բեկակալով անշարժացրեք կոտրվածքները՝ փափուկ հյուսվածքները պաշտպանելու և ցավը ու արյունահոսությունը նվազեցնելու համար։ Ստուգաթերթ. Ընթացիկ խնամքը տեղափոխման ժամանակ Առնվազն յուրաքանչյուր 15 րոպեն մեկ կրկնեք «ABCDE» մոտեցումը՝ ներառյալ կենսացուցանիշների կրկնակի ստուգումը և գլյուկոզայի մակարդակի ստուգումը, եթե հիվանդի մոտ եղել է հիպոգլիկեմիա Վերահսկեք արյունահոսությունը նախքան տեղափոխումը և հետևեք վերքի հատվածին՝ նոր արյունահոսության հայտնաբերման համար Կանոնավոր կերպով վերագնահատեք բեկակալով անշարժացված ցանկացած վերջույթի վիճակը Շարունակեք անհրաժեշտ բուժումները (օրինակ՝ թթվածին, ն/ե հեղուկներ, օքսիտոցին, գլյուկոզա) Թույլ մի տվեք, որ հիվանդը տեղափոխման ընթացքում շոգի կամ մրսի։ Մանկաբուժական նկատառումներ Պատրաստեք համապատասխան չափի սարքավորումներ և կրիտիկական դեղերի՝ քաշին համապատասխան դեղաչափեր Վերցրեք ընտանիքի անդամի կամ ընկերոջ ձեզ հետ և ասեք ընդունող հաստատությանը, թե ով է ուղեկցում երեխային Հիշեք, որ ծայրահեղ ծանր հիվանդ կամ վնասված երեխաները սկզբում կարող են լավ տեսք ունենալ, իսկ հետո արագ վատթարանալ։ Ուշադիր մշտադիտարկեք։ Երեխաների մոտ հաճախ առաջանում են հիպոթերմիա և հիպոգլիկեմիա։ Ուշադիր մշտադիտարկեք։ (3) ՀԱՆՁՆՈՒՄ Ֆորմալ հանձնում պետք է իրականացվի խնամքի նոր սպասարկողին փոխանցելու բոլոր դեպքերում, ներառյալ՝ հաստատության ներսում սպասարկողների միջև, տեղափոխում կատարողներին կամ նրանցից ընդունելիս, կամ հեռահար կերպով՝ ուղարկող հաստատությունից ընդունող հաստատության սպասարկողին։ Հիվանդին նոր սպասարկողի հանձնելու պահին բանավոր զեկույցից բացի, հիվանդին միշտ պետք է ուղեկցի կլինիկական վիճակի և բուժման գրավոր փաստաթուղթ՝ SBAR («ԻՆԳԱ») հանձնում Իրավիճակ (Situation) Հիվանդի մասին հիմնական տվյալներ (օրինակ՝ տարիք, սեռ)։ Հիմնական գանգատ (խնդրի նախնական նկարագրությունը հիվանդի կողմից, օրինակ՝ դժվարացած շնչառություն 3 օր շարունակ, կամ ընկնելուց հետո ցավ բազուկում և այլն)։ Նախադրյալներ (Background) Հիվանդի դեպքի և/կամ վիճակի 2–4 ամենակարևոր և համապատասխան ասպեկտները (դրանք, ըստ դեպքի, կարող են լինել հիվանդության պատմության, ֆիզիկական զննման կամ հետազոտությունների արդյունքների տարրեր)։ Ներառեք «ABCDE»-ի ցանկացած կարևոր տվյալ/միջամտություն։ Գնահատում (Assessment) Ըստ ձեզ՝ ինչ է պատահել հիվանդին։ Հանձնման/փոխանցման պատճառը։ Առաջարկություններ (Recommendations) Հատուկ նկատառումներ, որոնց նոր սպասարկողը պետք է պատրաստ լինի՝ բուժման պլանի հաջորդ քայլերը; հիվանդի վիճակի հնարավոր վատթարացումը (օրինակ՝ շնչուղիների ուշադիր հսկողության կարիք, եթե կասկածվում է ինհալացիոն այրվածք); զգուշացումներ նախկին բուժումների կամ միջամտությունների վերաբերյալ (օրինակ՝ ադրենալինի վերջին դեղաչափի ժամը՝ ախտանշանների վերադարձը կանխատեսելու համար, գիտակցության մշտադիտարկման կարիք, եթե տրվել են հանգստացնող դեղեր, եռակողմ վիրակապի մշտադիտարկում՝ մակարդման համար և այլն)։"},{"id":"s-Adultheadtiltandchinlift","cat":"skills","title":"Մեծահասակի գլխի հետթեքում և կզակի բարձրացում","keywords":"Adult head tilt and chin lift airway","html":"<p>Կիրառեք փոփոխված գիտակցությամբ հիվանդների մոտ, ովքեր ՉՈՒՆԵՆ վնասվածքի պատմության, բայց ի վիճակի չեն պաշտպանելու իրենց շնչուղիները:</p><ul><li>Պառկեցրեք հիվանդին մեջքի վրա՝ հարթ, կոշտ մակերևույթի վրա։</li><li>Մի ձեռքով գլուխը թեքեք հետ, իսկ մատներով բարձրացրեք կզակը։<ul><li>Դրա համար մի ձեռքը դրեք հիվանդի ճակատին, իսկ մյուս ձեռքի երկու մատերը՝ կզակին։ Պտտեք ձեռքերը՝ բարձրացնելով կզակը դեպի վեր՝ կրծքավանդակից հեռու։</li></ul></li><li>Հեռացրեք օտար մարմինները, եթե դրանք տեսանելի են։</li><li>Անհրաժեշտության դեպքում արտածծման եղանակով հեռացրեք շնչուղիներից ցանկացած հեղուկ կամ արտազատուկ։</li><li>Շնչուղիները բաց պահեք. թույլ մի տվեք, որ գլուխը վերադառնա իր նախկին դիրքին, քանի որ այդ դեպքում շնչուղիները կփակվեն։</li></ul><figure><img class=\"fig\" src=\"img/adult-head-tilt.webp\" alt=\"Մեծահասակի գլխի հետթեքում / կզակի բարձրացում\"><figcaption>Մեծահասակի գլխի հետթեքում / կզակի բարձրացում</figcaption></figure>","text":"Կիրառեք փոփոխված գիտակցությամբ հիվանդների մոտ, ովքեր ՉՈՒՆԵՆ վնասվածքի պատմության, բայց ի վիճակի չեն պաշտպանելու իրենց շնչուղիները: Պառկեցրեք հիվանդին մեջքի վրա՝ հարթ, կոշտ մակերևույթի վրա։ Մի ձեռքով գլուխը թեքեք հետ, իսկ մատներով բարձրացրեք կզակը։ Դրա համար մի ձեռքը դրեք հիվանդի ճակատին, իսկ մյուս ձեռքի երկու մատերը՝ կզակին։ Պտտեք ձեռքերը՝ բարձրացնելով կզակը դեպի վեր՝ կրծքավանդակից հեռու։ Հեռացրեք օտար մարմինները, եթե դրանք տեսանելի են։ Անհրաժեշտության դեպքում արտածծման եղանակով հեռացրեք շնչուղիներից ցանկացած հեղուկ կամ արտազատուկ։ Շնչուղիները բաց պահեք. թույլ մի տվեք, որ գլուխը վերադառնա իր նախկին դիրքին, քանի որ այդ դեպքում շնչուղիները կփակվեն։ Մեծահասակի գլխի հետթեքում / կզակի բարձրացում"},{"id":"s-PlaceIV","cat":"skills","title":"Ն/ե կատետրի տեղադրում (մեծահասակ)","keywords":"Insertion of IV cannula adult paediatric","html":"<p>Ներերակային կատետրի տեղադրումը շոկի բուժման համար անհրաժեշտ կարևորագույն հմտություն է։ Եթե մեծահասակի մոտ առկա են շոկի նշաններ և ախտանշաններ, տեղադրեք երկու մեծ տրամաչափի կատետր (14G կամ 16G)։</p><ul><li>Պատրաստեք կատետրը, ընտրված ն/ե հեղուկը, լարանը, ձեռնոցները, կատետրը ծածկելու վիրակապը և ալկոհոլային տամպոն։</li><li>Ձեռնոցներ կրեք։</li><li>Հիվանդի բազուկին էլաստիկ ժապավեն կամ ձեռնոց դրեք՝ որպես ժամանակավոր լարան, որպեսզի երակները լցվեն (այս «լարանը» վերևում նկարագրված լարանից տարբեր է և չպետք է այնքան սեղմել, որ զարկերակային արյան հոսքը դադարի)։ Խուսափեք կատետրը դնել այն բազուկին, որի վրա կարող է լինել երիկամային հիվանդության բուժման համար խուղակ։</li><li>Նայեք և շոշափեք՝ ուղիղ երակ գտնելու համար։ Խուսափեք անոթներից, որոնք անոթազարկ ունեն։ Եթե հիվանդը շոկի մեջ է, երակը գտնելը կարող է դժվար լինել։ Այդ դեպքում երակ որոնեք արմունկի ծալքի փոսում (որտեղ արմունկը ծալվում է, տես նկարը)։</li></ul><figure><img class=\"fig\" src=\"img/iv-antecubital.webp\" alt=\"Ն/ե կատետր արմունկի ծալքի փոսում\"><figcaption>Ն/ե կատետր արմունկի ծալքի փոսում</figcaption></figure><ul><li>Ալկոհոլով կամ մաշկի այլ համապատասխան ախտահանիչով սրբեք այն երակի շուրջ մաշկը, որը նախատեսում եք օգտագործել։</li><li>ՄԻ ՏԵՂԱԴՐԵՔ կատետրը վնասված կամ վարակված թվացող մաշկի միջով։</li><li>Նախապատրաստեք կատետրը։ Նախապատրաստումը կարող է տարբերվել՝ կախված տեղական ռեսուրսներից և կատետրի տեսակից։</li><li>Ասեք հիվանդին, թե ինչ եք անում։</li><li>Հեռացրեք կատետրի պաշտպանիչ պատյանը (ներմուծել պետք է միայն ասեղը՝ պլաստիկ կատետրով պատված)։</li><li>Ասեղը մտցրեք ուղղակի երակի վրայով և նրա ուղղությամբ՝ հնարավորինս հարթ և մաշկին զուգահեռ։ Երակ մտնելիս հետևեք արյան անմիջական հայտնվելուն կատետրում։<ul><li>Եթե արյունը շիթով, կանոնավոր պոմպային ռիթմով է հոսում, ամենայն հավանականությամբ վնասել եք զարկերակ. հեռացրեք ասեղը/կատետրը և տեղը ամուր սեղմեք առնվազն 5–10 րոպե։</li></ul></li><li>Կատետրում արյան հայտնվելուց հետո ասեղը մտցրեք ևս մի քանի միլիմետր, ապա պլաստիկ կատետրը ասեղի վրայով լրիվ առաջ տարեք հիվանդի երակի մեջ։ (Ասեղը ՉՊԵՏՔ Է առաջ շարժվի, երբ սկսում եք կատետրը առաջ տանել։)</li><li>Պահեք կատետրը իր տեղում՝ ճնշում գործադրելով կատետրի հիմքին (այն փակելու և արյան հոսքը դադարեցնելու համար), և հեռացրեք ասեղը՝ թողնելով կատետրը երակում։ Անհրաժեշտության դեպքում արյուն վերցրեք լաբորատոր հետազոտության համար։</li><li>Հանեք ն/ե լարանը և լվացրեք կատետրը նորմալ ֆիզիոլոգիական լուծույթով։</li><li>Կատետրի ծայրին դրեք գլխիկ, լավ ամրացրեք կատետրը և վիրակապեք հատվածը։ Նշումներում փաստաթղթավորեք կատետրի տեղադրման ամսաթիվը։</li><li>Համոզվեք, որ ասեղը դրվում է սուր պարագաների տարայի մեջ։</li></ul><p>Ամեն օր ստուգեք ն/ե հատվածը՝ վարակի նշաններ հայտնաբերելու համար (մաշկի կարմրություն, ցավ, այտուցվածություն)։ Համոզվեք, որ կատետրը դեռ երակում է, այլ ոչ թե երակի կողքին՝ մաշկի տակ, որի դեպքում հեղուկը կներարկվի մաշկի տակ՝ առաջացնելով ցավ և այտուցվածություն։ Եթե նկատեք այտուցվածության կամ վարակի որևէ նշան, հեռացրեք ն/ե կատետրը և կրկին գնահատեք վիճակը։</p><h2>Ն/ե կատետրի տեղադրում (մանկական)</h2><p>Նախ փորձեք կատետրը տեղադրել երեխայի ձեռքի հատվածում։ Կատետր տեղադրելու համար կարելի է օգտագործել նաև այլ վայրեր՝</p><ul><li>Գլխամաշկի երակներ</li><li>Արտաքին պարանոցային երակներ; արմնկային երակներ</li><li>Ազդրային երակներ</li><li>Երեխաների մոտ ն/ե կատետր տեղադրելու նախապատրաստվելիս խնդրեք օգնականին կամ ծնողին երեխայի ձեռքը անշարժ պահել։</li></ul><figure><img class=\"fig\" src=\"img/iv-veins-infant.webp\" alt=\"Երակները կրծքի տարիքի երեխաների մոտ\"><figcaption>Երակները կրծքի տարիքի երեխաների մոտ<br>1. Գլխամաշկի երակներ<br>2. Արտաքին պարանոցային երակներ<br>3. Արմնկային երակներ<br>4. Ձեռքի մեջքային երակներ<br>5. Ազդրային երակներ<br>6. Կոճի երակներ</figcaption></figure><ul><li>Պատրաստեք 21G կամ 23G կատետր։</li><li>Ձեռքի դրսային հատվածում կատետր տեղադրելիս ձեռքը թեք պահեք՝ երակային հետհոսքը կանխելու և երակները տեսանելի դարձնելու համար։ Անհրաժեշտության դեպքում դրեք «ն/ե լարան» (ինչպես վերևում)։ Եթե օգտագործում եք ն/ե լարան, անպայման հիշեք հանել այն։</li><li>Կատետրը տեղադրեք մեծահասակների մոտ կիրառվող նույն եղանակով։ Կրկին համոզվեք, որ արյունը հանգիստ է հոսում կատետրից, այլ ոչ թե պոմպային շիթով։ Տեղադրումից հետո անհրաժեշտության դեպքում լաբորատոր հետազոտության համար արյուն վերցրեք։ Հանեք լարանը և տեղադրումից հետո կատետրը ողողեք փոքր քանակով նորմալ ֆիզիոլոգիական լուծույթով։</li><li>Կատետրը լավ ամրացրեք։ Երեխաները կփորձեն հանել կատետրը և կքանդեն վիրակապերը։ Խուսափեք կպչուն ժապավենի (սպեղանու) մեկ կտորը վերջույթի ամբողջ շրջագծով փաթաթելուց, քանի որ դա կարող է սահմանափակել արյան հոսքը։</li><li>Եթե ն/ե կատետրը դրված է հոդի մոտ (ձեռք, արմնկափոս, ազդրի շրջան), բեկակալով անշարժացրեք հոդը, որպեսզի այն չծալվի և ն/ե հեղուկի ներմուծումը չխանգարվի, և կատետրի հատվածը թեթև վիրակապեք ծավալուն վիրակապերով, որպեսզի երեխան չքաշի տակի կպչուն վիրակապը։</li></ul><figure><img class=\"fig\" src=\"img/iv-secure-child.webp\" alt=\"Ն/ե կատետրի ֆիքսումը երեխայի մոտ\"><figcaption>Ն/ե կատետրի ֆիքսումը երեխայի մոտ</figcaption></figure><figure><img class=\"fig\" src=\"img/iv-insert-child-hand.webp\" alt=\"Ն/ե կատետրի տեղադրումը փոքր երեխայի ձեռքում\"><figcaption>Ն/ե կատետրի տեղադրումը փոքր երեխայի ձեռքում</figcaption></figure><p>Ամեն օր ստուգեք ն/ե ներարկման հատվածը՝ վարակի նշաններ հայտնաբերելու համար (մաշկի կարմրություն, ցավ, այտուցվածություն)։ Համոզվեք, որ կատետրը դեռ երակում է, այլ ոչ թե երակի կողքին՝ մաշկի տակ, որի դեպքում հեղուկը կներարկվի մաշկի տակ՝ առաջացնելով ցավ և այտուցվածություն։ Եթե նկատեք այտուցվածության կամ վարակի որևէ նշան, հեռացրեք ն/ե կատետրը և կրկին գնահատեք վիճակը։</p>","text":"Ներերակային կատետրի տեղադրումը շոկի բուժման համար անհրաժեշտ կարևորագույն հմտություն է։ Եթե մեծահասակի մոտ առկա են շոկի նշաններ և ախտանշաններ, տեղադրեք երկու մեծ տրամաչափի կատետր (14G կամ 16G)։ Պատրաստեք կատետրը, ընտրված ն/ե հեղուկը, լարանը, ձեռնոցները, կատետրը ծածկելու վիրակապը և ալկոհոլային տամպոն։ Ձեռնոցներ կրեք։ Հիվանդի բազուկին էլաստիկ ժապավեն կամ ձեռնոց դրեք՝ որպես ժամանակավոր լարան, որպեսզի երակները լցվեն (այս «լարանը» վերևում նկարագրված լարանից տարբեր է և չպետք է այնքան սեղմել, որ զարկերակային արյան հոսքը դադարի)։ Խուսափեք կատետրը դնել այն բազուկին, որի վրա կարող է լինել երիկամային հիվանդության բուժման համար խուղակ։ Նայեք և շոշափեք՝ ուղիղ երակ գտնելու համար։ Խուսափեք անոթներից, որոնք անոթազարկ ունեն։ Եթե հիվանդը շոկի մեջ է, երակը գտնելը կարող է դժվար լինել։ Այդ դեպքում երակ որոնեք արմունկի ծալքի փոսում (որտեղ արմունկը ծալվում է, տես նկարը)։ Ն/ե կատետր արմունկի ծալքի փոսում Ալկոհոլով կամ մաշկի այլ համապատասխան ախտահանիչով սրբեք այն երակի շուրջ մաշկը, որը նախատեսում եք օգտագործել։ ՄԻ ՏԵՂԱԴՐԵՔ կատետրը վնասված կամ վարակված թվացող մաշկի միջով։ Նախապատրաստեք կատետրը։ Նախապատրաստումը կարող է տարբերվել՝ կախված տեղական ռեսուրսներից և կատետրի տեսակից։ Ասեք հիվանդին, թե ինչ եք անում։ Հեռացրեք կատետրի պաշտպանիչ պատյանը (ներմուծել պետք է միայն ասեղը՝ պլաստիկ կատետրով պատված)։ Ասեղը մտցրեք ուղղակի երակի վրայով և նրա ուղղությամբ՝ հնարավորինս հարթ և մաշկին զուգահեռ։ Երակ մտնելիս հետևեք արյան անմիջական հայտնվելուն կատետրում։ Եթե արյունը շիթով, կանոնավոր պոմպային ռիթմով է հոսում, ամենայն հավանականությամբ վնասել եք զարկերակ. հեռացրեք ասեղը/կատետրը և տեղը ամուր սեղմեք առնվազն 5–10 րոպե։ Կատետրում արյան հայտնվելուց հետո ասեղը մտցրեք ևս մի քանի միլիմետր, ապա պլաստիկ կատետրը ասեղի վրայով լրիվ առաջ տարեք հիվանդի երակի մեջ։ (Ասեղը ՉՊԵՏՔ Է առաջ շարժվի, երբ սկսում եք կատետրը առաջ տանել։) Պահեք կատետրը իր տեղում՝ ճնշում գործադրելով կատետրի հիմքին (այն փակելու և արյան հոսքը դադարեցնելու համար), և հեռացրեք ասեղը՝ թողնելով կատետրը երակում։ Անհրաժեշտության դեպքում արյուն վերցրեք լաբորատոր հետազոտության համար։ Հանեք ն/ե լարանը և լվացրեք կատետրը նորմալ ֆիզիոլոգիական լուծույթով։ Կատետրի ծայրին դրեք գլխիկ, լավ ամրացրեք կատետրը և վիրակապեք հատվածը։ Նշումներում փաստաթղթավորեք կատետրի տեղադրման ամսաթիվը։ Համոզվեք, որ ասեղը դրվում է սուր պարագաների տարայի մեջ։ Ամեն օր ստուգեք ն/ե հատվածը՝ վարակի նշաններ հայտնաբերելու համար (մաշկի կարմրություն, ցավ, այտուցվածություն)։ Համոզվեք, որ կատետրը դեռ երակում է, այլ ոչ թե երակի կողքին՝ մաշկի տակ, որի դեպքում հեղուկը կներարկվի մաշկի տակ՝ առաջացնելով ցավ և այտուցվածություն։ Եթե նկատեք այտուցվածության կամ վարակի որևէ նշան, հեռացրեք ն/ե կատետրը և կրկին գնահատեք վիճակը։ Ն/ե կատետրի տեղադրում (մանկական) Նախ փորձեք կատետրը տեղադրել երեխայի ձեռքի հատվածում։ Կատետր տեղադրելու համար կարելի է օգտագործել նաև այլ վայրեր՝ Գլխամաշկի երակներ Արտաքին պարանոցային երակներ; արմնկային երակներ Ազդրային երակներ Երեխաների մոտ ն/ե կատետր տեղադրելու նախապատրաստվելիս խնդրեք օգնականին կամ ծնողին երեխայի ձեռքը անշարժ պահել։ Երակները կրծքի տարիքի երեխաների մոտ 1. Գլխամաշկի երակներ 2. Արտաքին պարանոցային երակներ 3. Արմնկային երակներ 4. Ձեռքի մեջքային երակներ 5. Ազդրային երակներ 6. Կոճի երակներ Պատրաստեք 21G կամ 23G կատետր։ Ձեռքի դրսային հատվածում կատետր տեղադրելիս ձեռքը թեք պահեք՝ երակային հետհոսքը կանխելու և երակները տեսանելի դարձնելու համար։ Անհրաժեշտության դեպքում դրեք «ն/ե լարան» (ինչպես վերևում)։ Եթե օգտագործում եք ն/ե լարան, անպայման հիշեք հանել այն։ Կատետրը տեղադրեք մեծահասակների մոտ կիրառվող նույն եղանակով։ Կրկին համոզվեք, որ արյունը հանգիստ է հոսում կատետրից, այլ ոչ թե պոմպային շիթով։ Տեղադրումից հետո անհրաժեշտության դեպքում լաբորատոր հետազոտության համար արյուն վերցրեք։ Հանեք լարանը և տեղադրումից հետո կատետրը ողողեք փոքր քանակով նորմալ ֆիզիոլոգիական լուծույթով։ Կատետրը լավ ամրացրեք։ Երեխաները կփորձեն հանել կատետրը և կքանդեն վիրակապերը։ Խուսափեք կպչուն ժապավենի (սպեղանու) մեկ կտորը վերջույթի ամբողջ շրջագծով փաթաթելուց, քանի որ դա կարող է սահմանափակել արյան հոսքը։ Եթե ն/ե կատետրը դրված է հոդի մոտ (ձեռք, արմնկափոս, ազդրի շրջան), բեկակալով անշարժացրեք հոդը, որպեսզի այն չծալվի և ն/ե հեղուկի ներմուծումը չխանգարվի, և կատետրի հատվածը թեթև վիրակապեք ծավալուն վիրակապերով, որպեսզի երեխան չքաշի տակի կպչուն վիրակապը։ Ն/ե կատետրի ֆիքսումը երեխայի մոտ Ն/ե կատետրի տեղադրումը փոքր երեխայի ձեռքում Ամեն օր ստուգեք ն/ե ներարկման հատվածը՝ վարակի նշաններ հայտնաբերելու համար (մաշկի կարմրություն, ցավ, այտուցվածություն)։ Համոզվեք, որ կատետրը դեռ երակում է, այլ ոչ թե երակի կողքին՝ մաշկի տակ, որի դեպքում հեղուկը կներարկվի մաշկի տակ՝ առաջացնելով ցավ և այտուցվածություն։ Եթե նկատեք այտուցվածության կամ վարակի որևէ նշան, հեռացրեք ն/ե կատետրը և կրկին գնահատեք վիճակը։"},{"id":"s-IVFluidAdministrationChild","cat":"skills","title":"Ներերակային հեղուկի ներարկում. երեխա","keywords":"IV fluid administration child shock malnutrition ReSoMal","html":"<p>(<a class=\"xref\" href=\"#/p/s-IVFluidAdministrationAdult\">Սեղմեք այստեղ՝ մեծահասակների ն/ե հեղուկների համար</a>)</p><h2>Հեղուկի ներմուծում շոկի դեպքում՝ երեխաների մոտ</h2><p>Ծանր հիվանդ երեխաների համար հեղուկի պատշաճ քանակը հակասական է՝ հաշվի առնելով վերջին տվյալները, որ բոլուսային հեղուկները կարող են վատթարացնել որոշ երեխաների վիճակը։ Բացի այդ, թույլ պերֆուզիայի և շոկի համապատասխան չափանիշները կարող են տարբերվել՝ ըստ կոնտեքստի։ Ծանր հիվանդ երեխաների խնամքի վերաբերյալ ԱՀԿ 2016 թվականի ուղեցույցներում բոլուսային հեղուկներ պահանջող շոկը սահմանվում է երեք կլինիկական հատկանիշների առկայությամբ՝ սառը վերջույթներ, մազանոթների վերալցում՝ 3 վայրկյանից ավելի, և թույլ ու արագ անոթազարկ։</p><p>Հեղուկի կորստի պատճառով թույլ պերֆուզիա ունեցող երեխաների համար, օրինակ՝ արյունահոսության, այրվածքների կամ ծանր փորլուծության/փսխման դեպքում, նույնպես խորհուրդ են տրվում բոլուսային հեղուկներ։</p><p>Թույլ պերֆուզիայի նշաններ ունեցող այլ երեխաների համար ավելի ապահով կարող է լինել հեղուկների ավելի փոքր քանակների ավելի դանդաղ ներմուծումը։</p><p>Երկրների մասնագիտական խմբերը պետք է հաշվի առնեն երեխայի կլինիկական դրսևորումը, սպասարկողների կարողությունը՝ հայտնաբերելու հիպերվոլեմիայի նշանները, և հսկողության ու աջակցության սարքավորումների հասանելիությունը՝ առաջարկությունները ազգային համատեքստին հարմարեցնելիս։</p><p>Ծանր թերսնուցում, ծանր անեմիա կամ հիպերվոլեմիա ՉՈՒՆԵՑՈՂ շոկային վիճակում գտնվող երեխայի մոտ ն/ե հեղուկային վերականգնում իրականացնելու համար՝</p><ul><li>Տեղադրեք ն/ե կատետր՝ ինչպես նկարագրված է վերևում։</li><li>Կշռեք երեխային կամ հարցրեք ծնողներին՝ վերջին քաշը։</li><li>Տվեք նորմալ ֆիզիոլոգիական լուծույթ կամ Ռինգերի լակտացված լուծույթ՝ մարմնի քաշի յուրաքանչյուր կիլոգրամի համար 10–20 մլ, 30 րոպեի ընթացքում։</li></ul><p><strong>Վերագնահատեք</strong> երեխայի վիճակը առաջին ներարկումից հետո։</p><ul><li>Եթե բարելավում չկա, կրկնեք՝ մարմնի քաշի յուրաքանչյուր կիլոգրամի համար 10 մլ, 30 րոպեի ընթացքում։</li></ul><p>Կանչեք օգնություն և պլանավորեք հանձնումը առավել բարձր կարգի սպասարկողին և արյան փոխներարկման հնարավորություն ունեցող բաժանմունքին։</p><h2>Ն/ե հեղուկային վերականգնում շոկի մեջ գտնվող երեխայի մոտ՝ ծանր թերսնուցման դեպքում</h2><p>Շոկի ԵՎ ծանր թերսնուցման դեպքում երեխաները պահանջում են հատուկ հեղուկներ (առկայության դեպքում)՝ ներմուծման տարբեր արագություններով։ Ծանր թերսնուցմամբ և շոկով երեխաների մոտ հիպոգլիկեմիայի ռիսկը շատ բարձր է, և նրանց հեղուկներից բացի շաքար է պետք <a class=\"xref\" href=\"#/list/medicines\">տե՛ս «ԴԵՂՈՐԱՅՔ» բաժինը</a>։ Եթե երեխան կարող է բերանով հեղուկ ընդունել, տվեք բերանային ռեհիդրացիա ReSoMal-ով (բացառությամբ այն դեպքի, երբ շոկը խոլերայի հետևանք է, որի դեպքում օգտագործեք ԲՌԼ)։ Եթե երեխան լեթարգիկ է, անգիտակից է կամ չի կարողանում հեղուկ ընդունել, տվեք ն/ե հեղուկներ։</p><ul><li>Տեղադրեք ն/ե համակարգ՝ ինչպես վերևում։</li><li>Կշռեք երեխային։</li><li>Տվեք ն/ե հեղուկ՝ 10–15 մլ յուրաքանչյուր կգ-ի համար, 1 ժամվա ընթացքում։ Եթե հատուկ հեղուկներ հասանելի են, տվեք հետևյալներից որևէ մեկը՝ ըստ հասանելիության՝<ul><li>Ռինգերի լակտացված լուծույթ՝ 5%-անոց գլյուկոզայով (դեքստրոզա)</li><li>Կիսով չափ նոսրացված Դարրոյի լուծույթ՝ 5%-անոց գլյուկոզայով (դեքստրոզա)</li><li>0,45%-անոց ֆիզիոլոգիական լուծույթ՝ 5%-անոց գլյուկոզայով (դեքստրոզա)։</li></ul></li><li>Եթե դեքստրոզա պարունակող հեղուկներ չունեք, տվեք հետևյալներից մեկը՝<ul><li>Ռինգերի լակտացված լուծույթ <strong>ԵՎ</strong> դեքստրոզայի առանձին բերանային կամ ն/ե դեղաչափ <a class=\"xref\" href=\"#/list/medicines\">տե՛ս «ԴԵՂՈՐԱՅՔ» բաժինը</a></li><li>Նորմալ ֆիզիոլոգիական լուծույթ <strong>ԵՎ</strong> դեքստրոզայի առանձին բերանային կամ ն/ե դեղաչափ <a class=\"xref\" href=\"#/list/medicines\">տե՛ս «ԴԵՂՈՐԱՅՔ» բաժինը</a>։</li></ul></li></ul><p><strong>Վերագնահատեք</strong> երեխայի վիճակը ներարկման առաջին 5–10 րոպեից հետո, ապա յուրաքանչյուր 5 րոպեն մեկ՝</p><p><strong>Եթե երեխայի վիճակը վատթարանում է ռեհիդրացիայի ընթացքում</strong> (շնչառությունն ավելի է դժվարանում, շնչառության հաճախականությունը բարձրանում է րոպեում 5-ով, իսկ անոթազարկինը՝ րոպեում 15-ով, կամ թոքերում խզզոց է առաջանում)՝</p><ul><li>Դադարեցրեք հեղուկները։</li><li>Կանչեք օգնություն և պլանավորեք հանձնումը առավել բարձր կարգի սպասարկողին։</li></ul><p><strong>Եթե առաջին ներմուծումից հետո բարելավում չկա՝</strong></p><ul><li>Կանչեք օգնություն։ Պլանավորեք հանձնումը առավել բարձր կարգի սպասարկողին այնպիսի կենտրոնում, որտեղ հնարավոր է արյան փոխներարկում։</li><li>Մինչև առավել բարձր կարգի սպասարկողին փոխանցելը տվեք հեղուկ՝ յուրաքանչյուր կգ-ի համար 4 մլ, 1 ժամվա ընթացքում։</li></ul><p><strong>Եթե երեխայի մոտ առկա են բարելավման նշաններ</strong> (մազանոթների վերալցման բարելավում, անոթազարկի և շնչառության հաճախականության նվազում)՝</p><ul><li>Անցեք բերանային կամ նազոգաստրալ ռեհիդրացիայի ReSoMal-ով (նատրիումի ցածր պարունակությամբ բերանային ռեհիդրացիոն լուծույթ)՝ յուրաքանչյուր կգ-ի համար ժամում 10 մլ, մինչև 10 ժամ։</li><li>Փոխանցեք թերսնուցման բաժանմունք։</li></ul>","text":"(Սեղմեք այստեղ՝ մեծահասակների ն/ե հեղուկների համար) Հեղուկի ներմուծում շոկի դեպքում՝ երեխաների մոտ Ծանր հիվանդ երեխաների համար հեղուկի պատշաճ քանակը հակասական է՝ հաշվի առնելով վերջին տվյալները, որ բոլուսային հեղուկները կարող են վատթարացնել որոշ երեխաների վիճակը։ Բացի այդ, թույլ պերֆուզիայի և շոկի համապատասխան չափանիշները կարող են տարբերվել՝ ըստ կոնտեքստի։ Ծանր հիվանդ երեխաների խնամքի վերաբերյալ ԱՀԿ 2016 թվականի ուղեցույցներում բոլուսային հեղուկներ պահանջող շոկը սահմանվում է երեք կլինիկական հատկանիշների առկայությամբ՝ սառը վերջույթներ, մազանոթների վերալցում՝ 3 վայրկյանից ավելի, և թույլ ու արագ անոթազարկ։ Հեղուկի կորստի պատճառով թույլ պերֆուզիա ունեցող երեխաների համար, օրինակ՝ արյունահոսության, այրվածքների կամ ծանր փորլուծության/փսխման դեպքում, նույնպես խորհուրդ են տրվում բոլուսային հեղուկներ։ Թույլ պերֆուզիայի նշաններ ունեցող այլ երեխաների համար ավելի ապահով կարող է լինել հեղուկների ավելի փոքր քանակների ավելի դանդաղ ներմուծումը։ Երկրների մասնագիտական խմբերը պետք է հաշվի առնեն երեխայի կլինիկական դրսևորումը, սպասարկողների կարողությունը՝ հայտնաբերելու հիպերվոլեմիայի նշանները, և հսկողության ու աջակցության սարքավորումների հասանելիությունը՝ առաջարկությունները ազգային համատեքստին հարմարեցնելիս։ Ծանր թերսնուցում, ծանր անեմիա կամ հիպերվոլեմիա ՉՈՒՆԵՑՈՂ շոկային վիճակում գտնվող երեխայի մոտ ն/ե հեղուկային վերականգնում իրականացնելու համար՝ Տեղադրեք ն/ե կատետր՝ ինչպես նկարագրված է վերևում։ Կշռեք երեխային կամ հարցրեք ծնողներին՝ վերջին քաշը։ Տվեք նորմալ ֆիզիոլոգիական լուծույթ կամ Ռինգերի լակտացված լուծույթ՝ մարմնի քաշի յուրաքանչյուր կիլոգրամի համար 10–20 մլ, 30 րոպեի ընթացքում։ Վերագնահատեք երեխայի վիճակը առաջին ներարկումից հետո։ Եթե բարելավում չկա, կրկնեք՝ մարմնի քաշի յուրաքանչյուր կիլոգրամի համար 10 մլ, 30 րոպեի ընթացքում։ Կանչեք օգնություն և պլանավորեք հանձնումը առավել բարձր կարգի սպասարկողին և արյան փոխներարկման հնարավորություն ունեցող բաժանմունքին։ Ն/ե հեղուկային վերականգնում շոկի մեջ գտնվող երեխայի մոտ՝ ծանր թերսնուցման դեպքում Շոկի ԵՎ ծանր թերսնուցման դեպքում երեխաները պահանջում են հատուկ հեղուկներ (առկայության դեպքում)՝ ներմուծման տարբեր արագություններով։ Ծանր թերսնուցմամբ և շոկով երեխաների մոտ հիպոգլիկեմիայի ռիսկը շատ բարձր է, և նրանց հեղուկներից բացի շաքար է պետք տե՛ս «ԴԵՂՈՐԱՅՔ» բաժինը։ Եթե երեխան կարող է բերանով հեղուկ ընդունել, տվեք բերանային ռեհիդրացիա ReSoMal-ով (բացառությամբ այն դեպքի, երբ շոկը խոլերայի հետևանք է, որի դեպքում օգտագործեք ԲՌԼ)։ Եթե երեխան լեթարգիկ է, անգիտակից է կամ չի կարողանում հեղուկ ընդունել, տվեք ն/ե հեղուկներ։ Տեղադրեք ն/ե համակարգ՝ ինչպես վերևում։ Կշռեք երեխային։ Տվեք ն/ե հեղուկ՝ 10–15 մլ յուրաքանչյուր կգ-ի համար, 1 ժամվա ընթացքում։ Եթե հատուկ հեղուկներ հասանելի են, տվեք հետևյալներից որևէ մեկը՝ ըստ հասանելիության՝ Ռինգերի լակտացված լուծույթ՝ 5%-անոց գլյուկոզայով (դեքստրոզա) Կիսով չափ նոսրացված Դարրոյի լուծույթ՝ 5%-անոց գլյուկոզայով (դեքստրոզա) 0,45%-անոց ֆիզիոլոգիական լուծույթ՝ 5%-անոց գլյուկոզայով (դեքստրոզա)։ Եթե դեքստրոզա պարունակող հեղուկներ չունեք, տվեք հետևյալներից մեկը՝ Ռինգերի լակտացված լուծույթ ԵՎ դեքստրոզայի առանձին բերանային կամ ն/ե դեղաչափ տե՛ս «ԴԵՂՈՐԱՅՔ» բաժինը Նորմալ ֆիզիոլոգիական լուծույթ ԵՎ դեքստրոզայի առանձին բերանային կամ ն/ե դեղաչափ տե՛ս «ԴԵՂՈՐԱՅՔ» բաժինը։ Վերագնահատեք երեխայի վիճակը ներարկման առաջին 5–10 րոպեից հետո, ապա յուրաքանչյուր 5 րոպեն մեկ՝ Եթե երեխայի վիճակը վատթարանում է ռեհիդրացիայի ընթացքում (շնչառությունն ավելի է դժվարանում, շնչառության հաճախականությունը բարձրանում է րոպեում 5-ով, իսկ անոթազարկինը՝ րոպեում 15-ով, կամ թոքերում խզզոց է առաջանում)՝ Դադարեցրեք հեղուկները։ Կանչեք օգնություն և պլանավորեք հանձնումը առավել բարձր կարգի սպասարկողին։ Եթե առաջին ներմուծումից հետո բարելավում չկա՝ Կանչեք օգնություն։ Պլանավորեք հանձնումը առավել բարձր կարգի սպասարկողին այնպիսի կենտրոնում, որտեղ հնարավոր է արյան փոխներարկում։ Մինչև առավել բարձր կարգի սպասարկողին փոխանցելը տվեք հեղուկ՝ յուրաքանչյուր կգ-ի համար 4 մլ, 1 ժամվա ընթացքում։ Եթե երեխայի մոտ առկա են բարելավման նշաններ (մազանոթների վերալցման բարելավում, անոթազարկի և շնչառության հաճախականության նվազում)՝ Անցեք բերանային կամ նազոգաստրալ ռեհիդրացիայի ReSoMal-ով (նատրիումի ցածր պարունակությամբ բերանային ռեհիդրացիոն լուծույթ)՝ յուրաքանչյուր կգ-ի համար ժամում 10 մլ, մինչև 10 ժամ։ Փոխանցեք թերսնուցման բաժանմունք։"},{"id":"s-IVFluidAdministrationAdult","cat":"skills","title":"Ներերակային հեղուկի ներարկում. մեծահասակ","keywords":"IV fluid administration adult shock","html":"<p>(<a class=\"xref\" href=\"#/p/s-IVFluidAdministrationChild\">Սեղմեք այստեղ՝ երեխաների ն/ե հեղուկների համար</a>)</p><h2>Հեղուկի ներմուծում շոկի դեպքում՝ մեծահասակների մոտ</h2><ul><li>Միացրեք նորմալ ֆիզիոլոգիական լուծույթ կամ Ռինգերի լակտացված լուծույթ կատետրին։</li><li>Մեծահասակին տվեք 1 լիտր՝ մինչև 30 րոպեի ընթացքում։</li><li>Հեղուկի բոլուսից անմիջապես հետո գնահատեք հեղուկի նկատմամբ արձագանքը։ Գնահատեք պերֆուզիան (մազանոթների վերալցումը, գիտակցության վիճակը, մեզի քանակը) և ստուգեք անոթազարկի հաճախականությունը և արյան ճնշումը։ Եթե վիճակը բարելավվում է, անոթազարկի հաճախականությունը պետք է նվազի, իսկ արյան ճնշումը՝ բարձրանա։ Կարող է բարելավվել նաև գիտակցության վիճակը։</li><li>Ստուգեք հիպերվոլեմիայի առկայությունը (տես նշանները վերևում)։</li><li>Եթե հիվանդը դեռ շոկի մեջ է, և հիպերվոլեմիայի նշաններ չկան, տվեք ևս 1 լիտր բոլուս։</li><li>Եթե ն/ե հեղուկի 2 լիտրից հետո հիվանդը դեռ շոկի մեջ է, վերագնահատեք շարունակվող արյան կորուստը (արտաքին և ներքին) կամ ողնաշարի վնասվածքը և կանչեք առավել բարձր կարգի սպասարկողի։</li></ul><p>Եթե առկա են ծանր թերսնուցման, ծանր անեմիայի կամ հիպերվոլեմիայի նշաններ՝</p><ul><li>Շոկային վիճակում հիվանդներին դեռ անհրաժեշտ են ն/ե հեղուկներ, սակայն կարևոր է հաճախակի վերագնահատել վատթարացող հիպերվոլեմիայի նշանները։</li><li>Հիպերվոլեմիայի բարձր ռիսկ ունեցող այդ մեծահասակ հիվանդների մոտ սկզբում տվեք 500 մլ ն/ե հեղուկ բոլուսով, ապա վերագնահատեք։ Եթե հիպերվոլեմիայի կամ թոքերում հեղուկի նշաններ չկան, տվեք ևս 500 մլ։</li></ul><h2>Հեղուկի ներմուծում շոկի դեպքում՝ երեխաների մոտ</h2><p>Ծանր հիվանդ երեխաների համար հեղուկի պատշաճ քանակը հակասական է՝ հաշվի առնելով վերջին տվյալները, որ բոլուսային հեղուկները կարող են վատթարացնել որոշ երեխաների վիճակը։ Բացի այդ, թույլ պերֆուզիայի և շոկի համապատասխան չափանիշները կարող են տարբերվել՝ ըստ կոնտեքստի։ Ծանր հիվանդ երեխաների խնամքի վերաբերյալ ԱՀԿ 2016 թվականի ուղեցույցներում բոլուսային հեղուկներ պահանջող շոկը սահմանվում է երեք կլինիկական հատկանիշների առկայությամբ՝ սառը վերջույթներ, մազանոթների վերալցում՝ 3 վայրկյանից ավելի, և թույլ ու արագ անոթազարկ։</p><p>Հեղուկի կորստի պատճառով թույլ պերֆուզիա ունեցող երեխաների համար, օրինակ՝ արյունահոսության, այրվածքների կամ ծանր փորլուծության/փսխման դեպքում, նույնպես խորհուրդ են տրվում բոլուսային հեղուկներ։</p><p>Թույլ պերֆուզիայի նշաններ ունեցող այլ երեխաների համար ավելի ապահով կարող է լինել հեղուկների ավելի փոքր քանակների ավելի դանդաղ ներմուծումը։</p><p>Երկրների մասնագիտական խմբերը պետք է հաշվի առնեն երեխայի կլինիկական դրսևորումը, սպասարկողների կարողությունը՝ հայտնաբերելու հիպերվոլեմիայի նշանները, և հսկողության ու աջակցության սարքավորումների հասանելիությունը՝ առաջարկությունները ազգային համատեքստին հարմարեցնելիս։</p><p>Ծանր թերսնուցում, ծանր անեմիա կամ հիպերվոլեմիա ՉՈՒՆԵՑՈՂ շոկային վիճակում գտնվող երեխայի մոտ ն/ե հեղուկային վերականգնում իրականացնելու համար՝</p><ul><li>Տեղադրեք ն/ե կատետր՝ ինչպես նկարագրված է վերևում։</li><li>Կշռեք երեխային կամ հարցրեք ծնողներին՝ վերջին քաշը։</li><li>Տվեք նորմալ ֆիզիոլոգիական լուծույթ կամ Ռինգերի լակտացված լուծույթ՝ մարմնի քաշի յուրաքանչյուր կիլոգրամի համար 10–20 մլ, 30 րոպեի ընթացքում։</li></ul><p><strong>Վերագնահատեք</strong> երեխայի վիճակը առաջին ներարկումից հետո։</p><ul><li>Եթե բարելավում չկա, կրկնեք՝ մարմնի քաշի յուրաքանչյուր կիլոգրամի համար 10 մլ, 30 րոպեի ընթացքում։</li></ul><p>Կանչեք օգնություն և պլանավորեք հանձնումը առավել բարձր կարգի սպասարկողին և արյան փոխներարկման հնարավորություն ունեցող բաժանմունքին։</p><h2>Ն/ե հեղուկային վերականգնում շոկի մեջ գտնվող երեխայի մոտ՝ ծանր թերսնուցման դեպքում</h2><p>Շոկի ԵՎ ծանր թերսնուցման դեպքում երեխաները պահանջում են հատուկ հեղուկներ (առկայության դեպքում)՝ ներմուծման տարբեր արագություններով։ Ծանր թերսնուցմամբ և շոկով երեխաների մոտ հիպոգլիկեմիայի ռիսկը շատ բարձր է, և նրանց հեղուկներից բացի շաքար է պետք <a class=\"xref\" href=\"#/list/medicines\">տե՛ս «ԴԵՂՈՐԱՅՔ» բաժինը</a>։ Եթե երեխան կարող է բերանով հեղուկ ընդունել, տվեք բերանային ռեհիդրացիա ReSoMal-ով (բացառությամբ այն դեպքի, երբ շոկը խոլերայի հետևանք է, որի դեպքում օգտագործեք ԲՌԼ)։ Եթե երեխան լեթարգիկ է, անգիտակից է կամ չի կարողանում հեղուկ ընդունել, տվեք ն/ե հեղուկներ։</p><ul><li>Տեղադրեք ն/ե համակարգ՝ ինչպես վերևում։</li><li>Կշռեք երեխային։</li><li>Տվեք ն/ե հեղուկ՝ 10–15 մլ յուրաքանչյուր կգ-ի համար, 1 ժամվա ընթացքում։ Եթե հատուկ հեղուկներ հասանելի են, տվեք հետևյալներից որևէ մեկը՝ ըստ հասանելիության՝<ul><li>Ռինգերի լակտացված լուծույթ՝ 5%-անոց գլյուկոզայով (դեքստրոզա)</li><li>Կիսով չափ նոսրացված Դարրոյի լուծույթ՝ 5%-անոց գլյուկոզայով (դեքստրոզա)</li><li>0,45%-անոց ֆիզիոլոգիական լուծույթ՝ 5%-անոց գլյուկոզայով (դեքստրոզա)։</li></ul></li><li>Եթե դեքստրոզա պարունակող հեղուկներ չունեք, տվեք հետևյալներից մեկը՝<ul><li>Ռինգերի լակտացված լուծույթ <strong>ԵՎ</strong> դեքստրոզայի առանձին բերանային կամ ն/ե դեղաչափ <a class=\"xref\" href=\"#/list/medicines\">տե՛ս «ԴԵՂՈՐԱՅՔ» բաժինը</a></li><li>Նորմալ ֆիզիոլոգիական լուծույթ <strong>ԵՎ</strong> դեքստրոզայի առանձին բերանային կամ ն/ե դեղաչափ <a class=\"xref\" href=\"#/list/medicines\">տե՛ս «ԴԵՂՈՐԱՅՔ» բաժինը</a>։</li></ul></li></ul><p><strong>Վերագնահատեք</strong> երեխայի վիճակը ներարկման առաջին 5–10 րոպեից հետո, ապա յուրաքանչյուր 5 րոպեն մեկ՝</p><p><strong>Եթե երեխայի վիճակը վատթարանում է ռեհիդրացիայի ընթացքում</strong> (շնչառությունն ավելի է դժվարանում, շնչառության հաճախականությունը բարձրանում է րոպեում 5-ով, իսկ անոթազարկինը՝ րոպեում 15-ով, կամ թոքերում խզզոց է առաջանում)՝</p><ul><li>Դադարեցրեք հեղուկները։</li><li>Կանչեք օգնություն և պլանավորեք հանձնումը առավել բարձր կարգի սպասարկողին։</li></ul><p><strong>Եթե առաջին ներմուծումից հետո բարելավում չկա՝</strong></p><ul><li>Կանչեք օգնություն։ Պլանավորեք հանձնումը առավել բարձր կարգի սպասարկողին այնպիսի կենտրոնում, որտեղ հնարավոր է արյան փոխներարկում։</li><li>Մինչև առավել բարձր կարգի սպասարկողին փոխանցելը տվեք հեղուկ՝ յուրաքանչյուր կգ-ի համար 4 մլ, 1 ժամվա ընթացքում։</li></ul><p><strong>Եթե երեխայի մոտ առկա են բարելավման նշաններ</strong> (մազանոթների վերալցման բարելավում, անոթազարկի և շնչառության հաճախականության նվազում)՝</p><ul><li>Անցեք բերանային կամ նազոգաստրալ ռեհիդրացիայի ReSoMal-ով (նատրիումի ցածր պարունակությամբ բերանային ռեհիդրացիոն լուծույթ)՝ յուրաքանչյուր կգ-ի համար ժամում 10 մլ, մինչև 10 ժամ։</li><li>Փոխանցեք թերսնուցման բաժանմունք։</li></ul>","text":"(Սեղմեք այստեղ՝ երեխաների ն/ե հեղուկների համար) Հեղուկի ներմուծում շոկի դեպքում՝ մեծահասակների մոտ Միացրեք նորմալ ֆիզիոլոգիական լուծույթ կամ Ռինգերի լակտացված լուծույթ կատետրին։ Մեծահասակին տվեք 1 լիտր՝ մինչև 30 րոպեի ընթացքում։ Հեղուկի բոլուսից անմիջապես հետո գնահատեք հեղուկի նկատմամբ արձագանքը։ Գնահատեք պերֆուզիան (մազանոթների վերալցումը, գիտակցության վիճակը, մեզի քանակը) և ստուգեք անոթազարկի հաճախականությունը և արյան ճնշումը։ Եթե վիճակը բարելավվում է, անոթազարկի հաճախականությունը պետք է նվազի, իսկ արյան ճնշումը՝ բարձրանա։ Կարող է բարելավվել նաև գիտակցության վիճակը։ Ստուգեք հիպերվոլեմիայի առկայությունը (տես նշանները վերևում)։ Եթե հիվանդը դեռ շոկի մեջ է, և հիպերվոլեմիայի նշաններ չկան, տվեք ևս 1 լիտր բոլուս։ Եթե ն/ե հեղուկի 2 լիտրից հետո հիվանդը դեռ շոկի մեջ է, վերագնահատեք շարունակվող արյան կորուստը (արտաքին և ներքին) կամ ողնաշարի վնասվածքը և կանչեք առավել բարձր կարգի սպասարկողի։ Եթե առկա են ծանր թերսնուցման, ծանր անեմիայի կամ հիպերվոլեմիայի նշաններ՝ Շոկային վիճակում հիվանդներին դեռ անհրաժեշտ են ն/ե հեղուկներ, սակայն կարևոր է հաճախակի վերագնահատել վատթարացող հիպերվոլեմիայի նշանները։ Հիպերվոլեմիայի բարձր ռիսկ ունեցող այդ մեծահասակ հիվանդների մոտ սկզբում տվեք 500 մլ ն/ե հեղուկ բոլուսով, ապա վերագնահատեք։ Եթե հիպերվոլեմիայի կամ թոքերում հեղուկի նշաններ չկան, տվեք ևս 500 մլ։ Հեղուկի ներմուծում շոկի դեպքում՝ երեխաների մոտ Ծանր հիվանդ երեխաների համար հեղուկի պատշաճ քանակը հակասական է՝ հաշվի առնելով վերջին տվյալները, որ բոլուսային հեղուկները կարող են վատթարացնել որոշ երեխաների վիճակը։ Բացի այդ, թույլ պերֆուզիայի և շոկի համապատասխան չափանիշները կարող են տարբերվել՝ ըստ կոնտեքստի։ Ծանր հիվանդ երեխաների խնամքի վերաբերյալ ԱՀԿ 2016 թվականի ուղեցույցներում բոլուսային հեղուկներ պահանջող շոկը սահմանվում է երեք կլինիկական հատկանիշների առկայությամբ՝ սառը վերջույթներ, մազանոթների վերալցում՝ 3 վայրկյանից ավելի, և թույլ ու արագ անոթազարկ։ Հեղուկի կորստի պատճառով թույլ պերֆուզիա ունեցող երեխաների համար, օրինակ՝ արյունահոսության, այրվածքների կամ ծանր փորլուծության/փսխման դեպքում, նույնպես խորհուրդ են տրվում բոլուսային հեղուկներ։ Թույլ պերֆուզիայի նշաններ ունեցող այլ երեխաների համար ավելի ապահով կարող է լինել հեղուկների ավելի փոքր քանակների ավելի դանդաղ ներմուծումը։ Երկրների մասնագիտական խմբերը պետք է հաշվի առնեն երեխայի կլինիկական դրսևորումը, սպասարկողների կարողությունը՝ հայտնաբերելու հիպերվոլեմիայի նշանները, և հսկողության ու աջակցության սարքավորումների հասանելիությունը՝ առաջարկությունները ազգային համատեքստին հարմարեցնելիս։ Ծանր թերսնուցում, ծանր անեմիա կամ հիպերվոլեմիա ՉՈՒՆԵՑՈՂ շոկային վիճակում գտնվող երեխայի մոտ ն/ե հեղուկային վերականգնում իրականացնելու համար՝ Տեղադրեք ն/ե կատետր՝ ինչպես նկարագրված է վերևում։ Կշռեք երեխային կամ հարցրեք ծնողներին՝ վերջին քաշը։ Տվեք նորմալ ֆիզիոլոգիական լուծույթ կամ Ռինգերի լակտացված լուծույթ՝ մարմնի քաշի յուրաքանչյուր կիլոգրամի համար 10–20 մլ, 30 րոպեի ընթացքում։ Վերագնահատեք երեխայի վիճակը առաջին ներարկումից հետո։ Եթե բարելավում չկա, կրկնեք՝ մարմնի քաշի յուրաքանչյուր կիլոգրամի համար 10 մլ, 30 րոպեի ընթացքում։ Կանչեք օգնություն և պլանավորեք հանձնումը առավել բարձր կարգի սպասարկողին և արյան փոխներարկման հնարավորություն ունեցող բաժանմունքին։ Ն/ե հեղուկային վերականգնում շոկի մեջ գտնվող երեխայի մոտ՝ ծանր թերսնուցման դեպքում Շոկի ԵՎ ծանր թերսնուցման դեպքում երեխաները պահանջում են հատուկ հեղուկներ (առկայության դեպքում)՝ ներմուծման տարբեր արագություններով։ Ծանր թերսնուցմամբ և շոկով երեխաների մոտ հիպոգլիկեմիայի ռիսկը շատ բարձր է, և նրանց հեղուկներից բացի շաքար է պետք տե՛ս «ԴԵՂՈՐԱՅՔ» բաժինը։ Եթե երեխան կարող է բերանով հեղուկ ընդունել, տվեք բերանային ռեհիդրացիա ReSoMal-ով (բացառությամբ այն դեպքի, երբ շոկը խոլերայի հետևանք է, որի դեպքում օգտագործեք ԲՌԼ)։ Եթե երեխան լեթարգիկ է, անգիտակից է կամ չի կարողանում հեղուկ ընդունել, տվեք ն/ե հեղուկներ։ Տեղադրեք ն/ե համակարգ՝ ինչպես վերևում։ Կշռեք երեխային։ Տվեք ն/ե հեղուկ՝ 10–15 մլ յուրաքանչյուր կգ-ի համար, 1 ժամվա ընթացքում։ Եթե հատուկ հեղուկներ հասանելի են, տվեք հետևյալներից որևէ մեկը՝ ըստ հասանելիության՝ Ռինգերի լակտացված լուծույթ՝ 5%-անոց գլյուկոզայով (դեքստրոզա) Կիսով չափ նոսրացված Դարրոյի լուծույթ՝ 5%-անոց գլյուկոզայով (դեքստրոզա) 0,45%-անոց ֆիզիոլոգիական լուծույթ՝ 5%-անոց գլյուկոզայով (դեքստրոզա)։ Եթե դեքստրոզա պարունակող հեղուկներ չունեք, տվեք հետևյալներից մեկը՝ Ռինգերի լակտացված լուծույթ ԵՎ դեքստրոզայի առանձին բերանային կամ ն/ե դեղաչափ տե՛ս «ԴԵՂՈՐԱՅՔ» բաժինը Նորմալ ֆիզիոլոգիական լուծույթ ԵՎ դեքստրոզայի առանձին բերանային կամ ն/ե դեղաչափ տե՛ս «ԴԵՂՈՐԱՅՔ» բաժինը։ Վերագնահատեք երեխայի վիճակը ներարկման առաջին 5–10 րոպեից հետո, ապա յուրաքանչյուր 5 րոպեն մեկ՝ Եթե երեխայի վիճակը վատթարանում է ռեհիդրացիայի ընթացքում (շնչառությունն ավելի է դժվարանում, շնչառության հաճախականությունը բարձրանում է րոպեում 5-ով, իսկ անոթազարկինը՝ րոպեում 15-ով, կամ թոքերում խզզոց է առաջանում)՝ Դադարեցրեք հեղուկները։ Կանչեք օգնություն և պլանավորեք հանձնումը առավել բարձր կարգի սպասարկողին։ Եթե առաջին ներմուծումից հետո բարելավում չկա՝ Կանչեք օգնություն։ Պլանավորեք հանձնումը առավել բարձր կարգի սպասարկողին այնպիսի կենտրոնում, որտեղ հնարավոր է արյան փոխներարկում։ Մինչև առավել բարձր կարգի սպասարկողին փոխանցելը տվեք հեղուկ՝ յուրաքանչյուր կգ-ի համար 4 մլ, 1 ժամվա ընթացքում։ Եթե երեխայի մոտ առկա են բարելավման նշաններ (մազանոթների վերալցման բարելավում, անոթազարկի և շնչառության հաճախականության նվազում)՝ Անցեք բերանային կամ նազոգաստրալ ռեհիդրացիայի ReSoMal-ով (նատրիումի ցածր պարունակությամբ բերանային ռեհիդրացիոն լուծույթ)՝ յուրաքանչյուր կգ-ի համար ժամում 10 մլ, մինչև 10 ժամ։ Փոխանցեք թերսնուցման բաժանմունք։"},{"id":"s-ManagementofChoking","cat":"skills","title":"Շնչահեղձության կառավարում մեծահասակի կամ ավելի մեծ երեխայի մոտ","keywords":"Management of choking abdominal thrusts back blows","html":"<p>Եթե ուտելիս հանկարծակի առաջանում է շնչառական խանգարում, և մարդը բռնում է իր կոկորդը, փորձում է հազալ, առկա է ցիանոզ (մաշկը կապտում է), ստրիդոր կամ աղմկոտ շնչառություն, ապա կասկածեք շնչուղիները խցանող օտար մարմնի առկայության մասին։</p><p>Հնարավորության դեպքում հորդորեք հիվանդին խոսել կամ հազալ և հետևեք՝ արդյոք խցանումը վերանում է։ Մի կիրառեք ստորև նկարագրված հնարքները, եթե հիվանդը լսելիորեն հազում է և/կամ կարողանում է ձայներ արձակել։</p><p>Այն հիվանդը, ով չի կարողանում խոսել կամ հազալ, ունի շնչուղիների լիակատար խցանում և անհապաղ օգնության կարիք ունի՝</p><ul><li>Ասեք հիվանդին, որ պատրաստվում եք օգնել նրան։</li><li>Կատարեք հինգ որովայնի սեղմում (հղիների համար փոփոխությունները տես ստորև)։<ul><li>Կանգնեք հիվանդի հետևում և նրան թեքեք առաջ։<ul><li>Մի ձեռքով բռունցք կազմեք և դրեք որովայնի կենտրոնում՝ պորտի և կրծոսկրի ստորին եզրի միջև։</li><li>Մյուս ձեռքով ծածկեք բռունցքը։</li><li>ՆՇՈՒՄ. Եթե հիվանդը հղի է, բռունցքը կողքով դրեք կրծքավանդակի կենտրոնում և կտրուկ քաշեք դեպի ներս։</li><li>Ուժեղ և արագ սեղմումներով հինգ անգամ քաշեք դեպի ներս և վերև։ Սա օդը դուրս է մղում թոքերից՝ փորձելով «դուրս փչել» խցանը։</li></ul></li><li>Եթե խցանումը պահպանվում է, հիվանդին թեքեք գոտկատեղից առաջ և հինգ անգամ հարվածեք մեջքին (ձեռքի ափի հիմքով հարվածեք թիակների միջև՝ դեպի գլուխ ուղղությամբ)։</li><li>Վերագնահատեք վիճակը։</li><li>Կրկնեք որովայնի սեղմումները, ապա թիկունքին հարվածները՝ մինչև հիվանդը սկսի խոսել, հազալ կամ կորցնի գիտակցությունը։</li><li>Եթե խեղդվող հիվանդը կորցնի գիտակցությունը, պառկեցրեք նրան մեջքի վրա՝ կոշտ մակերևույթի վրա։ Կրծքավանդակի սեղմումները կարող են վերացնել խցանումը։ Եթե կրծքավանդակի սեղմումների շարքը արդյունք չի տալիս, շարունակեք արհեստական շնչառությունը և կրծքավանդակի սեղմումները՝ համապատասխան ՍԹՎ գործելակարգերով։</li></ul></li></ul><figure><img class=\"fig\" src=\"img/choking-adult.webp\" alt=\"Որովայնի սեղմումներ շնչահեղձությամբ մեծահասակի մոտ\"><figcaption>Որովայնի սեղմումներ շնչահեղձությամբ մեծահասակի մոտ<br>Կրծքավանդակի սեղմումներ շնչահեղձության դեպքում՝ հղիության վերջին շրջանում</figcaption></figure><h2>Շնչահեղձության կառավարում կրծքի տարիքի երեխայի կամ փոքր երեխայի մոտ</h2><p>Կրծքի տարիքի երեխային պառկեցրեք ձեր ձեռքին կամ ազդրին՝ դեմքով ներքև, այնպես որ գլուխը որովայնից ցածր լինի։</p><ul><li>Կատարեք հինգ հարված թիկունքին (ձեռքի ափի հիմքով կտրուկ հարվածեք թիակների միջև՝ դեպի գլուխ ուղղությամբ)։</li><li>Եթե խցանումը պահպանվում է, շրջեք երեխային։</li><li>Երկու մատով կատարեք հինգ սեղմում կրծքավանդակին՝ պտկային գծից անմիջապես ներքև, կրծքավանդակի միջին գծում։</li><li>Եթե խցանումը պահպանվում է, ստուգեք երեխայի բերանը՝ հեռացվող տեսանելի խցանումը հայտնաբերելու համար։ (Զգուշացեք կծելուց։)</li><li>Անհրաժեշտության դեպքում կրկնեք ամբողջ գործընթացը, մինչև օտար մարմինը հեռացվի։</li></ul><figure><img class=\"fig\" src=\"img/choking-infant-back.webp\" alt=\"Հարվածներ թիկունքին շնչահեղձության դեպքում՝ կրծքի տարիքի երեխայի մոտ\"><figcaption>Հարվածներ թիկունքին շնչահեղձության դեպքում՝ կրծքի տարիքի երեխայի մոտ</figcaption></figure><figure><img class=\"fig\" src=\"img/choking-infant-chest.webp\" alt=\"Կրծքավանդակի սեղմումներ շնչահեղձության դեպքում՝ կրծքի տարիքի երեխայի մոտ\"><figcaption>Կրծքավանդակի սեղմումներ շնչահեղձության դեպքում՝ կրծքի տարիքի երեխայի մոտ</figcaption></figure>","text":"Եթե ուտելիս հանկարծակի առաջանում է շնչառական խանգարում, և մարդը բռնում է իր կոկորդը, փորձում է հազալ, առկա է ցիանոզ (մաշկը կապտում է), ստրիդոր կամ աղմկոտ շնչառություն, ապա կասկածեք շնչուղիները խցանող օտար մարմնի առկայության մասին։ Հնարավորության դեպքում հորդորեք հիվանդին խոսել կամ հազալ և հետևեք՝ արդյոք խցանումը վերանում է։ Մի կիրառեք ստորև նկարագրված հնարքները, եթե հիվանդը լսելիորեն հազում է և/կամ կարողանում է ձայներ արձակել։ Այն հիվանդը, ով չի կարողանում խոսել կամ հազալ, ունի շնչուղիների լիակատար խցանում և անհապաղ օգնության կարիք ունի՝ Ասեք հիվանդին, որ պատրաստվում եք օգնել նրան։ Կատարեք հինգ որովայնի սեղմում (հղիների համար փոփոխությունները տես ստորև)։ Կանգնեք հիվանդի հետևում և նրան թեքեք առաջ։ Մի ձեռքով բռունցք կազմեք և դրեք որովայնի կենտրոնում՝ պորտի և կրծոսկրի ստորին եզրի միջև։ Մյուս ձեռքով ծածկեք բռունցքը։ ՆՇՈՒՄ. Եթե հիվանդը հղի է, բռունցքը կողքով դրեք կրծքավանդակի կենտրոնում և կտրուկ քաշեք դեպի ներս։ Ուժեղ և արագ սեղմումներով հինգ անգամ քաշեք դեպի ներս և վերև։ Սա օդը դուրս է մղում թոքերից՝ փորձելով «դուրս փչել» խցանը։ Եթե խցանումը պահպանվում է, հիվանդին թեքեք գոտկատեղից առաջ և հինգ անգամ հարվածեք մեջքին (ձեռքի ափի հիմքով հարվածեք թիակների միջև՝ դեպի գլուխ ուղղությամբ)։ Վերագնահատեք վիճակը։ Կրկնեք որովայնի սեղմումները, ապա թիկունքին հարվածները՝ մինչև հիվանդը սկսի խոսել, հազալ կամ կորցնի գիտակցությունը։ Եթե խեղդվող հիվանդը կորցնի գիտակցությունը, պառկեցրեք նրան մեջքի վրա՝ կոշտ մակերևույթի վրա։ Կրծքավանդակի սեղմումները կարող են վերացնել խցանումը։ Եթե կրծքավանդակի սեղմումների շարքը արդյունք չի տալիս, շարունակեք արհեստական շնչառությունը և կրծքավանդակի սեղմումները՝ համապատասխան ՍԹՎ գործելակարգերով։ Որովայնի սեղմումներ շնչահեղձությամբ մեծահասակի մոտ Կրծքավանդակի սեղմումներ շնչահեղձության դեպքում՝ հղիության վերջին շրջանում Շնչահեղձության կառավարում կրծքի տարիքի երեխայի կամ փոքր երեխայի մոտ Կրծքի տարիքի երեխային պառկեցրեք ձեր ձեռքին կամ ազդրին՝ դեմքով ներքև, այնպես որ գլուխը որովայնից ցածր լինի։ Կատարեք հինգ հարված թիկունքին (ձեռքի ափի հիմքով կտրուկ հարվածեք թիակների միջև՝ դեպի գլուխ ուղղությամբ)։ Եթե խցանումը պահպանվում է, շրջեք երեխային։ Երկու մատով կատարեք հինգ սեղմում կրծքավանդակին՝ պտկային գծից անմիջապես ներքև, կրծքավանդակի միջին գծում։ Եթե խցանումը պահպանվում է, ստուգեք երեխայի բերանը՝ հեռացվող տեսանելի խցանումը հայտնաբերելու համար։ (Զգուշացեք կծելուց։) Անհրաժեշտության դեպքում կրկնեք ամբողջ գործընթացը, մինչև օտար մարմինը հեռացվի։ Հարվածներ թիկունքին շնչահեղձության դեպքում՝ կրծքի տարիքի երեխայի մոտ Կրծքավանդակի սեղմումներ շնչահեղձության դեպքում՝ կրծքի տարիքի երեխայի մոտ"},{"id":"s-BagValveMaskVentilation","cat":"skills","title":"Շնչեցում տոպրակ-փական-դիմակով (ՏՓԴ)","keywords":"Bag valve mask ventilation BVM","html":"<p>Գնահատեք և կառավարեք շնչուղիները և կիրառեք շնչեցում տոպրակ-փական-դիմակով (ՏՓԴ) ցանկացած հիվանդի դեպքում, եթե նա չի շնչում կամ շնչում է ոչ համարժեք (իր տարիքի համար չափազանց դանդաղ կամ մակերեսային), ցանկացած անգիտակից հիվանդի դեպքում՝ ոչ նորմալ շնչառությամբ (դանդաղ, մակերեսային, հևացող կամ աղմկոտ), կամ ցանկացած հիվանդի դեպքում, ում անոթազարկը շոշափվում է, սակայն նա ինքնուրույն չի շնչում (եթե անոթազարկը բացակայում է, առաջնորդվեք համապատասխան ՍԹՎ գործելակարգերով)։</p><div class=\"callout caution\"><strong>ԶԳՈՒՇԱՑՈՒՄ! Խուսափեք թոքերի գերագրեսիվ վենտիլյացիայից (տոպրակ-փական-դիմակի չափազանց արագ օգտագործումից կամ շատ մեծ ճնշումից), քանի որ սա կարող է վնասել թոքերը։ Երեխաների թոքերն ավելի փոքր են և փխրուն։ Երեխային շնչեցում կատարելիս հատկապես զգույշ եղեք. գործադրեք միայն այնքան ճնշում, որ կրծքավանդակը բարձրանա, և շնչերի միջև բավարար ժամանակ թողեք արտաշնչման համար (որպեսզի օդը դուրս գա)։ Օդի մեծ ծավալը կամ բարձր ճնշումը կարող են հանգեցնել պնևմոթորաքսի կամ թոքերի անդառնալի վնասման։</strong></div><p class=\"label\">Շնչեցման քայլերը տոպրակ-փական-դիմակով:</p><ul><li>Եթե առկա է թթվածին, ապա միացրեք տոպրակ-փական-դիմակի խողովակը և թթվածնի հոսքի արագությունը դրեք հնարավոր ամենաբարձր մակարդակի վրա։ ՄԻ ՀԵՏԱՁԳԵՔ շնչեցումը՝ թթվածինը նախապատրաստելու համար։ (Թթվածինը կարելի է միացնել նաև ավելի ուշ։)</li><li>Տեղադրեք դիմակը հիվանդի բերանի և քթի վրա (երկու անձանց ներկայության դեպքում մեկը սեղմում է տոպրակը, իսկ մյուսը պահում է դիմակը հիվանդի դեմքին՝ վերահսկելով շնչուղիների անցանելությունը)։</li><li>Ապահովեք հերմետիկություն, որպեսզի օդը դիմակի եզրից դուրս չգա։ Ձեռքը կամ ձեռքերը պահեք «EC» դիրքով՝ բութ մատը և ցուցամատը պետք է կազմեն «C»՝ բռնելով դիմակի վերին հատվածը և հավասար սեղմելով այն դեպի ներքև, իսկ մնացած երեք մատները պետք է բռնեն ծնոտի ոսկրի տակից («E»-ի նման) և ծնոտը դեպի վեր քաշեն՝ շնչուղին բացելու համար։<ul><li>Դեմքը վեր քաշեք դեպի դիմակը (այդպիսով բացելով շնչուղիները), իսկ դիմակը ներքև սեղմեք դեմքին (ապահովելով հերմետիկություն)։</li><li>Եթե շատ ուժեղ սեղմեք դիմակը դեմքին՝ առանց դեմքը դեպի վեր ձգելու, ապա կփակեք շնչուղիները, և հիվանդին շնչեցնելը դժվար կլինի։ Եթե շնչեցնելիս դժվարություն ունեք, փոխեք ձեռքերի և դիմակի դիրքը և կրկին փորձեք։</li></ul></li><li>Եթե հիվանդը շնչում է ինքնուրույն, ապա համաձայնեցրեք պարկի սեղմումը հիվանդի ներշնչման հետ։ Մի փորձեք արհեստական ներշունչ առաջացնել, երբ հիվանդը արտաշնչում է։</li><li>Եթե դիմակի դիրքը փոխելուց հետո դեռ չեք կարողանում շնչեցում կատարել, դիտարկեք շնչուղիների օտար մարմնով խցանման կամ օդի արտահոսքի հավանականությունը։ Եթե դեռ տեղադրված չէ, տեղադրեք բերան-ըմպանային կամ քիթ-ըմպանային օդուղի (տե՛ս «ՀՄՏՈՒԹՅՈՒՆՆԵՐ» բաժինը)։</li><li>Պահեք պարկը մեկ ձեռքում և սեղմեք այն այնքան, որ կրծքավանդակը բարձրանա (մեծահասակի դեպքում՝ մոտավորապես ծավալի մեկ երրորդը. համոզվեք, որ ճիշտ չափի պարկ եք օգտագործում. մեծահասակի պարկը պետք է ունենա մոտ 2 լիտր տարողություն)։</li><li>Սեղմեք պարկը 1–2 վայրկյանի ընթացքում՝ կրծքավանդակի բարձրացման համար (շունչն ավելի արագ տալը կարող է վնասել թոքերը)։</li><li>Մեծահասակին տվեք մեկ շունչ յուրաքանչյուր 6 վայրկյանը մեկ (րոպեում 10 շունչ), ավելի մեծ երեխաներին՝ յուրաքանչյուր 4 վայրկյանը մեկ (րոպեում 15 շունչ), կրծքի տարիքի երեխաներին՝ յուրաքանչյուր 3 վայրկյանը մեկ (րոպեում 20 շունչ)։ ԶԳՈՒՅՇ ԵՂԵՔ փոքր երեխաներին տրվող շնչի ծավալը որոշելիս (տե՛ս «ՀՄՏՈՒԹՅՈՒՆՆԵՐ» բաժինը)։ Մեծ ծավալով շունչ տալը կարող է պնևմոթորաքս առաջացնել։</li><li>Յուրաքանչյուր շնչից հետո սպասեք, որ կրծքավանդակը իջնի՝ նախքան հաջորդ շունչ տալը։</li><li>Հետևեք, որ կրծքավանդակը հավասարաչափ բարձրանա և իջնի յուրաքանչյուր շնչի հետ։</li></ul><figure><img class=\"fig\" src=\"img/bvm.webp\" alt=\"ՏՓԴ. Մեկ սպասարկող\"><figcaption>ՏՓԴ. Մեկ սպասարկող<br>ՏՓԴ. Երկու սպասարկող<br>ՏՓԴ. Աշխատանք երեխայի հետ</figcaption></figure>","text":"Գնահատեք և կառավարեք շնչուղիները և կիրառեք շնչեցում տոպրակ-փական-դիմակով (ՏՓԴ) ցանկացած հիվանդի դեպքում, եթե նա չի շնչում կամ շնչում է ոչ համարժեք (իր տարիքի համար չափազանց դանդաղ կամ մակերեսային), ցանկացած անգիտակից հիվանդի դեպքում՝ ոչ նորմալ շնչառությամբ (դանդաղ, մակերեսային, հևացող կամ աղմկոտ), կամ ցանկացած հիվանդի դեպքում, ում անոթազարկը շոշափվում է, սակայն նա ինքնուրույն չի շնչում (եթե անոթազարկը բացակայում է, առաջնորդվեք համապատասխան ՍԹՎ գործելակարգերով)։ ԶԳՈՒՇԱՑՈՒՄ! Խուսափեք թոքերի գերագրեսիվ վենտիլյացիայից (տոպրակ-փական-դիմակի չափազանց արագ օգտագործումից կամ շատ մեծ ճնշումից), քանի որ սա կարող է վնասել թոքերը։ Երեխաների թոքերն ավելի փոքր են և փխրուն։ Երեխային շնչեցում կատարելիս հատկապես զգույշ եղեք. գործադրեք միայն այնքան ճնշում, որ կրծքավանդակը բարձրանա, և շնչերի միջև բավարար ժամանակ թողեք արտաշնչման համար (որպեսզի օդը դուրս գա)։ Օդի մեծ ծավալը կամ բարձր ճնշումը կարող են հանգեցնել պնևմոթորաքսի կամ թոքերի անդառնալի վնասման։ Շնչեցման քայլերը տոպրակ-փական-դիմակով: Եթե առկա է թթվածին, ապա միացրեք տոպրակ-փական-դիմակի խողովակը և թթվածնի հոսքի արագությունը դրեք հնարավոր ամենաբարձր մակարդակի վրա։ ՄԻ ՀԵՏԱՁԳԵՔ շնչեցումը՝ թթվածինը նախապատրաստելու համար։ (Թթվածինը կարելի է միացնել նաև ավելի ուշ։) Տեղադրեք դիմակը հիվանդի բերանի և քթի վրա (երկու անձանց ներկայության դեպքում մեկը սեղմում է տոպրակը, իսկ մյուսը պահում է դիմակը հիվանդի դեմքին՝ վերահսկելով շնչուղիների անցանելությունը)։ Ապահովեք հերմետիկություն, որպեսզի օդը դիմակի եզրից դուրս չգա։ Ձեռքը կամ ձեռքերը պահեք «EC» դիրքով՝ բութ մատը և ցուցամատը պետք է կազմեն «C»՝ բռնելով դիմակի վերին հատվածը և հավասար սեղմելով այն դեպի ներքև, իսկ մնացած երեք մատները պետք է բռնեն ծնոտի ոսկրի տակից («E»-ի նման) և ծնոտը դեպի վեր քաշեն՝ շնչուղին բացելու համար։ Դեմքը վեր քաշեք դեպի դիմակը (այդպիսով բացելով շնչուղիները), իսկ դիմակը ներքև սեղմեք դեմքին (ապահովելով հերմետիկություն)։ Եթե շատ ուժեղ սեղմեք դիմակը դեմքին՝ առանց դեմքը դեպի վեր ձգելու, ապա կփակեք շնչուղիները, և հիվանդին շնչեցնելը դժվար կլինի։ Եթե շնչեցնելիս դժվարություն ունեք, փոխեք ձեռքերի և դիմակի դիրքը և կրկին փորձեք։ Եթե հիվանդը շնչում է ինքնուրույն, ապա համաձայնեցրեք պարկի սեղմումը հիվանդի ներշնչման հետ։ Մի փորձեք արհեստական ներշունչ առաջացնել, երբ հիվանդը արտաշնչում է։ Եթե դիմակի դիրքը փոխելուց հետո դեռ չեք կարողանում շնչեցում կատարել, դիտարկեք շնչուղիների օտար մարմնով խցանման կամ օդի արտահոսքի հավանականությունը։ Եթե դեռ տեղադրված չէ, տեղադրեք բերան-ըմպանային կամ քիթ-ըմպանային օդուղի (տե՛ս «ՀՄՏՈՒԹՅՈՒՆՆԵՐ» բաժինը)։ Պահեք պարկը մեկ ձեռքում և սեղմեք այն այնքան, որ կրծքավանդակը բարձրանա (մեծահասակի դեպքում՝ մոտավորապես ծավալի մեկ երրորդը. համոզվեք, որ ճիշտ չափի պարկ եք օգտագործում. մեծահասակի պարկը պետք է ունենա մոտ 2 լիտր տարողություն)։ Սեղմեք պարկը 1–2 վայրկյանի ընթացքում՝ կրծքավանդակի բարձրացման համար (շունչն ավելի արագ տալը կարող է վնասել թոքերը)։ Մեծահասակին տվեք մեկ շունչ յուրաքանչյուր 6 վայրկյանը մեկ (րոպեում 10 շունչ), ավելի մեծ երեխաներին՝ յուրաքանչյուր 4 վայրկյանը մեկ (րոպեում 15 շունչ), կրծքի տարիքի երեխաներին՝ յուրաքանչյուր 3 վայրկյանը մեկ (րոպեում 20 շունչ)։ ԶԳՈՒՅՇ ԵՂԵՔ փոքր երեխաներին տրվող շնչի ծավալը որոշելիս (տե՛ս «ՀՄՏՈՒԹՅՈՒՆՆԵՐ» բաժինը)։ Մեծ ծավալով շունչ տալը կարող է պնևմոթորաքս առաջացնել։ Յուրաքանչյուր շնչից հետո սպասեք, որ կրծքավանդակը իջնի՝ նախքան հաջորդ շունչ տալը։ Հետևեք, որ կրծքավանդակը հավասարաչափ բարձրանա և իջնի յուրաքանչյուր շնչի հետ։ ՏՓԴ. Մեկ սպասարկող ՏՓԴ. Երկու սպասարկող ՏՓԴ. Աշխատանք երեխայի հետ"},{"id":"s-Spinalimmobilization","cat":"skills","title":"Ողնաշարի անշարժացում","keywords":"Spinal immobilization log roll recovery position backboard cervical collar","html":"<p><strong>Ողնաշարի անշարժացման երկու տեսակ կա՝ ողնաշարի պարանոցային հատվածի և կրծքային/գոտկային հատվածի անշարժացում։</strong> Դրանք միասին կոչվում են ողնաշարի ամբողջական անշարժացում։ Անշարժացումը կայունացնում է ոսկորները՝ ողնաշարի հետագա վնասումից խուսափելու համար։ <strong>Ողնաշարի անշարժացում կատարեք պոլիտրավմայի պատմությամբ ցանկացած հիվանդի, որն անգիտակից է, կամ որը գիտակից է և ունի պարանոցի ցավ, ողնաշարի ցավազգայունություն, թմրածություն կամ թուլություն։</strong> Հիշեք՝ անշարժացված հիվանդներն ի վիճակի չեն ազատ շարժվելու, և նրանց մոտ մեծ է շնչուղիների խցանման (արտազատուկների կամ փսխունքի պատճառով) և պառկելախոցերի առաջացման վտանգը։ Մշտադիտարկեք նրանց։</p><p class=\"label\">1. Ողնաշարի պարանոցային հատվածն անշարժացնելու համար՝</p><ul><li>Հիվանդը պետք է ուղիղ պառկած լինի մեջքի վրա՝ դեմքով դեպի վերև, հարթ մակերևույթի վրա (օրինակ՝ մահճակալի)։</li><li>Ասեք հիվանդին, թե ինչ եք անում։</li><li>Երկու ձեռքերով պահեք հիվանդի գլուխը երկու կողմից՝ ողնաշարի ուղղությամբ։</li><li>Հիվանդի պարանոցի շարժումները կանխելու համար օգտագործեք ձեռքի տակ եղած պարագաները (ոլորած սրբիչներ, թերթեր, ավազով լցված կամ ն/ե հեղուկներով լի պարկեր) կամ պարանոցի բեկակալ, եթե առկա է։ Դրանք կարելի է ամրացնել գլխին կպչուն ժապավենով (կպչուն սպեղանիով), բայց ոչ երբեք մահճակալին։ (Եթե հիվանդը փսխի, դուք չեք կարողանա նրան շրջել, իսկ եթե հիվանդն ընկնի, ապա կպչուն ժապավենը (սպեղանին) կարող է վնասել ողնաշարի պարանոցային հատվածը։)</li><li>Եթե հիվանդը փսխում է, նրան ամբողջությամբ թեքեք կողքի՝ «գերանի գլորում» մեթոդով (տես ստորև)՝ գլուխը պահելով մարմնի հետ նույն գծի վրա։</li><li>Ապահովեք ինչ-որ մեկի անընդհատ ներկայությունը հիվանդի մոտ՝ նրա շնչուղիների վիճակին հետևելու համար։</li><li>Հիշեք՝ մարմնի այլ մասում ուժեղ ցավ կամ լուրջ վնասվածք ունեցող հիվանդը կարող է պարանոցում ցավ չզգալ, նույնիսկ եթե այդտեղ կոտրվածք կա։ Վնասվածքի առաջացման մեխանիզմը պետք է կասկած առաջացնի։</li></ul><h2>2. «Գերանի գլորում» մեթոդը</h2><p>Ցանկացած անշարժացված հիվանդին կամ ողնաշարի վնասվածքի կասկածով ցանկացած հիվանդի տեղաշարժելու համար (օրինակ՝ երբ հիվանդը փսխելու է կամ պետք է տեղափոխվի) կիրառեք «գերանի գլորում» մեթոդը (տես նկարը)՝</p><ul><li>Օգնություն խնդրեք։ Լավագույն տարբերակն է, երբ մեկ անձ պահում է հիվանդի գլուխը, մեկ կամ երկու հոգի՝ մարմինը, և մեկը՝ ոտքերը։</li><li>Գլխի մոտ գտնվողը պետք է գլուխը, պարանոցը և իրանը պահի ողնաշարի մնացած մասի հետ նույն առանցքի վրա։ Նա պետք է նախաբազուկները ամուր դնի գլխի երկու կողմերում, իսկ ձեռքերով բռնի ուսերից, որպեսզի գլուխը և պարանոցը մնան ողնաշարի մնացած մասի ուղղությամբ։ Հիվանդին շրջելիս պետք է պահպանել այս ուղղվածությունը։</li><li>Գլուխը և պարանոցը պահողը ղեկավարում է թիմին և ասում է «մեկ, երկու, երեք, շրջեցինք»՝ բոլոր օգնականների համար շրջելու ժամանակը համաձայնեցնելու համար։</li><li>Միասին աշխատելով՝ շրջեք հիվանդին կողքի՝ ողնաշարը ուղիղ պահելով։</li><li>Շրջելու ժամանակ գլուխը և պարանոցը կարգավորողը պետք է ապահովի, որ ողնաշարի պարանոցային հատվածը մնա ողնաշարի մնացած մասի ուղղությամբ։ Իսկ մարմինը շրջողները պետք է ապահովեն, որ ողնաշարի մնացած մասը մնա հնարավորինս ուղիղ։</li><li>Երբ հիվանդը շրջված է կողքի, բուժաշխատողներից մեկը կարող է զննել մեջքը, անհրաժեշտության դեպքում դնել կամ հեռացնել ողնաշարի տախտակը (հարթ պատգարակը) և/կամ մշակել մեջքի վերքերը։</li><li>Հիվանդին կրկին մեջքի վրա պառկեցնելու համար գլուխը և պարանոցը պահող անձը հրահանգում է «մեկ, երկու, երեք, շրջեցինք»՝ համակարգված շարժում ապահովելու համար։</li><li>Ողնաշարի տախտակը միշտ հեռացրեք հնարավորինս շուտ՝ «գերանի գլորում» մեթոդով։ Տախտակի վրա անցկացրած ժամանակը մեծացնում է պառկելախոցերի առաջացման վտանգը։ Հաճախակի ստուգեք մարմնի հետնամասում ճնշվող կետերը՝ «գերանի գլորում» մեթոդի օգնությամբ։</li></ul><figure><img class=\"fig\" src=\"img/log-roll-prep.webp\" alt=\"«Գերանի գլորում» մեթոդով շրջելուն նախապատրաստվելը\"><figcaption>«Գերանի գլորում» մեթոդով շրջելուն նախապատրաստվելը</figcaption></figure><p><strong>3. Ողնաշարի կրծքային և գոտկային հատվածներն անշարժացնելու համար՝</strong></p><ul><li>Անշարժացրեք ողնաշարի պարանոցային հատվածը, ինչպես նկարագրված է նախորդ բաժնում։</li><li>Հիվանդին պառկեցրեք հարթ մակերևույթի վրա՝ հրահանգելով պառկել ուղիղ և չշարժվել։</li><li>Տեղափոխման համար «գերանի գլորում» մեթոդով հիվանդին պառկեցրեք հարթ մակերևույթի (օրինակ՝ ողնաշարի տախտակի) վրա՝ ողնաշարի շարժումները կանխելու համար։ Տախտակը մի ամրացրեք մահճակալին, քանի որ այդ դեպքում անհրաժեշտության դեպքում չեք կարողանա կիրառել «գերանի գլորում» մեթոդը (տես վերևում)։</li><li>Նախքան անշարժացնելը համոզվեք, որ հիվանդի մեջքի վրա կամ տակ ապակու կտորներ կամ այլ բեկորներ չկան։ Դա ստուգելու համար կիրառեք «գերանի գլորում» մեթոդը։ Անշարժացված հիվանդներին պետք է հաճախակի ստուգել՝ ճնշման կետերում վերքերից (պառկելախոցերից) խուսափելու համար։</li><li>Եթե հիվանդը սկսում է փսխել. «գերանի գլորում» մեթոդով նրան շրջեք կողքի, որպեսզի փսխունքը չհայտնվի շնչուղիներում։</li><li>Ողնաշարի տախտակները պետք է օգտագործել ՄԻԱՅՆ հիվանդներին տեղաշարժելու համար։ Հիվանդներին տախտակների վրա երկար թողնելը կարող է պառկելախոցեր առաջացնել։ Հիվանդներին տախտակից հանեք հնարավորինս շուտ՝ բուժհաստատություն հասնելուն պես, երբ նրանց կարելի է պառկեցնել հարթ մակերևույթի վրա։</li></ul><figure><img class=\"fig\" src=\"img/spinal-transport.webp\" alt=\"Ողնաշարի անշարժացում՝ հիվանդին տեղափոխելու համար\"><figcaption>Ողնաշարի անշարժացում՝ հիվանդին տեղափոխելու համար</figcaption></figure><p class=\"label\">Հատուկ դեպքեր:</p><h2>Հղիություն</h2><p>Եթե հիվանդը 20 շաբաթից ավելի հղի է և կարիք ունի ողնաշարի անշարժացման, անշարժացրեք ողնաշարը վերը նկարագրված եղանակով։ Այնուհետև տախտակի տակ՝ մեջքի և կոնքի մոտ աջ կողմից, տեղադրեք բարձիկ՝ հիվանդին դեպի ձախ թեքված դիրքավորելու համար։ Սա կօգնի կանխել հղի արգանդի կողմից մեծ արյունատար անոթների սեղմումը, ինչը կարող է նվազեցնել դեպի սիրտ վերադարձող արյան քանակը։</p><h2>Անգիտակից վիճակ</h2><p>Եթե հիվանդը անգիտակից է կամ կիսագիտակից, և ՎՆԱՍՎԱԾՔ ՉԿԱ, պառկեցրեք նրան ձախ կողմի վրա։ Կայունացրեք հիվանդի դիրքը՝ վերևի ոտքը ծալելով դեպի առաջ։ Ձախ ձեռքը պետք է ուղիղ լինի, և հիվանդի գլուխը հենվի այդ ձեռքին, ինչը կբարձրացնի գլուխը և բերանը կդարձնի դեպի ներքև։ Այս դիրքը թույլ կտա փսխունքին և այլ արտազատուկներին դուրս հոսել բերանից՝ շնչուղիների խցանման ավելի ցածր ռիսկով։ Սա կոչվում է «կողքի ապահովության դիրք» (տես նկարը)։</p><figure><img class=\"fig\" src=\"img/recovery-position.webp\" alt=\"Կողքի ապահովության դիրք\"><figcaption>Կողքի ապահովության դիրք</figcaption></figure>","text":"Ողնաշարի անշարժացման երկու տեսակ կա՝ ողնաշարի պարանոցային հատվածի և կրծքային/գոտկային հատվածի անշարժացում։ Դրանք միասին կոչվում են ողնաշարի ամբողջական անշարժացում։ Անշարժացումը կայունացնում է ոսկորները՝ ողնաշարի հետագա վնասումից խուսափելու համար։ Ողնաշարի անշարժացում կատարեք պոլիտրավմայի պատմությամբ ցանկացած հիվանդի, որն անգիտակից է, կամ որը գիտակից է և ունի պարանոցի ցավ, ողնաշարի ցավազգայունություն, թմրածություն կամ թուլություն։ Հիշեք՝ անշարժացված հիվանդներն ի վիճակի չեն ազատ շարժվելու, և նրանց մոտ մեծ է շնչուղիների խցանման (արտազատուկների կամ փսխունքի պատճառով) և պառկելախոցերի առաջացման վտանգը։ Մշտադիտարկեք նրանց։ 1. Ողնաշարի պարանոցային հատվածն անշարժացնելու համար՝ Հիվանդը պետք է ուղիղ պառկած լինի մեջքի վրա՝ դեմքով դեպի վերև, հարթ մակերևույթի վրա (օրինակ՝ մահճակալի)։ Ասեք հիվանդին, թե ինչ եք անում։ Երկու ձեռքերով պահեք հիվանդի գլուխը երկու կողմից՝ ողնաշարի ուղղությամբ։ Հիվանդի պարանոցի շարժումները կանխելու համար օգտագործեք ձեռքի տակ եղած պարագաները (ոլորած սրբիչներ, թերթեր, ավազով լցված կամ ն/ե հեղուկներով լի պարկեր) կամ պարանոցի բեկակալ, եթե առկա է։ Դրանք կարելի է ամրացնել գլխին կպչուն ժապավենով (կպչուն սպեղանիով), բայց ոչ երբեք մահճակալին։ (Եթե հիվանդը փսխի, դուք չեք կարողանա նրան շրջել, իսկ եթե հիվանդն ընկնի, ապա կպչուն ժապավենը (սպեղանին) կարող է վնասել ողնաշարի պարանոցային հատվածը։) Եթե հիվանդը փսխում է, նրան ամբողջությամբ թեքեք կողքի՝ «գերանի գլորում» մեթոդով (տես ստորև)՝ գլուխը պահելով մարմնի հետ նույն գծի վրա։ Ապահովեք ինչ-որ մեկի անընդհատ ներկայությունը հիվանդի մոտ՝ նրա շնչուղիների վիճակին հետևելու համար։ Հիշեք՝ մարմնի այլ մասում ուժեղ ցավ կամ լուրջ վնասվածք ունեցող հիվանդը կարող է պարանոցում ցավ չզգալ, նույնիսկ եթե այդտեղ կոտրվածք կա։ Վնասվածքի առաջացման մեխանիզմը պետք է կասկած առաջացնի։ 2. «Գերանի գլորում» մեթոդը Ցանկացած անշարժացված հիվանդին կամ ողնաշարի վնասվածքի կասկածով ցանկացած հիվանդի տեղաշարժելու համար (օրինակ՝ երբ հիվանդը փսխելու է կամ պետք է տեղափոխվի) կիրառեք «գերանի գլորում» մեթոդը (տես նկարը)՝ Օգնություն խնդրեք։ Լավագույն տարբերակն է, երբ մեկ անձ պահում է հիվանդի գլուխը, մեկ կամ երկու հոգի՝ մարմինը, և մեկը՝ ոտքերը։ Գլխի մոտ գտնվողը պետք է գլուխը, պարանոցը և իրանը պահի ողնաշարի մնացած մասի հետ նույն առանցքի վրա։ Նա պետք է նախաբազուկները ամուր դնի գլխի երկու կողմերում, իսկ ձեռքերով բռնի ուսերից, որպեսզի գլուխը և պարանոցը մնան ողնաշարի մնացած մասի ուղղությամբ։ Հիվանդին շրջելիս պետք է պահպանել այս ուղղվածությունը։ Գլուխը և պարանոցը պահողը ղեկավարում է թիմին և ասում է «մեկ, երկու, երեք, շրջեցինք»՝ բոլոր օգնականների համար շրջելու ժամանակը համաձայնեցնելու համար։ Միասին աշխատելով՝ շրջեք հիվանդին կողքի՝ ողնաշարը ուղիղ պահելով։ Շրջելու ժամանակ գլուխը և պարանոցը կարգավորողը պետք է ապահովի, որ ողնաշարի պարանոցային հատվածը մնա ողնաշարի մնացած մասի ուղղությամբ։ Իսկ մարմինը շրջողները պետք է ապահովեն, որ ողնաշարի մնացած մասը մնա հնարավորինս ուղիղ։ Երբ հիվանդը շրջված է կողքի, բուժաշխատողներից մեկը կարող է զննել մեջքը, անհրաժեշտության դեպքում դնել կամ հեռացնել ողնաշարի տախտակը (հարթ պատգարակը) և/կամ մշակել մեջքի վերքերը։ Հիվանդին կրկին մեջքի վրա պառկեցնելու համար գլուխը և պարանոցը պահող անձը հրահանգում է «մեկ, երկու, երեք, շրջեցինք»՝ համակարգված շարժում ապահովելու համար։ Ողնաշարի տախտակը միշտ հեռացրեք հնարավորինս շուտ՝ «գերանի գլորում» մեթոդով։ Տախտակի վրա անցկացրած ժամանակը մեծացնում է պառկելախոցերի առաջացման վտանգը։ Հաճախակի ստուգեք մարմնի հետնամասում ճնշվող կետերը՝ «գերանի գլորում» մեթոդի օգնությամբ։ «Գերանի գլորում» մեթոդով շրջելուն նախապատրաստվելը 3. Ողնաշարի կրծքային և գոտկային հատվածներն անշարժացնելու համար՝ Անշարժացրեք ողնաշարի պարանոցային հատվածը, ինչպես նկարագրված է նախորդ բաժնում։ Հիվանդին պառկեցրեք հարթ մակերևույթի վրա՝ հրահանգելով պառկել ուղիղ և չշարժվել։ Տեղափոխման համար «գերանի գլորում» մեթոդով հիվանդին պառկեցրեք հարթ մակերևույթի (օրինակ՝ ողնաշարի տախտակի) վրա՝ ողնաշարի շարժումները կանխելու համար։ Տախտակը մի ամրացրեք մահճակալին, քանի որ այդ դեպքում անհրաժեշտության դեպքում չեք կարողանա կիրառել «գերանի գլորում» մեթոդը (տես վերևում)։ Նախքան անշարժացնելը համոզվեք, որ հիվանդի մեջքի վրա կամ տակ ապակու կտորներ կամ այլ բեկորներ չկան։ Դա ստուգելու համար կիրառեք «գերանի գլորում» մեթոդը։ Անշարժացված հիվանդներին պետք է հաճախակի ստուգել՝ ճնշման կետերում վերքերից (պառկելախոցերից) խուսափելու համար։ Եթե հիվանդը սկսում է փսխել. «գերանի գլորում» մեթոդով նրան շրջեք կողքի, որպեսզի փսխունքը չհայտնվի շնչուղիներում։ Ողնաշարի տախտակները պետք է օգտագործել ՄԻԱՅՆ հիվանդներին տեղաշարժելու համար։ Հիվանդներին տախտակների վրա երկար թողնելը կարող է պառկելախոցեր առաջացնել։ Հիվանդներին տախտակից հանեք հնարավորինս շուտ՝ բուժհաստատություն հասնելուն պես, երբ նրանց կարելի է պառկեցնել հարթ մակերևույթի վրա։ Ողնաշարի անշարժացում՝ հիվանդին տեղափոխելու համար Հատուկ դեպքեր: Հղիություն Եթե հիվանդը 20 շաբաթից ավելի հղի է և կարիք ունի ողնաշարի անշարժացման, անշարժացրեք ողնաշարը վերը նկարագրված եղանակով։ Այնուհետև տախտակի տակ՝ մեջքի և կոնքի մոտ աջ կողմից, տեղադրեք բարձիկ՝ հիվանդին դեպի ձախ թեքված դիրքավորելու համար։ Սա կօգնի կանխել հղի արգանդի կողմից մեծ արյունատար անոթների սեղմումը, ինչը կարող է նվազեցնել դեպի սիրտ վերադարձող արյան քանակը։ Անգիտակից վիճակ Եթե հիվանդը անգիտակից է կամ կիսագիտակից, և ՎՆԱՍՎԱԾՔ ՉԿԱ, պառկեցրեք նրան ձախ կողմի վրա։ Կայունացրեք հիվանդի դիրքը՝ վերևի ոտքը ծալելով դեպի առաջ։ Ձախ ձեռքը պետք է ուղիղ լինի, և հիվանդի գլուխը հենվի այդ ձեռքին, ինչը կբարձրացնի գլուխը և բերանը կդարձնի դեպի ներքև։ Այս դիրքը թույլ կտա փսխունքին և այլ արտազատուկներին դուրս հոսել բերանից՝ շնչուղիների խցանման ավելի ցածր ռիսկով։ Սա կոչվում է «կողքի ապահովության դիրք» (տես նկարը)։ Կողքի ապահովության դիրք"},{"id":"s-Spacer","cat":"skills","title":"Սփեյսերի պատրաստումը պլաստիկ շշից","keywords":"Spacer plastic bottle salbutamol inhaler","html":"<p>Սփեյսերի նպատակն է իր մեջ պահել դեղաչափող ինհալյատորից արձակվող դեղը (սալբուտամոլ), որպեսզի հիվանդը բավարար ժամանակ ունենա այն արդյունավետ ներշնչելու համար։ (Առանց փորձի և պատշաճ վերապատրաստման՝ դեղաչափող ինհալյատորից արդյունավետ օգտվելը կարող է դժվար լինել, և դեղը հաճախ կորչում է բերանում կամ կոկորդում։) Սակայն սփեյսերները պետք է պատրաստել նախապես։ Մի հետաձգեք սալբուտամոլի տրամադրումը՝ սփեյսեր պատրաստելու համար։</p><figure><img class=\"fig\" src=\"img/spacer-bottle.webp\" alt=\"Պլաստիկ շշից պատրաստված սփեյսեր\"><figcaption>Պլաստիկ շշից պատրաստված սփեյսեր</figcaption></figure><ul><li>Օգտագործեք մաքուր, 300–500 մլ-անոց պլաստիկ շիշ (լվացեք մաքրող միջոցով, ողողեք և լավ չորացրեք)։</li><li>Հանեք դեղաչափող ինհալյատորի կափարիչը և գծեք ինհալյատորի բացվածքի ձևը շշի հատակին՝ անմիջապես շշի բերանի հակառակ կողմում։</li><li>Պլաստիկ շշից պատրաստված սփեյսեր</li><li>Շշի հատակում բացվածք կտրեք՝ գծված ձևից մի փոքր ավելի փոքր։ Կարող եք կտրել մկրատով կամ տաքացրած թղթի ամրակով։</li><li>Ինհալյատորը մտցրեք սփեյսերի մեջ՝ չափը ստուգելու համար (ինհալյատորը պետք է ամուր նստի կտրված բացվածքում)։</li><li>Օգտագործելուց առաջ միշտ հիշեք սփեյսերը նախապատրաստել հինգ փչումով՝ «մեռած» տարածությունը մաքրելու համար։</li></ul>","text":"Սփեյսերի նպատակն է իր մեջ պահել դեղաչափող ինհալյատորից արձակվող դեղը (սալբուտամոլ), որպեսզի հիվանդը բավարար ժամանակ ունենա այն արդյունավետ ներշնչելու համար։ (Առանց փորձի և պատշաճ վերապատրաստման՝ դեղաչափող ինհալյատորից արդյունավետ օգտվելը կարող է դժվար լինել, և դեղը հաճախ կորչում է բերանում կամ կոկորդում։) Սակայն սփեյսերները պետք է պատրաստել նախապես։ Մի հետաձգեք սալբուտամոլի տրամադրումը՝ սփեյսեր պատրաստելու համար։ Պլաստիկ շշից պատրաստված սփեյսեր Օգտագործեք մաքուր, 300–500 մլ-անոց պլաստիկ շիշ (լվացեք մաքրող միջոցով, ողողեք և լավ չորացրեք)։ Հանեք դեղաչափող ինհալյատորի կափարիչը և գծեք ինհալյատորի բացվածքի ձևը շշի հատակին՝ անմիջապես շշի բերանի հակառակ կողմում։ Պլաստիկ շշից պատրաստված սփեյսեր Շշի հատակում բացվածք կտրեք՝ գծված ձևից մի փոքր ավելի փոքր։ Կարող եք կտրել մկրատով կամ տաքացրած թղթի ամրակով։ Ինհալյատորը մտցրեք սփեյսերի մեջ՝ չափը ստուգելու համար (ինհալյատորը պետք է ամուր նստի կտրված բացվածքում)։ Օգտագործելուց առաջ միշտ հիշեք սփեյսերը նախապատրաստել հինգ փչումով՝ «մեռած» տարածությունը մաքրելու համար։"},{"id":"s-SnakeBiteWoundManagement","cat":"skills","title":"Վերքերի վարում. օձի կծած","keywords":"Snake bite wound management","html":"<div class=\"callout remember\">Նշում. Հնարավորության դեպքում լուսանկարեք օձին և ուղարկեք լուսանկարը հիվանդի հետ։</div><p>Օձի կծածից հետո վերջույթի անշարժացումը կարևոր է՝ շարժումները սահմանափակելու և թույնի ներծծումը դանդաղեցնելու համար։</p><ul><li>Ցանկացած վերք վիրակապելուց կամ բեկակալ դնելուց առաջ և հետո միշտ գնահատեք անոթազարկը, մազանոթների վերալցումը և զգայունությունը։</li><li>Կարող եք օգտագործել լայն էլաստիկ վիրակապ և փաթաթել այն կծածի ստորին հատվածից դեպի վեր։ Վիրակապը պետք է լինի ամուր, սակայն չպետք է ընդհատի վերջույթի անոթազարկերը։ Վիրակապը փաթաթեք հնարավորինս ընդգրկելով վերջույթն ամբողջությամբ։<ul><li>Սա խորհուրդ է տրվում, եթե ձեր տարածքի օձերը թույն են արտադրում, որը վնասում է նյարդերը, առաջացնում է կաթված, ծանրացնում է հիվանդի վիճակը, կամ եթե տեղափոխումը երկար է տևելու։</li><li>Սա խորհուրդ ՉԻ տրվում, եթե ձեր տարածքի օձերը թույն են արտադրում, որը հիմնականում վնասում է կծածի մոտ գտնվող հյուսվածքները և ամբողջ մարմնի ախտանշաններ չի առաջացնում։</li></ul></li><li>Բեկակալ ամրացրեք վերջույթին՝ այն հնարավորինս անշարժացնելու համար։</li><li>Նշեք վիրակապ դնելու ժամը։</li><li>Հիվանդին պահեք հանգիստ վիճակում՝ պառկած։</li><li>ՄԻ ՏԵՂԱԴՐԵՔ լարան օձի կծածի շուրջը կամ վերջույթի վրա։</li><li>ՄԻ ԿՏՐԵՔ կծածը, քանի որ դա կհանգեցնի անհարկի արյունահոսության։</li><li>ՄԻ ՓՈՐՁԵՔ հեռացնել թույնը՝ կծածը արտածծելով։</li></ul>","text":"Նշում. Հնարավորության դեպքում լուսանկարեք օձին և ուղարկեք լուսանկարը հիվանդի հետ։ Օձի կծածից հետո վերջույթի անշարժացումը կարևոր է՝ շարժումները սահմանափակելու և թույնի ներծծումը դանդաղեցնելու համար։ Ցանկացած վերք վիրակապելուց կամ բեկակալ դնելուց առաջ և հետո միշտ գնահատեք անոթազարկը, մազանոթների վերալցումը և զգայունությունը։ Կարող եք օգտագործել լայն էլաստիկ վիրակապ և փաթաթել այն կծածի ստորին հատվածից դեպի վեր։ Վիրակապը պետք է լինի ամուր, սակայն չպետք է ընդհատի վերջույթի անոթազարկերը։ Վիրակապը փաթաթեք հնարավորինս ընդգրկելով վերջույթն ամբողջությամբ։ Սա խորհուրդ է տրվում, եթե ձեր տարածքի օձերը թույն են արտադրում, որը վնասում է նյարդերը, առաջացնում է կաթված, ծանրացնում է հիվանդի վիճակը, կամ եթե տեղափոխումը երկար է տևելու։ Սա խորհուրդ ՉԻ տրվում, եթե ձեր տարածքի օձերը թույն են արտադրում, որը հիմնականում վնասում է կծածի մոտ գտնվող հյուսվածքները և ամբողջ մարմնի ախտանշաններ չի առաջացնում։ Բեկակալ ամրացրեք վերջույթին՝ այն հնարավորինս անշարժացնելու համար։ Նշեք վիրակապ դնելու ժամը։ Հիվանդին պահեք հանգիստ վիճակում՝ պառկած։ ՄԻ ՏԵՂԱԴՐԵՔ լարան օձի կծածի շուրջը կամ վերջույթի վրա։ ՄԻ ԿՏՐԵՔ կծածը, քանի որ դա կհանգեցնի անհարկի արյունահոսության։ ՄԻ ՓՈՐՁԵՔ հեռացնել թույնը՝ կծածը արտածծելով։"},{"id":"m-Adrenaline_Epinephrine_","cat":"medicines","title":"Ադրենալին (Epinephrine)","keywords":"Adrenaline (Epinephrine)","html":"<p class=\"label\">Դեղորայքի ցուցում:</p><ul><li>Անաֆիլաքսիա/ուժեղ ալերգիկ ռեակցիա և ուժգին սուլոց</li></ul><p class=\"label\">Դեղաչափ:</p><ul><li>Լուծույթ՝ 1 մգ 1 մլ-անոց շշիկում (1:1000)</li><li>Նշում:<ul><li>Ստորև ներկայացված դեղաչափերը նախատեսված են միջմկանային, այլ ոչ ն/ե ներարկման համար։</li><li>Ներարկման նախընտրելի տեղը՝ ազդրի միջին հատվածի դրսի կողմը։</li></ul></li><li>Մեծահասակներ. Միջմկանային (մ/մ)՝<ul><li>50 կգ և ավելի՝ 0,5 մգ մ/մ (0,5 մլ 1:1000)</li><li>40 կգ՝ 0,4 մգ մ/մ (0,4 մլ 1:1000)</li><li>30 կգ՝ 0,3 մգ մ/մ (0,3 մլ 1:1000)</li><li>Կարելի է կրկնել 5 րոպեանոց ինտերվալներով</li></ul></li><li>Մանկաբուժություն:<ul><li>Անաֆիլաքսիա՝ 0,15 մգ մ/մ (0,15 մլ 1:1000), անհրաժեշտության դեպքում կրկնել յուրաքանչյուր 5–15 րոպեն մեկ</li><li>Ծանր ասթմա՝ 0,01 մգ/կգ մ/մ մինչև 0,3 մգ, անհրաժեշտության դեպքում կրկնել յուրաքանչյուր 5–15 րոպեն մեկ</li></ul></li></ul><p class=\"label\">Անցանկալի ազդեցություններ:</p><ul><li>Տագնապ/վախ</li><li>Սրտխփոց</li><li>Տախիկարդիա (հաճախասրտություն)</li><li>Գլխապտույտ</li><li>Քրտնարտադրություն</li><li>Սրտխառնոց</li><li>Փսխում</li><li>Հիպերգլիկեմիա (արյան մեջ գլյուկոզայի բարձր պարունակություն)</li><li>Ցավ կրծքավանդակում</li><li>Արյան բարձր ճնշում</li><li>Ներարկման հատվածում հյուսվածքների մեռուկացում</li></ul>","text":"Դեղորայքի ցուցում: Անաֆիլաքսիա/ուժեղ ալերգիկ ռեակցիա և ուժգին սուլոց Դեղաչափ: Լուծույթ՝ 1 մգ 1 մլ-անոց շշիկում (1:1000) Նշում: Ստորև ներկայացված դեղաչափերը նախատեսված են միջմկանային, այլ ոչ ն/ե ներարկման համար։ Ներարկման նախընտրելի տեղը՝ ազդրի միջին հատվածի դրսի կողմը։ Մեծահասակներ. Միջմկանային (մ/մ)՝ 50 կգ և ավելի՝ 0,5 մգ մ/մ (0,5 մլ 1:1000) 40 կգ՝ 0,4 մգ մ/մ (0,4 մլ 1:1000) 30 կգ՝ 0,3 մգ մ/մ (0,3 մլ 1:1000) Կարելի է կրկնել 5 րոպեանոց ինտերվալներով Մանկաբուժություն: Անաֆիլաքսիա՝ 0,15 մգ մ/մ (0,15 մլ 1:1000), անհրաժեշտության դեպքում կրկնել յուրաքանչյուր 5–15 րոպեն մեկ Ծանր ասթմա՝ 0,01 մգ/կգ մ/մ մինչև 0,3 մգ, անհրաժեշտության դեպքում կրկնել յուրաքանչյուր 5–15 րոպեն մեկ Անցանկալի ազդեցություններ: Տագնապ/վախ Սրտխփոց Տախիկարդիա (հաճախասրտություն) Գլխապտույտ Քրտնարտադրություն Սրտխառնոց Փսխում Հիպերգլիկեմիա (արյան մեջ գլյուկոզայի բարձր պարունակություն) Ցավ կրծքավանդակում Արյան բարձր ճնշում Ներարկման հատվածում հյուսվածքների մեռուկացում"},{"id":"m-Acetylsalicylicacid_Aspirin_","cat":"medicines","title":"Ացետիլսալիցիլաթթու (Aspirin)","keywords":"Acetylsalicylic acid (Aspirin)","html":"<p class=\"label\">Դեղորայքի ցուցում:</p><ul><li>Սրտի ինֆարկտի կասկած</li></ul><p class=\"label\">Դեղաչափ:</p><ul><li>Դեղահաբ՝ 100 մգ, 300 մգ</li><li>Բերանով՝ 300 մգ (ցանկալի է ծամել կամ լուծել ջրի մեջ), տրվում է անմիջապես՝ որպես մեկանգամյա դեղաչափ։</li><li>Մի՛ տվեք ասպիրին, մինչև առավել բարձր կարգի սպասարկողը չգնահատի վիճակը, եթե առկա է՝<ul><li class=\"num\">1. Ցանկացած տիպի ակտիվ արյունահոսություն, կամ</li><li class=\"num\">2. Կրծքավանդակի ցավ, որը հանկարծակի է, սկսվելու պահին շատ ուժեղ է, սուր և պատռող է, և ճառագայթում է դեպի թիկունք (կարող է ցույց տալ աորտայի պատռվածք)։</li></ul></li></ul><p class=\"label\">Անցանկալի ազդեցություններ:</p><ul><li>Արյան կորստով ուղեկցվող ստամոքսաղիքային խանգարում</li><li>Տինիտուս (ականջներում զնգոց կամ աղմուկ)</li><li>Անաֆիլաքսիա</li></ul>","text":"Դեղորայքի ցուցում: Սրտի ինֆարկտի կասկած Դեղաչափ: Դեղահաբ՝ 100 մգ, 300 մգ Բերանով՝ 300 մգ (ցանկալի է ծամել կամ լուծել ջրի մեջ), տրվում է անմիջապես՝ որպես մեկանգամյա դեղաչափ։ Մի՛ տվեք ասպիրին, մինչև առավել բարձր կարգի սպասարկողը չգնահատի վիճակը, եթե առկա է՝ 1. Ցանկացած տիպի ակտիվ արյունահոսություն, կամ 2. Կրծքավանդակի ցավ, որը հանկարծակի է, սկսվելու պահին շատ ուժեղ է, սուր և պատռող է, և ճառագայթում է դեպի թիկունք (կարող է ցույց տալ աորտայի պատռվածք)։ Անցանկալի ազդեցություններ: Արյան կորստով ուղեկցվող ստամոքսաղիքային խանգարում Տինիտուս (ականջներում զնգոց կամ աղմուկ) Անաֆիլաքսիա"},{"id":"m-Benzodiazepines_diazepam_","cat":"medicines","title":"Բենզոդիազեպին (դիազեպամ)","keywords":"Benzodiazepines (diazepam)","html":"<p class=\"label\">Դեղորայքի ցուցում:</p><ul><li>Նոպաներ/ցնցումներ</li></ul><p class=\"label\">Դեղաչափ:</p><ul><li>Դեղահաբ՝ 2 մգ, 5 մգ</li><li>Լուծույթ՝ 5 մգ/1 մլ շշիկով</li><li>Մեծահասակներ:<ul><li>Առաջին դեղաչափ՝ 10 մգ դանդաղ ն/ե ներմուծում կամ 20 մգ ուղիղաղիքային ներմուծում</li><li>Երկրորդ դեղաչափ 10 րոպեից՝ 5 մգ դանդաղ ն/ե ներմուծում կամ 10 մգ ուղիղաղիքային ներմուծում</li><li>Առավելագույն ն/ե դեղաչափ՝ 30 մգ</li></ul></li><li>Երեխաներ:<ul><li>Առաջին դեղաչափ՝ 0,2 մգ/կգ դանդաղ ն/ե ներմուծում կամ 0,5 մգ/կգ ուղիղաղիքային ներմուծում։ Եթե նոպաները/ցնցումները շարունակվեն, 10 րոպեից կարելի է կրկնել առաջին դեղաչափի կեսը։</li><li>Առավելագույն ն/ե դեղաչափ՝ 20 մգ</li></ul></li><li>Մի տվեք երկրորդ դեղաչափը, եթե շնչառության հաճախականությունը րոպեում 10-ից պակաս է։</li><li>Մի ներարկեք դիազեպամ միջմկանային եղանակով (անկանխատեսելի ներծծում)։</li><li>Ինչպես ներմուծել դիազեպամ ուղիղաղիքային եղանակով:<ul><li>Հավաքեք դիազեպամի դեղաչափը շշիկից փոքր ներարկչի մեջ (առկայության դեպքում՝ տուբերկուլինի)։ Հնարավորության դեպքում դեղաչափը որոշեք երեխայի քաշի հիման վրա։</li><li>Հեռացրեք ասեղը ներարկչից։</li><li>Ներարկիչը 4–5 սմ խորությամբ մտցրեք ուղիղ աղու մեջ և ներարկեք դիազեպամի լուծույթը։</li><li>Մի քանի րոպե հետույքի թշերը իրար մոտեցրած պահեք։</li></ul></li><li>ՈՒՇԱԴԻՐ ՄՇՏԱԴԻՏԱՐԿԵՔ ՇՆՉԱՌՈՒԹՅՈՒՆԸ դիազեպամ ստացած բոլոր հիվանդների մոտ։</li></ul><p class=\"label\">Անցանկալի ազդեցություններ:</p><ul><li>Հանգստացնող ազդեցություն</li><li>Շնչառության անկում</li><li>Արյան ճնշման անկում</li><li>Բրադիկարդիա (դանդաղասրտություն)</li><li>Սրտխառնոց և փսխում</li><li>Որովայնի սպազմեր</li></ul>","text":"Դեղորայքի ցուցում: Նոպաներ/ցնցումներ Դեղաչափ: Դեղահաբ՝ 2 մգ, 5 մգ Լուծույթ՝ 5 մգ/1 մլ շշիկով Մեծահասակներ: Առաջին դեղաչափ՝ 10 մգ դանդաղ ն/ե ներմուծում կամ 20 մգ ուղիղաղիքային ներմուծում Երկրորդ դեղաչափ 10 րոպեից՝ 5 մգ դանդաղ ն/ե ներմուծում կամ 10 մգ ուղիղաղիքային ներմուծում Առավելագույն ն/ե դեղաչափ՝ 30 մգ Երեխաներ: Առաջին դեղաչափ՝ 0,2 մգ/կգ դանդաղ ն/ե ներմուծում կամ 0,5 մգ/կգ ուղիղաղիքային ներմուծում։ Եթե նոպաները/ցնցումները շարունակվեն, 10 րոպեից կարելի է կրկնել առաջին դեղաչափի կեսը։ Առավելագույն ն/ե դեղաչափ՝ 20 մգ Մի տվեք երկրորդ դեղաչափը, եթե շնչառության հաճախականությունը րոպեում 10-ից պակաս է։ Մի ներարկեք դիազեպամ միջմկանային եղանակով (անկանխատեսելի ներծծում)։ Ինչպես ներմուծել դիազեպամ ուղիղաղիքային եղանակով: Հավաքեք դիազեպամի դեղաչափը շշիկից փոքր ներարկչի մեջ (առկայության դեպքում՝ տուբերկուլինի)։ Հնարավորության դեպքում դեղաչափը որոշեք երեխայի քաշի հիման վրա։ Հեռացրեք ասեղը ներարկչից։ Ներարկիչը 4–5 սմ խորությամբ մտցրեք ուղիղ աղու մեջ և ներարկեք դիազեպամի լուծույթը։ Մի քանի րոպե հետույքի թշերը իրար մոտեցրած պահեք։ ՈՒՇԱԴԻՐ ՄՇՏԱԴԻՏԱՐԿԵՔ ՇՆՉԱՌՈՒԹՅՈՒՆԸ դիազեպամ ստացած բոլոր հիվանդների մոտ։ Անցանկալի ազդեցություններ: Հանգստացնող ազդեցություն Շնչառության անկում Արյան ճնշման անկում Բրադիկարդիա (դանդաղասրտություն) Սրտխառնոց և փսխում Որովայնի սպազմեր"},{"id":"m-Glucose_dextrose_","cat":"medicines","title":"Գլյուկոզա (dextrose)","keywords":"Glucose (dextrose)","html":"<p class=\"label\">Դեղորայքի ցուցում:</p><ul><li>Հիպոգլիկեմիա (արյան մեջ գլյուկոզայի ցածր պարունակություն)</li></ul><p class=\"label\">Դեղաչափ:</p><ul><li>Լուծույթ՝ 50%-անոց դեքստրոզա (D50), 40%-անոց դեքստրոզա (D40), 25%-անոց դեքստրոզա (D25), 10%-անոց դեքստրոզա (D10) և 5%-անոց դեքստրոզա (D5)։</li><li>ՆՇՈՒՄ. Դեքստրոզան ԵՐԲԵՔ չպետք է ներմուծվի միջմկանային եղանակով, քանի որ այն կարող է հյուսվածքների լուրջ վնասվածքներ առաջացնել։</li><li>Մեծահասակներին և 40 կգ-ից ավելի կշռող երեխաներին՝ ն/ե:<ul><li>D50՝ 25–50 մլ; D40՝ 30–60 մլ; D10՝ 125–250 մլ; D5՝ 250–500 մլ</li></ul></li><li>Մինչև 40 կգ երեխաներին:<ul><li>D40՝ 1,2 մլ/կգ ն/ե; D10՝ 5 մլ/կգ ն/ե; D5՝ 10 մլ/կգ ն/ե</li><li>Մինչև 40 կգ քաշ ունեցող երեխաներին ցանկալի է տալ D10։ Եթե D10 հասանելի չէ, կարող եք օգտվել 50-ի կանոնից, որպեսզի հիշեք դեքստրոզայի համարժեք քանակը մեկ այլ լուծույթի մեջ։ Ստորև ներկայացված բոլոր տարբերակները պարունակում են դեքստրոզայի նույն քանակը:<ul><li>5 մլ D10</li><li>2 մլ D25</li><li>1 մլ D50</li></ul></li></ul></li><li>Եթե ն/ե ներարկումն անհնար է:<ul><li>2–5 մլ 50%-անոց դեքստրոզան լցրեք այտի ներսի կողմում՝ այտի և լնդի արանքում։</li><li>ԿԱՄ տվեք շաքարաջուր՝ 1 թեյի գդալ շաքարավազ՝ հարթեցված և ջրով թրջված՝ ամեն 10–20 րոպեն մեկ՝ այտի ներսում։</li></ul></li></ul><p class=\"label\">Անցանկալի ազդեցություններ:</p><ul><li>Հիպերգլիկեմիա (արյան մեջ գլյուկոզայի բարձր պարունակություն)</li><li>Գլխապտույտ</li><li>Մաշկի մեռուկացում, եթե ներարկվող դեղամիջոցն անցել է մաշկի տակ, այլ ոչ երակի մեջ</li></ul>","text":"Դեղորայքի ցուցում: Հիպոգլիկեմիա (արյան մեջ գլյուկոզայի ցածր պարունակություն) Դեղաչափ: Լուծույթ՝ 50%-անոց դեքստրոզա (D50), 40%-անոց դեքստրոզա (D40), 25%-անոց դեքստրոզա (D25), 10%-անոց դեքստրոզա (D10) և 5%-անոց դեքստրոզա (D5)։ ՆՇՈՒՄ. Դեքստրոզան ԵՐԲԵՔ չպետք է ներմուծվի միջմկանային եղանակով, քանի որ այն կարող է հյուսվածքների լուրջ վնասվածքներ առաջացնել։ Մեծահասակներին և 40 կգ-ից ավելի կշռող երեխաներին՝ ն/ե: D50՝ 25–50 մլ; D40՝ 30–60 մլ; D10՝ 125–250 մլ; D5՝ 250–500 մլ Մինչև 40 կգ երեխաներին: D40՝ 1,2 մլ/կգ ն/ե; D10՝ 5 մլ/կգ ն/ե; D5՝ 10 մլ/կգ ն/ե Մինչև 40 կգ քաշ ունեցող երեխաներին ցանկալի է տալ D10։ Եթե D10 հասանելի չէ, կարող եք օգտվել 50-ի կանոնից, որպեսզի հիշեք դեքստրոզայի համարժեք քանակը մեկ այլ լուծույթի մեջ։ Ստորև ներկայացված բոլոր տարբերակները պարունակում են դեքստրոզայի նույն քանակը: 5 մլ D10 2 մլ D25 1 մլ D50 Եթե ն/ե ներարկումն անհնար է: 2–5 մլ 50%-անոց դեքստրոզան լցրեք այտի ներսի կողմում՝ այտի և լնդի արանքում։ ԿԱՄ տվեք շաքարաջուր՝ 1 թեյի գդալ շաքարավազ՝ հարթեցված և ջրով թրջված՝ ամեն 10–20 րոպեն մեկ՝ այտի ներսում։ Անցանկալի ազդեցություններ: Հիպերգլիկեմիա (արյան մեջ գլյուկոզայի բարձր պարունակություն) Գլխապտույտ Մաշկի մեռուկացում, եթե ներարկվող դեղամիջոցն անցել է մաշկի տակ, այլ ոչ երակի մեջ"},{"id":"m-Antibiotics","cat":"medicines","title":"Հակաբիոտիկներ","keywords":"Antibiotics","html":"<p class=\"label\">Դեղաչափ:</p><ul><li>Այս խմբի կոնկրետ դեղերը որոշվում են տեղական բուժման գործելակարգերով և դեղերի հասանելիությամբ։ Դրանք պետք է ներառեն լայն սպեկտրի հակաբիոտիկներով բուժում կյանքին վտանգ սպառնացող վարակների դեպքում, որը կարելի է կիրառել էմպիրիկ ձևով (մինչ վարակի աղբյուրի վերջնական հայտնաբերումը) շատ ծանր հիվանդների մոտ։</li></ul><p class=\"label\">Անցանկալի ազդեցություններ:</p><ul><li>Ալերգիկ ռեակցիաներ</li><li>Ստամոքսաղիքային խանգարում</li><li>Այլ ազդեցություններ՝ կախված հակաբիոտիկից</li></ul>","text":"Դեղաչափ: Այս խմբի կոնկրետ դեղերը որոշվում են տեղական բուժման գործելակարգերով և դեղերի հասանելիությամբ։ Դրանք պետք է ներառեն լայն սպեկտրի հակաբիոտիկներով բուժում կյանքին վտանգ սպառնացող վարակների դեպքում, որը կարելի է կիրառել էմպիրիկ ձևով (մինչ վարակի աղբյուրի վերջնական հայտնաբերումը) շատ ծանր հիվանդների մոտ։ Անցանկալի ազդեցություններ: Ալերգիկ ռեակցիաներ Ստամոքսաղիքային խանգարում Այլ ազդեցություններ՝ կախված հակաբիոտիկից"},{"id":"m-Magnesiumsulphate","cat":"medicines","title":"Մագնեզիումի սուլֆատ","keywords":"Magnesium sulphate","html":"<p class=\"label\">Դեղորայքի ցուցում:</p><ul><li>Էկլամպսիա կամ նոպաներ/ցնցումներ հղիների մոտ</li></ul><p class=\"label\">Դեղաչափ:</p><ul><li>Լուծույթի ձևեր:<ul><li>1 գ՝ 2 մլ-անոց շշիկում (50%)<ul><li>Ն/ե ներմուծման համար պատրաստեք 20%-անոց լուծույթ. 2 մլ-անոց շշիկին ավելացրեք 3 մլ ստերիլ ֆիզիոլոգիական լուծույթ։</li></ul></li><li>5 գ՝ 10 մլ-անոց շշիկում (50%)<ul><li>Ն/ե ներմուծման համար պատրաստեք 20%-անոց լուծույթ. 10 մլ-անոց շշիկին ավելացրեք 15 մլ ստերիլ ֆիզիոլոգիական լուծույթ։</li></ul></li></ul></li><li>Բեռնման դեղաչափ (ն/ե + մ/մ):<ul><li>4 գ ն/ե (նոսրացրեք մինչև 20%-անոց լուծույթ և 20 մլ-ն ներմուծեք դանդաղ՝ 20 րոպեի ընթացքում)</li><li>ԵՎ 10 գ մ/մ (միջմկանային). 5 գ (10 մլ 50%-անոց լուծույթ) 1 մլ 2%-անոց լիդոկաինով՝ հետույքի յուրաքանչյուր կողմի վերին արտաքին քառորդում։ Մագնեզիումը կարող է իջեցնել արյան ճնշումը. մշտադիտարկեք հիվանդին։</li></ul></li><li>ԵԹԵ հնարավոր չէ ն/ե ներմուծում, կատարեք միայն 10 գ մ/մ ներարկում (ինչպես նշված է վերևում՝ 5 գ հետույքի յուրաքանչյուր կողմում)։</li><li>Եթե նոպաները/ցնցումները կրկնվեն. 15 րոպեից տվեք ևս 2 գ (10 մլ 20%-անոց) ն/ե՝ 20 րոպեի ընթացքում։</li><li>Եթե տեղափոխումը ձգձգվում է, շարունակեք բուժումը. ներարկեք 5 գ 50%-անոց լուծույթ 1 մլ 2%-անոց լիդոկաինով մ/մ՝ չորս ժամը մեկ՝ հետույքի հերթափոխվող կողմերում։</li></ul><p class=\"label\">Անցանկալի ազդեցություններ:</p><ul><li>Արյան ճնշման անկում</li><li>Շնչառության անկում</li><li>Քնկոտություն</li><li>Շփոթվածություն</li><li>Ռեֆլեքսների կորուստ</li><li>Մկանային թուլություն</li><li>Սրտխառնոց</li><li>Փսխում</li><li>Կարմրած մաշկ</li><li>Ծարավ</li></ul><p class=\"label\">ԴԱԴԱՐԵՑՐԵՔ, եթե:</p><ul><li>Զարգանում է շնչառության անկում (շնչառության հաճախականություն &lt;16)։</li></ul><p class=\"label\">Թունավորման նշաններ:</p><ul><li>Արյան ճնշման անկում</li><li>Շնչառության անկում</li><li>Ծնկի ռեֆլեքսի կորուստ</li><li>Մեզի ծավալ &lt;100 մլ/4 ժամ</li></ul>","text":"Դեղորայքի ցուցում: Էկլամպսիա կամ նոպաներ/ցնցումներ հղիների մոտ Դեղաչափ: Լուծույթի ձևեր: 1 գ՝ 2 մլ-անոց շշիկում (50%) Ն/ե ներմուծման համար պատրաստեք 20%-անոց լուծույթ. 2 մլ-անոց շշիկին ավելացրեք 3 մլ ստերիլ ֆիզիոլոգիական լուծույթ։ 5 գ՝ 10 մլ-անոց շշիկում (50%) Ն/ե ներմուծման համար պատրաստեք 20%-անոց լուծույթ. 10 մլ-անոց շշիկին ավելացրեք 15 մլ ստերիլ ֆիզիոլոգիական լուծույթ։ Բեռնման դեղաչափ (ն/ե + մ/մ): 4 գ ն/ե (նոսրացրեք մինչև 20%-անոց լուծույթ և 20 մլ-ն ներմուծեք դանդաղ՝ 20 րոպեի ընթացքում) ԵՎ 10 գ մ/մ (միջմկանային). 5 գ (10 մլ 50%-անոց լուծույթ) 1 մլ 2%-անոց լիդոկաինով՝ հետույքի յուրաքանչյուր կողմի վերին արտաքին քառորդում։ Մագնեզիումը կարող է իջեցնել արյան ճնշումը. մշտադիտարկեք հիվանդին։ ԵԹԵ հնարավոր չէ ն/ե ներմուծում, կատարեք միայն 10 գ մ/մ ներարկում (ինչպես նշված է վերևում՝ 5 գ հետույքի յուրաքանչյուր կողմում)։ Եթե նոպաները/ցնցումները կրկնվեն. 15 րոպեից տվեք ևս 2 գ (10 մլ 20%-անոց) ն/ե՝ 20 րոպեի ընթացքում։ Եթե տեղափոխումը ձգձգվում է, շարունակեք բուժումը. ներարկեք 5 գ 50%-անոց լուծույթ 1 մլ 2%-անոց լիդոկաինով մ/մ՝ չորս ժամը մեկ՝ հետույքի հերթափոխվող կողմերում։ Անցանկալի ազդեցություններ: Արյան ճնշման անկում Շնչառության անկում Քնկոտություն Շփոթվածություն Ռեֆլեքսների կորուստ Մկանային թուլություն Սրտխառնոց Փսխում Կարմրած մաշկ Ծարավ ԴԱԴԱՐԵՑՐԵՔ, եթե: Զարգանում է շնչառության անկում (շնչառության հաճախականություն <16)։ Թունավորման նշաններ: Արյան ճնշման անկում Շնչառության անկում Ծնկի ռեֆլեքսի կորուստ Մեզի ծավալ <100 մլ/4 ժամ"},{"id":"m-Naloxone","cat":"medicines","title":"Նալոքսոն","keywords":"Naloxone","html":"<p class=\"label\">Դեղորայքի ցուցում:</p><ul><li>Ափիոնային (օպիոիդային) գերդոզավորում</li></ul><p class=\"label\">Դեղաչափ:</p><ul><li>Լուծույթ՝ 400 մկգ/մլ (հիդրոքլորիդ) 1 մլ-անոց շշիկում</li><li>Կարելի է տալ ն/ե ԿԱՄ մ/մ ճանապարհով:<ul><li>Ն/ե՝ 100 մկգ՝ մեկանգամյա դեղաչափ</li><li>Մ/մ՝ 400 մկգ՝ մեկանգամյա դեղաչափ</li></ul></li><li>Անհրաժեշտության դեպքում կարելի է կրկնել ամեն 5 րոպեն մեկ։</li><li>Երկար ազդող օպիոիդների դեպքում կարող է պահանջվել շարունակական ներարկում՝ 0,4 մգ/ժամ, մի քանի ժամվա ընթացքում։</li></ul><p class=\"label\">Անցանկալի ազդեցություններ:</p><ul><li>Հիպերտենզիա (արյան բարձր ճնշում)</li><li>Սրտի առիթմիա</li><li>Թոքերի հիպերվենտիլյացիա</li><li>Դժվարացած շնչառություն</li><li>Գրգռվածություն</li></ul><p>*** Նալոքսոնի ազդեցությունը տևում է միայն 1–3 ժամ։ Շատ օպիոիդային դեղամիջոցներ ավելի երկար են ազդում, և կարող է կարիք լինել նալոքսոնի լրացուցիչ դեղաչափերի կամ նալոքսոնի ներմուծման ներարկման համակարգի միջոցով։ Նալոքսոնով բուժվող ցանկացած հիվանդի պետք է ուշադիր մշտադիտարկել։***</p>","text":"Դեղորայքի ցուցում: Ափիոնային (օպիոիդային) գերդոզավորում Դեղաչափ: Լուծույթ՝ 400 մկգ/մլ (հիդրոքլորիդ) 1 մլ-անոց շշիկում Կարելի է տալ ն/ե ԿԱՄ մ/մ ճանապարհով: Ն/ե՝ 100 մկգ՝ մեկանգամյա դեղաչափ Մ/մ՝ 400 մկգ՝ մեկանգամյա դեղաչափ Անհրաժեշտության դեպքում կարելի է կրկնել ամեն 5 րոպեն մեկ։ Երկար ազդող օպիոիդների դեպքում կարող է պահանջվել շարունակական ներարկում՝ 0,4 մգ/ժամ, մի քանի ժամվա ընթացքում։ Անցանկալի ազդեցություններ: Հիպերտենզիա (արյան բարձր ճնշում) Սրտի առիթմիա Թոքերի հիպերվենտիլյացիա Դժվարացած շնչառություն Գրգռվածություն *** Նալոքսոնի ազդեցությունը տևում է միայն 1–3 ժամ։ Շատ օպիոիդային դեղամիջոցներ ավելի երկար են ազդում, և կարող է կարիք լինել նալոքսոնի լրացուցիչ դեղաչափերի կամ նալոքսոնի ներմուծման ներարկման համակարգի միջոցով։ Նալոքսոնով բուժվող ցանկացած հիվանդի պետք է ուշադիր մշտադիտարկել։***"},{"id":"m-Paracetamol_acetaminophen_","cat":"medicines","title":"Պարացետամոլ (acetaminophen)","keywords":"Paracetamol (acetaminophen)","html":"<p class=\"label\">Դեղորայքի ցուցում:</p><ul><li>Թույլից մինչև չափավոր ցավ, տենդ և գլխացավ</li></ul><p class=\"label\">Դեղաչափ:</p><ul><li>Դեղահաբ՝ 250 մգ, 500 մգ</li><li>Ռեկտալ մոմիկներ՝ 250 մգ, 500 մգ</li><li>Մեծահասակներ. 500 մգ – 1 գ՝ յուրաքանչյուր 6 ժամը մեկ։ Առավելագույնը՝ 4 գ օրական, կամ 2 գ օրական՝ լյարդի անբավարարության կամ ցիռոզի դեպքում։</li><li>Երեխաներ. 10–15 մգ/կգ՝ օրական մինչև վեց անգամ։</li></ul><p class=\"label\">Անցանկալի ազդեցություններ:</p><ul><li>Ցան</li><li>Լյարդի վնասում՝ գերդոզավորման արդյունքում</li></ul>","text":"Դեղորայքի ցուցում: Թույլից մինչև չափավոր ցավ, տենդ և գլխացավ Դեղաչափ: Դեղահաբ՝ 250 մգ, 500 մգ Ռեկտալ մոմիկներ՝ 250 մգ, 500 մգ Մեծահասակներ. 500 մգ – 1 գ՝ յուրաքանչյուր 6 ժամը մեկ։ Առավելագույնը՝ 4 գ օրական, կամ 2 գ օրական՝ լյարդի անբավարարության կամ ցիռոզի դեպքում։ Երեխաներ. 10–15 մգ/կգ՝ օրական մինչև վեց անգամ։ Անցանկալի ազդեցություններ: Ցան Լյարդի վնասում՝ գերդոզավորման արդյունքում"},{"id":"m-Salbutamol_albuterol_","cat":"medicines","title":"Սալբուտամոլ (albuterol)","keywords":"Salbutamol (albuterol)","html":"<p class=\"label\">Դեղորայքի ցուցում:</p><ul><li>Ուժգին սուլոց</li></ul><p class=\"label\">Դեղաչափ:</p><ul><li>Առկայության դեպքում կարելի է օգտագործել նեբուլայզեր՝ համապատասխան դեղաչափով։<ul><li>Մեծահասակներ՝ 5 մգ՝ 5 մլ ստերիլ ֆիզիոլոգիական լուծույթում</li><li>Երեխաներ՝ 2,5 մգ՝ 3 մլ ստերիլ ֆիզիոլոգիական լուծույթում։</li></ul></li><li>Ինհալյատոր՝ 100 մկգ յուրաքանչյուր փչման համար</li><li>Սփեյսերով ինհալյատոր</li><li>Մեծահասակ. սփեյսերը նախապատրաստեք հինգ փչումով, ապա տվեք երկու փչում սփեյսերի միջոցով՝ ամեն երկու րոպեն մեկ, մինչև վիճակը լավանա։</li><li>Երեխա. սփեյսերը նախապատրաստեք հինգ փչումով, ապա տվեք երկու փչում սփեյսերի մեջ։<ul><li>Սփեյսերը պահեք երեխայի բերանում՝ երեքից հինգ ներշնչումների ընթացքում։</li><li>Կրկնեք, մինչև երեխան ստանա վեց փչում՝ մինչև 5 տարեկան երեխային, կամ 12 փչում՝ 5-ից բարձր տարիքում։ Կրկնեք կանոնավոր, քանի դեռ վիճակը չի լավացել։ Ծանր դեպքերում 6 կամ 12 փչումը կարելի է տալ մեկ ժամվա ընթացքում՝ մի քանի անգամ։</li><li>Հիշեք. երեխան պետք է կարողանա բերանով փակել սփեյսերի բացվածքը ամբողջությամբ։ Կրծքի տարիքի երեխաներին, ամենայն հավանականությամբ, պետք կլինի սփեյսերային դիմակ կամ նեբուլայզեր։</li></ul></li><li>Ծանր սուլոցների դեպքում վերոնշյալ դեղաչափերը կարող են տրվել մի քանի անգամ՝ մեկ ժամվա ընթացքում։</li></ul><p class=\"label\">Անցանկալի ազդեցություններ:</p><ul><li>Սրտխփոց</li><li>Մանր դողդոջյուն</li><li>Գլխացավ</li><li>Տախիկարդիա (սրտի արագացած զարկ)</li></ul>","text":"Դեղորայքի ցուցում: Ուժգին սուլոց Դեղաչափ: Առկայության դեպքում կարելի է օգտագործել նեբուլայզեր՝ համապատասխան դեղաչափով։ Մեծահասակներ՝ 5 մգ՝ 5 մլ ստերիլ ֆիզիոլոգիական լուծույթում Երեխաներ՝ 2,5 մգ՝ 3 մլ ստերիլ ֆիզիոլոգիական լուծույթում։ Ինհալյատոր՝ 100 մկգ յուրաքանչյուր փչման համար Սփեյսերով ինհալյատոր Մեծահասակ. սփեյսերը նախապատրաստեք հինգ փչումով, ապա տվեք երկու փչում սփեյսերի միջոցով՝ ամեն երկու րոպեն մեկ, մինչև վիճակը լավանա։ Երեխա. սփեյսերը նախապատրաստեք հինգ փչումով, ապա տվեք երկու փչում սփեյսերի մեջ։ Սփեյսերը պահեք երեխայի բերանում՝ երեքից հինգ ներշնչումների ընթացքում։ Կրկնեք, մինչև երեխան ստանա վեց փչում՝ մինչև 5 տարեկան երեխային, կամ 12 փչում՝ 5-ից բարձր տարիքում։ Կրկնեք կանոնավոր, քանի դեռ վիճակը չի լավացել։ Ծանր դեպքերում 6 կամ 12 փչումը կարելի է տալ մեկ ժամվա ընթացքում՝ մի քանի անգամ։ Հիշեք. երեխան պետք է կարողանա բերանով փակել սփեյսերի բացվածքը ամբողջությամբ։ Կրծքի տարիքի երեխաներին, ամենայն հավանականությամբ, պետք կլինի սփեյսերային դիմակ կամ նեբուլայզեր։ Ծանր սուլոցների դեպքում վերոնշյալ դեղաչափերը կարող են տրվել մի քանի անգամ՝ մեկ ժամվա ընթացքում։ Անցանկալի ազդեցություններ: Սրտխփոց Մանր դողդոջյուն Գլխացավ Տախիկարդիա (սրտի արագացած զարկ)"},{"id":"m-Tetanusvaccination","cat":"medicines","title":"Փայտացման դեմ պատվաստում","keywords":"Tetanus vaccination","html":"<p class=\"label\">Դեղորայքի ցուցում:</p><ul><li>Փայտացման դեմ պատվաստում</li></ul><p class=\"label\">Դեղաչափ:</p><ul><li>Լուծույթ՝ 5 միավոր 0,5 մլ-ում<br>0,5 մլ՝ մ/մ</li><li>Տվեք վնասվածք ստացած բոլոր այն երեխաներին, որոնց պատվաստումները ժամկետանց են, և բոլոր այն մեծահասակներին, ովքեր վերջին 5 տարվա ընթացքում այս պատվաստումը չեն ստացել։ Եթե իմունիզացիայի կարգավիճակն անհայտ է, ապա կատարեք պատվաստումը։</li></ul><p class=\"label\">Անցանկալի ազդեցություններ:</p><ul><li>Ցավ ներարկման հատվածում</li><li>Ալերգիկ ռեակցիա</li><li>Ջերմություն</li><li>Սրտխառնոց</li></ul>","text":"Դեղորայքի ցուցում: Փայտացման դեմ պատվաստում Դեղաչափ: Լուծույթ՝ 5 միավոր 0,5 մլ-ում 0,5 մլ՝ մ/մ Տվեք վնասվածք ստացած բոլոր այն երեխաներին, որոնց պատվաստումները ժամկետանց են, և բոլոր այն մեծահասակներին, ովքեր վերջին 5 տարվա ընթացքում այս պատվաստումը չեն ստացել։ Եթե իմունիզացիայի կարգավիճակն անհայտ է, ապա կատարեք պատվաստումը։ Անցանկալի ազդեցություններ: Ցավ ներարկման հատվածում Ալերգիկ ռեակցիա Ջերմություն Սրտխառնոց"},{"id":"m-Oxytocin","cat":"medicines","title":"Օքսիտոցին","keywords":"Oxytocin","html":"<p class=\"label\">Դեղորայքի ցուցում:</p><ul><li>Հետծննդաբերական արյունահոսության բուժում</li></ul><p class=\"label\">Դեղաչափ:</p><ul><li>Լուծույթ՝ 10 ՄՄ (միջազգային միավոր) 1 մլ-անոց շշիկում</li><li>Նախնական դեղաչափ՝ տվեք 10 ՄՄ մ/մ ԵՎ սկսեք ն/ե հեղուկներ՝ 20 ՄՄ/լ, 60 կաթիլ/րոպե։</li><li>Ընկերքն անջատվելուց հետո, եթե արյունահոսությունը դեռ շարունակվում է, շարունակեք ն/ե հեղուկները՝ 20 ՄՄ/լ, 30 կաթիլ/րոպե։</li><li>Եթե ընկերքը պետք է հեռացվի ձեռքով կամ եթե արգանդը չի կրճատվում. կրկնեք 10 ՄՄ մ/մ։</li><li>Արյունահոսության դադարելուց հետո շարունակեք ն/ե հեղուկները՝ 20 ՄՄ/լ, 20 կաթիլ/րոպե՝ մեկ ժամվա ընթացքում։</li><li>Առավելագույն դեղաքանակ՝ օքսիտոցին պարունակող 3 լ ն/ե հեղուկներ։</li></ul><p class=\"label\">Անցանկալի ազդեցություններ:</p><ul><li>Սրտխառնոց/փսխում</li><li>Գլխացավ</li><li>Ցան</li><li>Անաֆիլաքսիա</li><li>Արգանդի սպազմ (ցածր դեղաչափերի դեպքում)</li><li>Արգանդի գերխթանում (հիպերստիմուլացիա) (բարձր դեղաչափերի դեպքում)</li></ul>","text":"Դեղորայքի ցուցում: Հետծննդաբերական արյունահոսության բուժում Դեղաչափ: Լուծույթ՝ 10 ՄՄ (միջազգային միավոր) 1 մլ-անոց շշիկում Նախնական դեղաչափ՝ տվեք 10 ՄՄ մ/մ ԵՎ սկսեք ն/ե հեղուկներ՝ 20 ՄՄ/լ, 60 կաթիլ/րոպե։ Ընկերքն անջատվելուց հետո, եթե արյունահոսությունը դեռ շարունակվում է, շարունակեք ն/ե հեղուկները՝ 20 ՄՄ/լ, 30 կաթիլ/րոպե։ Եթե ընկերքը պետք է հեռացվի ձեռքով կամ եթե արգանդը չի կրճատվում. կրկնեք 10 ՄՄ մ/մ։ Արյունահոսության դադարելուց հետո շարունակեք ն/ե հեղուկները՝ 20 ՄՄ/լ, 20 կաթիլ/րոպե՝ մեկ ժամվա ընթացքում։ Առավելագույն դեղաքանակ՝ օքսիտոցին պարունակող 3 լ ն/ե հեղուկներ։ Անցանկալի ազդեցություններ: Սրտխառնոց/փսխում Գլխացավ Ցան Անաֆիլաքսիա Արգանդի սպազմ (ցածր դեղաչափերի դեպքում) Արգանդի գերխթանում (հիպերստիմուլացիա) (բարձր դեղաչափերի դեպքում)"},{"id":"r-ReferenceNormalVitalSignsChild","cat":"reference","title":"Երեխաների նորմալ կենսացուցանիշներ","keywords":"Normal paediatric vital signs heart rate respiratory rate weight","html":"<p>Երեխաների մոտ կենսացուցանիշները կախված են տարիքից։ Ավելի փոքր տարիքի երեխաների մոտ նորմալ սրտի զարկը և շնչառության հաճախականությունը ավելի բարձր են, իսկ նորմալ զարկերակային ճնշումը՝ ավելի ցածր։ Կրծքի տարիքի և փոքր երեխաների սրտի զարկը պետք է ստուգել բազկային զարկերակի վրա (բազկի մեջտեղում)։</p><div class=\"tw\"><table><thead><tr><th scope=\"col\">Տարիք (տարի)</th><th scope=\"col\">Սրտի զարկերի նորմա (րոպեում)</th></tr></thead><tbody><tr><td data-label=\"Տարիք (տարի)\">≤1</td><td data-label=\"Սրտի զարկերի նորմա (րոպեում)\">100–160</td></tr><tr><td data-label=\"Տարիք (տարի)\">1–3</td><td data-label=\"Սրտի զարկերի նորմա (րոպեում)\">90–150</td></tr><tr><td data-label=\"Տարիք (տարի)\">4–5</td><td data-label=\"Սրտի զարկերի նորմա (րոպեում)\">80–140</td></tr></tbody></table></div><div class=\"tw\"><table><thead><tr><th scope=\"col\">Տարիք</th><th scope=\"col\">Շնչառության հաճախականություն (ներշնչում րոպեում)</th></tr></thead><tbody><tr><td data-label=\"Տարիք\">≤2 ամսեկան</td><td data-label=\"Շնչառության հաճախականություն (ներշնչում րոպեում)\">40–60</td></tr><tr><td data-label=\"Տարիք\">2–12 ամսեկան</td><td data-label=\"Շնչառության հաճախականություն (ներշնչում րոպեում)\">25–50</td></tr><tr><td data-label=\"Տարիք\">1–5 տարեկան</td><td data-label=\"Շնչառության հաճախականություն (ներշնչում րոպեում)\">20–40</td></tr></tbody></table></div><figure><img class=\"fig\" src=\"img/brachial-pulse.webp\" alt=\"Բազկային զարկերակի վրա երեխայի անոթազարկի չափումը\"><figcaption>Բազկային զարկերակի վրա երեխայի անոթազարկի չափումը</figcaption></figure><ul><li>Երեխայի (1–10 տարեկան) քաշը կիլոգրամներով գնահատելու համար օգտվեք հետևյալ բանաձևից՝<br>[տարիք (տարիներով) + 4] x 2<ul><li>կամ օգտվեք քաշի գնահատման գործիքներից, ինչպիսիք են PAWPER-ը, Mercy TAPE-ը կամ Broselow ժապավենը։</li></ul></li><li>Շոկային վիճակում գտնվող երեխաների նորմալ զարկերակային ճնշումը կարող է պահպանվել ավելի երկար, քան մեծահասակներինը։ Ուշադիր ստուգեք թույլ պերֆուզիայի նշանների առկայությունը։</li><li>Երեխաներին ն/ե ներարկվող հեղուկի քանակը տարբերվում է մեծահասակներին ներարկվող հեղուկի քանակից։</li></ul>","text":"Երեխաների մոտ կենսացուցանիշները կախված են տարիքից։ Ավելի փոքր տարիքի երեխաների մոտ նորմալ սրտի զարկը և շնչառության հաճախականությունը ավելի բարձր են, իսկ նորմալ զարկերակային ճնշումը՝ ավելի ցածր։ Կրծքի տարիքի և փոքր երեխաների սրտի զարկը պետք է ստուգել բազկային զարկերակի վրա (բազկի մեջտեղում)։ Տարիք (տարի) Սրտի զարկերի նորմա (րոպեում) ≤1 100–160 1–3 90–150 4–5 80–140 Տարիք Շնչառության հաճախականություն (ներշնչում րոպեում) ≤2 ամսեկան 40–60 2–12 ամսեկան 25–50 1–5 տարեկան 20–40 Բազկային զարկերակի վրա երեխայի անոթազարկի չափումը Երեխայի (1–10 տարեկան) քաշը կիլոգրամներով գնահատելու համար օգտվեք հետևյալ բանաձևից՝ [տարիք (տարիներով) + 4] x 2 կամ օգտվեք քաշի գնահատման գործիքներից, ինչպիսիք են PAWPER-ը, Mercy TAPE-ը կամ Broselow ժապավենը։ Շոկային վիճակում գտնվող երեխաների նորմալ զարկերակային ճնշումը կարող է պահպանվել ավելի երկար, քան մեծահասակներինը։ Ուշադիր ստուգեք թույլ պերֆուզիայի նշանների առկայությունը։ Երեխաներին ն/ե ներարկվող հեղուկի քանակը տարբերվում է մեծահասակներին ներարկվող հեղուկի քանակից։"},{"id":"r-ReferencePaediatricConsiderations","cat":"reference","title":"Մանկաբուժական նկատառումներ","keywords":"Paediatric considerations children danger signs","html":"<h2>«ABCDE» մանկաբուժական նկատառումներ</h2><p>Թեև «ABCDE» մոտեցումը կիրառվում է և՛ մեծահասակների, և՛ երեխաների դեպքում, սակայն երեխաների վիճակի գնահատման և վարման մի շարք մոտեցումներ տարբերվում են մեծահասակների մոտեցումից։ Ձեռնարկի «Մանկաբուժական նկատառումներ» բաժինները ընդգծում են այդ տարբերությունները։</p><h3>Երեխաների շնչուղիների հետ կապված վիճակներ</h3><p>Առատ թքահոսությունը, ստրիդորը, շնչուղիների այտուցվածությունը և պարանոցը շարժելու դժկամությունը երեխաների մոտ բարձր ռիսկի նշաններ են։ Ուշադիր զննեք շնչուղիները՝ օտար մարմինների, այրվածքների և խցանման առկայության համար։ Թույլ տվեք, որ երեխան մնա իրեն հարմարավետ դիրքում։ Անհրաժեշտության դեպքում դիրքավորեք շնչուղիները՝ ինչպես ներկայացված է ստորև։</p><div class=\"tw\"><table class=\"stack\"><thead><tr><th scope=\"col\">Մեծահասակների հետ համեմատած երեխաների մոտ.</th><th scope=\"col\">Հետևաբար դուք պետք է անեք հետևյալը.</th></tr></thead><tbody><tr><td data-label=\"Մեծահասակների հետ համեմատած երեխաների մոտ.\">Լեզուն ավելի մեծ է։</td><td data-label=\"Հետևաբար դուք պետք է անեք հետևյալը.\"><ul><li>Երեխային պառկեցրեք «հոտ քաշելու» դիրքով (փոփոխված գլխի հետթեքում և կզակի բարձրացում՝ ինչպես ծաղիկ հոտոտելիս գլխի թեթև թեքումը վերև և առաջ)։</li></ul></td></tr><tr><td data-label=\"Մեծահասակների հետ համեմատած երեխաների մոտ.\">Պարանոցը կարճ է, շնչուղիները՝ ավելի փափուկ և հեշտ խցանվող։</td><td data-label=\"Հետևաբար դուք պետք է անեք հետևյալը.\"><ul><li>Խուսափեք պարանոցը գերձգելուց կամ կորացնելուց։</li></ul></td></tr><tr><td data-label=\"Մեծահասակների հետ համեմատած երեխաների մոտ.\">Գլուխն ավելի մեծ է մարմնի մնացած մասի համեմատ։</td><td data-label=\"Հետևաբար դուք պետք է անեք հետևյալը.\"><ul><li>Ուշադիր ստուգեք շնչուղիների խցանման հավանականությունը։</li><li>Եթե շնչուղիները բաց չեն, առաջ բերեք հիվանդի ծնոտը <a class=\"xref\" href=\"#/list/skills\">տե՛ս «ՀՄՏՈՒԹՅՈՒՆՆԵՐ» բաժինը</a>։</li><li>Եթե վնասվածքի կասկած չկա, շնչուղիները բացելու համար ճիշտ դիրքավորեք հիվանդի գլուխը (շատ փոքր երեխաների ուսերի տակ բարձիկ օգտագործելով) <a class=\"xref\" href=\"#/list/skills\">տե՛ս «ՀՄՏՈՒԹՅՈՒՆՆԵՐ» բաժինը</a>։</li></ul></td></tr></tbody></table></div><figure><img class=\"fig\" src=\"img/paed-airway.webp\" alt=\"նկար՝ երեխայի շնչուղու բացումը\"></figure><div class=\"callout remember\">Շնչահեղձության դեպքում կատարեք հարվածներ թիկունքին / կրծքավանդակի կամ որովայնի սեղմումներ՝ հաշվի առնելով երեխայի տարիքը <a class=\"xref\" href=\"#/list/skills\">տե՛ս «ՀՄՏՈՒԹՅՈՒՆՆԵՐ» բաժինը</a>։</div><h3>Երեխաների շնչառության հետ կապված վիճակներ</h3><ul><li><strong>Քթանցքերի լայնացումը</strong>, <strong>գլխի ներքև-վերև շարժումը</strong>, <strong>հևոցը</strong> և <strong>կրծքավանդակի ներքաշումը</strong> (ռետրակցիաները) երեխաների մոտ շնչառական խանգարման նշաններ են։</li><li><strong>ՑԻԱՆՈԶԸ</strong>՝ շրթունքների, բերանի կամ մատների ծայրերի շուրջը կապտամոխրագույն երանգը, թթվածնի պակասի հետևանք է և վտանգավոր նշան։</li><li><strong>ԿՐԾՔԱՎԱՆԴԱԿԻ ՆԵՐՔԱՇՈՒՄԸ</strong> երեխաների մոտ օժանդակ շնչառական մկանների մասնակցության տարածված դրսևորում է։<ul><li>Նայեք կրծքավանդակի ստորին մասին (ստորին կողերին)։ Երեխայի մոտ կրծքավանդակի ներքաշում կա, եթե կրծքավանդակի պատի ստորին հատվածը ՆԵՐՇՆՉԵԼԻՍ ներս է քաշվում։</li><li>Նորմալ շնչառության ժամանակ կրծքավանդակի ամբողջ պատը (վերին և ստորին հատվածները) և որովայնը ՆԵՐՇՆՉԵԼԻՍ ԴԵՊԻ ԴՈՒՐՍ են շարժվում։</li></ul></li></ul><figure><img class=\"fig\" src=\"img/chest-indrawing.webp\" alt=\"Կրծքավանդակի ներքաշում\"><figcaption>Կրծքավանդակի ներքաշում</figcaption></figure><ul><li><strong>ԱՆՁԱՅՆ ԿՐԾՔԱՎԱՆԴԱԿԸ</strong> (կրծքավանդակը լսելիս շնչառական ձայների բացակայությունը) երեխայի մոտ շնչառական ծանր խանգարման նշան է։ Շնչուղիների ուժեղ սպազմի և նեղացման դեպքում կարող է լինել օդի սահմանափակ շարժում և քիչ շնչառական ձայներ։ Տվեք սալբուտամոլ և թթվածին և հաճախակի կրկին գնահատեք վիճակը <a class=\"xref\" href=\"#/list/skills\">տե՛ս «ՀՄՏՈՒԹՅՈՒՆՆԵՐ» բաժինը</a>։</li><li><strong>ՍՏՐԻԴՈՐԸ</strong> վկայում է շնչուղիների ծանր խանգարման մասին, և դրա հնարավոր պատճառները բազմաթիվ են։ Ստրիդորով երեխային պետք է թույլ տալ մնալ իրեն հարմար դիրքում և անմիջապես փոխանցել առավել բարձր կարգի սպասարկողի։ Հետագա բուժումը հաճախ ներառում է ադրենալինի ներմուծում նեբուլայզերով։ Եթե անմիջական փոխանցումը հնարավոր չէ, դիտարկեք ադրենալինի միջմկանային ներարկում՝ ինչպես ծանր ալերգիկ ռեակցիայի դեպքում <a class=\"xref\" href=\"#/list/skills\">տե՛ս «ՀՄՏՈՒԹՅՈՒՆՆԵՐ» բաժինը</a>։</li></ul><h3>Երեխաների արյան շրջանառության հետ կապված վիճակներ</h3><ul><li><strong>ԵՐԵԽԱՆԵՐԻ ՄՈՏ ԹՈՒՅԼ ՊԵՐՖՈՒԶԻԱՅԻ ԲՈՒԺՈՒՄԸ ԿԱՐՈՂ Է ՏԱՐԲԵՐ ԼԻՆԵԼ</strong>՝ կախված երեխայի <strong>վիճակից</strong> և դրա <strong>պատճառից</strong> [տե՛ս «ՇՈԿ» և «ՀՄՏՈՒԹՅՈՒՆՆԵՐ» մոդուլները]։</li><li><strong>ԵՐԵԽԱՅԻ ՄՈՏ ԱՐՅԱՆ ՑԱԾՐ ՃՆՇՈՒՄԸ ԾԱՆՐ ՇՈԿԻ ՆՇԱՆ Է։</strong> Շոկի դեպքում երեխաները արյան նորմալ ճնշումը կարող են պահպանել ավելի երկար, քան մեծահասակները։ Ուշադիր հետևեք թույլ պերֆուզիայի այլ նշաններին, ինչպիսիք են <strong>մեզի քանակի նվազումը</strong> և <strong>գիտակցության փոփոխությունը</strong>։</li><li><strong>ԵՐԵԽԱՆԵՐԻՆ ՏՐՎՈՂ ՆԵՐԵՐԱԿԱՅԻՆ ՀԵՂՈՒԿԻ ՔԱՆԱԿԸ ՏԱՐԲԵՐ Է ՄԵԾԱՀԱՍԱԿՆԵՐԻՑ</strong> <a class=\"xref\" href=\"#/list/skills\">տե՛ս «ՀՄՏՈՒԹՅՈՒՆՆԵՐ» բաժինը</a>։</li><li><strong>ԹԵՐՍՆՈՒՑՎԱԾ ԵՐԵԽԱՆԵՐԻ ՄՈՏ</strong> տարբեր են և՛ հեղուկի ներարկման արագությունը, և՛ հեղուկի տեսակը <a class=\"xref\" href=\"#/list/skills\">տե՛ս «ՀՄՏՈՒԹՅՈՒՆՆԵՐ» բաժինը</a>։</li><li><strong>ԾԱՆՐ ՆՇԱՆՆԵՐ.</strong> Փոս ընկած գաղթուն, մաշկի կսմթոցի անբավարար արդյունք <a class=\"xref\" href=\"#/list/skills\">տե՛ս «ՀՄՏՈՒԹՅՈՒՆՆԵՐ» բաժինը</a>, լեթարգիա, գիտակցության փոփոխություն։</li></ul><h3>Երեխաների գիտակցության խանգարումների հետ կապված վիճակներ</h3><ul><li><strong>ԱՐՅԱՆ ՄԵՋ ԳԼՅՈՒԿՈԶԱՅԻ ՑԱԾՐ ՊԱՐՈՒՆԱԿՈՒԹՅՈՒՆԸ</strong> հիվանդ երեխաների մոտ գիտակցության խանգարումների շատ տարածված պատճառ է։<ul><li>Հնարավորության դեպքում ստուգեք արյան մեջ գլյուկոզայի մակարդակը այն երեխաների մոտ, որոնց մոտ նկատվում է գիտակցության խանգարում։</li><li>Եթե հնարավոր չէ ստուգել արյան մեջ գլյուկոզայի մակարդակը, տվեք գլյուկոզա։</li></ul></li><li>Միշտ ստուգեք նոպաների/ցնցումների առկայությունը։</li><li>Երբեմն դժվար է որոշել՝ կրծքի տարիքի երեխայի վարքագիծը նորմալ է, թե ոչ։ Միշտ հարցրեք երեխային խնամող անձին։</li></ul><h3>Երեխաների մոտ բացահայտման հետ կապված վիճակներ</h3><ul><li><strong>ՆՈՐԱԾԻՆՆԵՐԸ ԵՎ ԵՐԵԽԱՆԵՐԸ ԴԺՎԱՐՈՒԹՅԱՄԲ ԵՆ ՊԱՀՊԱՆՈՒՄ ՄԱՐՄՆԻ ՋԵՐՄԱՍՏԻՃԱՆԸ,</strong> ուստի նրանց մոտ շատ արագ կարող է զարգանալ հիպոթերմիա (մարմնի ցածր ջերմաստիճան) կամ հիպերթերմիա (մարմնի բարձր ջերմաստիճան)։<ul><li>Հանեք թաց հագուստը և մաշկը լավ չորացրեք։ Հնարավորության դեպքում կրծքի տարիքի երեխաներին գրկեք՝ մաշկը մաշկին հպում ապահովելու համար։</li><li>Հիպոթերմիայի դեպքում անպայման ծածկեք կրծքի տարիքի երեխաների գլուխը (սակայն մի փակեք դեմքը)։</li><li>Հիպերթերմիայի դեպքում քանդեք կրծքի տարիքի երեխաների ձիգ բարուրը։</li></ul></li></ul><h2>«ABCDE» մոտեցման ժամանակ երեխաների վտանգավոր նշանները</h2><p>«ABCDE» հիմնավոր մոտեցմանը զուգընթաց՝ բոլոր երեխա հիվանդները պետք է գնահատվեն վտանգավոր նշանների առկայության համար։ Վտանգավոր նշաններով երեխաները ՀՐԱՏԱՊ ուշադրության և առավել բարձր կարգի մանկաբուժական խնամք ապահովող սպասարկողին փոխանցման/հանձնման կարիք ունեն։</p><p class=\"label\">Երեխաների վտանգավոր նշաններն են՝</p><ul><li>Շնչուղիների խցանման նշաններ (ստրիդոր կամ թքահոսություն/թուքը կուլ տալու անկարողություն)</li><li>Շնչառական ջանքի ավելացում (արագացած շնչառություն, քթանցքերի լայնացում, հևոց, կրծքավանդակի ներքաշում)</li><li>Ցիանոզ (մաշկի կապտավուն գույն, հատկապես շրթունքների մոտ և մատների ծայրերին)</li><li>Գիտակցության փոփոխություն (այդ թվում՝ լեթարգիա կամ անսովոր քնկոտություն, շփոթվածություն, ապակողմնորոշում)</li><li>Երեխան շարժվում է միայն խթանման դեպքում կամ ընդհանրապես չի շարժվում (AVPU-ում՝ «A»-ից բացի այլ մակարդակ)</li><li>Երեխան վատ է սնվում կամ ի վիճակի չէ խմել կամ կրծքով կերակրվել</li><li>Երեխան փսխում է այն ամենը, ինչ ստանում է</li><li>Նոպաներ/ցնցումներ</li><li>Մարմնի ցածր ջերմաստիճան (հիպոթերմիա)</li></ul>","text":"«ABCDE» մանկաբուժական նկատառումներ Թեև «ABCDE» մոտեցումը կիրառվում է և՛ մեծահասակների, և՛ երեխաների դեպքում, սակայն երեխաների վիճակի գնահատման և վարման մի շարք մոտեցումներ տարբերվում են մեծահասակների մոտեցումից։ Ձեռնարկի «Մանկաբուժական նկատառումներ» բաժինները ընդգծում են այդ տարբերությունները։ Երեխաների շնչուղիների հետ կապված վիճակներ Առատ թքահոսությունը, ստրիդորը, շնչուղիների այտուցվածությունը և պարանոցը շարժելու դժկամությունը երեխաների մոտ բարձր ռիսկի նշաններ են։ Ուշադիր զննեք շնչուղիները՝ օտար մարմինների, այրվածքների և խցանման առկայության համար։ Թույլ տվեք, որ երեխան մնա իրեն հարմարավետ դիրքում։ Անհրաժեշտության դեպքում դիրքավորեք շնչուղիները՝ ինչպես ներկայացված է ստորև։ Մեծահասակների հետ համեմատած երեխաների մոտ. Հետևաբար դուք պետք է անեք հետևյալը. Լեզուն ավելի մեծ է։ • Երեխային պառկեցրեք «հոտ քաշելու» դիրքով (փոփոխված գլխի հետթեքում և կզակի բարձրացում՝ ինչպես ծաղիկ հոտոտելիս գլխի թեթև թեքումը վերև և առաջ)։ Պարանոցը կարճ է, շնչուղիները՝ ավելի փափուկ և հեշտ խցանվող։ • Խուսափեք պարանոցը գերձգելուց կամ կորացնելուց։ Գլուխն ավելի մեծ է մարմնի մնացած մասի համեմատ։ • Ուշադիր ստուգեք շնչուղիների խցանման հավանականությունը։ • Եթե շնչուղիները բաց չեն, առաջ բերեք հիվանդի ծնոտը տե՛ս «ՀՄՏՈՒԹՅՈՒՆՆԵՐ» բաժինը։ • Եթե վնասվածքի կասկած չկա, շնչուղիները բացելու համար ճիշտ դիրքավորեք հիվանդի գլուխը (շատ փոքր երեխաների ուսերի տակ բարձիկ օգտագործելով) տե՛ս «ՀՄՏՈՒԹՅՈՒՆՆԵՐ» բաժինը։ Շնչահեղձության դեպքում կատարեք հարվածներ թիկունքին / կրծքավանդակի կամ որովայնի սեղմումներ՝ հաշվի առնելով երեխայի տարիքը տե՛ս «ՀՄՏՈՒԹՅՈՒՆՆԵՐ» բաժինը։ Երեխաների շնչառության հետ կապված վիճակներ Քթանցքերի լայնացումը, գլխի ներքև-վերև շարժումը, հևոցը և կրծքավանդակի ներքաշումը (ռետրակցիաները) երեխաների մոտ շնչառական խանգարման նշաններ են։ ՑԻԱՆՈԶԸ՝ շրթունքների, բերանի կամ մատների ծայրերի շուրջը կապտամոխրագույն երանգը, թթվածնի պակասի հետևանք է և վտանգավոր նշան։ ԿՐԾՔԱՎԱՆԴԱԿԻ ՆԵՐՔԱՇՈՒՄԸ երեխաների մոտ օժանդակ շնչառական մկանների մասնակցության տարածված դրսևորում է։ Նայեք կրծքավանդակի ստորին մասին (ստորին կողերին)։ Երեխայի մոտ կրծքավանդակի ներքաշում կա, եթե կրծքավանդակի պատի ստորին հատվածը ՆԵՐՇՆՉԵԼԻՍ ներս է քաշվում։ Նորմալ շնչառության ժամանակ կրծքավանդակի ամբողջ պատը (վերին և ստորին հատվածները) և որովայնը ՆԵՐՇՆՉԵԼԻՍ ԴԵՊԻ ԴՈՒՐՍ են շարժվում։ Կրծքավանդակի ներքաշում ԱՆՁԱՅՆ ԿՐԾՔԱՎԱՆԴԱԿԸ (կրծքավանդակը լսելիս շնչառական ձայների բացակայությունը) երեխայի մոտ շնչառական ծանր խանգարման նշան է։ Շնչուղիների ուժեղ սպազմի և նեղացման դեպքում կարող է լինել օդի սահմանափակ շարժում և քիչ շնչառական ձայներ։ Տվեք սալբուտամոլ և թթվածին և հաճախակի կրկին գնահատեք վիճակը տե՛ս «ՀՄՏՈՒԹՅՈՒՆՆԵՐ» բաժինը։ ՍՏՐԻԴՈՐԸ վկայում է շնչուղիների ծանր խանգարման մասին, և դրա հնարավոր պատճառները բազմաթիվ են։ Ստրիդորով երեխային պետք է թույլ տալ մնալ իրեն հարմար դիրքում և անմիջապես փոխանցել առավել բարձր կարգի սպասարկողի։ Հետագա բուժումը հաճախ ներառում է ադրենալինի ներմուծում նեբուլայզերով։ Եթե անմիջական փոխանցումը հնարավոր չէ, դիտարկեք ադրենալինի միջմկանային ներարկում՝ ինչպես ծանր ալերգիկ ռեակցիայի դեպքում տե՛ս «ՀՄՏՈՒԹՅՈՒՆՆԵՐ» բաժինը։ Երեխաների արյան շրջանառության հետ կապված վիճակներ ԵՐԵԽԱՆԵՐԻ ՄՈՏ ԹՈՒՅԼ ՊԵՐՖՈՒԶԻԱՅԻ ԲՈՒԺՈՒՄԸ ԿԱՐՈՂ Է ՏԱՐԲԵՐ ԼԻՆԵԼ՝ կախված երեխայի վիճակից և դրա պատճառից [տե՛ս «ՇՈԿ» և «ՀՄՏՈՒԹՅՈՒՆՆԵՐ» մոդուլները]։ ԵՐԵԽԱՅԻ ՄՈՏ ԱՐՅԱՆ ՑԱԾՐ ՃՆՇՈՒՄԸ ԾԱՆՐ ՇՈԿԻ ՆՇԱՆ Է։ Շոկի դեպքում երեխաները արյան նորմալ ճնշումը կարող են պահպանել ավելի երկար, քան մեծահասակները։ Ուշադիր հետևեք թույլ պերֆուզիայի այլ նշաններին, ինչպիսիք են մեզի քանակի նվազումը և գիտակցության փոփոխությունը։ ԵՐԵԽԱՆԵՐԻՆ ՏՐՎՈՂ ՆԵՐԵՐԱԿԱՅԻՆ ՀԵՂՈՒԿԻ ՔԱՆԱԿԸ ՏԱՐԲԵՐ Է ՄԵԾԱՀԱՍԱԿՆԵՐԻՑ տե՛ս «ՀՄՏՈՒԹՅՈՒՆՆԵՐ» բաժինը։ ԹԵՐՍՆՈՒՑՎԱԾ ԵՐԵԽԱՆԵՐԻ ՄՈՏ տարբեր են և՛ հեղուկի ներարկման արագությունը, և՛ հեղուկի տեսակը տե՛ս «ՀՄՏՈՒԹՅՈՒՆՆԵՐ» բաժինը։ ԾԱՆՐ ՆՇԱՆՆԵՐ. Փոս ընկած գաղթուն, մաշկի կսմթոցի անբավարար արդյունք տե՛ս «ՀՄՏՈՒԹՅՈՒՆՆԵՐ» բաժինը, լեթարգիա, գիտակցության փոփոխություն։ Երեխաների գիտակցության խանգարումների հետ կապված վիճակներ ԱՐՅԱՆ ՄԵՋ ԳԼՅՈՒԿՈԶԱՅԻ ՑԱԾՐ ՊԱՐՈՒՆԱԿՈՒԹՅՈՒՆԸ հիվանդ երեխաների մոտ գիտակցության խանգարումների շատ տարածված պատճառ է։ Հնարավորության դեպքում ստուգեք արյան մեջ գլյուկոզայի մակարդակը այն երեխաների մոտ, որոնց մոտ նկատվում է գիտակցության խանգարում։ Եթե հնարավոր չէ ստուգել արյան մեջ գլյուկոզայի մակարդակը, տվեք գլյուկոզա։ Միշտ ստուգեք նոպաների/ցնցումների առկայությունը։ Երբեմն դժվար է որոշել՝ կրծքի տարիքի երեխայի վարքագիծը նորմալ է, թե ոչ։ Միշտ հարցրեք երեխային խնամող անձին։ Երեխաների մոտ բացահայտման հետ կապված վիճակներ ՆՈՐԱԾԻՆՆԵՐԸ ԵՎ ԵՐԵԽԱՆԵՐԸ ԴԺՎԱՐՈՒԹՅԱՄԲ ԵՆ ՊԱՀՊԱՆՈՒՄ ՄԱՐՄՆԻ ՋԵՐՄԱՍՏԻՃԱՆԸ, ուստի նրանց մոտ շատ արագ կարող է զարգանալ հիպոթերմիա (մարմնի ցածր ջերմաստիճան) կամ հիպերթերմիա (մարմնի բարձր ջերմաստիճան)։ Հանեք թաց հագուստը և մաշկը լավ չորացրեք։ Հնարավորության դեպքում կրծքի տարիքի երեխաներին գրկեք՝ մաշկը մաշկին հպում ապահովելու համար։ Հիպոթերմիայի դեպքում անպայման ծածկեք կրծքի տարիքի երեխաների գլուխը (սակայն մի փակեք դեմքը)։ Հիպերթերմիայի դեպքում քանդեք կրծքի տարիքի երեխաների ձիգ բարուրը։ «ABCDE» մոտեցման ժամանակ երեխաների վտանգավոր նշանները «ABCDE» հիմնավոր մոտեցմանը զուգընթաց՝ բոլոր երեխա հիվանդները պետք է գնահատվեն վտանգավոր նշանների առկայության համար։ Վտանգավոր նշաններով երեխաները ՀՐԱՏԱՊ ուշադրության և առավել բարձր կարգի մանկաբուժական խնամք ապահովող սպասարկողին փոխանցման/հանձնման կարիք ունեն։ Երեխաների վտանգավոր նշաններն են՝ Շնչուղիների խցանման նշաններ (ստրիդոր կամ թքահոսություն/թուքը կուլ տալու անկարողություն) Շնչառական ջանքի ավելացում (արագացած շնչառություն, քթանցքերի լայնացում, հևոց, կրծքավանդակի ներքաշում) Ցիանոզ (մաշկի կապտավուն գույն, հատկապես շրթունքների մոտ և մատների ծայրերին) Գիտակցության փոփոխություն (այդ թվում՝ լեթարգիա կամ անսովոր քնկոտություն, շփոթվածություն, ապակողմնորոշում) Երեխան շարժվում է միայն խթանման դեպքում կամ ընդհանրապես չի շարժվում (AVPU-ում՝ «A»-ից բացի այլ մակարդակ) Երեխան վատ է սնվում կամ ի վիճակի չէ խմել կամ կրծքով կերակրվել Երեխան փսխում է այն ամենը, ինչ ստանում է Նոպաներ/ցնցումներ Մարմնի ցածր ջերմաստիճան (հիպոթերմիա)"},{"id":"r-ReferenceNormalVitalSigns","cat":"reference","title":"Մեծահասակների նորմալ կենսացուցանիշներ","keywords":"Normal adult vital signs pulse blood pressure oxygen saturation","html":"<ul><li>Սրտի զարկ՝ րոպեում 60–100 զարկ</li><li>Շնչառության հաճախականություն՝ րոպեում 10–20 ներշնչում<ul><li>Րոպեում 8-ից պակաս ներշնչումը վտանգավոր ցուցանիշ է, որի դեպքում հնարավոր է, որ պահանջվի միջամտություն։</li></ul></li><li>Սիստոլիկ զարկերակային ճնշում՝ &gt;90 մմ ս.ս.</li><li>Թթվածնային հագեցում՝ &gt;92%</li><li>Եթե չունեք հնարավորություն չափելու զարկերակային ճնշումը, կարող եք գնահատել սիստոլիկ զարկերակային ճնշումը պուլսի միջոցով։ Պուլսը ստուգել կարելի է ստորև ներկայացված եղանակներով, որոնք կօգնեն գնահատել մեծահասակների մոտ սիստոլիկ զարկերակային ճնշումը (թեև տարեց հիվանդի մոտ այս մեթոդը կարող է արդյունավետ չլինել)՝<ul><li>Քնային զարկերակ (պարանոցին)՝ ≥ 60 մմ ս.ս.</li><li>Ազդրային զարկերակ (աճուկում)՝ ≥ 70 մմ ս.ս.</li><li>Ճաճանչային զարկերակ (դաստակին)՝ ≥ 80 մմ ս.ս.</li></ul></li></ul>","text":"Սրտի զարկ՝ րոպեում 60–100 զարկ Շնչառության հաճախականություն՝ րոպեում 10–20 ներշնչում Րոպեում 8-ից պակաս ներշնչումը վտանգավոր ցուցանիշ է, որի դեպքում հնարավոր է, որ պահանջվի միջամտություն։ Սիստոլիկ զարկերակային ճնշում՝ >90 մմ ս.ս. Թթվածնային հագեցում՝ >92% Եթե չունեք հնարավորություն չափելու զարկերակային ճնշումը, կարող եք գնահատել սիստոլիկ զարկերակային ճնշումը պուլսի միջոցով։ Պուլսը ստուգել կարելի է ստորև ներկայացված եղանակներով, որոնք կօգնեն գնահատել մեծահասակների մոտ սիստոլիկ զարկերակային ճնշումը (թեև տարեց հիվանդի մոտ այս մեթոդը կարող է արդյունավետ չլինել)՝ Քնային զարկերակ (պարանոցին)՝ ≥ 60 մմ ս.ս. Ազդրային զարկերակ (աճուկում)՝ ≥ 70 մմ ս.ս. Ճաճանչային զարկերակ (դաստակին)՝ ≥ 80 մմ ս.ս."},{"id":"s-ABCDE","cat":"abcde","title":"«ABCDE» մոտեցում","keywords":"The ABCDE approach ABCDE log roll գերանի գլորում airway breathing circulation disability exposure","html":"<p>«ABCDE» մոտեցումն ապահովում է մի շրջանակ՝ սուր հիվանդություններով հիվանդների համակարգված և կազմակերպված գնահատման համար, որպեսզի արագ բացահայտվեն և վերացվեն կյանքին սպառնացող վիճակները:</p><p><strong>A – Շնչուղիներ.</strong> Ստուգեք և վերացրեք դեպի թոքեր գնացող օդի ցանկացած խոչընդոտ</p><p><strong>B – Շնչառություն.</strong> Ապահովեք դեպի թոքեր գնացող օդի պատշաճ հոսքը</p><p><strong>C – Արյան շրջանառություն.</strong> Գնահատեք, թե արդյոք առկա է հյուսվածքներին թթվածին ապահովող պատշաճ պերֆուզիա. ստուգեք կյանքին սպառնացող արյունահոսության նշանների առկայությունը</p><p><strong>D – Գիտակցության խանգարում (ԿՆՀ-ի գործունեություն).</strong> Գնահատեք և ապահովեք գլխուղեղի և ողնաշարի գործունեության պաշտպանությունը</p><p><strong>E – Բացահայտում / վտանգավոր արտաքին ազդեցություններ.</strong> Հայտնաբերեք բոլոր վնասվածքները և միջավայրի ցանկացած սպառնալիք և կանխեք հիպոթերմիան</p><p>Այս քայլ առ քայլ մոտեցումը նախատեսված է, որպեսզի կյանքին վտանգ սպառնացող վիճակները բացահայտվեն և բուժվեն վաղ փուլում՝ առաջնահերթության կարգով։ Եթե այս քայլերից որևէ մեկի ժամանակ խնդիր է բացահայտվում, այն պետք է անմիջապես լուծել՝ նախքան հաջորդ քայլին անցնելը։ «ABCDE» մոտեցումը պետք է իրականացնել առաջին 5 րոպեների ընթացքում և կրկնել հիվանդի վիճակի ցանկացած փոփոխության կամ վատթարացման դեպքում։</p><div class=\"callout remember\"><strong>ՀԻՇԵ՛Ք.</strong> Միշտ ստուգեք վնասվածքի նշանների առկայությունը «ABCDE»-ի յուրաքանչյուր բաժնում, իսկ անհրաժեշտության դեպքում դիմեք վնասվածքների մոդուլին։</div><h2 id=\"airway\">Շնչուղիներ</h2><p>Կարո՞ղ է հիվանդը նորմալ խոսել։ Եթե այո, ապա շնչուղիներն ազատ են։</p><p class=\"label\">Եթե հիվանդը չի կարողանում նորմալ խոսել:</p><ul><li>Նայեք՝ արդյո՞ք կրծքավանդակը շարժվում է, և ստուգեք՝ արդյո՞ք բերանից կամ քթից օդի շարժում է լսվում։</li><li>Ստուգեք՝ արդյո՞ք շնչուղիներից լսվում են ոչ բնորոշ ձայներ (օրինակ՝ ստրիդոր, հևոց կամ խռխռոց) կամ խռպոտ, խռխռացող ձայն. սա մասնակի խցանված շնչուղիների նշան է։<ul><li>Ստրիդորը՝ այտուցի և/կամ եղնջացանի հետ միասին, վկայում է սուր ալերգիկ ռեակցիայի (անաֆիլաքսիայի) մասին։</li></ul></li><li>Նայեք և լսեք՝ արդյո՞ք շնչուղիներում առկա է հեղուկ (օրինակ՝ արյուն, փսխունք)։</li><li>Նայեք՝ արդյո՞ք շնչուղիների շրջանում նկատվում է օտար մարմին կամ ոչ բնորոշ այտուցվածություն, ինչպես նաև՝ արդյո՞ք գիտակցությունը փոփոխված է։</li><li>Ստուգեք՝ արդյո՞ք հիվանդը կարողանում է թուքը կուլ տալ, թե՞ թուքը բերանից դուրս է հոսում։</li></ul><h3>Վարման հիմնական որոշումներ</h3><p>Եթե հիվանդը անգիտակից է և նորմալ չի շնչում, ընդ որում՝</p><ul><li>ՎՆԱՍՎԱԾՔ ՉԿԱ. բացեք շնչուղին՝ կատարելով գլխի հետթեքում և կզակի բարձրացում (<a class=\"xref\" href=\"#/p/s-Adultheadtiltandchinlift\">մեծահասակների</a> և <a class=\"xref\" href=\"#/p/s-Paediatricheadtiltandchinlift\">երեխաների</a> համար)։</li><li>ՎՆԱՍՎԱԾՔԻ ԿԱՍԿԱԾ ԿԱ. <a class=\"xref\" href=\"#/p/s-Spinalimmobilization\">անշարժացրեք ողնաշարի պարանոցային հատվածը</a> և բացեք շնչուղին՝ <a class=\"xref\" href=\"#/p/s-Jawthrust\">ծնոտը դեպի առաջ հրելով</a>։</li><li>Տեղադրեք <a class=\"xref\" href=\"#/p/s-Basicairwaydeviceinsertion\">բերան-ըմպանային կամ քիթ-ըմպանային օդուղի</a>՝ շնչուղու անցանելիությունն ապահովելու համար։</li></ul><h2 id=\"breathing\">Շնչառություն</h2><ul><li>Նայեք, լսեք և շոշափեք՝ պարզելու համար, թե արդյո՞ք հիվանդը շնչում է։</li><li>Գնահատեք՝ արդյո՞ք շնչառությունը շատ արագ է, շատ դանդաղ, թե՞ շատ մակերեսային։</li><li>Նայեք՝ արդյո՞ք առկա են շնչելու հավելյալ աշխատանքի նշաններ (օրինակ՝ օժանդակ շնչառական մկանների աշխատանք, կրծքավանդակի ներքաշում, քթանցքերի լայնացում) կամ կրծքավանդակի պատի ոչ բնորոշ շարժումներ։</li><li>Լսեք՝ արդյո՞ք առկա են շնչառության ոչ բնորոշ ձայներ, ինչպիսիք են սուլոցը կամ խզզոցը։</li><li>Ծանր սուլոցի դեպքում զննելիս շնչառական ձայները կարող են թուլացած լինել կամ ընդհանրապես չլսվել, քանի որ շնչուղիների խիստ նեղացման պատճառով շնչառությունը կարող է լսելի չլինել։</li><li>Լսեք՝ արդյո՞ք շնչառական ձայները կրծքավանդակի երկու կողմերում միանման են։</li><li>Ստուգեք շնչառության ձայնի բացակայությունը, ինչպես նաև պերկուսիայի ժամանակ մի կողմից ձայնի բթացումը (ծավալուն պլևրալ էֆուզիա կամ հեմոթորաքս)։</li><li>Եթե մի կողմում շնչառական ձայներ չեն լսվում և առկա է հիպոտենզիա, ստուգեք պարանոցի երակների լայնացումը կամ շնչափողի շեղումը (լարված պնևմոթորաքս)։</li><li>Հնարավորության դեպքում ստուգեք թթվածնային հագեցումը՝ պուլսօքսիմետրով։</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Եթե հիվանդն անգիտակից է և շնչում է ոչ նորմալ, սկսեք <a class=\"xref\" href=\"#/p/s-BagValveMaskVentilation\">շնչեցում տոպրակ-փական-դիմակով</a> և առաջնորդվեք ՍԹՎ համապատասխան գործելակարգերով։</li><li>Եթե հիվանդը համարժեք չի շնչում (տարիքի համար չափազանց դանդաղ կամ չափազանց մակերեսային), սկսեք շնչեցում տոպրակ-փական-դիմակով՝ օգտագործելով թթվածին։ Եթե թթվածինն անմիջապես հասանելի չէ, ՄԻ՛ ՀԵՏԱՁԳԵՔ շնչեցումը. սկսեք այն, մինչ թթվածինը պատրաստվում է։ <a class=\"xref\" href=\"#/p/s-Transferandhandover\">Պլանավորեք հիվանդի արագ փոխանցումը/հանձնումը։</a></li><li>Արագացած շնչառության կամ թթվածնաքաղցի դեպքում <a class=\"xref\" href=\"#/p/s-Giveoxygen\">տվեք թթվածին</a>։</li></ul><h2 id=\"circulation\">Արյան շրջանառություն</h2><ul><li>Նայեք և շոշափեք՝ պարզելու համար շոկի և թույլ պերֆուզիայի նշանները (սառը, խոնավ վերջույթներ, մազանոթների վերալցման ուշացում՝ 3 վայրկյանից ավելի, արյան ցածր ճնշում, տախիպնոէ, տախիկարդիա, բացակայող պուլս)։</li><li>Ստուգեք <a class=\"xref\" href=\"#/p/s-Externalbleedingcontrol\">արտաքին</a>, ԵՎ ներքին արյունահոսության առկայությունը, ներառյալ արյունահոսությունը՝<ul><li>կրծքավանդակում;</li><li>որովայնում;</li><li>ստամոքսից կամ աղիներից;</li><li>կոնքի կամ ազդրոսկրի կոտրվածքից;</li><li>վերքերից։</li></ul></li><li>Ստուգեք հիպոտենզիայի, պարանոցի երակների լայնացման և սրտի խլացած ձայների առկայությունը, որոնք կարող են վկայել սրտի (պերիկարդի) տամպոնադի մասին։</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Սրտի կանգի դեպքում կատարեք ՍԹՎ՝ համապատասխան գործելակարգերով։</li><li>Թույլ պերֆուզիայի նշանների դեպքում տվեք ն/ե հեղուկներ և թթվածին և՝<ul><li><a class=\"xref\" href=\"#/p/s-Externalbleedingcontrol\">Արտաքին արյունահոսության դեպքում ուղիղ ճնշում գործադրեք կամ կիրառեք արյունահոսությունը վերահսկելու այլ եղանակ։</a></li><li>Ներքին արյունահոսության կամ սրտի (պերիկարդի) տամպոնադի կասկածի դեպքում <a class=\"xref\" href=\"#/p/s-Transferandhandover\">շտապ փոխանցեք հիվանդին վիրաբուժական հնարավորություններ ունեցող կենտրոն</a>։</li></ul></li><li>Եթե պատճառն անհայտ է, հիշեք վնասվածքի հավանականության մասին. <a class=\"xref\" href=\"#/p/s-Pelvicbinderapplication\">կապեք կոնքի կոտրվածքը</a> և <a class=\"xref\" href=\"#/p/s-Fractureimmobilization\">անշարժացրեք ազդրոսկրի կոտրվածքը</a>, ինչպես նաև արյան հոսքի խանգարմամբ ուղեկցվող ցանկացած կոտրվածք։</li></ul><h2 id=\"disability\">Գիտակցության խանգարում</h2><ul><li>Գնահատեք գիտակցության մակարդակը <a class=\"xref\" href=\"#/p/s-GCSAVPU\">AVPU/ԶԽՑԱ սանդղակով (զգոնություն, խոսք, ցավ, անարձագանք) կամ վնասվածքի դեպքում՝ Գլազգոյի կոմայի սանդղակով (ԳԿՍ)</a>։</li><li>Միշտ ստուգեք արյան մեջ գլյուկոզայի մակարդակը՝ շփոթված գիտակցությամբ կամ անգիտակից հիվանդի մոտ։</li><li>Ստուգեք բիբերի չափերը՝ արդյո՞ք դրանք հավասար են, և արդյո՞ք արձագանքում են լույսին։</li><li>Ստուգեք բոլոր չորս վերջույթների շարժողական և զգայական գործունեությունը։</li><li>Ուշադրություն դարձրեք կրկնվող ոչ բնորոշ շարժումներին կամ մարմնի մեկ կամ երկու կողմում ցնցումներին (նոպա/ցնցումներ)։</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Գիտակցության փոփոխության և վնասվածքի բացակայության դեպքում՝ <a class=\"xref\" href=\"#/p/s-Spinalimmobilization\">հիվանդին պառկեցրեք կողքի ապահովության դիրքում</a>։</li><li>Արյան մեջ գլյուկոզայի ցածր մակարդակի (&lt;3,5 մմոլ/լ), կամ գիտակցության փոփոխության առկայության և գլյուկոզան որոշելու անհնարինության դեպքում՝ հիվանդին գլյուկոզա տվեք։</li><li>Ակտիվ ցնցումների դեպքում տվեք բենզոդիազեպին։<ul><li>Հղի կնոջ մոտ ցնցումների դեպքում տվեք մագնեզիումի սուլֆատ։</li></ul></li><li>Եթե բիբերը նեղացած են, իսկ շնչառությունը դանդաղ է, դիտարկեք ափիոնային (օպիոիդային) գերդոզավորումը և տվեք նալոքսոն։</li><li>Եթե բիբերի չափերը տարբեր են, դիտարկեք ուղեղի վրա ճնշման ավելացման հավանականությունը և, եթե ողնաշարի վնասվածքի կասկած չկա, մահճակալի գլխամասը բարձրացրեք 30 աստիճանով։ Պլանավորեք հիվանդի շտապ փոխանցումը առավել բարձր կարգի սպասարկողի կամ նյարդավիրաբուժական հնարավորություններով կենտրոն։</li><li>Եթե պատճառն անհայտ է, հիշեք վնասվածքի հավանականության մասին. <a class=\"xref\" href=\"#/p/s-Spinalimmobilization\">վնասվածքի կասկածի դեպքում անշարժացրեք ողնաշարի պարանոցային հատվածը։</a></li></ul><h2 id=\"exposure\">Բացահայտում</h2><ul><li>Ամբողջությամբ զննեք հիվանդի մարմինը՝ թաքնված վնասվածքների, ցանի, կծածքների և այլ ախտահարումների հայտնաբերման համար։</li><li>Ցանը, օրինակ՝ եղնջացանը, կարող է վկայել ալերգիկ ռեակցիայի մասին, իսկ ցանի այլ տեսակներ՝ լուրջ վարակի մասին։</li></ul><h3>Վարման հիմնական որոշումներ</h3><ul><li>Օձի կծածի կասկածի դեպքում անշարժացրեք վերջույթը։ Հնարավորության դեպքում որոշակի հեռավորությունից լուսանկարեք օձին և ուղարկեք լուսանկարը հիվանդի հետ։ Մի վտանգեք ինքներդ ձեզ՝ փորձելով բռնել/սպանել օձին։</li><li>Հանեք սեղմող հագուստը և բոլոր զարդերը։</li><li>Հնարավորինս արագ ծածկեք հիվանդին՝ հիպոթերմիայից պաշտպանելու համար։ Սուր հիվանդների օրգանիզմը դժվարությամբ է կարգավորում մարմնի ջերմաստիճանը։</li><li>Հանեք ցանկացած թաց հագուստ և հիվանդի մարմինը լավ չորացրեք։</li><li>Նորածինները և երեխաները դժվարությամբ են պահպանում մարմնի ջերմաստիճանը և շատ արագ կարող են հիպոթերմիայի կամ հիպերթերմիայի ենթարկվել։<ul><li>Հանեք թաց հագուստը և մաշկը լավ չորացրեք։ Հնարավորության դեպքում կրծքի տարիքի երեխաներին գրկեք՝ մաշկը մաշկին հպում ապահովելու համար։</li><li>Հիպոթերմիայի դեպքում անպայման ծածկեք կրծքի տարիքի երեխաների գլուխը (սակայն մի փակեք դեմքը)։</li><li>Հիպերթերմիայի դեպքում քանդեք կրծքի տարիքի երեխաների ձիգ բարուրը։</li></ul></li><li>Հարգեք հիվանդին և պահպանեք նրա արժանապատվությունը՝ մերկության ժամանակ։</li><li>Եթե պատճառն անհայտ է, հիշեք վնասվածքի հավանականության մասին. ողնաշարի վնասվածքի կասկածի դեպքում <a class=\"xref\" href=\"#/p/s-Spinalimmobilization\">կիրառեք գերանի գլորում մեթոդը</a>։</li></ul><p><strong>Կենսացուցանիշների ամբողջական հավաքածուն (արյան ճնշում, սրտի զարկ, շնչառության հաճախականություն և հնարավորության դեպքում՝ թթվածնային հագեցում) պետք է չափել «ABCDE» մոտեցումից հետո։ Կենսացուցանիշների չափման պատճառով մի հետաձգեք «ABCDE»-ի միջամտությունները։</strong></p><p><strong>«ABCDE» մոտեցումը նախատեսված է կյանքին սպառնացող սակայն շրջելի վիճակների արագ բացահայտման համար։ Իդեալական դեպքում «ABCDE» մոտեցումը պետք է կրկնել առնվազն 15 րոպեն մեկ կամ վիճակի ցանկացած փոփոխության դեպքում։</strong></p>","text":"«ABCDE» մոտեցումն ապահովում է մի շրջանակ՝ սուր հիվանդություններով հիվանդների համակարգված և կազմակերպված գնահատման համար, որպեսզի արագ բացահայտվեն և վերացվեն կյանքին սպառնացող վիճակները: A – Շնչուղիներ. Ստուգեք և վերացրեք դեպի թոքեր գնացող օդի ցանկացած խոչընդոտ B – Շնչառություն. Ապահովեք դեպի թոքեր գնացող օդի պատշաճ հոսքը C – Արյան շրջանառություն. Գնահատեք, թե արդյոք առկա է հյուսվածքներին թթվածին ապահովող պատշաճ պերֆուզիա. ստուգեք կյանքին սպառնացող արյունահոսության նշանների առկայությունը D – Գիտակցության խանգարում (ԿՆՀ-ի գործունեություն). Գնահատեք և ապահովեք գլխուղեղի և ողնաշարի գործունեության պաշտպանությունը E – Բացահայտում / վտանգավոր արտաքին ազդեցություններ. Հայտնաբերեք բոլոր վնասվածքները և միջավայրի ցանկացած սպառնալիք և կանխեք հիպոթերմիան Այս քայլ առ քայլ մոտեցումը նախատեսված է, որպեսզի կյանքին վտանգ սպառնացող վիճակները բացահայտվեն և բուժվեն վաղ փուլում՝ առաջնահերթության կարգով։ Եթե այս քայլերից որևէ մեկի ժամանակ խնդիր է բացահայտվում, այն պետք է անմիջապես լուծել՝ նախքան հաջորդ քայլին անցնելը։ «ABCDE» մոտեցումը պետք է իրականացնել առաջին 5 րոպեների ընթացքում և կրկնել հիվանդի վիճակի ցանկացած փոփոխության կամ վատթարացման դեպքում։ ՀԻՇԵ՛Ք. Միշտ ստուգեք վնասվածքի նշանների առկայությունը «ABCDE»-ի յուրաքանչյուր բաժնում, իսկ անհրաժեշտության դեպքում դիմեք վնասվածքների մոդուլին։ Շնչուղիներ Կարո՞ղ է հիվանդը նորմալ խոսել։ Եթե այո, ապա շնչուղիներն ազատ են։ Եթե հիվանդը չի կարողանում նորմալ խոսել: Նայեք՝ արդյո՞ք կրծքավանդակը շարժվում է, և ստուգեք՝ արդյո՞ք բերանից կամ քթից օդի շարժում է լսվում։ Ստուգեք՝ արդյո՞ք շնչուղիներից լսվում են ոչ բնորոշ ձայներ (օրինակ՝ ստրիդոր, հևոց կամ խռխռոց) կամ խռպոտ, խռխռացող ձայն. սա մասնակի խցանված շնչուղիների նշան է։ Ստրիդորը՝ այտուցի և/կամ եղնջացանի հետ միասին, վկայում է սուր ալերգիկ ռեակցիայի (անաֆիլաքսիայի) մասին։ Նայեք և լսեք՝ արդյո՞ք շնչուղիներում առկա է հեղուկ (օրինակ՝ արյուն, փսխունք)։ Նայեք՝ արդյո՞ք շնչուղիների շրջանում նկատվում է օտար մարմին կամ ոչ բնորոշ այտուցվածություն, ինչպես նաև՝ արդյո՞ք գիտակցությունը փոփոխված է։ Ստուգեք՝ արդյո՞ք հիվանդը կարողանում է թուքը կուլ տալ, թե՞ թուքը բերանից դուրս է հոսում։ Վարման հիմնական որոշումներ Եթե հիվանդը անգիտակից է և նորմալ չի շնչում, ընդ որում՝ ՎՆԱՍՎԱԾՔ ՉԿԱ. բացեք շնչուղին՝ կատարելով գլխի հետթեքում և կզակի բարձրացում (մեծահասակների և երեխաների համար)։ ՎՆԱՍՎԱԾՔԻ ԿԱՍԿԱԾ ԿԱ. անշարժացրեք ողնաշարի պարանոցային հատվածը և բացեք շնչուղին՝ ծնոտը դեպի առաջ հրելով։ Տեղադրեք բերան-ըմպանային կամ քիթ-ըմպանային օդուղի՝ շնչուղու անցանելիությունն ապահովելու համար։ Շնչառություն Նայեք, լսեք և շոշափեք՝ պարզելու համար, թե արդյո՞ք հիվանդը շնչում է։ Գնահատեք՝ արդյո՞ք շնչառությունը շատ արագ է, շատ դանդաղ, թե՞ շատ մակերեսային։ Նայեք՝ արդյո՞ք առկա են շնչելու հավելյալ աշխատանքի նշաններ (օրինակ՝ օժանդակ շնչառական մկանների աշխատանք, կրծքավանդակի ներքաշում, քթանցքերի լայնացում) կամ կրծքավանդակի պատի ոչ բնորոշ շարժումներ։ Լսեք՝ արդյո՞ք առկա են շնչառության ոչ բնորոշ ձայներ, ինչպիսիք են սուլոցը կամ խզզոցը։ Ծանր սուլոցի դեպքում զննելիս շնչառական ձայները կարող են թուլացած լինել կամ ընդհանրապես չլսվել, քանի որ շնչուղիների խիստ նեղացման պատճառով շնչառությունը կարող է լսելի չլինել։ Լսեք՝ արդյո՞ք շնչառական ձայները կրծքավանդակի երկու կողմերում միանման են։ Ստուգեք շնչառության ձայնի բացակայությունը, ինչպես նաև պերկուսիայի ժամանակ մի կողմից ձայնի բթացումը (ծավալուն պլևրալ էֆուզիա կամ հեմոթորաքս)։ Եթե մի կողմում շնչառական ձայներ չեն լսվում և առկա է հիպոտենզիա, ստուգեք պարանոցի երակների լայնացումը կամ շնչափողի շեղումը (լարված պնևմոթորաքս)։ Հնարավորության դեպքում ստուգեք թթվածնային հագեցումը՝ պուլսօքսիմետրով։ Վարման հիմնական որոշումներ Եթե հիվանդն անգիտակից է և շնչում է ոչ նորմալ, սկսեք շնչեցում տոպրակ-փական-դիմակով և առաջնորդվեք ՍԹՎ համապատասխան գործելակարգերով։ Եթե հիվանդը համարժեք չի շնչում (տարիքի համար չափազանց դանդաղ կամ չափազանց մակերեսային), սկսեք շնչեցում տոպրակ-փական-դիմակով՝ օգտագործելով թթվածին։ Եթե թթվածինն անմիջապես հասանելի չէ, ՄԻ՛ ՀԵՏԱՁԳԵՔ շնչեցումը. սկսեք այն, մինչ թթվածինը պատրաստվում է։ Պլանավորեք հիվանդի արագ փոխանցումը/հանձնումը։ Արագացած շնչառության կամ թթվածնաքաղցի դեպքում տվեք թթվածին։ Արյան շրջանառություն Նայեք և շոշափեք՝ պարզելու համար շոկի և թույլ պերֆուզիայի նշանները (սառը, խոնավ վերջույթներ, մազանոթների վերալցման ուշացում՝ 3 վայրկյանից ավելի, արյան ցածր ճնշում, տախիպնոէ, տախիկարդիա, բացակայող պուլս)։ Ստուգեք արտաքին, ԵՎ ներքին արյունահոսության առկայությունը, ներառյալ արյունահոսությունը՝ կրծքավանդակում; որովայնում; ստամոքսից կամ աղիներից; կոնքի կամ ազդրոսկրի կոտրվածքից; վերքերից։ Ստուգեք հիպոտենզիայի, պարանոցի երակների լայնացման և սրտի խլացած ձայների առկայությունը, որոնք կարող են վկայել սրտի (պերիկարդի) տամպոնադի մասին։ Վարման հիմնական որոշումներ Սրտի կանգի դեպքում կատարեք ՍԹՎ՝ համապատասխան գործելակարգերով։ Թույլ պերֆուզիայի նշանների դեպքում տվեք ն/ե հեղուկներ և թթվածին և՝ Արտաքին արյունահոսության դեպքում ուղիղ ճնշում գործադրեք կամ կիրառեք արյունահոսությունը վերահսկելու այլ եղանակ։ Ներքին արյունահոսության կամ սրտի (պերիկարդի) տամպոնադի կասկածի դեպքում շտապ փոխանցեք հիվանդին վիրաբուժական հնարավորություններ ունեցող կենտրոն։ Եթե պատճառն անհայտ է, հիշեք վնասվածքի հավանականության մասին. կապեք կոնքի կոտրվածքը և անշարժացրեք ազդրոսկրի կոտրվածքը, ինչպես նաև արյան հոսքի խանգարմամբ ուղեկցվող ցանկացած կոտրվածք։ Գիտակցության խանգարում Գնահատեք գիտակցության մակարդակը AVPU/ԶԽՑԱ սանդղակով (զգոնություն, խոսք, ցավ, անարձագանք) կամ վնասվածքի դեպքում՝ Գլազգոյի կոմայի սանդղակով (ԳԿՍ)։ Միշտ ստուգեք արյան մեջ գլյուկոզայի մակարդակը՝ շփոթված գիտակցությամբ կամ անգիտակից հիվանդի մոտ։ Ստուգեք բիբերի չափերը՝ արդյո՞ք դրանք հավասար են, և արդյո՞ք արձագանքում են լույսին։ Ստուգեք բոլոր չորս վերջույթների շարժողական և զգայական գործունեությունը։ Ուշադրություն դարձրեք կրկնվող ոչ բնորոշ շարժումներին կամ մարմնի մեկ կամ երկու կողմում ցնցումներին (նոպա/ցնցումներ)։ Վարման հիմնական որոշումներ Գիտակցության փոփոխության և վնասվածքի բացակայության դեպքում՝ հիվանդին պառկեցրեք կողքի ապահովության դիրքում։ Արյան մեջ գլյուկոզայի ցածր մակարդակի (<3,5 մմոլ/լ), կամ գիտակցության փոփոխության առկայության և գլյուկոզան որոշելու անհնարինության դեպքում՝ հիվանդին գլյուկոզա տվեք։ Ակտիվ ցնցումների դեպքում տվեք բենզոդիազեպին։ Հղի կնոջ մոտ ցնցումների դեպքում տվեք մագնեզիումի սուլֆատ։ Եթե բիբերը նեղացած են, իսկ շնչառությունը դանդաղ է, դիտարկեք ափիոնային (օպիոիդային) գերդոզավորումը և տվեք նալոքսոն։ Եթե բիբերի չափերը տարբեր են, դիտարկեք ուղեղի վրա ճնշման ավելացման հավանականությունը և, եթե ողնաշարի վնասվածքի կասկած չկա, մահճակալի գլխամասը բարձրացրեք 30 աստիճանով։ Պլանավորեք հիվանդի շտապ փոխանցումը առավել բարձր կարգի սպասարկողի կամ նյարդավիրաբուժական հնարավորություններով կենտրոն։ Եթե պատճառն անհայտ է, հիշեք վնասվածքի հավանականության մասին. վնասվածքի կասկածի դեպքում անշարժացրեք ողնաշարի պարանոցային հատվածը։ Բացահայտում Ամբողջությամբ զննեք հիվանդի մարմինը՝ թաքնված վնասվածքների, ցանի, կծածքների և այլ ախտահարումների հայտնաբերման համար։ Ցանը, օրինակ՝ եղնջացանը, կարող է վկայել ալերգիկ ռեակցիայի մասին, իսկ ցանի այլ տեսակներ՝ լուրջ վարակի մասին։ Վարման հիմնական որոշումներ Օձի կծածի կասկածի դեպքում անշարժացրեք վերջույթը։ Հնարավորության դեպքում որոշակի հեռավորությունից լուսանկարեք օձին և ուղարկեք լուսանկարը հիվանդի հետ։ Մի վտանգեք ինքներդ ձեզ՝ փորձելով բռնել/սպանել օձին։ Հանեք սեղմող հագուստը և բոլոր զարդերը։ Հնարավորինս արագ ծածկեք հիվանդին՝ հիպոթերմիայից պաշտպանելու համար։ Սուր հիվանդների օրգանիզմը դժվարությամբ է կարգավորում մարմնի ջերմաստիճանը։ Հանեք ցանկացած թաց հագուստ և հիվանդի մարմինը լավ չորացրեք։ Նորածինները և երեխաները դժվարությամբ են պահպանում մարմնի ջերմաստիճանը և շատ արագ կարող են հիպոթերմիայի կամ հիպերթերմիայի ենթարկվել։ Հանեք թաց հագուստը և մաշկը լավ չորացրեք։ Հնարավորության դեպքում կրծքի տարիքի երեխաներին գրկեք՝ մաշկը մաշկին հպում ապահովելու համար։ Հիպոթերմիայի դեպքում անպայման ծածկեք կրծքի տարիքի երեխաների գլուխը (սակայն մի փակեք դեմքը)։ Հիպերթերմիայի դեպքում քանդեք կրծքի տարիքի երեխաների ձիգ բարուրը։ Հարգեք հիվանդին և պահպանեք նրա արժանապատվությունը՝ մերկության ժամանակ։ Եթե պատճառն անհայտ է, հիշեք վնասվածքի հավանականության մասին. ողնաշարի վնասվածքի կասկածի դեպքում կիրառեք գերանի գլորում մեթոդը։ Կենսացուցանիշների ամբողջական հավաքածուն (արյան ճնշում, սրտի զարկ, շնչառության հաճախականություն և հնարավորության դեպքում՝ թթվածնային հագեցում) պետք է չափել «ABCDE» մոտեցումից հետո։ Կենսացուցանիշների չափման պատճառով մի հետաձգեք «ABCDE»-ի միջամտությունները։ «ABCDE» մոտեցումը նախատեսված է կյանքին սպառնացող սակայն շրջելի վիճակների արագ բացահայտման համար։ Իդեալական դեպքում «ABCDE» մոտեցումը պետք է կրկնել առնվազն 15 րոպեն մեկ կամ վիճակի ցանկացած փոփոխության դեպքում։"}]};
